const fs = require('fs');

const data = fs.readFileSync('eslint-report.json', 'utf8');
// remove BOM if present
const content = data.charCodeAt(0) === 0xFEFF ? data.slice(1) : data;
const results = JSON.parse(content);

const targetRules = [
  "sonarjs/prefer-single-boolean-return",
  "sonarjs/no-gratuitous-expressions",
  "@typescript-eslint/ban-ts-comment",
  "sonarjs/no-identical-expressions",
  "sonarjs/no-identical-functions",
  "sonarjs/use-type-alias",
  "sonarjs/no-ignored-exceptions",
  "@typescript-eslint/no-unused-vars",
  "react-hooks/exhaustive-deps"
];

for (const res of results) {
  for (const msg of res.messages) {
    if (targetRules.includes(msg.ruleId)) {
      console.log(`${res.filePath}:${msg.line}:${msg.column} - ${msg.ruleId}`);
    }
  }
}

"use client";

import { useState, useEffect } from "react";
import { useSearchParams } from "next/navigation";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { ListTree, Wrench, Activity, Package } from "lucide-react";
import ServicesClientPage from "@/app/(protected)/finances/services/client-page";
import GeneralServicesClient from "@/app/(protected)/finances/general-services/GeneralServicesClient";
import RecoveryClientPage from "@/app/(protected)/finances/recovery/client-page";
import InventoryClient from "@/app/(protected)/inventory/InventoryClient";
import { useAppStore } from "@/store/use-app-store";

interface CatalogsClientProps {
  services: any[];
  recoveryServices: any[];
}

export default function CatalogsClient({
  services,
  recoveryServices,
}: CatalogsClientProps) {
  const searchParams = useSearchParams();
  const { activeBranch } = useAppStore();
  const isRecoveryOnly = activeBranch === "recoveryzone";

  const defaultTab = isRecoveryOnly
    ? "recovery"
    : searchParams.get("tab") || "services";
  const [catalogsSubTab, setCatalogsSubTab] = useState<string>(defaultTab);

  useEffect(() => {
    if (isRecoveryOnly) {
      setCatalogsSubTab("recovery");
    }
  }, [isRecoveryOnly]);

  return (
    <div className="space-y-10">
      <div className="pt-2">
        <Tabs
          defaultValue={defaultTab}
          value={catalogsSubTab}
          onValueChange={setCatalogsSubTab}
          className="space-y-6"
        >
          <TabsList className="bg-zinc-100 dark:bg-zinc-900/50 p-1 rounded-2xl h-11 w-full sm:w-fit border border-zinc-200/40 dark:border-zinc-800/40 mb-2 overflow-x-auto no-scrollbar justify-start flex sm:inline-flex">
            {!isRecoveryOnly && (
              <>
                <TabsTrigger
                  value="services"
                  className="rounded-xl px-5 text-xs font-semibold tracking-wide data-[state=active]:bg-white dark:data-[state=active]:bg-zinc-800 data-[state=active]:text-zinc-950 data-[state=active]:shadow-sm dark:data-[state=active]:text-white shadow-none transition-all whitespace-nowrap"
                >
                  <ListTree className="h-3.5 w-3.5 mr-2" />
                  Тренировки
                </TabsTrigger>
                <TabsTrigger
                  value="general"
                  className="rounded-xl px-5 text-xs font-semibold tracking-wide data-[state=active]:bg-white dark:data-[state=active]:bg-zinc-800 data-[state=active]:text-zinc-950 data-[state=active]:shadow-sm dark:data-[state=active]:text-white shadow-none transition-all whitespace-nowrap"
                >
                  <Wrench className="h-3.5 w-3.5 mr-2" />
                  Клубни Услуги
                </TabsTrigger>
              </>
            )}
            <TabsTrigger
              value="recovery"
              className="rounded-xl px-5 text-xs font-semibold tracking-wide data-[state=active]:bg-white dark:data-[state=active]:bg-zinc-800 data-[state=active]:text-zinc-950 data-[state=active]:shadow-sm dark:data-[state=active]:text-white shadow-none transition-all whitespace-nowrap"
            >
              <Activity className="h-3.5 w-3.5 mr-2" />
              Възстановяване
            </TabsTrigger>
            {!isRecoveryOnly && (
              <TabsTrigger
                value="inventory"
                className="rounded-xl px-5 text-xs font-semibold tracking-wide data-[state=active]:bg-white dark:data-[state=active]:bg-zinc-800 data-[state=active]:text-zinc-950 data-[state=active]:shadow-sm dark:data-[state=active]:text-white shadow-none transition-all whitespace-nowrap"
              >
                <Package className="h-3.5 w-3.5 mr-2" />
                Магазин / Стоки
              </TabsTrigger>
            )}
          </TabsList>

          {!isRecoveryOnly && (
            <>
              <TabsContent value="services" className="outline-none mt-0">
                <div className="bg-white dark:bg-zinc-950 border border-zinc-100 dark:border-zinc-900 rounded-5xl p-6 sm:p-8 shadow-sm">
                  <ServicesClientPage showPageHeader={false} data={services} />
                </div>
              </TabsContent>

              <TabsContent value="general" className="outline-none mt-0">
                <div className="bg-white dark:bg-zinc-950 border border-zinc-100 dark:border-zinc-900 rounded-5xl p-6 sm:p-8 shadow-sm">
                  <GeneralServicesClient showPageHeader={false} />
                </div>
              </TabsContent>
            </>
          )}

          <TabsContent value="recovery" className="outline-none mt-0">
            <div className="bg-white dark:bg-zinc-950 border border-zinc-100 dark:border-zinc-900 rounded-5xl p-6 sm:p-8 shadow-sm">
              <RecoveryClientPage
                showPageHeader={false}
                data={recoveryServices}
              />
            </div>
          </TabsContent>

          {!isRecoveryOnly && (
            <TabsContent value="inventory" className="outline-none mt-0">
              <div className="bg-white dark:bg-zinc-950 border border-zinc-100 dark:border-zinc-900 rounded-5xl p-6 sm:p-8 shadow-sm">
                <InventoryClient showPageHeader={false} />
              </div>
            </TabsContent>
          )}
        </Tabs>
      </div>
    </div>
  );
}

import { Suspense } from "react";
import { PageHeader } from "@/components/layout/page-header";
import { getAdminDb } from "@/lib/firebase-admin";
import { serializeFirestoreData } from "@/lib/serialize-utils";
import { ServiceSchema } from "../finances/services/service.types";
import { ClubService } from "@/types";
import { serverCache } from "@/lib/server-cache";
import CatalogsClient from "./CatalogsClient";

export const dynamic = "force-dynamic";

export default async function CatalogsPage() {
  const adminDb = getAdminDb();

  const [services, recoveryServices] = await Promise.all([
    serverCache.get(
      "clubServices",
      async () => {
        const servicesSnapshot = await adminDb.collection("clubServices").get();
        return servicesSnapshot.docs.map((doc) => {
          const data = doc.data();
          const serializedData = serializeFirestoreData({
            id: doc.id,
            ...data,
          });
          return ServiceSchema.parse(serializedData);
        });
      },
      300000
    ),
    serverCache.get(
      "recoveryServices",
      async () => {
        const sessionsSnapshot = await adminDb.collection("sessions").get();
        return sessionsSnapshot.docs.map((doc) => {
          const data = doc.data();
          const parseZones = (z: any) => {
            if (Array.isArray(z)) return z;
            if (typeof z === "string") return z.split(",").filter(Boolean);
            return [];
          };
          return {
            id: doc.id,
            siteId: "recoveryzone",
            name: data.name || "Неименувана услуга",
            description: data.description || "",
            price: data.price || 0,
            currency: "EUR",
            durationMinutes: data.duration || 0,
            category: data.category || "Други",
            zones: parseZones(data.zones),
            athleteCount: data.athleteCount || 1,
            numberOfDays: data.numberOfDays || 1,
            proceduresPerDay: data.proceduresPerDay || 1,
            sessionType: data.sessionType || "Възстановяване",
            requiresBooking: true,
            createdAt: data.createdAt?.toDate
              ? data.createdAt.toDate().toISOString()
              : data.createdAt || new Date().toISOString(),
            updatedAt: data.updatedAt?.toDate
              ? data.updatedAt.toDate().toISOString()
              : data.updatedAt || new Date().toISOString(),
            requiredResources: data.requiredResources || null,
            imageUrl: data.imageUrl || null,
            imageDisplayMode: data.imageDisplayMode || "collage",
          } as unknown as ClubService;
        });
      },
      300000
    ),
  ]);

  return (
    <div className="space-y-12 animate-in fade-in duration-700 pb-24">
      <PageHeader
        title="Клубни Каталози"
        description="Управление на ценоразписи, тренировъчни програми и възстановителни процедури."
        breadcrumbs={[
          { label: "Начало", href: "/dashboard" },
          { label: "Каталози" },
        ]}
      />

      <Suspense
        fallback={
          <div className="p-8 text-center text-zinc-500">
            Зареждане на каталозите...
          </div>
        }
      >
        <CatalogsClient
          services={services}
          recoveryServices={recoveryServices}
        />
      </Suspense>
    </div>
  );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { useRouter } from "next/navigation";
import { useAuth } from "@/context/auth-context";
import { useLanguage } from "@/context/language-context";
import { BentoCard } from "@/components/ui/bento-card";
import { PageHeader } from "@/components/layout/page-header";
import { QuickTasks } from "@/components/dashboard/quick-tasks";
import { AttendanceReminder } from "@/components/dashboard/AttendanceReminder";
import { BirthdayReminder } from "@/components/dashboard/BirthdayReminder";
import {
  Users,
  Calendar,
  TrendingUp,
  AlertCircle,
  ArrowUpRight,
  RefreshCw,
  CheckCircle2,
  Sparkles,
} from "lucide-react";
import { Skeleton } from "@/components/ui/skeleton";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { formatPrice } from "@/lib/currency";
import {
  getDashboardDataServerAction,
  invalidateDashboardCacheAction,
} from "@/lib/actions/dashboard";

import { useAppStore } from "@/store/use-app-store";

interface DashboardClientProps {
  initialData: any;
}

export default function DashboardClient({ initialData }: DashboardClientProps) {
  const router = useRouter();
  const { user } = useAuth();
  const { t, language } = useLanguage();
  const { activeBranch } = useAppStore();

  const [stats, setStats] = useState<any>(initialData?.stats || null);
  const [todayTrainings, setTodayTrainings] = useState<any[]>(
    initialData?.todayTrainings || []
  );
  const loading = false;
  const [refreshing, setRefreshing] = useState(false);
  const [mounted, setMounted] = useState(false);
  const [quotaExhausted, setQuotaExhausted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  const handleRefresh = useCallback(
    async (quiet = false) => {
      // Don't retry if quota is known to be exhausted
      if (quiet && quotaExhausted) return;
      if (!quiet) {
        setRefreshing(true);
        // Force clear the dashboard server cache on manual refresh
        await invalidateDashboardCacheAction().catch((err) =>
          console.error("Cache invalidation failed on manual refresh", err)
        );
      }
      try {
        const result = await getDashboardDataServerAction(activeBranch);
        if (result.success) {
          const data = (result as any).data;
          if (data) {
            setStats(data.stats);
            setTodayTrainings(data.todayTrainings);
            setQuotaExhausted(false);
          }
        } else {
          const errMsg = (result as any).error || "";
          if (
            errMsg.includes("RESOURCE_EXHAUSTED") ||
            errMsg.includes("Quota")
          ) {
            setQuotaExhausted(true);
          }
        }
      } catch (err: any) {
        console.error("Error refreshing dashboard data:", err);
        if (
          err?.message?.includes("RESOURCE_EXHAUSTED") ||
          err?.message?.includes("Quota")
        ) {
          setQuotaExhausted(true);
        }
      } finally {
        if (!quiet) setRefreshing(false);
      }
    },
    [activeBranch, quotaExhausted]
  );

  useEffect(() => {
    // Quiet refresh when branch changes or on timer (skip if quota exhausted)
    if (!quotaExhausted) handleRefresh(true);

    const interval = setInterval(() => {
      handleRefresh(true);
    }, 300000); // 5 minutes

    return () => clearInterval(interval);
  }, [handleRefresh, quotaExhausted]);

  // Branch-specific display logic
  const isRecoveryZone = activeBranch === "recoveryzone";

  const displayEmail = isRecoveryZone
    ? "recoveryzonebyzm@gmail.com"
    : user?.email || "bkgalabovo2014@gmail.com";

  const displayGreeting = isRecoveryZone
    ? "Ето какво се случва в зоната за възстановяване днес."
    : "Ето какво се случва в клуба днес.";

  const firstName = `Админ ${displayEmail}`;

  // Use values from stats or fallback to 0/placeholder
  const monthlyRevenue = stats?.revenueLast30Days || 0;

  const renderMembersContent = () => {
    if (loading) {
      return (
        <div className="space-y-1.5">
          <Skeleton className="h-3 w-full bg-blue-200/50 dark:bg-zinc-800" />
          <Skeleton className="h-3 w-full bg-blue-200/50 dark:bg-zinc-800" />
          <Skeleton className="h-3 w-full bg-blue-200/50 dark:bg-zinc-800" />
        </div>
      );
    }
    return (
      <div className="space-y-1 text-zinc-700 dark:text-zinc-300">
        <div className="flex items-center justify-between text-[11px] leading-tight">
          <span className="font-light">Клубни членове:</span>
          <span className="font-bold text-blue-700 dark:text-blue-300">
            {stats?.totalClubMembers ?? 0}
          </span>
        </div>
        <div className="flex items-center justify-between text-[11px] leading-tight">
          <span className="font-light">Външни клиенти:</span>
          <span className="font-bold text-amber-700 dark:text-amber-400">
            {stats?.totalGuests ?? 0}
          </span>
        </div>
        <div className="flex items-center justify-between text-[11px] leading-tight">
          <span className="font-light">Възстановяване:</span>
          <span className="font-bold text-emerald-700 dark:text-emerald-400">
            {stats?.totalRecovery ?? 0}
          </span>
        </div>
        <div className="flex items-center justify-between text-[11px] leading-tight">
          <span className="font-light">Неактивни:</span>
          <span className="font-bold text-rose-600 dark:text-rose-400">
            {stats?.inactiveMembersCount ?? 0}
          </span>
        </div>
        <div className="flex items-center justify-between text-[11px] leading-tight">
          <span className="font-light">Семейства:</span>
          <span className="font-bold text-purple-700 dark:text-purple-400">
            {stats?.totalFamilies ?? 0}
          </span>
        </div>
      </div>
    );
  };

  const renderScheduleContent = () => {
    if (loading) {
      return (
        <div className="space-y-1.5">
          <Skeleton className="h-3 w-full bg-emerald-200/50 dark:bg-zinc-800" />
          <Skeleton className="h-3 w-full bg-emerald-200/50 dark:bg-zinc-800" />
          <Skeleton className="h-3 w-full bg-emerald-200/50 dark:bg-zinc-800" />
        </div>
      );
    }
    return (
      <div className="space-y-3">
        <div className="space-y-1 text-zinc-700 dark:text-zinc-300 border-b border-emerald-100 dark:border-emerald-800/50 pb-3">
          <div className="flex items-center justify-between text-[11px] leading-tight">
            <span className="font-light">Тренировки:</span>
            <span className="font-bold text-emerald-700 dark:text-emerald-300">
              {stats?.todayTrainingsCount ?? 0}
            </span>
          </div>
          <div className="flex items-center justify-between text-[11px] leading-tight">
            <span className="font-light">Състезания:</span>
            <span className="font-bold text-rose-600 dark:text-rose-400">
              {stats?.todayCompetitionsCount ?? 0}
            </span>
          </div>
          <div className="flex items-center justify-between text-[11px] leading-tight">
            <span className="font-light">Лагери & Други:</span>
            <span className="font-bold text-amber-700 dark:text-amber-400">
              {(stats?.todayCampsCount ?? 0) +
                (stats?.todayOtherEventsCount ?? 0)}
            </span>
          </div>
          <div className="flex items-center justify-between text-[11px] leading-tight">
            <span className="font-light">Възстановяване:</span>
            <span className="font-bold text-blue-600 dark:text-blue-400">
              {stats?.todayRecoveryCount ?? 0}
            </span>
          </div>
          <div className="flex items-center justify-between text-[11px] leading-tight">
            <span className="font-light">Кортове:</span>
            <span className="font-bold text-purple-600 dark:text-purple-400">
              {stats?.todayCourtCount ?? 0}
            </span>
          </div>
        </div>

        {stats?.todayEventsList && stats.todayEventsList.length > 0 && (
          <div className="space-y-2 pt-1">
            {stats.todayEventsList.slice(0, 3).map((event: any) => (
              <div
                key={event.id}
                className="flex items-start justify-between text-[10px] leading-tight bg-white/50 dark:bg-black/20 p-2 rounded-xl"
              >
                <div className="flex flex-col gap-0.5">
                  <span className="font-bold text-emerald-800 dark:text-emerald-200 line-clamp-1">
                    {event.title}
                  </span>
                  <span className="font-light text-zinc-500 dark:text-zinc-400">
                    {new Date(event.startDate).toLocaleTimeString(
                      "bg-BG",
                      { hour: "2-digit", minute: "2-digit" }
                    )}
                  </span>
                </div>
                <span className="px-1.5 py-0.5 bg-emerald-100 dark:bg-emerald-900/40 rounded text-emerald-700 dark:text-emerald-300 font-medium whitespace-nowrap">
                  {event.attendeesCount} зап.
                </span>
              </div>
            ))}
            {stats.todayEventsList.length > 3 && (
              <div
                className="text-[10px] text-center text-emerald-600/70 dark:text-emerald-400/70 font-medium mt-1 cursor-pointer hover:underline"
                onClick={() => router.push("/schedule")}
              >
                + още {stats.todayEventsList.length - 3} събития
              </div>
            )}
          </div>
        )}
      </div>
    );
  };

  const renderRevenueContent = () => {
    if (loading) {
      return (
        <div className="space-y-1.5">
          <Skeleton className="h-3 w-full bg-purple-200/50 dark:bg-zinc-800" />
          <Skeleton className="h-3 w-full bg-purple-200/50 dark:bg-zinc-800" />
          <Skeleton className="h-3 w-full bg-purple-200/50 dark:bg-zinc-800" />
        </div>
      );
    }
    return (
      <div className="space-y-1 text-zinc-700 dark:text-zinc-300">
        <div className="flex items-center justify-between text-[11px] leading-tight">
          <span className="font-light">Тренировки:</span>
          <span className="font-bold text-purple-700 dark:text-purple-300">
            {formatPrice(stats?.revenueTrainings ?? 0)}
          </span>
        </div>
        <div className="flex items-center justify-between text-[11px] leading-tight">
          <span className="font-light">Клубни услуги:</span>
          <span className="font-bold text-teal-800 dark:text-teal-400">
            {formatPrice(stats?.revenueServices ?? 0)}
          </span>
        </div>
        <div className="flex items-center justify-between text-[11px] leading-tight">
          <span className="font-light">Възстановяване:</span>
          <span className="font-bold text-indigo-600 dark:text-indigo-400">
            {formatPrice(stats?.revenueRecovery ?? 0)}
          </span>
        </div>
        <div className="flex items-center justify-between text-[11px] leading-tight">
          <span className="font-light">Кортове:</span>
          <span className="font-bold text-pink-800 dark:text-pink-400">
            {formatPrice(stats?.revenueCourts ?? 0)}
          </span>
        </div>
        <div className="flex items-center justify-between text-[11px] leading-tight">
          <span className="font-light">Магазин / Стоки:</span>
          <span className="font-bold text-purple-700 dark:text-purple-300">
            {formatPrice(stats?.revenueShop ?? 0)}
          </span>
        </div>
      </div>
    );
  };

  const renderLowStockContent = () => {
    if (loading) {
      return (
        <div className="space-y-1.5">
          <Skeleton className="h-3 w-full bg-current opacity-10" />
          <Skeleton className="h-3 w-full bg-current opacity-10" />
        </div>
      );
    }
    if ((stats?.lowStockCount || 0) > 0) {
      return (
        <div className="space-y-1.5 relative">
          {stats?.lowStockProducts?.slice(0, 4).map((p: any) => (
            <div
              key={p.id}
              className="flex items-center justify-between text-[11px] leading-tight bg-white/40 dark:bg-black/20 px-2 py-1 rounded-md border border-rose-100/50 dark:border-rose-900/20"
            >
              <span
                className="font-medium truncate max-w-[100px] text-zinc-700 dark:text-zinc-300"
                title={p.name}
              >
                {p.name}
              </span>
              <span className="font-extrabold text-rose-700 dark:text-rose-400">
                {p.stock} бр.
              </span>
            </div>
          ))}
          {(stats?.lowStockProducts?.length || 0) > 4 && (
            <div className="text-[9px] font-medium text-right mt-1 opacity-70 text-rose-600 dark:text-rose-400">
              + още {(stats?.lowStockProducts?.length || 0) - 4}
            </div>
          )}
        </div>
      );
    }
    return (
      <div className="space-y-1">
        <div className="text-[12px] font-medium leading-tight text-emerald-800 dark:text-emerald-300">
          Всички стоки са налични.
        </div>
        <div className="text-[10px] opacity-70">Към магазина</div>
      </div>
    );
  };

  if (!mounted) {
    return (
      <div className="space-y-8 animate-pulse pb-12">
        <div className="h-32 bg-zinc-50 rounded-3xl w-full" />
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <div className="h-40 bg-zinc-50 rounded-3xl" />
          <div className="h-40 bg-zinc-50 rounded-3xl" />
          <div className="h-40 bg-zinc-50 rounded-3xl" />
          <div className="h-40 bg-zinc-50 rounded-3xl" />
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-700 pb-12">
      <PageHeader
        title={firstName}
        description={displayGreeting}
        breadcrumbs={[{ label: "Начало" }]}
      >
        <div className="flex gap-3 items-center">
          <Button
            variant="outline"
            size="icon"
            className="rounded-xl border-zinc-200 hover:bg-zinc-50 transition-all h-12 w-12 flex items-center justify-center shrink-0"
            onClick={() => handleRefresh(false)}
            disabled={refreshing}
            aria-label={language === "bg" ? "Обнови" : "Refresh"}
            title={language === "bg" ? "Обнови" : "Refresh"}
          >
            <RefreshCw
              className={cn(
                "h-4 w-4 text-zinc-600 transition-transform duration-500",
                refreshing && "animate-spin"
              )}
            />
          </Button>
        </div>
      </PageHeader>

      {/* Main Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <BentoCard
          onClick={() => router.push("/members")}
          className="p-6 flex flex-col justify-between border shadow-none bg-blue-50 text-blue-600 border-blue-100 dark:bg-blue-900/10 dark:text-blue-400 dark:border-blue-800/50 rounded-4xl h-full min-h-48 transition-all duration-300 group cursor-pointer relative overflow-hidden hover:bg-blue-100/50 dark:hover:bg-blue-950/20"
