} from "@/components/ui/select";

interface AddGeneralServiceDialogProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
}

export const AddGeneralServiceDialog = ({
  isOpen,
  onClose,
  onSuccess,
}: AddGeneralServiceDialogProps) => {
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [price, setPrice] = useState("");
  const [pricingUnit, setPricingUnit] = useState<"fixed" | "per_hour" | "per_session">("fixed");
  const [performerName, setPerformerName] = useState("");
  const [performerType, setPerformerType] = useState<"internal" | "external">("internal");
  const [imageUrl, setImageUrl] = useState("");
  
  const [isProcessing, setIsProcessing] = useState(false);
  const { activeBranch } = useAppStore();

  const handleAdd = async () => {
    if (!name || !price || !performerName) {
      toast.error("Грешка", {
        description: "Моля попълнете задължителните полета (Име, Цена, Изпълнител).",
      });
      return;
    }

    setIsProcessing(true);
    try {
      const serviceData = {
        name,
        description,
        price: parseFloat(price),
        pricingUnit,
        performerName,
        performerType,
        imageUrl: imageUrl || null,
        currency: "EUR" as const,
        siteId: activeBranch || "bkgalabovo",
      };

      const result = await createGeneralServiceAction(serviceData);

      if (result.success) {
        toast.success("Успех!", { description: "Услугата е създадена успешно." });
        onSuccess();
        onClose();
        // Clear form
        setName("");
        setDescription("");
        setPrice("");
        setPricingUnit("fixed");
        setPerformerName("");
        setPerformerType("internal");
        setImageUrl("");
      } else {
        toast.error("Грешка", { description: result.error });
      }
    } catch (error) {
      toast.error("Грешка при добавяне", {
        description: (error as Error).message,
      });
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-[480px] rounded-4xl p-8 bg-white dark:bg-zinc-950 border-none shadow-xl">
        <DialogHeader>
          <DialogTitle className="text-2xl font-light text-zinc-950 dark:text-zinc-50">
            Добавяне на услуга
          </DialogTitle>
          <DialogDescription className="font-light text-zinc-400 mt-1">
            Въведете детайлите за новата клубна услуга.
          </DialogDescription>
        </DialogHeader>

        <div className="grid gap-4 py-4 mt-2">
          <div className="grid gap-1.5">
            <Label htmlFor="name" className="text-xs font-bold text-zinc-700 dark:text-zinc-300">
              Име на услугата *
            </Label>
            <Input
              id="name"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="напр. Наем на корт"
              className="rounded-xl h-11"
              disabled={isProcessing}
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="grid gap-1.5">
              <Label htmlFor="price" className="text-xs font-bold text-zinc-700 dark:text-zinc-300">
                Цена (EUR) *
              </Label>
              <Input
                id="price"
                type="number"
                step="0.01"
                value={price}
                onChange={(e) => setPrice(e.target.value)}
                placeholder="0.00"
                className="rounded-xl h-11"
                disabled={isProcessing}
              />
            </div>
            <div className="grid gap-1.5">
              <Label htmlFor="pricingUnit" className="text-xs font-bold text-zinc-700 dark:text-zinc-300">
                Ценообразуване *
              </Label>
              <Select
                value={pricingUnit}
                onValueChange={(val: any) => setPricingUnit(val)}
                disabled={isProcessing}
              >
                <SelectTrigger className="rounded-xl h-11 border-zinc-200 dark:border-zinc-800 bg-zinc-50 dark:bg-zinc-900/50">
                  <SelectValue placeholder="Избери..." />
                </SelectTrigger>
                <SelectContent className="rounded-xl">
                  <SelectItem value="fixed">Фиксирана сума</SelectItem>
                  <SelectItem value="per_hour">На час</SelectItem>
                  <SelectItem value="per_session">На сесия</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="grid gap-1.5">
              <Label htmlFor="performerName" className="text-xs font-bold text-zinc-700 dark:text-zinc-300">
                Изпълнител *
              </Label>
              <Input
                id="performerName"
                value={performerName}
                onChange={(e) => setPerformerName(e.target.value)}
                placeholder="Име на треньор/клуб"
                className="rounded-xl h-11"
                disabled={isProcessing}
              />
            </div>
            <div className="grid gap-1.5">
              <Label htmlFor="performerType" className="text-xs font-bold text-zinc-700 dark:text-zinc-300">
                Тип изпълнител *
              </Label>
              <Select
                value={performerType}
                onValueChange={(val: any) => setPerformerType(val)}
                disabled={isProcessing}
              >
                <SelectTrigger className="rounded-xl h-11 border-zinc-200 dark:border-zinc-800 bg-zinc-50 dark:bg-zinc-900/50">
                  <SelectValue placeholder="Избери..." />
                </SelectTrigger>
                <SelectContent className="rounded-xl">
                  <SelectItem value="internal">Вътрешен (Клуб)</SelectItem>
                  <SelectItem value="external">Външен партньор</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="grid gap-1.5">
            <Label htmlFor="imageUrl" className="text-xs font-bold text-zinc-700 dark:text-zinc-300">
              Изображение URL (Снимка)
            </Label>
            <Input
              id="imageUrl"
              value={imageUrl}
              onChange={(e) => setImageUrl(e.target.value)}
              placeholder="Линк към снимка на услугата..."
              className="rounded-xl h-11"
              disabled={isProcessing}
            />
          </div>

          <div className="grid gap-1.5">
            <Label htmlFor="description" className="text-xs font-bold text-zinc-700 dark:text-zinc-300">
              Описание (Опционално)
            </Label>
            <Textarea
              id="description"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Допълнителни детайли..."
              className="rounded-xl min-h-[100px] resize-none"
              disabled={isProcessing}
            />
          </div>
        </div>

        <DialogFooter className="mt-6 flex justify-end gap-3">
          <Button
            variant="outline"
            onClick={onClose}
            disabled={isProcessing}
            className="rounded-xl px-6 h-11"
          >
            Отказ
          </Button>
          <Button
            onClick={handleAdd}
            disabled={isProcessing}
            className="rounded-xl px-6 h-11 bg-zinc-950 text-white hover:bg-zinc-800"
          >
            Добави услуга
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

"use client";

import { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import { GeneralService, GeneralServiceEvent, Sale } from "@/types";
import {
  updateGeneralServiceAction,
  getGeneralServiceHistoryAction,
  getGeneralServiceSalesAction,
} from "@/lib/actions/general-services-server";
import { useAppStore } from "@/store/use-app-store";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Wrench, Sparkles, Loader2 } from "lucide-react";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { getAllMembers } from "@/services/member-service";
import { formatDateTimeDisplay } from "@/lib/date-utils";
import { Badge } from "@/components/ui/badge";
import { formatPrice } from "@/lib/currency";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

interface EditGeneralServiceDialogProps {
  service: GeneralService | null;
  isOpen: boolean;
  onClose: () => void;
  onServiceUpdate: () => void;
}

export const EditGeneralServiceDialog = ({
  service,
  isOpen,
  onClose,
  onServiceUpdate,
}: EditGeneralServiceDialogProps) => {
  // Service info states
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [price, setPrice] = useState("");
  const [pricingUnit, setPricingUnit] = useState<"fixed" | "per_hour" | "per_session">("fixed");
  const [performerName, setPerformerName] = useState("");
  const [performerType, setPerformerType] = useState<"internal" | "external">("internal");
  const [imageUrl, setImageUrl] = useState("");

  const [isProcessing, setIsProcessing] = useState(false);
  const { activeBranch } = useAppStore();

  // History and Tab states
  const [activeTab, setActiveTab] = useState("movements");
  const [movements, setMovements] = useState<GeneralServiceEvent[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [membersMap, setMembersMap] = useState<Record<string, string>>({});
  const [historyLoading, setHistoryLoading] = useState(false);

  useEffect(() => {
    if (isOpen && service && activeBranch) {
      const fetchHistory = async () => {
        setHistoryLoading(true);
        try {
          // Fetch events
          const historyRes = await getGeneralServiceHistoryAction(activeBranch);
          if (historyRes.success && historyRes.data) {
            const filteredEvents = historyRes.data.filter(
              (e): e is import("@/types").GeneralServiceEvent => e !== null && e.serviceId === service.id
            );
            setMovements(filteredEvents);
          }

          // Fetch sales
          const salesRes = await getGeneralServiceSalesAction(activeBranch);
          if (salesRes.success && salesRes.data) {
            const filteredSales = salesRes.data.filter((s) =>
              s.items?.some((i) => i.productId === service.id)
            );
            setSales(filteredSales);
          }

          // Fetch members map
          const membersData = await getAllMembers();
          const map: Record<string, string> = {};
          membersData.forEach((m) => {
            map[m.id] = `${m.firstName} ${m.lastName}`;
          });
          setMembersMap(map);
        } catch (err) {
          console.error("Error fetching service history:", err);
        } finally {
          setHistoryLoading(false);
        }
      };
      fetchHistory();
    }
  }, [isOpen, service, activeBranch]);

  const getEventLabel = (type: string) => {
    switch (type) {
      case "create":
        return "Създаване";
      case "update":
        return "Редакция";
      case "sale":
        return "Продажба";
      case "delete":
        return "Изтриване";
      default:
        return "Друго";
    }
  };

  const getEventBadgeClass = (type: string) => {
    switch (type) {
      case "create":
        return "bg-green-50 text-green-700 dark:bg-green-950/20 dark:text-green-400";
      case "sale":
        return "bg-rose-50 text-rose-700 dark:bg-rose-950/20 dark:text-rose-400";
      case "update":
        return "bg-amber-50 text-amber-700 dark:bg-amber-950/20 dark:text-amber-400";
      default:
        return "bg-zinc-100 text-zinc-700 dark:bg-zinc-900 dark:text-zinc-400";
    }
  };

  // Populate states when service changes
  useEffect(() => {
    if (service) {
      setName(service.name || "");
      setDescription(service.description || "");
      setPrice(service.price?.toString() || "0");
      setPricingUnit(service.pricingUnit || "fixed");
      setPerformerName(service.performerName || "");
      setPerformerType(service.performerType || "internal");
      setImageUrl(service.imageUrl || "");
    }
  }, [service]);

  const handleUpdateInfo = async () => {
    if (!service) return;
    if (!name.trim() || !price || !performerName.trim()) {
      toast.error("Грешка", {
        description: "Моля, попълнете задължителните полета.",
      });
      return;
    }

    const priceVal = parseFloat(price);
    if (isNaN(priceVal) || priceVal < 0) {
      toast.error("Грешка", {
        description: "Моля, въведете валидна, неотрицателна цена.",
      });
      return;
    }

    setIsProcessing(true);
    try {
      const serviceData = {
        name,
        description,
        price: priceVal,
        pricingUnit,
        performerName,
        performerType,
        imageUrl: imageUrl || null,
      };

      const result = await updateGeneralServiceAction(service.id, serviceData);

      if (result.success) {
        toast.success("Успех!", { description: "Информацията е запазена успешно." });
        onServiceUpdate();
        onClose();
      } else {
        toast.error("Грешка", { description: result.error });
      }
    } catch (error) {
      toast.error("Грешка при актуализация", {
        description: (error as Error).message,
      });
    } finally {
      setIsProcessing(false);
    }
  };

  const renderMovementsContent = () => {
    if (historyLoading) {
      return (
        <div className="py-20 flex flex-col items-center justify-center space-y-4">
          <Loader2 className="h-8 w-8 animate-spin text-amber-500 opacity-35" />
          <p className="text-zinc-400 text-xs font-light">
            Зареждане на движения...
          </p>
        </div>
      );
    }
    if (movements.length === 0) {
      return (
        <div className="py-20 text-center text-zinc-400 text-xs font-light">
          Няма записани движения за тази услуга.
        </div>
      );
    }
    return (
      <div className="space-y-3">
        {movements.map((move) => {
          return (
            <div
              key={move.id}
              className="p-4 bg-zinc-50 dark:bg-zinc-900/30 rounded-2xl border border-zinc-100/50 dark:border-zinc-900 space-y-2 text-xs"
            >
              <div className="flex justify-between items-center">
                <span className="text-zinc-400 text-[10px]">
                  {formatDateTimeDisplay(move.createdAt)}
                </span>
                <Badge
                  className={`px-2 py-0.5 rounded text-[9px] uppercase font-bold tracking-wider shadow-none border-none ${getEventBadgeClass(
                    move.type
                  )}`}
                >
                  {getEventLabel(move.type)}
                </Badge>
              </div>
              {move.oldPrice !== undefined && move.newPrice !== undefined && (
                <div className="flex justify-between items-center text-[11px] text-zinc-500">
                  <span>Промяна на цена:</span>
                  <span>
                    {formatPrice(move.oldPrice)} &rarr; {formatPrice(move.newPrice)}
                  </span>
                </div>
              )}
              <div className="text-[10px] text-zinc-400/80 text-right mt-1">
                Оператор: {move.userName}
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const renderSalesContent = () => {
    if (historyLoading) {
      return (
        <div className="py-20 flex flex-col items-center justify-center space-y-4">
          <Loader2 className="h-8 w-8 animate-spin text-emerald-500 opacity-35" />
          <p className="text-zinc-400 text-xs font-light">
            Зареждане на продажби...
          </p>
        </div>
      );
    }
    if (sales.length === 0) {
      return (
        <div className="py-20 text-center text-zinc-400 text-xs font-light">
          Няма записани продажби за тази услуга.
        </div>
      );
    }
    return (
      <div className="space-y-3">
        {sales.map((sale) => {
          const item = sale.items.find(
            (i) => i.productId === service?.id
          );
          const memberName =
            sale.memberId === "GUEST_EXTERNAL"
              ? "Външен клиент"
              : membersMap[sale.memberId] || "Зареден Член";
          return (
            <div
              key={sale.id}
              className="p-4 bg-zinc-50 dark:bg-zinc-900/30 rounded-2xl border border-zinc-100/50 dark:border-zinc-900 space-y-2 text-xs"
            >
              <div className="flex justify-between items-center">
                <span className="text-zinc-400 text-[10px]">
                  {new Date(sale.saleDate).toLocaleDateString(
                    "bg-BG"
                  )}
                </span>
                <Badge
                  className={`px-2 py-0.5 rounded text-[9px] uppercase font-bold tracking-wider shadow-none border-none ${
                    sale.isPaid
                      ? "bg-emerald-50 text-emerald-700 dark:bg-emerald-950/20 dark:text-emerald-400"
                      : "bg-rose-50 text-rose-700 dark:bg-rose-950/20 dark:text-rose-400"
                  }`}
                >
                  {sale.isPaid ? "Платено" : "Неплатено"}
                </Badge>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-zinc-500">Клиент:</span>
                <span className="font-semibold text-zinc-900 dark:text-white">
                  {memberName}
                </span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-zinc-500">Брой:</span>
                <span className="font-medium">
                  {item?.quantity || 1} бр.
                </span>
              </div>
              <div className="flex justify-between items-center pt-1 border-t border-zinc-200/50 dark:border-zinc-800/50">
                <span className="text-zinc-500">Сума:</span>
                <span className="font-bold text-emerald-500">
                  {formatPrice(sale.totalAmount)}
                </span>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  if (!service) return null;

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-[850px] p-8 sm:p-10 rounded-4xl bg-white dark:bg-zinc-950 border-none shadow-xl max-h-[90vh] overflow-y-auto custom-scrollbar">
        <DialogHeader className="mb-6">
          <DialogTitle className="text-2xl font-light text-zinc-950 dark:text-zinc-50 flex items-center gap-3">
            <Wrench className="h-6 w-6 text-zinc-650" strokeWidth={1.5} />
            Редактиране на: {service.name}
          </DialogTitle>
          <DialogDescription className="font-light text-zinc-400 mt-1">
            Промяна на информацията за услугата и преглед на историята.
          </DialogDescription>
        </DialogHeader>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
          {/* LEFT COLUMN: Service Details */}
          <div className="space-y-6">
            <div className="flex items-center gap-2 pb-2 border-b border-zinc-100 dark:border-zinc-900">
              <Sparkles className="h-4 w-4 text-primary" strokeWidth={2} />
              <h3 className="text-sm font-semibold text-zinc-950 dark:text-zinc-50">
                Информация за услугата
              </h3>
            </div>

            <div className="grid gap-4">
              <div className="grid gap-2">
                <Label htmlFor="edit-name" className="text-xs font-bold text-zinc-700 dark:text-zinc-300">
                  Име на услугата *
                </Label>
                <Input
                  id="edit-name"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder="напр. Наем на корт"
                  className="rounded-xl h-11"
                  disabled={isProcessing}
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="grid gap-2">
                  <Label htmlFor="edit-price" className="text-xs font-bold text-zinc-700 dark:text-zinc-300">
                    Цена (EUR) *
                  </Label>
                  <Input
                    id="edit-price"
                    type="number"
                    step="0.01"
                    value={price}
                    onChange={(e) => setPrice(e.target.value)}
                    placeholder="0.00"
                    className="rounded-xl h-11"
                    disabled={isProcessing}
                  />
                </div>
                <div className="grid gap-2">
                  <Label htmlFor="edit-pricingUnit" className="text-xs font-bold text-zinc-700 dark:text-zinc-300">
                    Ценообразуване *
                  </Label>
                  <Select
                    value={pricingUnit}
                    onValueChange={(val: any) => setPricingUnit(val)}
                    disabled={isProcessing}
                  >
                    <SelectTrigger className="rounded-xl h-11 border-zinc-200 dark:border-zinc-800 bg-zinc-50 dark:bg-zinc-900/50">
                      <SelectValue placeholder="Избери..." />
                    </SelectTrigger>
                    <SelectContent className="rounded-xl">
                      <SelectItem value="fixed">Фиксирана сума</SelectItem>
                      <SelectItem value="per_hour">На час</SelectItem>
                      <SelectItem value="per_session">На сесия</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="grid gap-2">
                  <Label htmlFor="edit-performerName" className="text-xs font-bold text-zinc-700 dark:text-zinc-300">
                    Изпълнител *
                  </Label>
                  <Input
                    id="edit-performerName"
                    value={performerName}
                    onChange={(e) => setPerformerName(e.target.value)}
                    placeholder="Име на треньор/клуб"
                    className="rounded-xl h-11"
                    disabled={isProcessing}
                  />
                </div>
                <div className="grid gap-2">
                  <Label htmlFor="edit-performerType" className="text-xs font-bold text-zinc-700 dark:text-zinc-300">
                    Тип изпълнител *
                  </Label>
                  <Select
                    value={performerType}
                    onValueChange={(val: any) => setPerformerType(val)}
                    disabled={isProcessing}
                  >
                    <SelectTrigger className="rounded-xl h-11 border-zinc-200 dark:border-zinc-800 bg-zinc-50 dark:bg-zinc-900/50">
                      <SelectValue placeholder="Избери..." />
                    </SelectTrigger>
                    <SelectContent className="rounded-xl">
                      <SelectItem value="internal">Вътрешен (Клуб)</SelectItem>
                      <SelectItem value="external">Външен партньор</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="grid gap-2">
                <Label htmlFor="edit-imageUrl" className="text-xs font-bold text-zinc-700 dark:text-zinc-300">
                  Изображение URL (Снимка)
                </Label>
                <Input
                  id="edit-imageUrl"
                  value={imageUrl}
                  onChange={(e) => setImageUrl(e.target.value)}
                  placeholder="Линк към снимка на услугата..."
                  className="rounded-xl h-11"
                  disabled={isProcessing}
                />
              </div>

              <div className="grid gap-2">
                <Label htmlFor="edit-description" className="text-xs font-bold text-zinc-700 dark:text-zinc-300">
                  Описание
                </Label>
                <Textarea
                  id="edit-description"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  placeholder="Допълнителни детайли..."
                  className="rounded-xl min-h-[80px]"
                  rows={3}
                  disabled={isProcessing}
                />
              </div>
            </div>

            <Button
              onClick={handleUpdateInfo}
              disabled={isProcessing}
              className="w-full rounded-xl bg-zinc-950 text-white hover:bg-zinc-800 h-12 font-medium text-[11px] uppercase tracking-widest transition-all mt-4"
            >
              Запази информацията
            </Button>
          </div>

          {/* RIGHT COLUMN: Service History System with Tabs */}
          <div className="space-y-6 md:border-l md:border-zinc-100 md:dark:border-zinc-900 md:pl-10 flex flex-col h-full min-h-[450px]">
            <Tabs
              defaultValue="movements"
              value={activeTab}
              onValueChange={setActiveTab}
              className="w-full flex-1 flex flex-col"
            >
              <TabsList className="bg-zinc-100 dark:bg-zinc-900/50 p-1 rounded-2xl h-11 w-full border border-zinc-200/40 dark:border-zinc-800/40 mb-6 flex">
                <TabsTrigger
                  value="movements"
                  className="flex-1 rounded-xl text-xs font-semibold data-[state=active]:bg-white dark:data-[state=active]:bg-zinc-800 data-[state=active]:text-zinc-950 data-[state=active]:shadow-sm dark:data-[state=active]:text-white shadow-none transition-all py-2"
                >
                  Движения
                </TabsTrigger>
                <TabsTrigger
                  value="sales"
                  className="flex-1 rounded-xl text-xs font-semibold data-[state=active]:bg-white dark:data-[state=active]:bg-zinc-800 data-[state=active]:text-zinc-950 data-[state=active]:shadow-sm dark:data-[state=active]:text-white shadow-none transition-all py-2"
                >
                  Продажби
                </TabsTrigger>
              </TabsList>

              <TabsContent
                value="movements"
                className="outline-none flex-1 max-h-[380px] overflow-y-auto custom-scrollbar space-y-4 pr-1 mt-0"
              >
                {renderMovementsContent()}
              </TabsContent>

              <TabsContent
                value="sales"
                className="outline-none flex-1 max-h-[380px] overflow-y-auto custom-scrollbar space-y-4 pr-1 mt-0"
              >
                {renderSalesContent()}
              </TabsContent>
            </Tabs>
          </div>
        </div>

        <DialogFooter className="mt-8 pt-6 border-t border-zinc-100 dark:border-zinc-900 flex justify-end gap-3">
          <Button
            variant="outline"
            onClick={onClose}
            disabled={isProcessing}
            className="rounded-xl px-6"
          >
            Затвори
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

"use client";

import { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import { Sale } from "@/types";
import { updateSale } from "@/services/sales-service";
import { Label } from "@/components/ui/label";
import { ShoppingBag, CreditCard } from "lucide-react";
import { Checkbox } from "@/components/ui/checkbox";
import { formatPrice } from "@/lib/currency";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

interface EditSaleDialogProps {
  sale: Sale | null;
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
}

export const EditSaleDialog = ({
  sale,
  isOpen,
  onClose,
  onSuccess,
}: EditSaleDialogProps) => {
  const [isPaid, setIsPaid] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState("В брой");
  const [totalAmount, setTotalAmount] = useState("");
  const [isProcessing, setIsProcessing] = useState(false);

  useEffect(() => {
    if (sale) {
      setIsPaid(sale.isPaid);
      setPaymentMethod(sale.paymentMethod || "В брой");
      setTotalAmount(sale.totalAmount.toString());
    }
  }, [sale]);

  const handleUpdate = async () => {
    if (!sale) return;
    
    const amountVal = parseFloat(totalAmount);
    if (isNaN(amountVal) || amountVal < 0) {
      toast.error("Грешка", {
        description: "Моля, въведете валидна сума.",
      });
      return;
    }

    setIsProcessing(true);
    try {
      await updateSale(sale.id, {
        isPaid,
        paymentMethod,
        totalAmount: amountVal,
      });

      toast.success("Успех!", { description: "Продажбата е обновена успешно." });
      onSuccess();
      onClose();
    } catch (error: any) {
      toast.error("Грешка", {
        description: error.message || "Грешка при обновяване на продажбата.",
      });
    } finally {
      setIsProcessing(false);
    }
  };

  if (!sale) return null;

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-[450px] p-8 rounded-3xl bg-white dark:bg-zinc-950 border border-zinc-100 dark:border-zinc-900 shadow-xl">
        <DialogHeader className="mb-6">
          <DialogTitle className="text-xl font-light text-zinc-950 dark:text-zinc-50 flex items-center gap-2">
            <ShoppingBag className="h-5 w-5 text-emerald-500" strokeWidth={1.5} />
            Редакция на продажба
          </DialogTitle>
          <DialogDescription className="font-light text-zinc-400 mt-1">
            Промяна на статуса на плащане и сумата на продажбата.
          </DialogDescription>
        </DialogHeader>

        <div className="grid gap-6">
          <div className="flex items-center justify-between p-4 bg-zinc-50 dark:bg-zinc-900/50 rounded-2xl border border-zinc-100 dark:border-zinc-800">
            <div className="flex flex-col">
              <span className="text-sm font-semibold text-zinc-900 dark:text-zinc-100">
                Статус на плащане
              </span>
              <span className="text-xs text-zinc-500 mt-0.5">
                {isPaid ? "Маркирано като платено" : "Маркирано като неплатено"}
              </span>
            </div>
            <Checkbox
              checked={isPaid}
              onCheckedChange={(checked) => setIsPaid(checked === true)}
              disabled={isProcessing}
              className="data-[state=checked]:bg-emerald-500 data-[state=checked]:border-emerald-500"
            />
          </div>

          <div className="grid gap-2">
            <Label className="text-xs font-bold text-zinc-700 dark:text-zinc-300">
              Начин на плащане
            </Label>
            <Select
              value={paymentMethod}
              onValueChange={setPaymentMethod}
              disabled={isProcessing}
            >
              <SelectTrigger className="h-11 rounded-xl bg-white dark:bg-zinc-950">
                <SelectValue placeholder="Изберете начин" />
              </SelectTrigger>
              <SelectContent className="rounded-xl">
                <SelectItem value="В брой">В брой</SelectItem>
                <SelectItem value="ПОС терминал">ПОС терминал</SelectItem>
                <SelectItem value="Банков път">Банков път</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="grid gap-2">
            <Label className="text-xs font-bold text-zinc-700 dark:text-zinc-300 flex items-center justify-between">
              Обща сума (EUR)
              <span className="text-[10px] text-zinc-400 font-normal">
                По подразбиране: {formatPrice(sale.totalAmount)}
              </span>
            </Label>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <CreditCard className="h-4 w-4 text-zinc-400" />
              </div>
              <Input
                type="number"
                step="0.01"
                value={totalAmount}
                onChange={(e) => setTotalAmount(e.target.value)}
                disabled={isProcessing}
                className="pl-10 h-11 rounded-xl"
              />
            </div>
          </div>
        </div>

        <DialogFooter className="mt-8 pt-6 border-t border-zinc-100 dark:border-zinc-900 flex justify-end gap-3">
          <Button
            variant="outline"
            onClick={onClose}
            disabled={isProcessing}
            className="rounded-xl px-6"
          >
            Отказ
          </Button>
          <Button
            onClick={handleUpdate}
            disabled={isProcessing}
            className="rounded-xl px-6 bg-zinc-950 text-white hover:bg-zinc-800"
          >
            {isProcessing ? "Запазване..." : "Запази промените"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

"use client";

import { useState, useEffect } from "react";
import { mutate } from "swr";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { toast } from "sonner";
import { GeneralService, Member } from "@/types";
import { getAllMembers } from "@/services/member-service";
import { createMemberAction } from "@/lib/actions/members";
import { executeGeneralServiceSaleAction } from "@/lib/actions/general-services-server";
import { formatPrice } from "@/lib/currency";
import { clubInfo } from "@/config/club";
import { useAuth } from "@/context/auth-context";
import { cn } from "@/lib/utils";
import { useAppStore } from "@/store/use-app-store";
import {
  ShoppingBag,
  Search,
  User,
  Check,
  CreditCard,
  Receipt,
  Loader2,
  ArrowLeft,
  ArrowRight,
  Printer,
  Sparkles,
  PlusCircle,
} from "lucide-react";

interface GeneralServiceSaleWizardDialogProps {
  service: GeneralService;
  isOpen: boolean;
  onClose: () => void;
  onSaleSuccess: () => void;
}

export const GeneralServiceSaleWizardDialog = ({
  service,
  isOpen,
  onClose,
  onSaleSuccess,
}: GeneralServiceSaleWizardDialogProps) => {
  const [step, setStep] = useState(1);
  const [members, setMembers] = useState<Member[]>([]);
  const [membersLoading, setMembersLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedMember, setSelectedMember] = useState<Member | null>(null);

  const [clientTypeTab, setClientTypeTab] = useState<"member" | "guest">(
    "member"
  );
  const [showNewGuestForm, setShowNewGuestForm] = useState(false);
  const [newGuestFirstName, setNewGuestFirstName] = useState("");
  const [newGuestLastName, setNewGuestLastName] = useState("");
  const [newGuestPhone, setNewGuestPhone] = useState("");
  const [newGuestEmail, setNewGuestEmail] = useState("");
  const [isSavingNewGuest, setIsSavingNewGuest] = useState(false);

  // Form states
  const [quantity, setQuantity] = useState("1");
  const [price, setPrice] = useState(service.price.toString());
  const [paymentMethod, setPaymentMethod] = useState("В брой");
  const [isPaid, setIsPaid] = useState(true);
  const [note, setNote] = useState("");
  const [isProcessing, setIsProcessing] = useState(false);
  const [completedSaleId, setCompletedSaleId] = useState<string | null>(null);

  const { activeBranch } = useAppStore();
  const { idToken } = useAuth();

  // Load members
  useEffect(() => {
    if (isOpen) {
      const fetchMembers = async () => {
        setMembersLoading(true);
        try {
          const fetchedMembers = await getAllMembers();
          setMembers(fetchedMembers);
        } catch (err) {
          console.error("Error loading members:", err);
          toast.error("Грешка", {
            description: "Неуспешно зареждане на клубните членове.",
          });
        } finally {
          setMembersLoading(false);
        }
      };
      fetchMembers();

      // Reset state on open
      setStep(1);
      setQuantity("1");
      setPrice(service.price.toString());
      setSelectedMember(null);
      setCompletedSaleId(null);
      setNote("");
      setClientTypeTab("member");
      setShowNewGuestForm(false);
      setNewGuestFirstName("");
      setNewGuestLastName("");
      setNewGuestPhone("");
      setNewGuestEmail("");
      setIsSavingNewGuest(false);
    }
  }, [isOpen, service]);

  const filteredMembers = members.filter((m) => {
    const isGuest = m.isGuest || m.memberType === "guest";
    const matchesTab = clientTypeTab === "guest" ? isGuest : !isGuest;
    if (!matchesTab) return false;

    const fullName = `${m.firstName} ${m.lastName}`.toLowerCase();
    return fullName.includes(searchTerm.toLowerCase());
  });

  const handleNextStep = () => {
    if (step === 1 && !selectedMember) {
      toast.error("Избор на клиент", {
        description:
          "Моля, изберете член от списъка или Външен клиент, за да продължите.",
      });
      return;
    }

    if (step === 2) {
      const qtyVal = parseInt(quantity, 10);
      const priceVal = parseFloat(price);
      if (isNaN(qtyVal) || qtyVal <= 0) {
        toast.error("Невалидно количество", {
          description: "Моля, въведете валидно положително количество.",
        });
        return;
      }
      if (isNaN(priceVal) || priceVal < 0) {
