        setStep(3);
        toast.error("Грешка", { description: result.error });
      }
    } catch (error: any) {
      setStep(3);
      toast.error("Грешка при продажба", {
        description: error.message,
      });
    } finally {
      setIsProcessing(false);
    }
  };

