                  <div className="text-right text-[9px] space-y-0.5 text-zinc-500">
                    <p className="font-bold uppercase text-zinc-700 dark:text-zinc-300">
                      {clubInfo.name}
                    </p>
                    <p className="uppercase">{clubInfo.address}</p>
                    <p className="uppercase">{clubInfo.contact}</p>
                  </div>
                </div>

                <div className="mb-3 text-[9px] flex justify-between items-start bg-zinc-50 dark:bg-zinc-900/50 p-2.5 border border-zinc-100 dark:border-zinc-800 rounded-lg">
                  <div>
                    <p className="text-[8px] text-zinc-400 font-bold uppercase tracking-widest mb-0.5">
                      Получател
                    </p>
                    <p className="font-bold uppercase text-zinc-800 dark:text-zinc-200">
                      {selectedMember.firstName} {selectedMember.lastName}
                    </p>
                    <p className="text-zinc-500 text-[8px] mt-0.5">
                      {selectedMember.id === "GUEST_EXTERNAL"
                        ? "Няма имейл (Външен клиент)"
                        : selectedMember.email || "Няма имейл"}
                    </p>
                  </div>

                  <div className="text-right text-zinc-600 dark:text-zinc-400">
                    <p className="text-[8px] text-zinc-400 font-bold uppercase tracking-widest mb-0.5">
                      Детайли за плащане
                    </p>
                    <p className="font-bold">
                      Дата: {new Date().toLocaleDateString("bg-BG")} г.
                    </p>
                    <p className="mt-0.5">Начин: {paymentMethod}</p>
                    <p className="mt-0.5 font-bold">
                      Статус:{" "}
                      <span
                        className={
                          isPaid
                            ? "text-emerald-600 dark:text-emerald-400"
                            : "text-rose-600 dark:text-rose-400"
                        }
                      >
                        {isPaid ? "ПЛАТЕНО" : "ОЧАКВА ПЛАЩАНЕ"}
                      </span>
                    </p>
                  </div>
                </div>

                <div className="mb-3">
                  <table className="w-full border-collapse border border-zinc-200 dark:border-zinc-800 text-[9px]">
                    <thead>
                      <tr className="bg-zinc-50 dark:bg-zinc-900 border-b border-zinc-200 dark:border-zinc-800 text-[8px] font-bold uppercase text-zinc-500">
                        <th className="p-1.5 text-left border-r border-zinc-200 dark:border-zinc-800">
                          Описание на услугата
                        </th>
                        <th className="p-1.5 text-center border-r border-zinc-200 dark:border-zinc-800">
                          К-во
                        </th>
                        <th className="p-1.5 text-right border-r border-zinc-200 dark:border-zinc-800">
                          Ед. цена
                        </th>
                        <th className="p-1.5 text-right">Общо</th>
                      </tr>
                    </thead>
                    <tbody>
                      <tr className="border-b border-zinc-200 dark:border-zinc-800 font-medium">
                        <td className="p-1.5 border-r border-zinc-200 dark:border-zinc-800 font-bold text-left text-zinc-800 dark:text-zinc-200">
                          {service.name}
                        </td>
                        <td className="p-1.5 text-center border-r border-zinc-200 dark:border-zinc-800 text-zinc-600 dark:text-zinc-400">
                          {quantity}
                        </td>
                        <td className="p-1.5 text-right border-r border-zinc-200 dark:border-zinc-800 text-zinc-600 dark:text-zinc-400">
                          {formatPrice(unitPrice)}
                        </td>
                        <td className="p-1.5 text-right font-bold text-zinc-800 dark:text-zinc-200">
                          {formatPrice(totalAmount)}
                        </td>
                      </tr>
                      <tr>
                        <td
                          colSpan={3}
                          className="p-1.5 text-right border-r border-zinc-200 dark:border-zinc-800 font-bold uppercase text-[8px] text-zinc-400"
                        >
                          Обща стойност:
                        </td>
                        <td className="p-1.5 text-right font-bold text-[10px] text-zinc-900 dark:text-white">
                          {formatPrice(totalAmount)}
                        </td>
                      </tr>
                    </tbody>
                  </table>
                </div>

                {note && (
                  <div className="mb-3 p-2 border border-dashed border-zinc-300 dark:border-zinc-700 bg-zinc-50/50 dark:bg-zinc-900/30 text-[9px] rounded-lg">
                    <span className="font-bold text-zinc-500 uppercase mr-1">
                      Забележка:
                    </span>
                    <span className="italic text-zinc-800 dark:text-zinc-200">
                      {note}
                    </span>
                  </div>
                )}

                <div className="mt-4 flex justify-between gap-12 text-zinc-500">
                  <div className="flex-1">
                    <div className="h-px bg-zinc-300 dark:bg-zinc-800 w-full" />
                    <p className="text-[7px] font-bold mt-0.5 uppercase text-center">
                      Доставчик: {clubInfo.name}
                    </p>
                  </div>
                  <div className="flex-1">
                    <div className="h-px bg-zinc-300 dark:bg-zinc-800 w-full" />
                    <p className="text-[7px] font-bold mt-0.5 uppercase text-center">
                      Получател: {selectedMember.firstName}{" "}
                      {selectedMember.lastName}
                    </p>
                  </div>
                </div>
              </div>
            </div>

            <div className="flex gap-3 justify-center">
              <Button
                onClick={() => {
                  if (completedSaleId) {
                    window.open(`/sales/${completedSaleId}/receipt`, "_blank");
                  }
                }}
                className="rounded-xl bg-zinc-900 text-white hover:bg-zinc-800 h-11 px-6 text-xs font-semibold flex items-center gap-2"
              >
                <Printer className="h-4 w-4" /> Отвори за печат (PDF)
              </Button>
            </div>
          </div>
        )}

        {/* DIALOG FOOTER & NAVIGATION BUTTONS */}
        {step < 4 && (
          <DialogFooter className="px-8 py-6 border-t border-zinc-100 dark:border-zinc-900 flex flex-row justify-between items-center sm:justify-between w-full">
            <div>
              {step > 1 ? (
                <Button
                  variant="outline"
                  onClick={handlePrevStep}
                  disabled={isProcessing}
                  className="rounded-xl px-5 h-11 flex items-center gap-2 text-zinc-500 hover:text-zinc-800"
                >
                  <ArrowLeft className="h-4 w-4" /> Назад
                </Button>
              ) : (
                <Button
                  variant="outline"
                  onClick={onClose}
                  disabled={isProcessing}
                  className="rounded-xl px-5 h-11 text-zinc-500 hover:text-zinc-800"
                >
                  Отказ
                </Button>
              )}
            </div>

            <div>
              {step < 3 ? (
                <Button
                  onClick={handleNextStep}
                  disabled={isProcessing}
                  className="rounded-xl px-6 h-11 bg-zinc-950 hover:bg-zinc-800 text-white flex items-center gap-2 font-medium text-[11px] uppercase tracking-widest"
                >
                  Напред <ArrowRight className="h-3.5 w-3.5" />
                </Button>
              ) : (
                <Button
                  onClick={handleExecuteSale}
                  disabled={isProcessing || !selectedMember}
                  className="rounded-xl px-8 h-11 bg-emerald-500 hover:bg-emerald-600 text-white flex items-center gap-2 font-medium text-[11px] uppercase tracking-widest"
                >
                  Завърши продажбата <Check className="h-4 w-4" />
                </Button>
              )}
            </div>
          </DialogFooter>
        )}

        {step === 5 && (
          <DialogFooter className="px-8 py-6 border-t border-zinc-100 dark:border-zinc-900 flex justify-end">
            <Button
              onClick={handleClose}
              className="rounded-xl px-8 h-11 bg-zinc-950 hover:bg-zinc-800 text-white font-medium text-[11px] uppercase tracking-widest"
            >
              Затвори
            </Button>
          </DialogFooter>
        )}
      </DialogContent>
    </Dialog>
  );
};

"use client";

import { useEffect, useState } from "react";
import { getAllMembers } from "@/services/member-service";
import { Member } from "@/types";
import { useGeneralServices } from "@/hooks/useGeneralServices";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { formatPrice } from "@/lib/currency";
import { useRouter } from "next/navigation";
import { ShoppingBag, MoreVertical, Edit2, Trash2, Loader2, Receipt, Eye } from "lucide-react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { deleteGeneralServiceSaleAction } from "@/lib/actions/general-services-server";
import { Sale } from "@/types";
import { EditSaleDialog } from "./EditSaleDialog";

export function GeneralServiceSalesHistory() {
  const { sales, isLoading, refetch } = useGeneralServices();
  const [membersMap, setMembersMap] = useState<Record<string, string>>({});
  const [membersLoading, setMembersLoading] = useState(true);

  const [saleToEdit, setSaleToEdit] = useState<Sale | null>(null);
  const [isDeleting, setIsDeleting] = useState<string | null>(null);
  const router = useRouter();

  useEffect(() => {
    const fetchMembers = async () => {
      try {
        const fetchedMembers = await getAllMembers();
        const dict: Record<string, string> = {};
        fetchedMembers.forEach((m: Member) => {
          dict[m.id] = `${m.firstName} ${m.lastName}`;
        });
        setMembersMap(dict);
      } catch (err) {
        console.error("Грешка при зареждане на членове", err);
      } finally {
        setMembersLoading(false);
      }
    };

    fetchMembers();
  }, []);

  const getClientName = (memberId: string) => {
    if (memberId === "GUEST_EXTERNAL") {
      return "Външен клиент";
    }
    return membersMap[memberId] || "Неизвестен клиент";
  };

  const handleDeleteSale = async (saleId: string) => {
    if (!confirm("Сигурни ли сте, че искате да изтриете тази продажба?")) return;
    
    setIsDeleting(saleId);
    try {
      const res = await deleteGeneralServiceSaleAction(saleId);
      if (!res.success) throw new Error(res.error);
      
      toast.success("Успех", { description: "Продажбата беше изтрита успешно." });
      if (refetch) refetch();
    } catch (error: any) {
      toast.error("Грешка", { description: error.message || "Грешка при изтриване." });
    } finally {
      setIsDeleting(null);
    }
  };

  const loading = isLoading || membersLoading;

  if (loading) {
    return (
      <div className="p-8 space-y-4">
        {[1, 2, 3, 4, 5].map((i) => (
          <div key={i} className="h-16 rounded-xl bg-zinc-100 dark:bg-zinc-900 animate-pulse" />
        ))}
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full bg-white dark:bg-zinc-950">
      <div className="p-6 md:p-8 border-b border-zinc-100 dark:border-zinc-900">
        <h2 className="text-xl font-light text-zinc-900 dark:text-zinc-50 flex items-center gap-2">
          <ShoppingBag className="h-5 w-5 text-emerald-500" />
          История на продажбите
        </h2>
        <p className="text-xs text-zinc-500 mt-1 font-light">
          Списък с всички продадени клубни услуги и техния статус на плащане.
        </p>
      </div>

      <div className="flex-1 overflow-auto custom-scrollbar">
        {sales.length > 0 ? (
          <Table>
            <TableHeader className="bg-zinc-50/50 dark:bg-zinc-900/50 sticky top-0 backdrop-blur-sm">
              <TableRow className="border-b border-zinc-100 dark:border-zinc-800 hover:bg-transparent">
                <TableHead className="text-[10px] uppercase tracking-widest text-zinc-400 font-semibold py-5">
                  Дата
                </TableHead>
                <TableHead className="text-[10px] uppercase tracking-widest text-zinc-400 font-semibold py-5">
                  Клиент
                </TableHead>
                <TableHead className="text-[10px] uppercase tracking-widest text-zinc-400 font-semibold py-5">
                  Услуга
                </TableHead>
                <TableHead className="text-[10px] uppercase tracking-widest text-zinc-400 font-semibold py-5">
                  Плащане
                </TableHead>
                <TableHead className="text-[10px] uppercase tracking-widest text-zinc-400 font-semibold py-5">
                  Статус
                </TableHead>
                <TableHead className="text-[10px] uppercase tracking-widest text-zinc-400 font-semibold py-5 text-right">
                  Сума
                </TableHead>
                <TableHead className="w-12"></TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {sales.map((sale) => (
                <TableRow
                  key={sale.id}
                  className="border-b border-zinc-50 dark:border-zinc-900 hover:bg-zinc-50 dark:hover:bg-zinc-900/50 transition-colors"
                >
                  <TableCell className="py-4">
                    <span className="font-medium text-sm text-zinc-900 dark:text-zinc-100">
                      {new Date(sale.saleDate).toLocaleDateString("bg-BG")}
                    </span>
                    <div className="text-[10px] text-zinc-400 mt-0.5">
                      {new Date(sale.saleDate).toLocaleTimeString("bg-BG", {
                        hour: "2-digit",
                        minute: "2-digit",
                      })}
                    </div>
                  </TableCell>
                  <TableCell className="py-4">
                    <span className="text-sm font-semibold text-zinc-900 dark:text-zinc-100">
                      {getClientName(sale.memberId)}
                    </span>
                  </TableCell>
                  <TableCell className="py-4">
                    <div className="flex flex-col gap-1">
                      {sale.items && sale.items.length > 0 ? (
                        sale.items.map((item, idx) => (
                          <span key={idx} className="text-sm font-medium text-zinc-700 dark:text-zinc-300">
                            {item.name}{" "}
                            <span className="text-xs text-zinc-400 font-normal">
                              x{item.quantity}
                            </span>
                          </span>
                        ))
                      ) : (
                        <span className="text-zinc-400">-</span>
                      )}
                    </div>
                  </TableCell>
                  <TableCell className="py-4">
                    <span className="text-sm font-light text-zinc-600 dark:text-zinc-400">
                      {sale.paymentMethod === "Cash" ? "В брой" : (sale.paymentMethod || "В брой")}
                    </span>
                  </TableCell>
                  <TableCell className="py-4">
                    <Badge
                      className={`px-2 py-0.5 rounded text-[9px] font-bold uppercase tracking-widest border shadow-none ${
                        sale.isPaid
                          ? "bg-emerald-50 text-emerald-600 border-emerald-100 dark:bg-emerald-950/20 dark:text-emerald-400 dark:border-emerald-900/30"
                          : "bg-amber-50 text-amber-600 border-amber-100 dark:bg-amber-950/20 dark:text-amber-400 dark:border-amber-900/30"
                      }`}
                    >
                      {sale.isPaid ? "Платено" : "Неплатено"}
                    </Badge>
                  </TableCell>
                  <TableCell className="py-4 text-right">
                    <span className="font-semibold text-sm text-zinc-900 dark:text-white">
                      {formatPrice(sale.totalAmount)}
                    </span>
                  </TableCell>
                  <TableCell className="py-4 text-right">
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8 text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-100"
                          disabled={isDeleting === sale.id}
                        >
                          {isDeleting === sale.id ? (
                            <Loader2 className="h-4 w-4 animate-spin" />
                          ) : (
                            <MoreVertical className="h-4 w-4" />
                          )}
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end" className="w-[160px] rounded-xl">
                        <DropdownMenuItem
                          onClick={() => router.push(`/finances/general-services/sales/${sale.id}/receipt`)}
                          className="flex items-center gap-2 text-xs font-medium cursor-pointer"
                        >
                          <Receipt className="h-3.5 w-3.5 text-zinc-500" />
                          Касова бележка
                        </DropdownMenuItem>
                        <DropdownMenuItem
                          onClick={() => router.push(`/finances/general-services/sales/${sale.id}`)}
                          className="flex items-center gap-2 text-xs font-medium cursor-pointer"
                        >
                          <Eye className="h-3.5 w-3.5 text-zinc-500" />
                          Детайли
                        </DropdownMenuItem>
                        <DropdownMenuItem
                          onClick={() => setSaleToEdit(sale)}
                          className="flex items-center gap-2 text-xs font-medium cursor-pointer"
                        >
                          <Edit2 className="h-3.5 w-3.5 text-zinc-500" />
                          Редактирай
                        </DropdownMenuItem>
                        <DropdownMenuItem
                          onClick={() => handleDeleteSale(sale.id)}
                          className="flex items-center gap-2 text-xs font-medium text-rose-600 focus:bg-rose-50 dark:focus:bg-rose-950/30 focus:text-rose-600 cursor-pointer"
                        >
                          <Trash2 className="h-3.5 w-3.5" />
                          Изтрий
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        ) : (
          <div className="py-32 flex flex-col items-center justify-center text-center">
            <ShoppingBag className="h-12 w-12 text-zinc-200 dark:text-zinc-800 mb-4" strokeWidth={1} />
            <p className="text-zinc-500 text-sm font-light">Няма регистрирани продажби на услуги.</p>
          </div>
        )}
      </div>

      {saleToEdit && (
        <EditSaleDialog
          sale={saleToEdit}
          isOpen={!!saleToEdit}
          onClose={() => setSaleToEdit(null)}
          onSuccess={() => {
            if (refetch) refetch();
            setSaleToEdit(null);
          }}
        />
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { format } from "date-fns";
import { bg } from "date-fns/locale";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { useRecoveryServices } from "@/hooks/useRecoveryServices";
import {
  PackageSearch,
  CheckCircle2,
  XCircle,
  MoreVertical,
  Trash2,
  Loader2,
  Plus,
} from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { useAuth } from "@/context/auth-context";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { deleteRecoveryPackageAction } from "@/lib/actions/recovery-services-server";

export function RecoveryClientPackages() {
  const { clientPackages, isLoading, refetch } = useRecoveryServices();
  const [isProcessing, setIsProcessing] = useState<string | null>(null);
  const { idToken } = useAuth();

  if (isLoading) {
    return (
      <div className="p-8 space-y-4">
        {[1, 2, 3].map((i) => (
          <div
            key={i}
            className="h-16 rounded-xl bg-zinc-100 dark:bg-zinc-900 animate-pulse"
          />
        ))}
      </div>
    );
  }

  const handleDelete = async (id: string) => {
    if (!idToken) return;
    if (!confirm("Сигурни ли сте, че искате да изтриете този пакет?")) return;

    setIsProcessing(id);
    try {
      const res = await deleteRecoveryPackageAction(idToken, id);
      if (!res.success) throw new Error(res.error);
      toast.success("Изтрит", { description: "Пакетът беше изтрит успешно." });
      if (refetch) refetch();
    } catch (error: any) {
      toast.error("Грешка", { description: error.message });
    } finally {
      setIsProcessing(null);
    }
  };

  return (
    <div className="flex flex-col h-full bg-white dark:bg-zinc-950">
      <div className="p-6 md:p-8 border-b border-zinc-100 dark:border-zinc-900 flex justify-between items-center">
        <div>
          <h2 className="text-xl font-light text-zinc-900 dark:text-zinc-50 flex items-center gap-2">
            <PackageSearch className="h-5 w-5 text-indigo-500" />
            Закупени Пакети
          </h2>
          <p className="text-xs text-zinc-500 mt-1 font-light">
            Проследяване на пакетите и оставащите сесии на клиентите.
          </p>
        </div>
        <Button
          onClick={() =>
            toast.info("Предстои добавяне", {
              description: "Функцията за ръчно добавяне се разработва.",
            })
          }
          className="bg-zinc-900 text-white hover:bg-zinc-800 rounded-full h-10 px-4 text-sm font-medium transition-all shadow-sm"
        >
          <Plus className="w-4 h-4 mr-2" />
          Добави Пакет
        </Button>
      </div>

      <div className="flex-1 overflow-auto custom-scrollbar">
        {clientPackages.length > 0 ? (
          <Table>
            <TableHeader className="bg-zinc-50/50 dark:bg-zinc-900/50 sticky top-0 backdrop-blur-sm">
              <TableRow className="border-b border-zinc-100 dark:border-zinc-800 hover:bg-transparent">
                <TableHead className="text-[10px] uppercase tracking-widest text-zinc-400 font-semibold py-5">
                  Клиент
                </TableHead>
                <TableHead className="text-[10px] uppercase tracking-widest text-zinc-400 font-semibold py-5">
                  Пакет
                </TableHead>
                <TableHead className="text-[10px] uppercase tracking-widest text-zinc-400 font-semibold py-5 text-center">
                  Оставащи
                </TableHead>
                <TableHead className="text-[10px] uppercase tracking-widest text-zinc-400 font-semibold py-5 text-right">
                  Статус
                </TableHead>
                <TableHead className="w-12"></TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {clientPackages.map((pkg) => (
                <TableRow
                  key={pkg.id}
                  className="border-b border-zinc-50 dark:border-zinc-900 hover:bg-zinc-50 dark:hover:bg-zinc-900/50 transition-colors"
                >
                  <TableCell className="py-4">
                    <div className="flex flex-col">
                      <span className="text-sm font-semibold text-zinc-900 dark:text-zinc-100">
                        {pkg.clientName}
                        {pkg.client2Name ? ` & ${pkg.client2Name}` : ""}
                      </span>
                      {pkg.clientPhone && (
                        <span className="text-xs text-zinc-400">
                          {pkg.clientPhone}
                        </span>
                      )}
                    </div>
                  </TableCell>
                  <TableCell className="py-4">
                    <div className="flex flex-col">
                      <span className="text-sm text-zinc-600 dark:text-zinc-400 font-medium">
                        {pkg.packageName || "Пакет"}
                      </span>
                      {pkg.purchaseDate && (
                        <span className="text-xs text-zinc-400 mt-1">
                          Закупен:{" "}
                          {format(new Date(pkg.purchaseDate), "dd MMM yyyy", {
                            locale: bg,
                          })}
                        </span>
                      )}
                    </div>
                  </TableCell>
                  <TableCell className="py-4 text-center">
                    <div className="flex items-center justify-center gap-1.5">
                      <span className="text-lg font-semibold text-zinc-900 dark:text-zinc-100">
                        {pkg.sessionsRemaining}
                      </span>
                      <span className="text-xs text-zinc-400 font-light mt-1">
                        / {pkg.sessionsTotal}
                      </span>
                    </div>
                  </TableCell>
                  <TableCell className="py-4 text-right">
                    {pkg.status === "active" && pkg.sessionsRemaining > 0 ? (
                      <Badge
                        variant="outline"
                        className="bg-emerald-50 text-emerald-600 border-emerald-100 dark:bg-emerald-500/10 dark:text-emerald-500 dark:border-emerald-500/20"
                      >
                        <CheckCircle2 className="w-3 h-3 mr-1" />
                        Активен
                      </Badge>
                    ) : (
                      <Badge
                        variant="outline"
                        className="bg-rose-50 text-rose-600 border-rose-100 dark:bg-rose-500/10 dark:text-rose-500 dark:border-rose-500/20"
                      >
                        <XCircle className="w-3 h-3 mr-1" />
                        Изчерпан
                      </Badge>
                    )}
                  </TableCell>
                  <TableCell className="py-4 text-right pr-6">
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8 text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-100"
                          disabled={isProcessing === pkg.id}
                        >
                          {isProcessing === pkg.id ? (
                            <Loader2 className="h-4 w-4 animate-spin" />
                          ) : (
                            <MoreVertical className="h-4 w-4" />
                          )}
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent
                        align="end"
                        className="w-[160px] rounded-xl"
                      >
                        <DropdownMenuItem
                          onClick={() => handleDelete(pkg.id)}
                          className="flex items-center gap-2 text-xs font-medium text-rose-600 focus:bg-rose-50 dark:focus:bg-rose-950/30 focus:text-rose-600 cursor-pointer"
                        >
                          <Trash2 className="h-3.5 w-3.5" />
                          Изтрий
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        ) : (
          <div className="py-32 flex flex-col items-center justify-center text-center">
            <PackageSearch
              className="h-12 w-12 text-zinc-200 dark:text-zinc-800 mb-4"
              strokeWidth={1}
            />
            <p className="text-zinc-500 text-sm font-light">
              Няма намерени пакети.
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";
import React from "react";

import Image from "next/image";
import { ClubService } from "@/types";
import { BentoCard } from "@/components/ui/bento-card";
import { Button } from "@/components/ui/button";
import { formatPrice } from "@/lib/currency";
import {
  Activity,
  Calendar,
  MoreHorizontal,
  Edit,
  Trash2,
  Clock,
  Users,
  ChevronLeft,
  ChevronRight,
} from "lucide-react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { useRouter } from "next/navigation";
import { useAuth } from "@/context/auth-context";
import { deleteRecoverySession } from "@/lib/actions/services";
import { toast } from "sonner";

interface RecoveryMenuProps {
  services: ClubService[];
  onSale?: (service: ClubService) => void;
}

export function RecoveryMenu({ services, onSale }: RecoveryMenuProps) {
  const router = useRouter();
  const { idToken } = useAuth();

  const grouped = services.reduce(
    (acc, s) => {
      const cat = s.category || "Други";
      if (!acc[cat]) acc[cat] = [];
      acc[cat].push(s);
      return acc;
    },
    {} as Record<string, ClubService[]>
  );

  const handleDelete = async (id: string, name: string) => {
    if (!idToken) return;
    if (confirm(`Сигурни ли сте, че искате да изтриете "${name}"?`)) {
      const result = await deleteRecoverySession(idToken, id);
      if (result.success) {
        toast.success(result.message);
      } else {
        toast.error(result.message);
      }
    }
  };

  return (
    <div className="space-y-16">
      {Object.entries(grouped).map(([category, catServices]) => (
        <section key={category} className="space-y-8">
          <div className="flex items-center gap-4">
            <div className="h-px flex-1 bg-zinc-100" />
            <h3 className="text-xs uppercase tracking-[0.3em] font-medium text-zinc-400">
              {category}
            </h3>
            <div className="h-px flex-1 bg-zinc-100" />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {catServices.map((service) => (
              <RecoveryCard
                key={service.id}
                service={service}
                onEdit={() => router.push(`/finances/recovery/${service.id}`)}
                onSale={() => onSale?.(service)}
                onDelete={() => handleDelete(service.id, service.name)}
              />
            ))}
          </div>
        </section>
      ))}

      {services.length === 0 && (
        <div className="flex flex-col items-center justify-center py-24 text-zinc-400 border-2 border-dashed border-zinc-100 rounded-5xl">
          <p className="font-light">
            Все още няма добавени процедури в каталога.
          </p>
        </div>
      )}
    </div>
  );
}

const RecoveryCard = ({
  service,
  onEdit,
  onSale,
  onDelete,
}: {
  service: ClubService;
  onEdit: () => void;
  onSale: () => void;
  onDelete: () => void;
}) => {
  const images = (service as any).imageUrl
    ? (service as any).imageUrl.split(",").filter(Boolean)
    : [];

  const displayMode = (service as any).imageDisplayMode || "collage";
  const [activeImgIndex, setActiveImgIndex] = React.useState(0);

  // Auto-rotate for carousel
  React.useEffect(() => {
    if (displayMode !== "carousel" || images.length <= 1) return;
    const interval = setInterval(() => {
      setActiveImgIndex((prev) => (prev + 1) % images.length);
    }, 4000);
    return () => clearInterval(interval);
  }, [displayMode, images.length]);

  const nextImg = (e: React.MouseEvent) => {
    e.stopPropagation();
    setActiveImgIndex((prev) => (prev + 1) % images.length);
  };

  const prevImg = (e: React.MouseEvent) => {
    e.stopPropagation();
    setActiveImgIndex((prev) => (prev - 1 + images.length) % images.length);
  };

  const renderImages = () => {
    if (images.length === 0) {
      return (
        <div className="w-full h-full flex flex-col items-center justify-center text-zinc-300 dark:text-zinc-800 bg-zinc-50 dark:bg-zinc-900">
          <Activity
            className="h-12 w-12 opacity-30 text-cyan-500"
            strokeWidth={1}
          />
          <span className="text-[9px] font-semibold uppercase tracking-[0.2em] opacity-40 mt-2">
            ПРОЦЕДУРА
          </span>
        </div>
      );
    }
    if (displayMode === "collage") {
      return (
        <div className="flex w-full h-full">
          {images.map((imgUrl: string, idx: number) => (
            <div
              key={imgUrl}
              className="h-full relative overflow-hidden"
              style={{ width: `${100 / images.length}%` }}
            >
              <Image
                src={imgUrl}
                alt={`${service.name} - ${idx + 1}`}
                fill
                sizes="(max-w-768px) 100vw, 33vw"
                className="object-cover transition-transform duration-700 hover:scale-110"
              />
              {idx > 0 && (
                <div className="absolute left-0 top-0 bottom-0 w-px bg-white/30 z-10" />
              )}
            </div>
          ))}
        </div>
      );
    }
    return (
      <>
        <Image
          src={images[activeImgIndex]}
          alt={`${service.name} - ${activeImgIndex + 1}`}
          fill
          sizes="(max-w-768px) 100vw, 33vw"
          className="object-cover transition-transform duration-700"
        />
        {images.length > 1 && (
          <>
            <button
              onClick={prevImg}
              className="absolute left-2 top-1/2 -translate-y-1/2 h-6 w-6 rounded-full bg-white/60 backdrop-blur-sm shadow-xs border border-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity hover:bg-white text-zinc-700"
            >
              <ChevronLeft size={14} />
            </button>
            <button
              onClick={nextImg}
              className="absolute right-2 top-1/2 -translate-y-1/2 h-6 w-6 rounded-full bg-white/60 backdrop-blur-sm shadow-xs border border-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity hover:bg-white text-zinc-700"
            >
              <ChevronRight size={14} />
            </button>
            <div className="absolute bottom-2 left-1/2 -translate-x-1/2 flex gap-1.5 z-10">
              {images.map((_: any, i: number) => (
                <div
                  key={i}
                  className={`h-1.5 rounded-full transition-all duration-300 ${
                    activeImgIndex === i
                      ? "bg-white w-4"
                      : "bg-white/50 w-1.5"
                  }`}
                />
              ))}
            </div>
          </>
        )}
      </>
    );
  };

  return (
    <BentoCard className="group relative overflow-hidden bg-white border border-zinc-100 shadow-none hover:border-zinc-300 hover:shadow-xl hover:shadow-zinc-100/20 transition-all duration-500 rounded-5xl flex flex-col h-full">
      {/* Cover Image Header with Horizontal Scroll */}
      <div className="relative h-48 bg-zinc-50 dark:bg-zinc-900 border-b border-zinc-50 dark:border-zinc-800 overflow-hidden">
        {renderImages()}

        {/* Dropdown Menu on Image Hover */}
        <div className="absolute top-4 right-4 z-10 flex gap-2">
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button
                variant="ghost"
                size="icon"
                className="h-8 w-8 rounded-full bg-white/90 dark:bg-zinc-900/90 backdrop-blur-md border border-zinc-100/50 dark:border-zinc-850 hover:bg-white"
              >
                <MoreHorizontal className="h-4 w-4 text-zinc-500" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent
              align="end"
              className="rounded-2xl border-zinc-100 p-2 min-w-[160px]"
            >
              <DropdownMenuItem
                onClick={onEdit}
                className="rounded-xl gap-2 focus:bg-zinc-50 py-3"
              >
                <Edit className="h-4 w-4 text-zinc-400" /> Редактиране
              </DropdownMenuItem>
              <DropdownMenuItem
                onClick={onDelete}
                className="rounded-xl gap-2 focus:bg-red-50 text-red-650 py-3"
              >
                <Trash2 className="h-4 w-4" /> Изтриване
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>

        {/* Status badge in bottom corner */}
        <div className="absolute bottom-4 left-4 z-10">
          {(() => {
            const res = service.requiredResources;
            const zones = (service.zones || []).map((z) => z.toUpperCase());

            const hasCompressor = (res?.compressors || 0) > 0;
            const hasMatchingAttachment =
              res &&
              ((zones.includes("КРАКА") && (res.attachments?.legs || 0) > 0) ||
                (zones.includes("РЪЦЕ") && (res.attachments?.arms || 0) > 0) ||
                (zones.includes("ТАЗ") && (res.attachments?.hips || 0) > 0));

            const isUpdated = hasCompressor && hasMatchingAttachment;

            if (!isUpdated) {
              return (
                <div className="px-3 py-1.5 rounded-lg text-[9px] font-bold uppercase tracking-widest border backdrop-blur-md bg-amber-50/90 border-amber-200 text-amber-700 flex items-center gap-1.5">
                  <span className="w-1.5 h-1.5 rounded-full bg-amber-400 animate-pulse" />
                  Поддръжка
                </div>
              );
            }
            return (
              <div className="px-3 py-1.5 rounded-lg text-[9px] font-bold uppercase tracking-widest border backdrop-blur-md bg-emerald-50/90 border-emerald-200 text-emerald-700 flex items-center gap-1.5">
                <span className="w-1.5 h-1.5 rounded-full bg-emerald-400" />
                Готова
              </div>
            );
          })()}
        </div>
      </div>

      {/* Content Area */}
      <div className="p-8 flex-1 flex flex-col justify-between">
        <div className="space-y-4">
          <div className="flex flex-wrap gap-2 mb-1">
            {service.category && (
              <span className="text-[9px] font-black uppercase tracking-widest text-zinc-400 bg-zinc-50 px-2 py-0.5 rounded-md">
                {service.category}
              </span>
            )}
            {service.sessionType && (
              <span className="text-[9px] font-black uppercase tracking-widest text-cyan-500 bg-cyan-50 px-2 py-0.5 rounded-md">
                {service.sessionType}
              </span>
            )}
          </div>
          <h4 className="text-xl font-medium tracking-tight text-zinc-900 group-hover:text-cyan-600 transition-colors line-clamp-1">
            {service.name}
          </h4>
          <p className="text-sm text-zinc-400 font-light leading-relaxed line-clamp-3 min-h-16">
            {service.description}
          </p>

          {/* Zones */}
          <div className="flex flex-wrap gap-2 pt-2">
            {Array.from(
              new Set(Array.isArray(service.zones) ? service.zones : [])
            ).map((zone) => (
              <span
                key={zone}
                className="px-3 py-1 bg-cyan-50 border border-cyan-100 rounded-full text-[10px] uppercase tracking-wider text-cyan-600 font-medium"
              >
                {zone}
              </span>
            ))}
          </div>

          {/* Features */}
          <div className="space-y-3 pt-4 border-t border-zinc-50">
            <div className="flex items-center gap-3 text-xs text-zinc-500">
              <Clock className="h-4 w-4 text-zinc-300" strokeWidth={1.5} />
              <span>
                {service.durationMinutes === 45 &&
                service.category === "VIP СЕСИИ" ? (
                  <span className="font-medium text-cyan-600">
                    15 минути + 30 минути
                  </span>
                ) : (
                  `${service.durationMinutes} минути`
                )}
              </span>
            </div>
            <div className="flex items-center gap-3 text-xs text-zinc-500">
              <Users className="h-4 w-4 text-zinc-300" strokeWidth={1.5} />
              <span>{service.athleteCount} спортисти</span>
            </div>
            {(service.numberOfDays || 0) > 1 && (
              <div className="flex items-center gap-3 text-xs text-zinc-500">
                <Calendar className="h-4 w-4 text-zinc-300" strokeWidth={1.5} />
                <span>
                  {service.numberOfDays} дни / {service.proceduresPerDay}{" "}
                  процедури на ден
                </span>
              </div>
            )}

            {service.requiredResources && (
              <div className="pt-2 mt-2 space-y-1">
                <p className="text-[9px] text-zinc-400 uppercase tracking-widest font-medium mb-1">
                  Ресурси
                </p>
                <div className="flex flex-wrap gap-x-3 gap-y-1">
                  {(service.requiredResources.compressors ?? 0) > 0 && (
                    <div className="flex items-center gap-1 text-[10px] text-zinc-500">
                      <span className="w-1 h-1 rounded-full bg-emerald-400" />
                      {service.requiredResources.compressors} компресора
                    </div>
                  )}
                  {(service.requiredResources.attachments?.arms ?? 0) > 0 && (
                    <div className="flex items-center gap-1 text-[10px] text-zinc-500">
                      <span className="w-1 h-1 rounded-full bg-blue-400" />
                      {service.requiredResources.attachments?.arms} РЪЦЕ
                    </div>
                  )}
                  {(service.requiredResources.attachments?.legs ?? 0) > 0 && (
                    <div className="flex items-center gap-1 text-[10px] text-zinc-500">
                      <span className="w-1 h-1 rounded-full bg-cyan-400" />
                      {service.requiredResources.attachments?.legs} КРАКА
                    </div>
                  )}
                  {(service.requiredResources.attachments?.hips ?? 0) > 0 && (
                    <div className="flex items-center gap-1 text-[10px] text-zinc-500">
                      <span className="w-1 h-1 rounded-full bg-purple-400" />
                      {service.requiredResources.attachments?.hips} ТАЗ
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>
        </div>

        <div>
          {/* Price */}
          <div className="flex items-baseline gap-1 pt-6 border-t border-zinc-50 mb-6 mt-6">
            <span className="text-3xl font-light tracking-tighter text-zinc-950">
              {formatPrice(service.price).replace(" EUR", "")}
            </span>
            <span className="text-sm font-medium text-zinc-400 uppercase tracking-widest ml-1">
              EUR
            </span>
          </div>

          {/* Actions */}
          <div className="grid grid-cols-2 gap-3 w-full">
            <Button
              variant="outline"
              size="sm"
              onClick={onSale}
              className="w-full h-11 rounded-xl font-medium text-[10px] uppercase tracking-widest border-zinc-200 text-zinc-700 hover:bg-zinc-50 dark:border-zinc-800 dark:text-zinc-300 dark:hover:bg-zinc-900 transition-all shadow-none"
            >
              Продажба
            </Button>
            <Button
              variant="default"
              size="sm"
              onClick={onEdit}
              className="w-full h-11 rounded-xl font-medium text-[10px] uppercase tracking-widest bg-zinc-950 text-white hover:bg-zinc-800 transition-all shadow-none border-none"
            >
              Редактиране
            </Button>
          </div>
        </div>
      </div>
    </BentoCard>
  );
};

"use client";

import { useState } from "react";
import { format } from "date-fns";
import { bg } from "date-fns/locale";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { formatPrice } from "@/lib/currency";
import { useRecoveryServices } from "@/hooks/useRecoveryServices";
import {
  CalendarDays,
  CheckCircle2,
  XCircle,
  MoreVertical,
  Trash2,
  Loader2,
  DollarSign,
} from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { useAuth } from "@/context/auth-context";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import {
  deleteReservationAction,
  markReservationAsPaidAction,
} from "@/lib/actions/reservations";

export function RecoveryReservationsHistory() {
  const { reservations, isLoading, refetch } = useRecoveryServices();
  const [isProcessing, setIsProcessing] = useState<string | null>(null);
  const { idToken } = useAuth();

  if (isLoading) {
    return (
      <div className="p-8 space-y-4">
        {[1, 2, 3, 4, 5].map((i) => (
          <div
            key={i}
            className="h-16 rounded-xl bg-zinc-100 dark:bg-zinc-900 animate-pulse"
          />
        ))}
      </div>
    );
  }

  const handleDelete = async (id: string) => {
    if (!idToken) return;
    if (!confirm("Сигурни ли сте, че искате да изтриете тази резервация?"))
      return;

    setIsProcessing(id);
    try {
      const res = await deleteReservationAction(idToken, id);
      if (!res.success) throw new Error(res.message);
      toast.success("Изтрита", {
        description: "Резервацията беше изтрита успешно.",
      });
      if (refetch) refetch();
    } catch (error: any) {
      toast.error("Грешка", { description: error.message });
    } finally {
      setIsProcessing(null);
    }
  };

  const handleMarkAsPaid = async (id: string) => {
    if (!idToken) return;
    if (!confirm("Маркиране на тази резервация като платена?")) return;

    setIsProcessing(id);
    try {
      const res = await markReservationAsPaidAction(idToken, id);
      if (!res.success) throw new Error(res.message);
      toast.success("Платена", {
        description: "Резервацията е маркирана като платена.",
      });
      if (refetch) refetch();
    } catch (error: any) {
      toast.error("Грешка", { description: error.message });
    } finally {
      setIsProcessing(null);
    }
  };

  return (
    <div className="flex flex-col h-full bg-white dark:bg-zinc-950">
      <div className="p-6 md:p-8 border-b border-zinc-100 dark:border-zinc-900 flex justify-between items-center">
        <div>
          <h2 className="text-xl font-light text-zinc-900 dark:text-zinc-50 flex items-center gap-2">
            <CalendarDays className="h-5 w-5 text-indigo-500" />
            История на резервациите
          </h2>
          <p className="text-xs text-zinc-500 mt-1 font-light">
            Проследяване на запазените часове от клиенти.
          </p>
        </div>
      </div>

      <div className="flex-1 overflow-auto custom-scrollbar">
        {reservations.length > 0 ? (
          <Table>
            <TableHeader className="bg-zinc-50/50 dark:bg-zinc-900/50 sticky top-0 backdrop-blur-sm">
              <TableRow className="border-b border-zinc-100 dark:border-zinc-800 hover:bg-transparent">
                <TableHead className="text-[10px] uppercase tracking-widest text-zinc-400 font-semibold py-5">
                  Дата и Час
                </TableHead>
                <TableHead className="text-[10px] uppercase tracking-widest text-zinc-400 font-semibold py-5">
                  Клиент
                </TableHead>
                <TableHead className="text-[10px] uppercase tracking-widest text-zinc-400 font-semibold py-5">
                  Процедура
                </TableHead>
                <TableHead className="text-[10px] uppercase tracking-widest text-zinc-400 font-semibold py-5">
                  Сума
                </TableHead>
                <TableHead className="text-[10px] uppercase tracking-widest text-zinc-400 font-semibold py-5 text-right">
                  Статус
                </TableHead>
                <TableHead className="w-12"></TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {reservations.map((res) => (
                <TableRow
                  key={res.id}
                  className="border-b border-zinc-50 dark:border-zinc-900 hover:bg-zinc-50 dark:hover:bg-zinc-900/50 transition-colors"
                >
                  <TableCell className="py-4">
                    <div className="flex flex-col">
                      <span className="font-medium text-sm text-zinc-900 dark:text-zinc-100">
                        {format(new Date(res.startTime), "dd MMM yyyy", {
                          locale: bg,
                        })}
                      </span>
                      <span className="text-xs text-zinc-400">
                        {format(new Date(res.startTime), "HH:mm")} -{" "}
                        {format(new Date(res.endTime), "HH:mm")}
                      </span>
                    </div>
                  </TableCell>
                  <TableCell className="py-4">
                    <div className="flex flex-col">
                      <span className="font-semibold text-sm text-zinc-900 dark:text-zinc-100">
                        {res.clientName}
                        {res.client2Name ? ` & ${res.client2Name}` : ""}
                      </span>
                      <span className="text-xs text-zinc-400">
                        {res.clientPhone || "Няма телефон"}
                      </span>
                    </div>
                  </TableCell>
                  <TableCell className="py-4">
                    <span className="text-sm text-zinc-600 dark:text-zinc-400">
                      {res.sessionName || "Процедура"}
                    </span>
                  </TableCell>
                  <TableCell className="py-4">
                    <span className="text-sm font-medium text-zinc-900 dark:text-zinc-100">
                      {formatPrice(res.totalPrice ?? res.price ?? 0)}
                    </span>
                  </TableCell>
                  <TableCell className="py-4 text-right">
                    {res.status === "paid" ? (
                      <Badge
                        variant="outline"
                        className="bg-emerald-50 text-emerald-600 border-emerald-100 dark:bg-emerald-500/10 dark:text-emerald-500 dark:border-emerald-500/20"
                      >
                        <CheckCircle2 className="w-3 h-3 mr-1" />
                        Платена
                      </Badge>
                    ) : (
                      <Badge
                        variant="outline"
                        className="bg-rose-50 text-rose-600 border-rose-100 dark:bg-rose-500/10 dark:text-rose-500 dark:border-rose-500/20"
                      >
                        <XCircle className="w-3 h-3 mr-1" />
                        Неплатена
                      </Badge>
                    )}
                  </TableCell>
                  <TableCell className="py-4 text-right pr-6">
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8 text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-100"
                          disabled={isProcessing === res.id}
                        >
                          {isProcessing === res.id ? (
                            <Loader2 className="h-4 w-4 animate-spin" />
                          ) : (
                            <MoreVertical className="h-4 w-4" />
                          )}
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent
                        align="end"
                        className="w-[160px] rounded-xl"
                      >
                        {res.status !== "paid" && (
                          <DropdownMenuItem
                            onClick={() => handleMarkAsPaid(res.id)}
                            className="flex items-center gap-2 text-xs font-medium cursor-pointer"
                          >
                            <DollarSign className="h-3.5 w-3.5 text-emerald-500" />
                            Маркирай платена
                          </DropdownMenuItem>
                        )}
                        <DropdownMenuItem
                          onClick={() => handleDelete(res.id)}
                          className="flex items-center gap-2 text-xs font-medium text-rose-600 focus:bg-rose-50 dark:focus:bg-rose-950/30 focus:text-rose-600 cursor-pointer"
                        >
                          <Trash2 className="h-3.5 w-3.5" />
                          Изтрий
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        ) : (
          <div className="py-32 flex flex-col items-center justify-center text-center">
            <CalendarDays
              className="h-12 w-12 text-zinc-200 dark:text-zinc-800 mb-4"
              strokeWidth={1}
            />
            <p className="text-zinc-500 text-sm font-light">
              Няма намерени резервации.
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, useMemo } from "react";
import { mutate } from "swr";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import { ClubService as Service } from "@/types";
import { Member, ScheduleEvent, Attendee } from "@/types";
import { getAllMembers } from "@/services/member-service";
import { getEventsByMemberId } from "@/services/schedule-service";
import { executeTrainingSaleAction } from "@/lib/actions/services";
import { createMemberAction } from "@/lib/actions/members";
import { useAuth } from "@/context/auth-context";
import { formatPrice } from "@/lib/currency";
import { clubInfo } from "@/config/club";
import { useAppStore } from "@/store/use-app-store";
import { format, getYear } from "date-fns";
import { bg } from "date-fns/locale";
import {
  ShoppingBag,
  Search,
  User,
  Check,
  CreditCard,
  Receipt,
  Loader2,
  ArrowLeft,
  ArrowRight,
  Printer,
  Sparkles,
  Calendar,
  CheckSquare,
  CalendarDays,
  AlertCircle,
  PlusCircle,
  Banknote,
  Smartphone,
} from "lucide-react";
import { cn } from "@/lib/utils";

interface RecoverySaleWizardDialogProps {
  service: Service;
  isOpen: boolean;
  onClose: () => void;
  onSaleSuccess: () => void;
}

type PaymentMode = "subscription" | "individual";

interface MemberAttendanceStats {
  memberId: string;
  firstName: string;
  paidCount: number;
  unpaidCount: number;
}

interface MonthAttendance {
  monthKey: string; // yyyy-MM
  monthLabel: string; // e.g. "Януари 2026"
  year: number;
  events: ScheduleEvent[];
  unpaidCount: number;
  paidCount: number;
  memberStats: Record<string, MemberAttendanceStats>;
}

export const RecoverySaleWizardDialog = ({
  service,
  isOpen,
  onClose,
  onSaleSuccess,
}: RecoverySaleWizardDialogProps) => {
  const [step, setStep] = useState(1);
  const [members, setMembers] = useState<Member[]>([]);
  const [membersLoading, setMembersLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedMember, setSelectedMember] = useState<Member | null>(null);
  const [isGuestSale, setIsGuestSale] = useState(false);

  const [clientTypeTab, setClientTypeTab] = useState<"member" | "guest">(
    "member"
  );
  const [showNewGuestForm, setShowNewGuestForm] = useState(false);
  const [newGuestFirstName, setNewGuestFirstName] = useState("");
  const [newGuestLastName, setNewGuestLastName] = useState("");
  const [newGuestPhone, setNewGuestPhone] = useState("");
  const [newGuestEmail, setNewGuestEmail] = useState("");
  const [isSavingNewGuest, setIsSavingNewGuest] = useState(false);

  // Attendance state
  const [attendanceLoading, setAttendanceLoading] = useState(false);
  const [memberEvents, setMemberEvents] = useState<ScheduleEvent[]>([]);

  // Billing config
  const [paymentMode, setPaymentMode] = useState<PaymentMode>("subscription");
  const [selectedMonthKeys, setSelectedMonthKeys] = useState<string[]>([]);
  const [selectedEventIds, setSelectedEventIds] = useState<string[]>([]);

  // Payment details
  const [price, setPrice] = useState(service.price.toString());
  const [paymentMethod, setPaymentMethod] = useState("В брой");
  const [isPaid, setIsPaid] = useState(true);
  const [note, setNote] = useState("");

  const [isProcessing, setIsProcessing] = useState(false);
  const [completedSaleId, setCompletedSaleId] = useState<string | null>(null);

  const { idToken } = useAuth();
  const { activeBranch } = useAppStore();

  // Determine payment mode from service type
  const isSubscriptionService = service.type === "Абонамент";

  // Load members
  useEffect(() => {
    if (isOpen) {
      const fetchMembers = async () => {
        setMembersLoading(true);
        try {
          const fetchedMembers = await getAllMembers();
          setMembers(fetchedMembers);
        } catch (err) {
          console.error("Error loading members:", err);
          toast.error("Грешка", {
            description: "Неуспешно зареждане на клубните членове.",
          });
        } finally {
          setMembersLoading(false);
        }
      };
      fetchMembers();

      // Reset state on open
      setStep(1);
      setPrice(service.price.toString());
      setSelectedMember(null);
      setIsGuestSale(false);
      setCompletedSaleId(null);
      setNote("");
      setSelectedMonthKeys([]);
      setSelectedEventIds([]);
      setMemberEvents([]);
      setPaymentMode(isSubscriptionService ? "subscription" : "individual");
      setSearchTerm("");
      setClientTypeTab("member");
      setShowNewGuestForm(false);
      setNewGuestFirstName("");
      setNewGuestLastName("");
      setNewGuestPhone("");
      setNewGuestEmail("");
      setIsSavingNewGuest(false);
    }
  }, [isOpen, service, isSubscriptionService]);

  const isFamilySubscription = useMemo(() => {
    return (
      isSubscriptionService && service.name.toLowerCase().includes("семеен")
    );
  }, [isSubscriptionService, service.name]);

  const familyMembers = useMemo(() => {
    if (!selectedMember || !isFamilySubscription) return [selectedMember];
    if (selectedMember.familyId) {
      return members.filter((m) => m.familyId === selectedMember.familyId);
    }
    return [selectedMember];
  }, [selectedMember, isFamilySubscription, members]);

  const targetMemberIds = useMemo(() => {
    return familyMembers.map((m) => m?.id).filter(Boolean) as string[];
  }, [familyMembers]);

  const clientDisplayName = useMemo(() => {
    if (isGuestSale) return "Външен клиент";
    if (isFamilySubscription && familyMembers.length > 0) {
      return familyMembers
        .map((m) => `${m?.firstName} ${m?.lastName}`)
        .join(", ");
    }
    return `${selectedMember?.firstName} ${selectedMember?.lastName}`;
  }, [isGuestSale, isFamilySubscription, familyMembers, selectedMember]);

  // Load attendance when member is selected and we move to step 2
  useEffect(() => {
    if (selectedMember && !isGuestSale && step === 2) {
      const fetchAttendance = async () => {
        setAttendanceLoading(true);
        try {
          const fetchPromises = targetMemberIds.map((id) =>
            getEventsByMemberId(id)
          );
          const results = await Promise.all(fetchPromises);
          const events = results.flat();

          // Filter to attended-only events for this training type
          const attended = events.filter((e) => {
            const rec = e.attendees?.find((a: Attendee) =>
              targetMemberIds.includes(a.memberId)
            );
            return rec?.attended === true;
          });

          // Deduplicate events by id
          const uniqueEventsMap = new Map();
          attended.forEach((e) => uniqueEventsMap.set(e.id, e));
          setMemberEvents(Array.from(uniqueEventsMap.values()));
        } catch (err) {
          console.error("Error loading member attendance:", err);
          toast.error("Грешка", {
            description: "Неуспешно зареждане на присъствията.",
          });
        } finally {
          setAttendanceLoading(false);
        }
      };
      fetchAttendance();
    }
  }, [selectedMember, isGuestSale, step, targetMemberIds]);

  // Group events by calendar month
  const monthlyAttendance = useMemo((): MonthAttendance[] => {
    const groupedMap = new Map<string, MonthAttendance>();

    for (const event of memberEvents) {
      const d = new Date(event.startDate);
      const monthKey = format(d, "yyyy-MM");
      const monthLabel =
        format(d, "LLLL", { locale: bg }).charAt(0).toUpperCase() +
        format(d, "LLLL", { locale: bg }).slice(1) +
        " " +
        getYear(d);

      // Find all target members in this event
      const targetAttendees =
        event.attendees?.filter((a: Attendee) =>
          targetMemberIds.includes(a.memberId)
        ) || [];

      if (!groupedMap.has(monthKey)) {
        groupedMap.set(monthKey, {
          monthKey,
          monthLabel,
          year: getYear(d),
          events: [],
          unpaidCount: 0,
          paidCount: 0,
          memberStats: {},
        });
      }

      const entry = groupedMap.get(monthKey)!;
      entry.events.push(event);

      // Count each attendee record separately so 2 siblings = 2 unpaid/paid items
      for (const att of targetAttendees) {
        if (!entry.memberStats[att.memberId]) {
          const familyMember = familyMembers.find(
            (m) => m?.id === att.memberId
          );
          entry.memberStats[att.memberId] = {
            memberId: att.memberId,
            firstName: familyMember?.firstName || "Неизвестен",
            paidCount: 0,
            unpaidCount: 0,
          };
        }

        if (att.paymentStatus === "paid") {
          entry.paidCount++;
          entry.memberStats[att.memberId].paidCount++;
        } else {
          entry.unpaidCount++;
          entry.memberStats[att.memberId].unpaidCount++;
        }
      }
    }

    return Array.from(groupedMap.values()).sort((a, b) =>
      b.monthKey.localeCompare(a.monthKey)
    );
  }, [memberEvents, targetMemberIds, familyMembers]);

  // Unpaid events for individual selection
  const unpaidEvents = useMemo(() => {
    return memberEvents
      .filter((e) => {
        const hasUnpaidTarget = e.attendees?.some(
          (a: Attendee) =>
            targetMemberIds.includes(a.memberId) &&
            (!a.paymentStatus || a.paymentStatus === "unpaid")
        );
        return hasUnpaidTarget;
      })
      .sort(
        (a, b) =>
          new Date(b.startDate).getTime() - new Date(a.startDate).getTime()
      );
  }, [memberEvents, targetMemberIds]);

  const filteredMembers = members.filter((m) => {
    const fullName = `${m.firstName} ${m.lastName}`.toLowerCase();
    return fullName.includes(searchTerm.toLowerCase());
  });

  const handleNextStep = () => {
    if (step === 1) {
      if (!selectedMember && !isGuestSale) {
        toast.error("Избор на клиент", {
          description:
            "Моля, изберете член от списъка или продажба на Външен клиент.",
        });
        return;
      }
    }

    if (step === 2 && !isGuestSale) {
      if (paymentMode === "subscription" && selectedMonthKeys.length === 0) {
        toast.error("Избор на месец", {
          description: "Моля, изберете поне един месец за плащане.",
        });
        return;
      }
      if (paymentMode === "individual" && selectedEventIds.length === 0) {
        toast.error("Избор на тренировки", {
          description: "Моля, изберете поне една тренировка за плащане.",
        });
        return;
      }
    }

    if (step === 3) {
      const priceVal = parseFloat(price);
      if (isNaN(priceVal) || priceVal < 0) {
        toast.error("Невалидна цена", {
          description: "Моля, въведете валидна цена.",
        });
        return;
      }
    }

    setStep((prev) => prev + 1);
  };

  const handlePrevStep = () => {
    setStep((prev) => prev - 1);
  };

  const toggleEventSelection = (eventId: string) => {
    setSelectedEventIds((prev) =>
      prev.includes(eventId)
        ? prev.filter((id) => id !== eventId)
        : [...prev, eventId]
    );
  };

  const toggleMonthSelection = (monthKey: string) => {
    setSelectedMonthKeys((prev) =>
      prev.includes(monthKey)
        ? prev.filter((k) => k !== monthKey)
        : [...prev, monthKey]
    );
  };

  // Months that have at least one unpaid visit
  const unpaidMonths = useMemo(
    () => monthlyAttendance.filter((m) => m.unpaidCount > 0),
    [monthlyAttendance]
  );

  const allUnpaidMonthsSelected =
    unpaidMonths.length > 0 &&
    unpaidMonths.every((m) => selectedMonthKeys.includes(m.monthKey));

  // Total = unitPrice × quantity
  const totalAmount = useMemo(() => {
    const base = parseFloat(price) || 0;

    if (isGuestSale) return base;

    if (paymentMode === "subscription") {
      const months = selectedMonthKeys.length || 1;
      return base * months;
    }

    if (paymentMode === "individual") {
      const eventsCount = selectedEventIds.length || 1;
      return base * eventsCount;
    }

    return base;
  }, [price, isGuestSale, paymentMode, selectedMonthKeys, selectedEventIds]);

  const getPaidEventIds = () => {
    if (isGuestSale || paymentMode !== "subscription") return [];

    return monthlyAttendance
      .filter((m) => selectedMonthKeys.includes(m.monthKey))
      .flatMap((m) =>
        m.events
          .filter((e) => {
            return e.attendees?.some(
              (a: Attendee) =>
                targetMemberIds.includes(a.memberId) &&
                (!a.paymentStatus || a.paymentStatus === "unpaid")
            );
          })
          .map((e) => e.id)
      );
  };

  const getSaleQuantity = () => {
    if (isGuestSale) return 1;
    if (paymentMode === "subscription") return selectedMonthKeys.length || 1;
    return selectedEventIds.length || 1;
  };

  const getTargetEventDates = () => {
    if (isGuestSale || paymentMode !== "individual") return null;
    return selectedEventIds
      .map((id) => {
        const ev = memberEvents.find((e) => e.id === id);
        return ev ? new Date(ev.startDate).toLocaleDateString("bg-BG") : null;
      })
      .filter(Boolean);
  };

  const getPaidEventIdsForSale = () => {
    if (isGuestSale) return [];
    if (paymentMode === "individual") return selectedEventIds;
    return getPaidEventIds();
  };

  const handleExecuteSale = async () => {
    if (!idToken) return;
    setIsProcessing(true);
    setStep(5);

    const customPrice = parseFloat(price);
    const paidEventIdsForSubscription = getPaidEventIds();
    const qty = getSaleQuantity();

    try {
      const clientName = isGuestSale
        ? "Външен клиент"
        : familyMembers.map((m) => `${m!.firstName} ${m!.lastName}`).join(", ");

      // Build month labels for the receipt/notes
      const selectedMonthLabels = monthlyAttendance
        .filter((m) => selectedMonthKeys.includes(m.monthKey))
        .sort((a, b) => a.monthKey.localeCompare(b.monthKey))
        .map((m) => m.monthLabel);

      const targetEventDates = getTargetEventDates();

      const saleData = {
        siteId: activeBranch || "bkgalabovo",
        memberId: isGuestSale ? "GUEST_EXTERNAL" : selectedMember!.id,
        clientName: clientName, // Ensure clientName is saved in the sale document
        saleDate: new Date().toISOString(),
        items: [
          {
            productId: service.id,
            name: service.name,
            quantity: qty,
            price: customPrice,
          },
        ],
        status: "completed",
        isPaid: isPaid,
        totalAmount: totalAmount,
        currency: "EUR",
        paymentMethod: paymentMethod,
        note: note || "",
        type: "recovery_service",
        // Attendance linking metadata
        paymentMode: isGuestSale ? null : paymentMode,
        targetMonths: isGuestSale ? null : selectedMonthKeys,
        targetMonthLabels: isGuestSale ? null : selectedMonthLabels,
        targetEventDates: targetEventDates,
        paidEventIds: getPaidEventIdsForSale(),
        memberIdForAttendance: isGuestSale ? null : selectedMember?.id,
        memberIdsForAttendance: isGuestSale ? null : targetMemberIds,
      };

      const result = await executeTrainingSaleAction(
        idToken,
        saleData,
        service.name,
        clientName
      );

      if (result.success && result.saleId) {
        setCompletedSaleId(result.saleId);
        setStep(6);
        if (!isGuestSale && selectedMember) {
          mutate(selectedMember.id);
          mutate(`events_${selectedMember.id}`);
        }
        toast.success("Готово!", {
          description: "Продажбата бе регистрирана успешно.",
        });
      } else {
        setStep(4);
        toast.error("Грешка", {
          description: result.error || "Грешка при продажба",
        });
      }
    } catch (error: any) {
      setStep(4);
      toast.error("Грешка при продажба", {
        description: error.message,
      });
    } finally {
      setIsProcessing(false);
    }
  };

  const handleClose = () => {
    if (completedSaleId) {
      onSaleSuccess();
    } else {
      onClose();
    }
  };

  const selectedMonthLabels = monthlyAttendance
    .filter((m) => selectedMonthKeys.includes(m.monthKey))
    .sort((a, b) => a.monthKey.localeCompare(b.monthKey))
    .map((m) => m.monthLabel);

  // Step labels
  const steps = isGuestSale
    ? ["Клиент", "Плащане", "Преглед"]
    : ["Клиент", "Присъствия", "Плащане", "Преглед"];
  const totalSteps = steps.length;

  const displayStep = Math.min(step, totalSteps);

  const getMemberButtonClasses = (isSelected: boolean, isGuestTab: boolean) => {
    if (!isSelected) return "hover:bg-zinc-50 dark:hover:bg-zinc-900/50 text-zinc-800 dark:text-zinc-200";
    return isGuestTab 
      ? "bg-amber-500/10 text-amber-950 dark:bg-amber-950/20 dark:text-amber-300"
      : "bg-emerald-50 text-emerald-950 dark:bg-emerald-950/20 dark:text-emerald-300";
  };

  const getMemberAvatarClasses = (isSelected: boolean, isGuestTab: boolean) => {
    if (!isSelected) return "bg-zinc-100 dark:bg-zinc-800 text-zinc-500";
    return isGuestTab ? "bg-amber-500 text-white" : "bg-emerald-500 text-white";
  };

  const renderMembersList = () => {
    if (filteredMembers.length === 0) {
      return (
        <div className="p-8 text-center text-zinc-400 text-xs font-light">
          {clientTypeTab === "guest"
            ? "Няма регистрирани външни гости. Създайте нов гост от бутона вдясно!"
            : "Няма намерени членове по този критерий."}
        </div>
      );
    }

    return filteredMembers.map((member) => {
      const isSelected = selectedMember?.id === member.id;
      const isGuestTab = clientTypeTab === "guest";
      return (
        <button
          key={member.id}
          type="button"
          onClick={() => {
            setSelectedMember(member);
            setIsGuestSale(member.isGuest || false);
          }}
          className={`w-full text-left px-5 py-3.5 flex justify-between items-center transition-colors text-sm font-light ${getMemberButtonClasses(isSelected, isGuestTab)}`}
        >
          <div className="flex items-center gap-3">
            <div
              className={cn(
                "h-7 w-7 rounded-lg flex items-center justify-center text-[10px] font-semibold shrink-0",
                getMemberAvatarClasses(isSelected, isGuestTab)
              )}
            >
              {member.firstName[0]}
              {member.lastName[0]}
            </div>
            <div className="flex flex-col">
              <span className="font-medium text-zinc-900 dark:text-zinc-50">
                {member.firstName} {member.lastName}
              </span>
              <span className="text-[10px] text-zinc-400 font-light mt-0.5">
                {member.phone || member.email || "Няма контакти"}
              </span>
            </div>
          </div>
          {isSelected && (
            <Check
              className={cn(
                "h-4 w-4 shrink-0",
                isGuestTab ? "text-amber-500" : "text-emerald-500"
              )}
            />
          )}
        </button>
      );
    });
  };

  return (
    <Dialog open={isOpen} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-[620px] p-8 sm:p-10 rounded-5xl bg-white dark:bg-zinc-950 border-none shadow-2xl max-h-[90vh] overflow-y-auto custom-scrollbar">
        <DialogHeader className="mb-6">
          <DialogTitle className="text-2xl font-light text-zinc-955 dark:text-zinc-50 flex items-center gap-3">
            <ShoppingBag
              className="h-6 w-6 text-emerald-500"
              strokeWidth={1.5}
            />
            Продажба: {service.name}
          </DialogTitle>
          <DialogDescription className="font-light text-zinc-500 mt-1">
            {step < 5 ? (
              <span>
                Стъпка {displayStep} от {totalSteps}:{" "}
                {isGuestSale
                  ? ["Избор на клиент", "Детайли на плащане", "Потвърждение"][
                      step - 1
                    ]
                  : [
                      "Избор на клиент",
                      "Присъствия и период",
                      "Начин на плащане",
                      "Потвърждение",
                    ][step - 1]}
              </span>
            ) : step === 5 ? (
              <span>Регистриране на продажбата...</span>
            ) : (
              <span>Продажбата е завършена успешно. Благодарим ви!</span>
            )}
          </DialogDescription>
        </DialogHeader>

        {/* STEP PROGRESS BAR */}
        {step <= totalSteps && (
          <div className="w-full bg-zinc-100 dark:bg-zinc-900 h-1.5 rounded-full mb-8 overflow-hidden">
            <div
              className="bg-emerald-500 h-full transition-all duration-500"
              style={{ width: `${(displayStep / totalSteps) * 100}%` }}
            />
          </div>
        )}

        {/* ===== STEP 1: SELECT BUYER ===== */}
        {step === 1 && (
          <div className="space-y-5">
            <div className="flex items-center justify-between pb-2 border-b border-zinc-100 dark:border-zinc-900">
              <div className="flex items-center gap-2">
                <User className="h-4 w-4 text-emerald-500" strokeWidth={1.5} />
                <h3 className="text-sm font-semibold text-zinc-950 dark:text-zinc-50">
                  Избор на клиент
                </h3>
              </div>
            </div>

            {showNewGuestForm ? (
              /* QUICK NEW GUEST FORM */
              <div className="space-y-4 p-5 border border-amber-200 dark:border-amber-900/35 bg-amber-50/20 dark:bg-amber-950/5 rounded-2xl animate-in fade-in duration-300">
