                          Описание
                        </th>
                        <th className="p-1.5 text-right">Сума</th>
                      </tr>
                    </thead>
                    <tbody>
                      <tr className="border-b border-zinc-200 dark:border-zinc-800 font-medium">
                        <td className="p-1.5 border-r border-zinc-200 dark:border-zinc-800 font-bold text-left text-zinc-800 dark:text-zinc-200">
                          {service.name}
                          {!isGuestSale &&
                            paymentMode === "subscription" &&
                            selectedMonthKeys.length > 0 &&
                            !selectedMonthKeys.includes("NO_EVENTS") && (
                              <span className="ml-1 font-normal text-zinc-500">
                                ({selectedMonthLabels.join(", ")})
                              </span>
                            )}
                          {!isGuestSale &&
                            paymentMode === "individual" &&
                            selectedEventIds.length > 0 && (
                              <span className="ml-1 font-normal text-zinc-500">
                                ({selectedEventIds.length} тренировки
                                {(() => {
                                  const dates = selectedEventIds
                                    .map((id) => {
                                      const ev = memberEvents.find(
                                        (e) => e.id === id
                                      );
                                      return ev
                                        ? new Date(
                                            ev.startDate
                                          ).toLocaleDateString("bg-BG")
                                        : "";
                                    })
                                    .filter(Boolean);
                                  return dates.length > 0
                                    ? ` на ${dates.join(", ")}`
                                    : "";
                                })()}
                                )
                              </span>
                            )}
                        </td>
                        <td className="p-1.5 text-right font-bold text-zinc-800 dark:text-zinc-200">
                          {formatPrice(totalAmount)}
                        </td>
                      </tr>
                      <tr>
                        <td className="p-1.5 text-right border-r border-zinc-200 dark:border-zinc-800 font-bold uppercase text-[8px] text-zinc-400">
                          Обща стойност:
                        </td>
                        <td className="p-1.5 text-right font-bold text-[10px] text-zinc-900 dark:text-white">
                          {formatPrice(totalAmount)}
                        </td>
                      </tr>
                    </tbody>
                  </table>
                </div>

                {note && (
                  <div className="mb-3 p-2 border border-dashed border-zinc-300 dark:border-zinc-700 bg-zinc-50/50 dark:bg-zinc-900/30 text-[9px] rounded-lg">
                    <span className="font-bold text-zinc-500 uppercase mr-1">
                      Забележка:
                    </span>
                    <span className="italic text-zinc-800 dark:text-zinc-200">
                      {note}
                    </span>
                  </div>
                )}

                <div className="mt-4 text-[7px] text-zinc-400 text-center border-t border-zinc-100 dark:border-zinc-800 pt-3">
                  Документът е издаден съгласно чл. 7, ал. 1 от Закона за
                  счетоводството.
                </div>

                <div className="mt-4 flex justify-between gap-12 text-zinc-500">
                  <div className="flex-1">
                    <div className="h-px bg-zinc-300 dark:bg-zinc-800 w-full" />
                    <p className="text-[7px] font-bold mt-0.5 uppercase text-center">
                      Доставчик: {clubInfo.name}
                    </p>
                  </div>
                  <div className="flex-1">
                    <div className="h-px bg-zinc-300 dark:bg-zinc-800 w-full" />
                    <p className="text-[7px] font-bold mt-0.5 uppercase text-center">
                      Получател:{" "}
                      {isGuestSale
                        ? "Външен клиент"
                        : `${selectedMember?.firstName} ${selectedMember?.lastName}`}
                    </p>
                  </div>
                </div>
              </div>
            </div>

            <div className="flex gap-3 justify-center">
              <Button
                onClick={() => {
                  if (completedSaleId) {
                    window.open(`/sales/${completedSaleId}/receipt`, "_blank");
                  }
                }}
                className="rounded-xl bg-zinc-900 text-white hover:bg-zinc-800 h-11 px-6 text-xs font-semibold flex items-center gap-2"
              >
                <Printer className="h-4 w-4" /> Отвори за печат (PDF)
              </Button>
            </div>
          </div>
        )}

        {/* ===== DIALOG FOOTER: NAVIGATION BUTTONS ===== */}
        {step < 5 && (
          <DialogFooter className="px-8 py-6 border-t border-zinc-100 dark:border-zinc-900 flex flex-row justify-between items-center sm:justify-between w-full">
            <div>
              {step > 1 ? (
                <Button
                  variant="outline"
                  onClick={handlePrevStep}
                  disabled={isProcessing}
                  className="rounded-xl px-5 h-11 flex items-center gap-2 text-zinc-500 hover:text-zinc-800"
                >
                  <ArrowLeft className="h-4 w-4" /> Назад
                </Button>
              ) : (
                <Button
                  variant="outline"
                  onClick={onClose}
                  disabled={isProcessing}
                  className="rounded-xl px-5 h-11 text-zinc-500 hover:text-zinc-800"
                >
                  Отказ
                </Button>
              )}
            </div>

            <div>
              {/* For guest: steps 1→2→3 = totalSteps 3, execute at step 3 */}
              {/* For member: steps 1→2→3→4 = totalSteps 4, execute at step 4 */}
              {step < (isGuestSale ? 3 : 4) ? (
                <Button
                  onClick={handleNextStep}
                  disabled={isProcessing}
                  className="rounded-xl px-6 h-11 bg-zinc-950 hover:bg-zinc-800 text-white flex items-center gap-2 font-medium text-[11px] uppercase tracking-widest"
                >
                  Напред <ArrowRight className="h-3.5 w-3.5" />
                </Button>
              ) : (
                <Button
                  onClick={handleExecuteSale}
                  disabled={isProcessing}
                  className="rounded-xl px-8 h-11 bg-emerald-500 hover:bg-emerald-600 text-white flex items-center gap-2 font-medium text-[11px] uppercase tracking-widest"
                >
                  Завърши продажбата <Check className="h-4 w-4" />
                </Button>
              )}
            </div>
          </DialogFooter>
        )}

        {step === 6 && (
          <DialogFooter className="px-8 py-6 border-t border-zinc-100 dark:border-zinc-900 flex justify-end">
            <Button
              onClick={handleClose}
              className="rounded-xl px-8 h-11 bg-zinc-950 hover:bg-zinc-800 text-white font-medium text-[11px] uppercase tracking-widest"
            >
              Затвори
            </Button>
          </DialogFooter>
        )}
      </DialogContent>
    </Dialog>
  );
};

"use client";

import { useState, useEffect } from "react";
import { format } from "date-fns";
import { bg } from "date-fns/locale";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { formatPrice } from "@/lib/currency";
import { useRecoveryServices } from "@/hooks/useRecoveryServices";
import {
  ShoppingCart,
  CheckCircle2,
  XCircle,
  MoreVertical,
  Receipt,
  Eye,
  Edit2,
  Trash2,
  Loader2,
} from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { getAllMembers } from "@/services/member-service";
import { Member, Sale } from "@/types";
import { useRouter } from "next/navigation";
import { useAuth } from "@/context/auth-context";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { deleteSaleAction } from "@/lib/actions/sales";
import { EditSaleDialog } from "./EditSaleDialog";

export function RecoverySalesHistory() {
  const { sales, isLoading, refetch } = useRecoveryServices();
  const [membersMap, setMembersMap] = useState<Record<string, string>>({});
  const [membersLoading, setMembersLoading] = useState(true);

  const [saleToEdit, setSaleToEdit] = useState<Sale | null>(null);
  const [isDeleting, setIsDeleting] = useState<string | null>(null);
  const router = useRouter();
  const { idToken } = useAuth();

  useEffect(() => {
    const fetchMembers = async () => {
      try {
        const fetchedMembers = await getAllMembers();
        const dict: Record<string, string> = {};
        fetchedMembers.forEach((m: Member) => {
          dict[m.id] = `${m.firstName} ${m.lastName}`;
        });
        setMembersMap(dict);
      } catch (err) {
        console.error("Грешка при зареждане на членове", err);
      } finally {
        setMembersLoading(false);
      }
    };

    fetchMembers();
  }, []);

  const getClientName = (sale: any) => {
    if (sale.clientName) return sale.clientName;
    if (sale.memberId === "GUEST_EXTERNAL") return "Гост";
    return membersMap[sale.memberId] || "Гост";
  };
  if (isLoading || membersLoading) {
    return (
      <div className="p-8 space-y-4">
        {[1, 2, 3, 4, 5].map((i) => (
          <div
            key={i}
            className="h-16 rounded-xl bg-zinc-100 dark:bg-zinc-900 animate-pulse"
          />
        ))}
      </div>
    );
  }

  const handleDeleteSale = async (saleId: string) => {
    if (!idToken) return;
    if (!confirm("Сигурни ли сте, че искате да изтриете тази продажба?"))
      return;

    setIsDeleting(saleId);
    try {
      const res = await deleteSaleAction(saleId, idToken);
      if (!res.success) throw new Error(res.message || "Грешка при изтриване.");

      toast.success("Успех", {
        description: "Продажбата беше изтрита успешно.",
      });
      if (refetch) refetch();
    } catch (error: any) {
      toast.error("Грешка", {
        description: error.message || "Грешка при изтриване.",
      });
    } finally {
      setIsDeleting(null);
    }
  };

  return (
    <div className="flex flex-col h-full bg-white dark:bg-zinc-950">
      <div className="p-6 md:p-8 border-b border-zinc-100 dark:border-zinc-900">
        <h2 className="text-xl font-light text-zinc-900 dark:text-zinc-50 flex items-center gap-2">
          <ShoppingCart className="h-5 w-5 text-emerald-500" />
          История на продажбите
        </h2>
        <p className="text-xs text-zinc-500 mt-1 font-light">
          Проследяване на всички направени продажби на възстановяване.
        </p>
      </div>

      <div className="flex-1 overflow-auto custom-scrollbar">
        {sales.length > 0 ? (
          <Table>
            <TableHeader className="bg-zinc-50/50 dark:bg-zinc-900/50 sticky top-0 backdrop-blur-sm">
              <TableRow className="border-b border-zinc-100 dark:border-zinc-800 hover:bg-transparent">
                <TableHead className="text-[10px] uppercase tracking-widest text-zinc-400 font-semibold py-5">
                  Дата
                </TableHead>
                <TableHead className="text-[10px] uppercase tracking-widest text-zinc-400 font-semibold py-5">
                  Клиент
                </TableHead>
                <TableHead className="text-[10px] uppercase tracking-widest text-zinc-400 font-semibold py-5">
                  Услуга
                </TableHead>
                <TableHead className="text-[10px] uppercase tracking-widest text-zinc-400 font-semibold py-5">
                  Сума
                </TableHead>
                <TableHead className="text-[10px] uppercase tracking-widest text-zinc-400 font-semibold py-5 text-right">
                  Статус
                </TableHead>
                <TableHead className="w-12"></TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {sales.map((sale) => (
                <TableRow
                  key={sale.id}
                  className="border-b border-zinc-50 dark:border-zinc-900 hover:bg-zinc-50 dark:hover:bg-zinc-900/50 transition-colors"
                >
                  <TableCell className="py-4">
                    <div className="flex flex-col">
                      <span className="font-medium text-sm text-zinc-900 dark:text-zinc-100">
                        {format(new Date(sale.saleDate), "dd MMM yyyy", {
                          locale: bg,
                        })}
                      </span>
                      <span className="text-xs text-zinc-400">
                        {format(new Date(sale.saleDate), "HH:mm")}
                      </span>
                    </div>
                  </TableCell>
                  <TableCell className="py-4">
                    <span className="text-sm font-semibold text-zinc-900 dark:text-zinc-100">
                      {getClientName(sale)}
                    </span>
                  </TableCell>
                  <TableCell className="py-4">
                    <div className="flex flex-col">
                      {sale.items.map((item, idx) => (
                        <span
                          key={idx}
                          className="text-sm text-zinc-600 dark:text-zinc-400"
                        >
                          {item.name || "Тренировка"}{" "}
                          {item.quantity > 1 ? `(x${item.quantity})` : ""}
                        </span>
                      ))}
                    </div>
                  </TableCell>
                  <TableCell className="py-4">
                    <span className="text-sm font-medium text-zinc-900 dark:text-zinc-100">
                      {formatPrice(sale.totalAmount)}
                    </span>
                  </TableCell>
                  <TableCell className="py-4 text-right">
                    {sale.isPaid ? (
                      <Badge
                        variant="outline"
                        className="bg-emerald-50 text-emerald-600 border-emerald-100 dark:bg-emerald-500/10 dark:text-emerald-500 dark:border-emerald-500/20"
                      >
                        <CheckCircle2 className="w-3 h-3 mr-1" />
                        Платено
                      </Badge>
                    ) : (
                      <Badge
                        variant="outline"
                        className="bg-rose-50 text-rose-600 border-rose-100 dark:bg-rose-500/10 dark:text-rose-500 dark:border-rose-500/20"
                      >
                        <XCircle className="w-3 h-3 mr-1" />
                        Неплатено
                      </Badge>
                    )}
                  </TableCell>
                  <TableCell className="py-4 text-right pr-6">
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8 text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-100"
                          disabled={isDeleting === sale.id}
                        >
                          {isDeleting === sale.id ? (
                            <Loader2 className="h-4 w-4 animate-spin" />
                          ) : (
                            <MoreVertical className="h-4 w-4" />
                          )}
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent
                        align="end"
                        className="w-[160px] rounded-xl"
                      >
                        <DropdownMenuItem
                          onClick={() =>
                            router.push(`/sales/${sale.id}/receipt`)
                          }
                          className="flex items-center gap-2 text-xs font-medium cursor-pointer"
                        >
                          <Receipt className="h-3.5 w-3.5 text-zinc-500" />
                          Касова бележка
                        </DropdownMenuItem>
                        <DropdownMenuItem
                          onClick={() => router.push(`/sales/${sale.id}`)}
                          className="flex items-center gap-2 text-xs font-medium cursor-pointer"
                        >
                          <Eye className="h-3.5 w-3.5 text-zinc-500" />
                          Детайли
                        </DropdownMenuItem>
                        <DropdownMenuItem
                          onClick={() => setSaleToEdit(sale)}
                          className="flex items-center gap-2 text-xs font-medium cursor-pointer"
                        >
                          <Edit2 className="h-3.5 w-3.5 text-zinc-500" />
                          Редактирай
                        </DropdownMenuItem>
                        <DropdownMenuItem
                          onClick={() => handleDeleteSale(sale.id)}
                          className="flex items-center gap-2 text-xs font-medium text-rose-600 focus:bg-rose-50 dark:focus:bg-rose-950/30 focus:text-rose-600 cursor-pointer"
                        >
                          <Trash2 className="h-3.5 w-3.5" />
                          Изтрий
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        ) : (
          <div className="py-32 flex flex-col items-center justify-center text-center">
            <ShoppingCart
              className="h-12 w-12 text-zinc-200 dark:text-zinc-800 mb-4"
              strokeWidth={1}
            />
            <p className="text-zinc-500 text-sm font-light">
              Няма намерени продажби.
            </p>
          </div>
        )}
      </div>

      <EditSaleDialog
        isOpen={!!saleToEdit}
        onClose={() => setSaleToEdit(null)}
        sale={saleToEdit}
        onSuccess={() => {
          if (refetch) refetch();
          setSaleToEdit(null);
        }}
      />
    </div>
  );
}

"use client";

import { useFormStatus } from "react-dom";
import { useState } from "react";
import Image from "next/image";
import { ClubService } from "@/types";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { BentoCard } from "@/components/ui/bento-card";
import {
  Loader2,
  Save,
  X,
  Info,
  Activity,
  MapPin,
  Camera,
  Trash,
  Check,
} from "lucide-react";

interface RecoverySessionFormProps {
  initialData?: Partial<ClubService>;
  siteInventory?: {
    compressors: number;
    attachments: {
      arms: number;
      legs: number;
      hips: number;
    };
  };
  onSubmit: (formData: FormData) => void;
  onCancel: () => void;
  errors?: Record<string, string[] | undefined>;
}

export function RecoverySessionForm({
  initialData,
  siteInventory,
  onSubmit,
  onCancel,
  errors,
}: RecoverySessionFormProps) {
  const [imageUrl, setImageUrl] = useState(
    (initialData as any)?.imageUrl || ""
  );
  const [imageDisplayMode, setImageDisplayMode] = useState<
    "collage" | "carousel"
  >((initialData as any)?.imageDisplayMode || "collage");

  // Supported zones in all caps to match UI
  const SUPPORTED_ZONES = ["РЪЦЕ", "КРАКА", "ТАЗ"];

  // Filter initial zones to only include supported ones and normalize case
  const initialZones = (initialData?.zones || [])
    .map((z) => z.toUpperCase())
    .filter((z) => SUPPORTED_ZONES.includes(z));

  const CATEGORIES = [
    "ЕДИНИЧНИ СЕСИИ",
    "КОМБИНИРАНИ СЕСИИ",
    "ТУРНИРНИ СЕСИИ",
    "VIP СЕСИИ",
  ];
  const SESSION_TYPES: Record<number, string> = {
    15: "ЗАГРЯВКА",
    30: "ВЪЗСТАНОВЯВАНЕ",
    45: "PRO RECOVERY",
  };

  const [category, setCategory] = useState(
    initialData?.category || "ЕДИНИЧНИ СЕСИИ"
  );
  const [sessionType, setSessionType] = useState(
    initialData?.sessionType || "ВЪЗСТАНОВЯВАНЕ"
  );
  const [duration, setDuration] = useState(initialData?.durationMinutes || 30);
  const [zones, setZones] = useState<string[]>(initialZones);
  const [athleteCount, setAthleteCount] = useState(
    initialData?.athleteCount || 1
  );
  const [numberOfDays, setNumberOfDays] = useState(
    initialData?.numberOfDays || 1
  );
  const [proceduresPerDay, setProceduresPerDay] = useState(
    initialData?.proceduresPerDay || 1
  );

  const [resCompressors, setResCompressors] = useState(
    initialData?.requiredResources?.compressors || 0
  );
  const [resLegs, setResLegs] = useState(
    initialData?.requiredResources?.attachments?.legs || 0
  );
  const [resArms, setResArms] = useState(
    initialData?.requiredResources?.attachments?.arms || 0
  );
  const [resHips, setResHips] = useState(
    initialData?.requiredResources?.attachments?.hips || 0
  );

  // Auto-logic for Session Type based on Duration
  const handleDurationChange = (mins: number) => {
    setDuration(mins);

    // ONLY VIP has special naming for 45 mins
    if (mins === 45 && category === "VIP СЕСИИ") {
      setSessionType("VIP ПРОТОКОЛ");
    } else if (SESSION_TYPES[mins]) {
      setSessionType(SESSION_TYPES[mins]);
    }
  };

  // Special VIP logic
  const handleCategoryChange = (cat: string) => {
    setCategory(cat);
    if (cat === "VIP СЕСИИ") {
      setProceduresPerDay(2); // VIP has 2 sessions per day
      setAthleteCount(2); // Usually for 2 athletes as per description
      setDuration(45);
      setSessionType("VIP ПРОТОКОЛ");
    } else {
      // Reset special session types if moving away from VIP
      if (duration === 45) {
        setSessionType("PRO RECOVERY");
      } else if (SESSION_TYPES[duration]) {
        setSessionType(SESSION_TYPES[duration]);
      }
    }
  };

  const handleZoneToggle = (zone: string) => {
    setZones((prev) => {
      const isChecking = !prev.includes(zone);
      const newZones = isChecking
        ? [...prev, zone]
        : prev.filter((z) => z !== zone);

      if (isChecking) {
        // Multiplied by athleteCount but capped by inventory
        if (zone === "КРАКА")
          setResLegs(
            Math.min(athleteCount, siteInventory?.attachments?.legs || 10)
          );
        if (zone === "РЪЦЕ")
          setResArms(
            Math.min(athleteCount, siteInventory?.attachments?.arms || 10)
          );
        if (zone === "ТАЗ")
          setResHips(
            Math.min(athleteCount, siteInventory?.attachments?.hips || 10)
          );
        setResCompressors(
          Math.min(athleteCount, siteInventory?.compressors || 10)
        );
      } else {
        if (zone === "КРАКА") setResLegs(0);
        if (zone === "РЪЦЕ") setResArms(0);
        if (zone === "ТАЗ") setResHips(0);

        const remainingZones = newZones.length;
        if (remainingZones === 0) setResCompressors(0);
      }

      return newZones;
    });
  };

  const handleAthleteCountChange = (count: number) => {
    setAthleteCount(count);
    // Re-scale currently active zones
    if (zones.includes("КРАКА"))
      setResLegs(Math.min(count, siteInventory?.attachments?.legs || 10));
    if (zones.includes("РЪЦЕ"))
      setResArms(Math.min(count, siteInventory?.attachments?.arms || 10));
    if (zones.includes("ТАЗ"))
      setResHips(Math.min(count, siteInventory?.attachments?.hips || 10));
    if (zones.length > 0)
      setResCompressors(Math.min(count, siteInventory?.compressors || 10));
  };

  const handleResourceChange = (field: string, value: number) => {
    if (field === "legs") {
      setResLegs(value);
      if (value > 0 && !zones.includes("КРАКА"))
        setZones((p) => [...p, "КРАКА"]);
      else if (value === 0 && zones.includes("КРАКА"))
        setZones((p) => p.filter((z) => z !== "КРАКА"));
    }
    if (field === "arms") {
      setResArms(value);
      if (value > 0 && !zones.includes("РЪЦЕ")) setZones((p) => [...p, "РЪЦЕ"]);
      else if (value === 0 && zones.includes("РЪЦЕ"))
        setZones((p) => p.filter((z) => z !== "РЪЦЕ"));
    }
    if (field === "hips") {
      setResHips(value);
      if (value > 0 && !zones.includes("ТАЗ")) setZones((p) => [...p, "ТАЗ"]);
      else if (value === 0 && zones.includes("ТАЗ"))
        setZones((p) => p.filter((z) => z !== "ТАЗ"));
    }
    if (field === "compressors") setResCompressors(value);
  };

  return (
    <form
      action={onSubmit}
      className="space-y-8 pb-12 animate-in fade-in duration-500"
    >
      <input type="hidden" name="category" value={category} />
      <input type="hidden" name="sessionType" value={sessionType} />
      <input type="hidden" name="duration" value={duration} />
      <input type="hidden" name="athleteCount" value={athleteCount} />
      <input type="hidden" name="numberOfDays" value={numberOfDays} />
      <input type="hidden" name="proceduresPerDay" value={proceduresPerDay} />
      <input type="hidden" name="zones" value={zones.join(",")} />
      <input type="hidden" name="imageUrl" value={imageUrl} />
      <input type="hidden" name="imageDisplayMode" value={imageDisplayMode} />

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Left Column: Basic Info */}
        <div className="lg:col-span-2 space-y-8">
          <BentoCard className="p-8 bg-white border-zinc-100 shadow-none rounded-5xl">
            <div className="flex items-center gap-3 mb-8">
              <div className="p-2.5 rounded-xl bg-blue-50 text-blue-600">
                <Info className="h-5 w-5" strokeWidth={1.5} />
              </div>
              <h3 className="text-xl font-light tracking-tight">
                Основна информация
              </h3>
            </div>

            <div className="space-y-6">
              <div className="space-y-2">
                <Label
                  htmlFor="name"
                  className="text-zinc-500 font-medium ml-1"
                >
                  Име на процедурата
                </Label>
                <Input
                  id="name"
                  name="name"
                  autoComplete="off"
                  defaultValue={initialData?.name}
                  placeholder="напр. Криотерапия - Цяло тяло"
                  className="h-14 rounded-2xl border-zinc-100 bg-zinc-50 focus:bg-white transition-all text-lg"
                  required
                />
                {errors?.name && (
                  <p className="text-xs text-red-500 mt-1 ml-1 animate-in slide-in-from-left-1">
                    {errors.name[0]}
                  </p>
                )}
              </div>

              <div className="space-y-4">
                <p className="text-sm text-zinc-500 font-medium ml-1">
                  Категория
                </p>
                <div className="grid grid-cols-2 gap-2">
                  {CATEGORIES.map((cat) => (
                    <button
                      key={cat}
                      type="button"
                      onClick={() => handleCategoryChange(cat)}
                      className={`h-12 rounded-xl text-[10px] font-black uppercase tracking-widest border transition-all ${category === cat ? "bg-zinc-950 text-white border-zinc-950" : "bg-zinc-50 text-zinc-400 border-zinc-100 hover:border-zinc-300"}`}
                    >
                      {cat}
                    </button>
                  ))}
                </div>
                {errors?.category && (
                  <p className="text-xs text-red-500 mt-1 ml-1 animate-in slide-in-from-left-1">
                    {errors.category[0]}
                  </p>
                )}
              </div>

              {category === "VIP СЕСИИ" && (
                <div className="p-4 bg-emerald-50 rounded-2xl border border-emerald-100 space-y-2">
                  <p className="text-[10px] font-bold text-emerald-700 uppercase tracking-widest">
                    💎 VIP Режим
                  </p>
                  <p className="text-xs text-emerald-600 leading-relaxed">
                    Специални условия: Сесията е разделена на сегменти (15 мин
                    Загрявка + 30 мин Възстановяване). Включва 2 сесии на ден на
                    спортист.
                  </p>
                </div>
              )}

              <div className="space-y-2">
                <Label
                  htmlFor="description"
                  className="text-zinc-500 font-medium ml-1"
                >
                  Описание
                </Label>
                <div className="relative">
                  <Textarea
                    id="description"
                    name="description"
                    defaultValue={initialData?.description}
                    placeholder="Опишете процедурата и ползите от нея..."
                    rows={4}
                    className="rounded-2xl border-zinc-100 bg-zinc-50 focus:bg-white transition-all resize-none p-4"
                  />
                  <div className="absolute bottom-4 right-4 px-3 py-1 bg-white/50 backdrop-blur-sm rounded-lg border border-zinc-100 text-[10px] font-black text-zinc-400 uppercase tracking-widest">
                    {sessionType}
                  </div>
                </div>
                {errors?.description && (
                  <p className="text-xs text-red-500 mt-1 ml-1 animate-in slide-in-from-left-1">
                    {errors.description[0]}
                  </p>
                )}
              </div>
            </div>
          </BentoCard>

          <BentoCard className="p-8 bg-white border-zinc-100 shadow-none rounded-5xl">
            <div className="flex items-center gap-3 mb-8">
              <div className="p-2.5 rounded-xl bg-cyan-50 text-cyan-600">
                <MapPin className="h-5 w-5" strokeWidth={1.5} />
              </div>
              <h3 className="text-xl font-light tracking-tight">
                Зони и ресурси
              </h3>
            </div>

            <div className="space-y-6">
              <div className="space-y-4">
                <p className="text-sm text-zinc-500 font-medium ml-1">
                  Зони за ползване
                </p>
                <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                  {SUPPORTED_ZONES.map((zone) => (
                    <div
                      key={zone}
                      onClick={() => handleZoneToggle(zone)}
                      className={`flex items-center gap-3 p-4 rounded-2xl border cursor-pointer transition-all ${zones.includes(zone) ? "bg-cyan-600 text-white border-cyan-600" : "bg-zinc-50 border-zinc-100 text-zinc-700 hover:bg-zinc-100"}`}
                    >
                      <Checkbox
                        checked={zones.includes(zone)}
                        className={zones.includes(zone) ? "border-white" : ""}
                      />
                      <span className="text-xs font-medium">{zone}</span>
                    </div>
                  ))}
                </div>
                {errors?.zones && (
                  <p className="text-xs text-red-500 mt-1 ml-1 animate-in slide-in-from-left-1">
                    {errors.zones[0]}
                  </p>
                )}
                {/* Hidden input to pass zones to FormData */}
                <input type="hidden" name="zones" value={zones.join(",")} />
              </div>

              <div className="space-y-6 pt-6 border-t border-zinc-50">
                <div className="flex items-center gap-2">
                  <p className="text-sm text-zinc-500 font-medium ml-1">
                    Необходими ресурси за сесията
                  </p>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <Label
                      htmlFor="req_compressors"
                      className="text-xs text-zinc-400"
                    >
                      Компресори
                    </Label>
                    <div className="flex items-center gap-3">
                      <Input
                        id="req_compressors"
                        name="req_compressors"
                        type="number"
                        min="0"
                        max={siteInventory?.compressors || 10}
                        value={resCompressors}
                        onChange={(e) =>
                          handleResourceChange(
                            "compressors",
                            parseInt(e.target.value) || 0
                          )
                        }
                        className="h-12 rounded-xl bg-zinc-50"
                      />
                      <span className="text-[10px] text-zinc-300 uppercase whitespace-nowrap">
                        от {siteInventory?.compressors || "?"} налични
                      </span>
                    </div>
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="req_legs" className="text-xs text-zinc-400">
                      Маншети за КРАКА
                    </Label>
                    <div className="flex items-center gap-3">
                      <Input
                        id="req_legs"
                        name="req_legs"
                        type="number"
                        min="0"
                        max={siteInventory?.attachments?.legs || 10}
                        value={resLegs}
                        onChange={(e) =>
                          handleResourceChange(
                            "legs",
                            parseInt(e.target.value) || 0
                          )
                        }
                        className="h-12 rounded-xl bg-zinc-50"
                      />
                      <span className="text-[10px] text-zinc-300 uppercase whitespace-nowrap">
                        от {siteInventory?.attachments?.legs || "?"} налични
                      </span>
                    </div>
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="req_arms" className="text-xs text-zinc-400">
                      Маншети за РЪЦЕ
                    </Label>
                    <div className="flex items-center gap-3">
                      <Input
                        id="req_arms"
                        name="req_arms"
                        type="number"
                        min="0"
                        max={siteInventory?.attachments?.arms || 10}
                        value={resArms}
                        onChange={(e) =>
                          handleResourceChange(
                            "arms",
                            parseInt(e.target.value) || 0
                          )
                        }
                        className="h-12 rounded-xl bg-zinc-50"
                      />
                      <span className="text-[10px] text-zinc-300 uppercase whitespace-nowrap">
                        от {siteInventory?.attachments?.arms || "?"} налични
                      </span>
                    </div>
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="req_hips" className="text-xs text-zinc-400">
                      Маншети за ТАЗ
                    </Label>
                    <div className="flex items-center gap-3">
                      <Input
                        id="req_hips"
                        name="req_hips"
                        type="number"
                        min="0"
                        max={siteInventory?.attachments?.hips || 10}
                        value={resHips}
                        onChange={(e) =>
                          handleResourceChange(
                            "hips",
                            parseInt(e.target.value) || 0
                          )
                        }
                        className="h-12 rounded-xl bg-zinc-50"
                      />
                      <span className="text-[10px] text-zinc-300 uppercase whitespace-nowrap">
                        от {siteInventory?.attachments?.hips || "?"} налични
                      </span>
                    </div>
                  </div>
                </div>
                <p className="text-[11px] text-amber-600 bg-amber-50 p-3 rounded-xl border border-amber-100/50">
                  Тези ресурси ще се блокират автоматично при резервация.
                  Уверете се, че съответстват на избраните зони.
                </p>
              </div>
            </div>
          </BentoCard>

          <BentoCard className="p-8 bg-white border-zinc-100 shadow-none rounded-5xl">
            <div className="flex items-center gap-3 mb-8">
              <div className="p-2.5 rounded-xl bg-amber-50 text-amber-600">
                <Camera className="h-5 w-5" strokeWidth={1.5} />
              </div>
              <h3 className="text-xl font-light tracking-tight">
                Изображения (Банер)
              </h3>
            </div>

            <div className="space-y-6">
              <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                {[
                  "/zones/arm.png",
                  "/zones/legs.webp",
                  "/zones/pelvis.webp",
                ].map((path) => {
                  const isSelected = imageUrl.includes(path);
                  return (
                    <div
                      key={path}
                      onClick={() => {
                        setImageUrl((prev: string) => {
                          const list = prev
                            ? prev.split(",").filter(Boolean)
                            : [];
                          if (list.includes(path)) {
                            return list
                              .filter((p: string) => p !== path)
                              .join(",");
                          } else {
                            return [...list, path].join(",");
                          }
                        });
                      }}
                      className={`relative aspect-video rounded-2xl overflow-hidden border-2 cursor-pointer transition-all ${
                        isSelected
                          ? "border-amber-500 shadow-md ring-2 ring-amber-500/20"
                          : "border-zinc-200 hover:border-amber-300"
                      }`}
                    >
                      <Image
                        src={path}
                        alt="Zone Preview"
                        fill
                        sizes="150px"
                        className="object-cover"
                      />
                      {isSelected && (
                        <div className="absolute top-2 right-2 bg-amber-500 text-white rounded-full p-1 shadow-sm">
                          <Check className="h-3 w-3" strokeWidth={3} />
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>

              {imageUrl ? (
                <div className="pt-6 border-t border-zinc-100 space-y-4">
                  <div className="flex justify-between items-center">
                    <p className="text-xs font-semibold uppercase tracking-wider text-zinc-500">
                      Избрани снимки (
                      {imageUrl.split(",").filter(Boolean).length})
                    </p>
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      onClick={() => setImageUrl("")}
                      className="text-xs font-medium text-red-650 hover:bg-red-50 hover:text-red-700 h-8 px-3 rounded-lg"
                    >
                      Премахни всички
                    </Button>
                  </div>
                  <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
                    {imageUrl
                      .split(",")
                      .filter(Boolean)
                      .map((path: string, index: number, arr: string[]) => (
                        <div
                          key={path}
                          className="relative aspect-video rounded-2xl overflow-hidden border border-zinc-200 bg-zinc-50 group shadow-sm"
                        >
                          <Image
                            src={path}
                            alt={`Preview ${index + 1}`}
                            fill
                            sizes="150px"
                            className="object-cover"
                          />
                          <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                            <Button
                              type="button"
                              variant="destructive"
                              size="icon"
                              onClick={() => {
                                const nextList = arr.filter(
                                  (p: string) => p !== path
                                );
                                setImageUrl(nextList.join(","));
                              }}
                              className="h-8 w-8 rounded-full"
                            >
                              <Trash className="h-4 w-4" />
                            </Button>
                          </div>
                        </div>
                      ))}
                  </div>
                </div>
              ) : null}

              {/* Display Mode Toggle */}
              {imageUrl && imageUrl.split(",").filter(Boolean).length > 1 && (
                <div className="pt-6 border-t border-zinc-100 space-y-4">
                  <p className="text-xs font-semibold uppercase tracking-wider text-zinc-500">
                    Режим на показване
                  </p>
                  <div className="flex bg-zinc-50 p-1 rounded-xl border border-zinc-100">
                    <button
                      type="button"
                      onClick={() => setImageDisplayMode("collage")}
                      className={`flex-1 py-2 text-sm font-medium rounded-lg transition-all ${
                        imageDisplayMode === "collage"
                          ? "bg-white text-zinc-900 shadow-sm border border-zinc-200"
                          : "text-zinc-500 hover:text-zinc-700"
                      }`}
                    >
                      Колаж (Обединени)
                    </button>
                    <button
                      type="button"
                      onClick={() => setImageDisplayMode("carousel")}
                      className={`flex-1 py-2 text-sm font-medium rounded-lg transition-all ${
                        imageDisplayMode === "carousel"
                          ? "bg-white text-zinc-900 shadow-sm border border-zinc-200"
                          : "text-zinc-500 hover:text-zinc-700"
                      }`}
                    >
                      Въртележка
                    </button>
                  </div>
                  <p className="text-xs text-zinc-400">
                    {imageDisplayMode === "collage"
                      ? "Снимките ще бъдат разделени на равни части и показани едновременно."
                      : "Снимките ще се сменят автоматично с възможност за ръчно прелистване."}
                  </p>
                </div>
              )}
            </div>
          </BentoCard>
        </div>

        {/* Right Column: Numbers & Settings */}
        <div className="space-y-8">
          <BentoCard className="p-8 bg-white border-zinc-100 shadow-none rounded-5xl">
            <div className="flex items-center gap-3 mb-8">
              <div className="p-2.5 rounded-xl bg-emerald-50 text-emerald-600">
                <Activity className="h-5 w-5" strokeWidth={1.5} />
              </div>
              <h3 className="text-xl font-light tracking-tight">Параметри</h3>
            </div>

            <div className="space-y-6">
              <div className="space-y-2">
                <Label
                  htmlFor="price"
                  className="text-zinc-500 font-medium ml-1"
                >
                  Цена (EUR)
                </Label>
                <div className="relative">
                  <Input
                    id="price"
                    name="price"
                    type="number"
                    step="0.01"
                    autoComplete="off"
                    defaultValue={initialData?.price}
                    className="h-12 rounded-xl border-zinc-100 bg-zinc-50 pl-10"
                    required
                  />
                  <span className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-400">
                    €
                  </span>
                </div>
                {errors?.price && (
                  <p className="text-xs text-red-500 mt-1 ml-1 animate-in slide-in-from-left-1">
                    {errors.price[0]}
                  </p>
                )}
              </div>

              <div className="space-y-4">
                <p className="text-sm text-zinc-500 font-medium ml-1">
                  Продължителност
                </p>
                <div className="grid grid-cols-3 gap-2">
                  {[15, 30, 45].map((mins) => (
                    <button
                      key={mins}
                      type="button"
                      onClick={() => handleDurationChange(mins)}
                      className={`h-12 rounded-xl text-xs font-bold border transition-all ${duration === mins ? "bg-cyan-600 text-white border-cyan-600 shadow-lg shadow-cyan-200" : "bg-zinc-50 text-zinc-500 border-zinc-100 hover:border-zinc-300"}`}
                    >
                      {mins} мин
                    </button>
                  ))}
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4 pt-4 border-t border-zinc-50">
                <div className="space-y-2">
                  <Label
                    htmlFor="athleteCountInput"
                    className="text-[10px] text-zinc-400 uppercase tracking-widest"
                  >
                    Брой спортисти
                  </Label>
                  <Input
                    id="athleteCountInput"
                    type="number"
                    value={athleteCount}
                    onChange={(e) =>
                      handleAthleteCountChange(parseInt(e.target.value) || 1)
                    }
                    className="h-10 rounded-lg bg-zinc-50"
                  />
                </div>
                <div className="space-y-2">
                  <Label
                    htmlFor="numberOfDaysInput"
                    className="text-[10px] text-zinc-400 uppercase tracking-widest"
                  >
                    Брой дни
                  </Label>
                  <Input
                    id="numberOfDaysInput"
                    type="number"
                    value={numberOfDays}
                    onChange={(e) =>
                      setNumberOfDays(parseInt(e.target.value) || 1)
                    }
                    className="h-10 rounded-lg bg-zinc-50"
                  />
                </div>
              </div>

              <div className="space-y-2">
                <Label
                  htmlFor="proceduresPerDayInput"
                  className="text-[10px] text-zinc-400 uppercase tracking-widest"
                >
                  Процедури на ден
                </Label>
                <Input
                  id="proceduresPerDayInput"
                  type="number"
                  value={proceduresPerDay}
                  onChange={(e) =>
                    setProceduresPerDay(parseInt(e.target.value) || 1)
                  }
                  className="h-10 rounded-lg bg-zinc-50"
                />
              </div>
            </div>
          </BentoCard>

          <div className="flex flex-col gap-3">
            <SubmitButton isEdit={!!initialData?.id} />
            <Button
              type="button"
              variant="outline"
              size="lg"
              onClick={onCancel}
              className="h-14 rounded-3xl border-zinc-100 text-zinc-500 hover:bg-zinc-50 transition-all"
            >
              <X className="mr-2 h-4 w-4" /> Отказ
            </Button>
          </div>
        </div>
      </div>
    </form>
  );
}

function SubmitButton({ isEdit }: { isEdit: boolean }) {
  const { pending } = useFormStatus();
  return (
    <Button
      type="submit"
      size="lg"
      disabled={pending}
      className="h-16 rounded-3xl bg-zinc-950 text-white hover:bg-zinc-800 transition-all text-sm uppercase tracking-widest font-medium"
    >
      {pending ? (
        <Loader2 className="mr-3 h-5 w-5 animate-spin" />
      ) : (
        <Save className="mr-3 h-5 w-5" strokeWidth={1.5} />
      )}
      {isEdit ? "Запази промените" : "Създай процедура"}
    </Button>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Service } from "@/app/(protected)/finances/services/service.types";
import { BentoCard } from "@/components/ui/bento-card";
import { Button } from "@/components/ui/button";
import { formatPrice } from "@/lib/currency";
import Image from "next/image";
import {
  CreditCard,
  Zap,
  Calendar,
  UserCheck,
  Shirt,
  Users,
  MoreHorizontal,
  Edit,
  Trash2,
  Clock,
} from "lucide-react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { useAuth } from "@/context/auth-context";
import { deleteClubService } from "@/lib/actions/services";
import { toast } from "sonner";

interface ServiceMenuProps {
  services: Service[];
  onEdit: (service: Service) => void;
  onSale: (service: Service) => void;
  onDeleteSuccess?: () => void;
}

export function ServiceMenu({
  services,
  onEdit,
  onSale,
  onDeleteSuccess,
}: ServiceMenuProps) {
  const { idToken } = useAuth();

  const amateurSubs = services.filter(
    (s) =>
      (s.type === "Абонамент" || s.type === "Годишен абонамент") &&
      s.targetGroups?.includes("Любители")
  );
  const monthlySubs = services.filter(
    (s) => s.type === "Абонамент" && !s.targetGroups?.includes("Любители")
  );
  const annualSubs = services.filter(
    (s) =>
      s.type === "Годишен абонамент" && !s.targetGroups?.includes("Любители")
  );
  const membershipFees = services.filter(
    (s) => s.type === "Членски внос" && !s.targetGroups?.includes("Любители")
  );
  const oneTime = services.filter((s) => s.type === "Еднократно плащане");

  const handleDelete = async (id: string, name: string) => {
    if (!idToken) return;
    if (confirm(`Сигурни ли сте, че искате да изтриете "${name}"?`)) {
      const result = await deleteClubService(idToken, id);
      if (result.success) {
        toast.success(result.message);
        onDeleteSuccess?.();
      } else {
        toast.error(result.message);
      }
    }
  };

  return (
    <div className="space-y-16">
      {/* Monthly Subscriptions Section */}
      {monthlySubs.length > 0 && (
        <section className="space-y-8">
          <div className="flex items-center gap-4">
            <div className="h-px flex-1 bg-zinc-100" />
            <h3 className="text-xs uppercase tracking-[0.3em] font-medium text-zinc-400">
              Месечни Абонаменти за Деца
            </h3>
            <div className="h-px flex-1 bg-zinc-100" />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {monthlySubs.map((service) => (
              <ServiceCard
                key={service.id}
                service={service}
                onEdit={() => onEdit(service)}
                onSale={() => onSale(service)}
                onDelete={() => handleDelete(service.id, service.name)}
              />
            ))}
          </div>
        </section>
      )}

      {/* Annual Subscriptions Section */}
      {annualSubs.length > 0 && (
        <section className="space-y-8">
          <div className="flex items-center gap-4">
            <div className="h-px flex-1 bg-zinc-100" />
            <h3 className="text-xs uppercase tracking-[0.3em] font-medium text-zinc-400">
              Годишни Абонаменти
            </h3>
            <div className="h-px flex-1 bg-zinc-100" />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {annualSubs.map((service) => (
              <ServiceCard
                key={service.id}
                service={service}
                onEdit={() => onEdit(service)}
                onSale={() => onSale(service)}
                onDelete={() => handleDelete(service.id, service.name)}
              />
            ))}
          </div>
        </section>
      )}

      {/* Amateur Subscriptions Section */}
      {amateurSubs.length > 0 && (
        <section className="space-y-8">
          <div className="flex items-center gap-4">
            <div className="h-px flex-1 bg-zinc-100" />
            <h3 className="text-xs uppercase tracking-[0.3em] font-medium text-zinc-400">
              Абонаменти за Любители
            </h3>
            <div className="h-px flex-1 bg-zinc-100" />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {amateurSubs.map((service) => (
              <ServiceCard
                key={service.id}
                service={service}
                onEdit={() => onEdit(service)}
                onSale={() => onSale(service)}
                onDelete={() => handleDelete(service.id, service.name)}
              />
            ))}
          </div>
        </section>
      )}

      {/* Membership Fees Section */}
      {membershipFees.length > 0 && (
        <section className="space-y-8">
          <div className="flex items-center gap-4">
            <div className="h-px flex-1 bg-zinc-100" />
            <h3 className="text-xs uppercase tracking-[0.3em] font-medium text-zinc-400">
              Членски Внос
            </h3>
            <div className="h-px flex-1 bg-zinc-100" />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {membershipFees.map((service) => (
              <ServiceCard
                key={service.id}
                service={service}
                onEdit={() => onEdit(service)}
                onSale={() => onSale(service)}
                onDelete={() => handleDelete(service.id, service.name)}
              />
            ))}
          </div>
        </section>
      )}

      {/* One-time Section */}
      {oneTime.length > 0 && (
        <section className="space-y-8">
          <div className="flex items-center gap-4">
            <div className="h-px flex-1 bg-zinc-100" />
            <h3 className="text-xs uppercase tracking-[0.3em] font-medium text-zinc-400">
              Еднократни Посещения и Персонални Тренировки
            </h3>
            <div className="h-px flex-1 bg-zinc-100" />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {oneTime.map((service) => (
              <ServiceCard
                key={service.id}
                service={service}
                onEdit={() => onEdit(service)}
                onSale={() => onSale(service)}
                onDelete={() => handleDelete(service.id, service.name)}
              />
            ))}
          </div>
        </section>
      )}

      {services.length === 0 && (
        <div className="flex flex-col items-center justify-center py-24 text-zinc-400 border-2 border-dashed border-zinc-100 rounded-[32px] bg-zinc-50/50">
          <Zap className="h-10 w-10 text-zinc-300 mb-3" strokeWidth={1} />
          <p className="text-sm font-light">Няма намерени услуги.</p>
        </div>
      )}
    </div>
  );
}

function ServiceCard({
  service,
  onEdit,
  onSale,
  onDelete,
}: {
  service: Service;
  onEdit: () => void;
  onSale: () => void;
  onDelete: () => void;
}) {
  const isSubscription = [
    "Абонамент",
    "Годишен абонамент",
    "Членски внос",
  ].includes(service.type);

  const images = service.imageUrl
    ? service.imageUrl.split(",").filter(Boolean)
    : [];
  const [activeImageIndex, setActiveImageIndex] = useState(0);

  useEffect(() => {
    if (images.length <= 1) return;
    const interval = setInterval(() => {
      setActiveImageIndex((prev) => (prev + 1) % images.length);
    }, 3000);
    return () => clearInterval(interval);
  }, [images.length]);

  return (
    <BentoCard className="group relative overflow-hidden bg-white border border-zinc-100 shadow-none hover:border-zinc-300 hover:shadow-xl hover:shadow-zinc-100/20 transition-all duration-500 rounded-5xl flex flex-col h-full">
      {/* Cover Image or Icon Header */}
      <div className="relative h-48 bg-zinc-50 dark:bg-zinc-900 flex items-center justify-center overflow-hidden border-b border-zinc-50 dark:border-zinc-800">
        {images.length > 0 ? (
          <>
            {images.map((imgUrl, idx) => (
              <Image
                key={imgUrl}
                src={imgUrl}
                alt={`${service.name} - ${idx + 1}`}
                fill
                sizes="(max-w-768px) 100vw, 33vw"
                className={`object-cover group-hover:scale-110 absolute inset-0 transition-all duration-1000 ${
                  idx === activeImageIndex
                    ? "opacity-100 z-0 scale-100"
                    : "opacity-0 -z-10 scale-95"
                }`}
              />
            ))}

            {images.length > 1 && (
              <div className="absolute bottom-4 right-4 z-10 flex gap-1 bg-black/20 dark:bg-black/40 backdrop-blur-md px-2 py-1.5 rounded-full">
                {images.map((_, idx) => (
                  <div
                    key={idx}
                    className={`h-1.5 rounded-full transition-all duration-300 ${
                      idx === activeImageIndex
                        ? "bg-white w-3"
                        : "bg-white/50 w-1.5"
                    }`}
                  />
                ))}
              </div>
            )}
          </>
        ) : (
          <div className="w-full h-full flex flex-col items-center justify-center text-zinc-300 dark:text-zinc-800 bg-zinc-50 dark:bg-zinc-900">
            {service.type === "Членски внос" ? (
              <UserCheck className="h-12 w-12 opacity-30" strokeWidth={1} />
            ) : isSubscription ? (
              <Calendar className="h-12 w-12 opacity-30" strokeWidth={1} />
            ) : (
              <Zap className="h-12 w-12 opacity-30" strokeWidth={1} />
            )}
            <span className="text-[9px] font-semibold uppercase tracking-[0.2em] opacity-40 mt-2">
              {service.type}
            </span>
          </div>
        )}

        {/* Dropdown Menu on Image Hover */}
        <div className="absolute top-4 right-4 z-10 flex gap-2">
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button
                variant="ghost"
                size="icon"
                className="h-8 w-8 rounded-full bg-white/90 dark:bg-zinc-900/90 backdrop-blur-md border border-zinc-100/50 dark:border-zinc-850 hover:bg-white"
              >
                <MoreHorizontal className="h-4 w-4 text-zinc-500" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent
              align="end"
              className="rounded-2xl border-zinc-100 p-2 min-w-[160px]"
            >
              <DropdownMenuItem
                onClick={onEdit}
                className="rounded-xl gap-2 focus:bg-zinc-50 py-3"
              >
                <Edit className="h-4 w-4 text-zinc-400" /> Редактиране
              </DropdownMenuItem>
              <DropdownMenuItem
                onClick={onDelete}
                className="rounded-xl gap-2 focus:bg-red-50 text-red-650 py-3"
              >
                <Trash2 className="h-4 w-4" /> Изтриване
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>

        {/* Badge in corner */}
        <div className="absolute bottom-4 left-4">
          <div className="px-3 py-1.5 rounded-lg text-[9px] font-semibold uppercase tracking-widest border backdrop-blur-md bg-white/80 dark:bg-zinc-900/80 border-zinc-100 dark:border-zinc-800 text-zinc-900 dark:text-white">
            {service.type}
          </div>
        </div>
      </div>

      {/* Content Area */}
      <div className="p-8 flex-1 flex flex-col justify-between">
        <div className="space-y-4">
          <h4 className="text-xl font-medium tracking-tight text-zinc-900 group-hover:text-primary transition-colors line-clamp-1">
            {service.name}
          </h4>
          <p className="text-sm text-zinc-400 font-light leading-relaxed line-clamp-3 min-h-18">
            {service.description}
          </p>

          {/* Tags */}
          <div className="flex flex-wrap gap-2 pt-2">
            {service.targetGroups?.map((group) => (
              <span
                key={group}
                className="px-3 py-1 bg-zinc-50 border border-zinc-100 rounded-full text-[10px] uppercase tracking-wider text-zinc-500 font-medium"
              >
                {group}
              </span>
            ))}
          </div>

          {/* Features */}
          <div className="space-y-3 pt-4 border-t border-zinc-50">
            {isSubscription ? (
              <>
                <div className="flex items-center gap-3 text-xs text-zinc-500">
                  <CreditCard
                    className="h-4 w-4 text-zinc-300"
                    strokeWidth={1.5}
                  />
                  <span>{service.billingPeriod || "Месечен"} период</span>
                </div>
                {service.grantsLicense && (
                  <div className="flex items-center gap-3 text-xs text-zinc-500">
                    <UserCheck
                      className="h-4 w-4 text-emerald-400"
                      strokeWidth={1.5}
                    />
                    <span>Право на картотека</span>
                  </div>
                )}
                {service.grantsApparel && (
                  <div className="flex items-center gap-3 text-xs text-zinc-500">
                    <Shirt
                      className="h-4 w-4 text-blue-400"
                      strokeWidth={1.5}
                    />
                    <span>Право на екипировка</span>
                  </div>
                )}
              </>
            ) : (
              <>
                <div className="flex items-center gap-3 text-xs text-zinc-500">
                  <Clock className="h-4 w-4 text-zinc-300" strokeWidth={1.5} />
                  <span>{service.durationMinutes || 90} минути</span>
                </div>
                {service.requiresBooking && (
                  <div className="flex items-center gap-3 text-xs text-zinc-500">
                    <Calendar
                      className="h-4 w-4 text-amber-400"
                      strokeWidth={1.5}
                    />
                    <span>Изисква резервация</span>
                  </div>
                )}
              </>
            )}
            <div className="flex items-center gap-3 text-xs text-zinc-500">
              <Users className="h-4 w-4 text-zinc-300" strokeWidth={1.5} />
              <span>
                {service.minMembers || 1} - {service.maxMembers || 1} участници
              </span>
            </div>
          </div>
        </div>

        <div>
          {/* Price */}
          <div className="flex items-baseline gap-1 pt-6 border-t border-zinc-50 mb-6 mt-6">
            <span className="text-3xl font-light tracking-tighter text-zinc-950">
              {formatPrice(service.price).replace(" EUR", "")}
            </span>
            <span className="text-sm font-medium text-zinc-400 uppercase tracking-widest ml-1">
              EUR
            </span>
            {isSubscription && (
              <span className="text-xs text-zinc-300 lowercase ml-2 font-light">
                /{" "}
                {service.billingPeriod?.toLowerCase().replace("ен", "ца") ||
                  "месец"}
              </span>
            )}
          </div>

          {/* Actions */}
          <div className="grid grid-cols-2 gap-3 w-full">
            <Button
              variant="outline"
              size="sm"
              onClick={onSale}
              className="w-full h-11 rounded-xl font-medium text-[10px] uppercase tracking-widest border-zinc-200 text-zinc-700 hover:bg-zinc-50 dark:border-zinc-800 dark:text-zinc-300 dark:hover:bg-zinc-900 transition-all shadow-none"
            >
              Продажба
            </Button>
            <Button
              variant="default"
              size="sm"
              onClick={onEdit}
              className="w-full h-11 rounded-xl font-medium text-[10px] uppercase tracking-widest bg-zinc-950 text-white hover:bg-zinc-800 transition-all shadow-none border-none"
            >
              Редактиране
            </Button>
          </div>
        </div>
      </div>
    </BentoCard>
  );
}

