                </span>
              </div>
              {!isGuestSale && (
                <>
                  <div className="flex justify-between items-center text-xs pb-3 border-b border-zinc-200/50 dark:border-zinc-800/50">
                    <span className="text-zinc-500">Тип плащане</span>
                    <span className="font-bold text-zinc-900 dark:text-white">
                      {paymentMode === "subscription"
                        ? "Месечен абонамент"
                        : "Еднократно (Индивидуални тренировки)"}
                    </span>
                  </div>
                  {paymentMode === "subscription" &&
                    selectedMonthKeys.length > 0 &&
                    !selectedMonthKeys.includes("NO_EVENTS") && (
                      <div className="flex justify-between items-center text-xs pb-3 border-b border-zinc-200/50 dark:border-zinc-800/50">
                        <span className="text-zinc-500">Период</span>
                        <span className="font-bold text-emerald-600">
                          {selectedMonthLabels.join(", ")}
                        </span>
                      </div>
                    )}
                  {paymentMode === "individual" &&
                    selectedEventIds.length > 0 && (
                      <div className="flex justify-between items-center text-xs pb-3 border-b border-zinc-200/50 dark:border-zinc-800/50">
                        <span className="text-zinc-500">Брой тренировки</span>
                        <span className="font-bold text-blue-600">
                          {selectedEventIds.length} тренировки
                        </span>
                      </div>
                    )}
                </>
              )}
              <div className="flex justify-between items-center text-xs pb-3 border-b border-zinc-200/50 dark:border-zinc-800/50">
                <span className="text-zinc-500">Начин на плащане</span>
                <span className="font-bold text-zinc-900 dark:text-white">
                  {paymentMethod}
                </span>
              </div>
              <div className="flex justify-between items-center text-xs pb-3 border-b border-zinc-200/50 dark:border-zinc-800/50">
                <span className="text-zinc-500">Статус</span>
                <span
                  className={`font-bold uppercase tracking-wider text-[10px] ${
                    isPaid ? "text-emerald-600" : "text-rose-600"
                  }`}
                >
                  {isPaid ? "Платено" : "Неплатено (Дълг)"}
                </span>
              </div>
              {note && (
                <div className="flex flex-col gap-1 text-xs pb-3 border-b border-zinc-200/50 dark:border-zinc-800/50">
                  <span className="text-zinc-500">Забележка</span>
                  <span className="font-medium text-zinc-900 dark:text-white italic">
                    {note}
                  </span>
                </div>
              )}
              <div className="flex justify-between items-center pt-2">
                <span className="text-sm font-semibold text-zinc-900 dark:text-white">
                  Обща сума
                </span>
                <span className="text-2xl font-bold text-emerald-500 tracking-tight">
                  {formatPrice(totalAmount)}
                </span>
              </div>
            </div>
          </div>
        )}

        {/* ===== STEP 5: PROCESSING ===== */}
        {step === 5 && (
          <div className="py-20 flex flex-col items-center justify-center space-y-6">
            <Loader2
              className="h-12 w-12 animate-spin text-emerald-500"
              strokeWidth={2}
            />
            <div className="text-center space-y-2">
              <p className="font-light text-zinc-900 dark:text-zinc-100 text-lg">
                Регистриране на продажбата...
              </p>
              <p className="text-zinc-500 text-xs font-light">
                Моля, изчакайте, докато транзакцията се записва в базата данни.
              </p>
            </div>
          </div>
        )}

        {/* ===== STEP 6: RECEIPT & PRINT ===== */}
        {step === 6 && (
          <div className="space-y-6">
            <div className="flex items-center gap-2 pb-2 border-b border-zinc-100 dark:border-zinc-900">
              <Receipt className="h-4 w-4 text-emerald-500" strokeWidth={1.5} />
              <h3 className="text-sm font-semibold text-zinc-950 dark:text-zinc-50">
                Касова бележка
              </h3>
            </div>

            <div
              className="flex flex-col border border-zinc-200 dark:border-zinc-800 p-6 bg-white dark:bg-zinc-950 rounded-2xl relative text-zinc-950 dark:text-zinc-50 w-full max-w-lg mx-auto shadow-sm"
              style={{
                fontFamily: "Arial, Helvetica, sans-serif",
                wordSpacing: "1px",
              }}
            >
              <div className="flex flex-col h-full">
                <div className="flex justify-between items-start border-b border-zinc-200 dark:border-zinc-800 pb-3 mb-3 text-[10px]">
                  <div className="space-y-1">
                    <h4 className="text-xs font-bold uppercase tracking-tight text-zinc-900 dark:text-white">
                      РАЗПИСКА ЗА ПЛАЩАНЕ
                    </h4>
                    <p className="text-[9px] font-bold uppercase text-zinc-500">
                      №{" "}
                      {completedSaleId
                        ? completedSaleId.substring(0, 8).toUpperCase()
                        : "N/A"}{" "}
                      / {new Date().toLocaleDateString("bg-BG")} г.
                    </p>
                  </div>
                  <div className="text-right text-[9px] space-y-0.5 text-zinc-500">
                    <p className="font-bold uppercase text-zinc-700 dark:text-zinc-300">
                      {clubInfo.name}
                    </p>
                    <p className="uppercase">{clubInfo.address}</p>
                    <p className="uppercase">{clubInfo.contact}</p>
                  </div>
                </div>

                <div className="mb-3 text-[9px] flex justify-between items-start bg-zinc-50 dark:bg-zinc-900/50 p-2.5 border border-zinc-100 dark:border-zinc-800 rounded-lg">
                  <div>
                    <p className="text-[8px] text-zinc-400 font-bold uppercase tracking-widest mb-0.5">
                      Получател
                    </p>
                    <p className="font-bold uppercase text-zinc-800 dark:text-zinc-200">
                      {clientDisplayName}
                    </p>
                  </div>
                  <div className="text-right text-zinc-600 dark:text-zinc-400">
                    <p className="text-[8px] text-zinc-400 font-bold uppercase tracking-widest mb-0.5">
                      Детайли за плащане
                    </p>
                    <p className="font-bold">
                      Дата: {new Date().toLocaleDateString("bg-BG")} г.
                    </p>
                    <p className="mt-0.5">Начин: {paymentMethod}</p>
                    <p className="mt-0.5 font-bold">
                      Статус:{" "}
                      <span
                        className={
                          isPaid
                            ? "text-emerald-600 dark:text-emerald-400"
                            : "text-rose-600 dark:text-rose-400"
                        }
                      >
                        {isPaid ? "ПЛАТЕНО" : "ОЧАКВА ПЛАЩАНЕ"}
                      </span>
                    </p>
                  </div>
                </div>

                <div className="mb-3">
                  <table className="w-full border-collapse border border-zinc-200 dark:border-zinc-800 text-[9px]">
                    <thead>
                      <tr className="bg-zinc-50 dark:bg-zinc-900 border-b border-zinc-200 dark:border-zinc-800 text-[8px] font-bold uppercase text-zinc-500">
                        <th className="p-1.5 text-left border-r border-zinc-200 dark:border-zinc-800">
                          Описание
                        </th>
                        <th className="p-1.5 text-right">Сума</th>
                      </tr>
                    </thead>
                    <tbody>
                      <tr className="border-b border-zinc-200 dark:border-zinc-800 font-medium">
                        <td className="p-1.5 border-r border-zinc-200 dark:border-zinc-800 font-bold text-left text-zinc-800 dark:text-zinc-200">
                          {service.name}
                          {!isGuestSale &&
                            paymentMode === "subscription" &&
                            selectedMonthKeys.length > 0 &&
                            !selectedMonthKeys.includes("NO_EVENTS") && (
                              <span className="ml-1 font-normal text-zinc-500">
                                ({selectedMonthLabels.join(", ")})
                              </span>
                            )}
                          {!isGuestSale &&
                            paymentMode === "individual" &&
                            selectedEventIds.length > 0 && (
                              <span className="ml-1 font-normal text-zinc-500">
                                ({selectedEventIds.length} тренировки
                                {(() => {
                                  const dates = selectedEventIds
                                    .map((id) => {
                                      const ev = memberEvents.find(
                                        (e) => e.id === id
                                      );
                                      return ev
                                        ? new Date(
                                            ev.startDate
                                          ).toLocaleDateString("bg-BG")
                                        : "";
                                    })
                                    .filter(Boolean);
                                  return dates.length > 0
                                    ? ` на ${dates.join(", ")}`
                                    : "";
                                })()}
                                )
                              </span>
                            )}
                        </td>
                        <td className="p-1.5 text-right font-bold text-zinc-800 dark:text-zinc-200">
                          {formatPrice(totalAmount)}
                        </td>
                      </tr>
                      <tr>
                        <td className="p-1.5 text-right border-r border-zinc-200 dark:border-zinc-800 font-bold uppercase text-[8px] text-zinc-400">
                          Обща стойност:
                        </td>
                        <td className="p-1.5 text-right font-bold text-[10px] text-zinc-900 dark:text-white">
                          {formatPrice(totalAmount)}
                        </td>
                      </tr>
                    </tbody>
                  </table>
                </div>

                {note && (
                  <div className="mb-3 p-2 border border-dashed border-zinc-300 dark:border-zinc-700 bg-zinc-50/50 dark:bg-zinc-900/30 text-[9px] rounded-lg">
                    <span className="font-bold text-zinc-500 uppercase mr-1">
                      Забележка:
                    </span>
                    <span className="italic text-zinc-800 dark:text-zinc-200">
                      {note}
                    </span>
                  </div>
                )}

                <div className="mt-4 text-[7px] text-zinc-400 text-center border-t border-zinc-100 dark:border-zinc-800 pt-3">
                  Документът е издаден съгласно чл. 7, ал. 1 от Закона за
                  счетоводството.
                </div>

                <div className="mt-4 flex justify-between gap-12 text-zinc-500">
                  <div className="flex-1">
                    <div className="h-px bg-zinc-300 dark:bg-zinc-800 w-full" />
                    <p className="text-[7px] font-bold mt-0.5 uppercase text-center">
                      Доставчик: {clubInfo.name}
                    </p>
                  </div>
                  <div className="flex-1">
                    <div className="h-px bg-zinc-300 dark:bg-zinc-800 w-full" />
                    <p className="text-[7px] font-bold mt-0.5 uppercase text-center">
                      Получател:{" "}
                      {isGuestSale
                        ? "Външен клиент"
                        : `${selectedMember?.firstName} ${selectedMember?.lastName}`}
                    </p>
                  </div>
                </div>
              </div>
            </div>

            <div className="flex gap-3 justify-center">
              <Button
                onClick={() => {
                  if (completedSaleId) {
                    window.open(`/sales/${completedSaleId}/receipt`, "_blank");
                  }
                }}
                className="rounded-xl bg-zinc-900 text-white hover:bg-zinc-800 h-11 px-6 text-xs font-semibold flex items-center gap-2"
              >
                <Printer className="h-4 w-4" /> Отвори за печат (PDF)
              </Button>
            </div>
          </div>
        )}

        {/* ===== DIALOG FOOTER: NAVIGATION BUTTONS ===== */}
        {step < 5 && (
          <DialogFooter className="px-8 py-6 border-t border-zinc-100 dark:border-zinc-900 flex flex-row justify-between items-center sm:justify-between w-full">
            <div>
              {step > 1 ? (
                <Button
                  variant="outline"
                  onClick={handlePrevStep}
                  disabled={isProcessing}
                  className="rounded-xl px-5 h-11 flex items-center gap-2 text-zinc-500 hover:text-zinc-800"
                >
                  <ArrowLeft className="h-4 w-4" /> Назад
                </Button>
              ) : (
                <Button
                  variant="outline"
                  onClick={onClose}
                  disabled={isProcessing}
                  className="rounded-xl px-5 h-11 text-zinc-500 hover:text-zinc-800"
                >
                  Отказ
                </Button>
              )}
            </div>

            <div>
              {/* For guest: steps 1→2→3 = totalSteps 3, execute at step 3 */}
              {/* For member: steps 1→2→3→4 = totalSteps 4, execute at step 4 */}
              {step < (isGuestSale ? 3 : 4) ? (
                <Button
                  onClick={handleNextStep}
                  disabled={isProcessing}
                  className="rounded-xl px-6 h-11 bg-zinc-950 hover:bg-zinc-800 text-white flex items-center gap-2 font-medium text-[11px] uppercase tracking-widest"
                >
                  Напред <ArrowRight className="h-3.5 w-3.5" />
                </Button>
              ) : (
                <Button
                  onClick={handleExecuteSale}
                  disabled={isProcessing}
                  className="rounded-xl px-8 h-11 bg-emerald-500 hover:bg-emerald-600 text-white flex items-center gap-2 font-medium text-[11px] uppercase tracking-widest"
                >
                  Завърши продажбата <Check className="h-4 w-4" />
                </Button>
              )}
            </div>
          </DialogFooter>
        )}

        {step === 6 && (
          <DialogFooter className="px-8 py-6 border-t border-zinc-100 dark:border-zinc-900 flex justify-end">
            <Button
              onClick={handleClose}
              className="rounded-xl px-8 h-11 bg-zinc-950 hover:bg-zinc-800 text-white font-medium text-[11px] uppercase tracking-widest"
            >
              Затвори
            </Button>
          </DialogFooter>
        )}
      </DialogContent>
    </Dialog>
  );
};

"use client";

import { useState, useEffect } from "react";
import { format } from "date-fns";
import { bg } from "date-fns/locale";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { formatPrice } from "@/lib/currency";
import { useTrainingServices } from "@/hooks/useTrainingServices";
import {
  ShoppingCart,
  CheckCircle2,
  XCircle,
  MoreVertical,
  Receipt,
  Eye,
  Edit2,
  Trash2,
  Loader2,
} from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { getAllMembers } from "@/services/member-service";
import { Member, Sale } from "@/types";
import { useRouter } from "next/navigation";
import { useAuth } from "@/context/auth-context";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { deleteSaleAction } from "@/lib/actions/sales";
import { EditSaleDialog } from "./EditSaleDialog";

export function TrainingSalesHistory() {
  const { sales, isLoading, refetch } = useTrainingServices();
  const [membersMap, setMembersMap] = useState<Record<string, string>>({});
  const [membersLoading, setMembersLoading] = useState(true);

  const [saleToEdit, setSaleToEdit] = useState<Sale | null>(null);
  const [isDeleting, setIsDeleting] = useState<string | null>(null);
  const router = useRouter();
  const { idToken } = useAuth();

  useEffect(() => {
    const fetchMembers = async () => {
      try {
        const fetchedMembers = await getAllMembers();
        const dict: Record<string, string> = {};
        fetchedMembers.forEach((m: Member) => {
          dict[m.id] = `${m.firstName} ${m.lastName}`;
        });
        setMembersMap(dict);
      } catch (err) {
        console.error("Грешка при зареждане на членове", err);
      } finally {
        setMembersLoading(false);
      }
    };

    fetchMembers();
  }, []);

  const getClientName = (sale: any) => {
    if (sale.clientName) return sale.clientName;
    if (sale.memberId === "GUEST_EXTERNAL") return "Гост";
    return membersMap[sale.memberId] || "Гост";
  };
  if (isLoading || membersLoading) {
    return (
      <div className="p-8 space-y-4">
        {[1, 2, 3, 4, 5].map((i) => (
          <div
            key={i}
            className="h-16 rounded-xl bg-zinc-100 dark:bg-zinc-900 animate-pulse"
          />
        ))}
      </div>
    );
  }

  const handleDeleteSale = async (saleId: string) => {
    if (!idToken) return;
    if (!confirm("Сигурни ли сте, че искате да изтриете тази продажба?"))
      return;

    setIsDeleting(saleId);
    try {
      const res = await deleteSaleAction(saleId, idToken);
      if (!res.success) throw new Error(res.message || "Грешка при изтриване.");

      toast.success("Успех", {
        description: "Продажбата беше изтрита успешно.",
      });
      if (refetch) refetch();
    } catch (error: any) {
      toast.error("Грешка", {
        description: error.message || "Грешка при изтриване.",
      });
    } finally {
      setIsDeleting(null);
    }
  };

  return (
    <div className="flex flex-col h-full bg-white dark:bg-zinc-950">
      <div className="p-6 md:p-8 border-b border-zinc-100 dark:border-zinc-900">
        <h2 className="text-xl font-light text-zinc-900 dark:text-zinc-50 flex items-center gap-2">
          <ShoppingCart className="h-5 w-5 text-emerald-500" />
          История на продажбите
        </h2>
        <p className="text-xs text-zinc-500 mt-1 font-light">
          Проследяване на всички реализирани продажби на тренировки и
          абонаменти.
        </p>
      </div>

      <div className="flex-1 overflow-auto custom-scrollbar">
        {sales.length > 0 ? (
          <Table>
            <TableHeader className="bg-zinc-50/50 dark:bg-zinc-900/50 sticky top-0 backdrop-blur-sm">
              <TableRow className="border-b border-zinc-100 dark:border-zinc-800 hover:bg-transparent">
                <TableHead className="text-[10px] uppercase tracking-widest text-zinc-400 font-semibold py-5">
                  Дата
                </TableHead>
                <TableHead className="text-[10px] uppercase tracking-widest text-zinc-400 font-semibold py-5">
                  Клиент
                </TableHead>
                <TableHead className="text-[10px] uppercase tracking-widest text-zinc-400 font-semibold py-5">
                  Услуга
                </TableHead>
                <TableHead className="text-[10px] uppercase tracking-widest text-zinc-400 font-semibold py-5">
                  Сума
                </TableHead>
                <TableHead className="text-[10px] uppercase tracking-widest text-zinc-400 font-semibold py-5 text-right">
                  Статус
                </TableHead>
                <TableHead className="w-12"></TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {sales.map((sale) => (
                <TableRow
                  key={sale.id}
                  className="border-b border-zinc-50 dark:border-zinc-900 hover:bg-zinc-50 dark:hover:bg-zinc-900/50 transition-colors"
                >
                  <TableCell className="py-4">
                    <div className="flex flex-col">
                      <span className="font-medium text-sm text-zinc-900 dark:text-zinc-100">
                        {format(new Date(sale.saleDate), "dd MMM yyyy", {
                          locale: bg,
                        })}
                      </span>
                      <span className="text-xs text-zinc-400">
                        {format(new Date(sale.saleDate), "HH:mm")}
                      </span>
                    </div>
                  </TableCell>
                  <TableCell className="py-4">
                    <span className="text-sm font-semibold text-zinc-900 dark:text-zinc-100">
                      {getClientName(sale)}
                    </span>
                  </TableCell>
                  <TableCell className="py-4">
                    <div className="flex flex-col">
                      {sale.items.map((item, idx) => (
                        <span
                          key={idx}
                          className="text-sm text-zinc-600 dark:text-zinc-400"
                        >
                          {item.name || "Тренировка"}{" "}
                          {item.quantity > 1 ? `(x${item.quantity})` : ""}
                        </span>
                      ))}
                    </div>
                  </TableCell>
                  <TableCell className="py-4">
                    <span className="text-sm font-medium text-zinc-900 dark:text-zinc-100">
                      {formatPrice(sale.totalAmount)}
                    </span>
                  </TableCell>
                  <TableCell className="py-4 text-right">
                    {sale.isPaid ? (
                      <Badge
                        variant="outline"
                        className="bg-emerald-50 text-emerald-600 border-emerald-100 dark:bg-emerald-500/10 dark:text-emerald-500 dark:border-emerald-500/20"
                      >
                        <CheckCircle2 className="w-3 h-3 mr-1" />
                        Платено
                      </Badge>
                    ) : (
                      <Badge
                        variant="outline"
                        className="bg-rose-50 text-rose-600 border-rose-100 dark:bg-rose-500/10 dark:text-rose-500 dark:border-rose-500/20"
                      >
                        <XCircle className="w-3 h-3 mr-1" />
                        Неплатено
                      </Badge>
                    )}
                  </TableCell>
                  <TableCell className="py-4 text-right pr-6">
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8 text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-100"
                          disabled={isDeleting === sale.id}
                        >
                          {isDeleting === sale.id ? (
                            <Loader2 className="h-4 w-4 animate-spin" />
                          ) : (
                            <MoreVertical className="h-4 w-4" />
                          )}
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent
                        align="end"
                        className="w-[160px] rounded-xl"
                      >
                        <DropdownMenuItem
                          onClick={() =>
                            router.push(`/sales/${sale.id}/receipt`)
                          }
                          className="flex items-center gap-2 text-xs font-medium cursor-pointer"
                        >
                          <Receipt className="h-3.5 w-3.5 text-zinc-500" />
                          Касова бележка
                        </DropdownMenuItem>
                        <DropdownMenuItem
                          onClick={() => router.push(`/sales/${sale.id}`)}
                          className="flex items-center gap-2 text-xs font-medium cursor-pointer"
                        >
                          <Eye className="h-3.5 w-3.5 text-zinc-500" />
                          Детайли
                        </DropdownMenuItem>
                        <DropdownMenuItem
                          onClick={() => setSaleToEdit(sale)}
                          className="flex items-center gap-2 text-xs font-medium cursor-pointer"
                        >
                          <Edit2 className="h-3.5 w-3.5 text-zinc-500" />
                          Редактирай
                        </DropdownMenuItem>
                        <DropdownMenuItem
                          onClick={() => handleDeleteSale(sale.id)}
                          className="flex items-center gap-2 text-xs font-medium text-rose-600 focus:bg-rose-50 dark:focus:bg-rose-950/30 focus:text-rose-600 cursor-pointer"
                        >
                          <Trash2 className="h-3.5 w-3.5" />
                          Изтрий
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        ) : (
          <div className="py-32 flex flex-col items-center justify-center text-center">
            <ShoppingCart
              className="h-12 w-12 text-zinc-200 dark:text-zinc-800 mb-4"
              strokeWidth={1}
            />
            <p className="text-zinc-500 text-sm font-light">
              Няма намерени продажби.
            </p>
          </div>
        )}
      </div>

      <EditSaleDialog
        isOpen={!!saleToEdit}
        onClose={() => setSaleToEdit(null)}
        sale={saleToEdit}
        onSuccess={() => {
          if (refetch) refetch();
          setSaleToEdit(null);
        }}
      />
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import { Product } from "@/types";
import {
  restockProductAction,
  adjustProductStockAction,
  updateProductAction,
} from "@/lib/actions/inventory";
import { useAuth } from "@/context/auth-context";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import {
  Package,
  ShieldAlert,
  Sparkles,
  RefreshCw,
  Loader2,
} from "lucide-react";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { getInventoryEvents } from "@/services/inventory-service";
import { getSales } from "@/services/sales-service";
import { getAllMembers } from "@/services/member-service";
import { formatDateTimeDisplay } from "@/lib/date-utils";
import { Badge } from "@/components/ui/badge";
import { InventoryEvent, Sale } from "@/types";
import { formatPrice } from "@/lib/currency";

interface EditProductDialogProps {
  product: Product | null;
  isOpen: boolean;
  onClose: () => void;
  onProductUpdate: () => void;
}

export const EditProductDialog = ({
  product,
  isOpen,
  onClose,
  onProductUpdate,
}: EditProductDialogProps) => {
  // Product info states
  const [name, setName] = useState("");
  const [category, setCategory] = useState("");
  const [price, setPrice] = useState("");
  const [imageUrl, setImageUrl] = useState("");
  const [restockThreshold, setRestockThreshold] = useState("");
  const [description, setDescription] = useState("");

  // Stock operations states
  const [restockAmount, setRestockAmount] = useState("");
  const [adjustmentAmount, setAdjustmentAmount] = useState("");
  const [adjustmentNotes, setAdjustmentNotes] = useState("");
  const [isProcessing, setIsProcessing] = useState(false);
  const { idToken } = useAuth();

  // History and Tab states
  const [activeTab, setActiveTab] = useState("stock");
  const [movements, setMovements] = useState<InventoryEvent[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [membersMap, setMembersMap] = useState<Record<string, string>>({});
  const [historyLoading, setHistoryLoading] = useState(false);

  useEffect(() => {
    if (isOpen && product) {
      const fetchHistory = async () => {
        setHistoryLoading(true);
        try {
          // Fetch events
          const allEvents = await getInventoryEvents();
          const filteredEvents = allEvents.filter(
            (e) => e.productId === product.id
          );
          setMovements(
            filteredEvents.sort(
              (a, b) =>
                new Date(b.createdAt).getTime() -
                new Date(a.createdAt).getTime()
            )
          );

          // Fetch sales
          const allSales = await getSales();
          const filteredSales = allSales.filter((s) =>
            s.items?.some((i) => i.productId === product.id)
          );
          setSales(filteredSales);

          // Fetch members map
          const membersData = await getAllMembers();
          const map: Record<string, string> = {};
          membersData.forEach((m) => {
            map[m.id] = `${m.firstName} ${m.lastName}`;
          });
          setMembersMap(map);
        } catch (err) {
          console.error("Error fetching product history:", err);
        } finally {
          setHistoryLoading(false);
        }
      };
      fetchHistory();
    }
  }, [isOpen, product]);

  const getEventLabel = (type: string) => {
    switch (type) {
      case "restock":
        return "Зареждане";
      case "correction":
        return "Корекция";
      case "price_update":
        return "Промяна цена";
      case "sale":
        return "Продажба";
      case "initial":
        return "Първоначално";
      default:
        return "Друго";
    }
  };

  const getEventBadgeClass = (type: string) => {
    switch (type) {
      case "restock":
        return "bg-green-50 text-green-700 dark:bg-green-950/20 dark:text-green-400";
      case "sale":
        return "bg-rose-50 text-rose-700 dark:bg-rose-950/20 dark:text-rose-400";
      case "price_update":
        return "bg-amber-50 text-amber-700 dark:bg-amber-950/20 dark:text-amber-400";
      case "correction":
      default:
        return "bg-zinc-100 text-zinc-700 dark:bg-zinc-900 dark:text-zinc-400";
    }
  };

  // Populate states when product changes
  useEffect(() => {
    if (product) {
      setName(product.name || "");
      setCategory(product.category || "");
      setPrice(product.price?.toString() || "0");
      setImageUrl(product.imageUrl || "");
      setRestockThreshold(product.restockThreshold?.toString() || "");
      setDescription(product.description || "");
    }
  }, [product]);

  const handleUpdateInfo = async () => {
    if (!product || !idToken) return;
    if (!name.trim() || !category.trim() || !price) {
      toast.error("Грешка", {
        description: "Моля, попълнете всички задължителни полета.",
      });
      return;
    }

    const priceVal = parseFloat(price);
    if (isNaN(priceVal) || priceVal < 0) {
      toast.error("Грешка", {
        description: "Моля, въведете валидна, неотрицателна цена.",
      });
      return;
    }

    setIsProcessing(true);
    try {
      const productData = {
        name,
        category,
        price: priceVal,
        description,
        imageUrl,
        restockThreshold: restockThreshold
          ? parseInt(restockThreshold, 10)
          : null,
      };

      const result = await updateProductAction(
        product.id,
        idToken,
        productData
      );

      if (result.success) {
        toast.success("Успех!", { description: result.message });
        onProductUpdate();
        onClose();
      } else {
        toast.error("Грешка", { description: result.message });
      }
    } catch (error) {
      toast.error("Грешка при актуализация", {
        description: (error as Error).message,
      });
    } finally {
      setIsProcessing(false);
    }
  };

  const handleRestock = async () => {
    if (!product || !restockAmount || !idToken) return;
    const amount = parseInt(restockAmount, 10);
    if (isNaN(amount) || amount <= 0) {
      toast.error("Грешка", {
        description:
          "Моля, въведете валидно положително число за презареждане.",
      });
      return;
    }

    setIsProcessing(true);
    try {
      const result = await restockProductAction(product.id, idToken, amount);

      if (result.success) {
        toast.success("Успех!", { description: result.message });
        onProductUpdate();
        onClose();
      } else {
        toast.error("Грешка", { description: result.message });
      }
    } catch (error) {
      toast.error("Грешка при презареждане", {
        description: (error as Error).message,
      });
    } finally {
      setIsProcessing(false);
      setRestockAmount("");
    }
  };

  const handleAdjustment = async () => {
    if (!product || !adjustmentAmount || !idToken) return;
    const amount = parseInt(adjustmentAmount, 10);

    if (isNaN(amount) || amount === 0) {
      toast.error("Грешка", {
        description: "Моля, въведете валидно, ненулево число за корекция.",
      });
      return;
    }

    if (amount < 0 && !adjustmentNotes) {
      toast.error("Грешка", {
        description: "При отписване на количества, бележката е задължителна.",
      });
      return;
    }

    setIsProcessing(true);
    try {
      const newStock = product.stock + amount;
      const result = await adjustProductStockAction(
        product.id,
        idToken,
        newStock,
        adjustmentNotes
      );

      if (result.success) {
        toast.success("Успех!", { description: result.message });
        onProductUpdate();
        onClose();
      } else {
        toast.error("Грешка", { description: result.message });
      }
    } catch (error) {
      toast.error("Грешка при корекция", {
        description: (error as Error).message,
      });
    } finally {
      setIsProcessing(false);
      setAdjustmentAmount("");
      setAdjustmentNotes("");
    }
  };

  if (!product) return null;

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-[850px] p-8 sm:p-10 rounded-4xl bg-white dark:bg-zinc-950 border-none shadow-xl max-h-[90vh] overflow-y-auto custom-scrollbar">
        <DialogHeader className="mb-6">
          <DialogTitle className="text-2xl font-light text-zinc-950 dark:text-zinc-50 flex items-center gap-3">
            <Package className="h-6 w-6 text-zinc-650" strokeWidth={1.5} />
            Редактиране на: {product.name}
          </DialogTitle>
          <DialogDescription className="font-light text-zinc-400 mt-1">
            Промяна на информацията за артикула, добавяне на снимки и управление
            на складовите наличности.
          </DialogDescription>
        </DialogHeader>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
          {/* LEFT COLUMN: Product Details */}
          <div className="space-y-6">
            <div className="flex items-center gap-2 pb-2 border-b border-zinc-100 dark:border-zinc-900">
              <Sparkles className="h-4 w-4 text-primary" strokeWidth={2} />
              <h3 className="text-sm font-semibold text-zinc-950 dark:text-zinc-50">
                Информация за продукта
              </h3>
            </div>

            <div className="grid gap-4">
              <div className="grid gap-2">
                <Label
                  htmlFor="edit-name"
                  className="text-xs font-bold text-zinc-700 dark:text-zinc-300"
                >
                  Име на артикула *
                </Label>
                <Input
                  id="edit-name"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder="напр. Грип Pro's Pro"
                  className="rounded-xl h-11"
                  disabled={isProcessing}
                />
              </div>

              <div className="grid gap-2">
                <Label
                  htmlFor="edit-category"
                  className="text-xs font-bold text-zinc-700 dark:text-zinc-300"
                >
                  Категория *
                </Label>
                <Input
                  id="edit-category"
                  value={category}
                  onChange={(e) => setCategory(e.target.value)}
                  placeholder="напр. Грипове, Пера, Екипировка"
                  className="rounded-xl h-11"
                  disabled={isProcessing}
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="grid gap-2">
                  <Label
                    htmlFor="edit-price"
                    className="text-xs font-bold text-zinc-700 dark:text-zinc-300"
                  >
                    Цена (EUR) *
                  </Label>
                  <Input
                    id="edit-price"
                    type="number"
                    step="0.01"
                    value={price}
                    onChange={(e) => setPrice(e.target.value)}
                    placeholder="0.00"
                    className="rounded-xl h-11"
                    disabled={isProcessing}
                  />
                </div>
                <div className="grid gap-2">
                  <Label
                    htmlFor="edit-threshold"
                    className="text-xs font-bold text-zinc-700 dark:text-zinc-300"
                  >
                    Минимален праг (бр.)
                  </Label>
                  <Input
                    id="edit-threshold"
                    type="number"
                    value={restockThreshold}
                    onChange={(e) => setRestockThreshold(e.target.value)}
                    placeholder="напр. 5"
                    className="rounded-xl h-11"
                    disabled={isProcessing}
                  />
                </div>
              </div>

              <div className="grid gap-2">
                <Label
                  htmlFor="edit-image"
                  className="text-xs font-bold text-zinc-700 dark:text-zinc-300"
                >
                  Изображение URL (Снимка)
                </Label>
                <Input
                  id="edit-image"
                  value={imageUrl}
                  onChange={(e) => setImageUrl(e.target.value)}
                  placeholder="Линк към снимка на артикула..."
                  className="rounded-xl h-11"
                  disabled={isProcessing}
                />
              </div>

              <div className="grid gap-2">
                <Label
                  htmlFor="edit-description"
                  className="text-xs font-bold text-zinc-700 dark:text-zinc-300"
                >
                  Описание
                </Label>
                <Textarea
                  id="edit-description"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  placeholder="Допълнителни спецификации, размери или бележки..."
                  className="rounded-xl"
                  rows={3}
                  disabled={isProcessing}
                />
              </div>
            </div>

            <Button
              onClick={handleUpdateInfo}
              disabled={isProcessing}
              className="w-full rounded-xl bg-zinc-950 text-white hover:bg-zinc-800 h-12 font-medium text-[11px] uppercase tracking-widest transition-all mt-4"
            >
              Запази информацията
            </Button>
          </div>

          {/* RIGHT COLUMN: Inventory Movements System with Tabs */}
          <div className="space-y-6 md:border-l md:border-zinc-100 md:dark:border-zinc-900 md:pl-10 flex flex-col h-full min-h-[450px]">
            <Tabs
              defaultValue="stock"
              value={activeTab}
              onValueChange={setActiveTab}
              className="w-full flex-1 flex flex-col"
            >
              <TabsList className="bg-zinc-100 dark:bg-zinc-900/50 p-1 rounded-2xl h-11 w-full border border-zinc-200/40 dark:border-zinc-800/40 mb-6 flex">
                <TabsTrigger
                  value="stock"
                  className="flex-1 rounded-xl text-xs font-semibold data-[state=active]:bg-white dark:data-[state=active]:bg-zinc-800 data-[state=active]:text-zinc-950 data-[state=active]:shadow-sm dark:data-[state=active]:text-white shadow-none transition-all py-2"
                >
                  Наличност
                </TabsTrigger>
                <TabsTrigger
                  value="movements"
                  className="flex-1 rounded-xl text-xs font-semibold data-[state=active]:bg-white dark:data-[state=active]:bg-zinc-800 data-[state=active]:text-zinc-950 data-[state=active]:shadow-sm dark:data-[state=active]:text-white shadow-none transition-all py-2"
                >
                  Движения
                </TabsTrigger>
                <TabsTrigger
                  value="sales"
                  className="flex-1 rounded-xl text-xs font-semibold data-[state=active]:bg-white dark:data-[state=active]:bg-zinc-800 data-[state=active]:text-zinc-950 data-[state=active]:shadow-sm dark:data-[state=active]:text-white shadow-none transition-all py-2"
                >
                  Продажби
                </TabsTrigger>
              </TabsList>

              {/* TAB 1: STOCK OPERATIONS */}
              <TabsContent
                value="stock"
                className="outline-none flex-1 space-y-6"
              >
                <div className="flex items-center justify-between pb-2 border-b border-zinc-100 dark:border-zinc-900">
                  <div className="flex items-center gap-2">
                    <RefreshCw className="h-4 w-4 text-amber-500 animate-spin-slow" />
                    <h3 className="text-sm font-semibold text-zinc-950 dark:text-zinc-50">
                      Склад & Движения
                    </h3>
                  </div>
                  <span className="text-xs font-medium text-zinc-500">
                    Текуща наличност:{" "}
                    <strong className="text-zinc-950 dark:text-white font-bold">
                      {product.stock} бр.
                    </strong>
                  </span>
                </div>

                <div className="space-y-6">
                  {/* RESTOCK */}
                  <div className="space-y-2">
                    <Label
                      htmlFor="restock-amount"
                      className="text-xs font-bold text-zinc-700 dark:text-zinc-300"
                    >
                      Презареждане (Добавяне на стока)
                    </Label>
                    <div className="flex items-center gap-2">
                      <Input
                        id="restock-amount"
                        type="number"
                        placeholder="Количество (напр. 10)"
                        value={restockAmount}
                        onChange={(e) => setRestockAmount(e.target.value)}
                        disabled={isProcessing}
                        className="rounded-xl h-11"
                      />
                      <Button
                        onClick={handleRestock}
                        disabled={isProcessing || !restockAmount}
                        className="rounded-xl h-11 px-5 bg-zinc-950 text-white hover:bg-zinc-800"
                      >
                        Заприходи
                      </Button>
                    </div>
                  </div>

                  <div className="border-t border-zinc-100 dark:border-zinc-900"></div>

                  {/* ADJUSTMENT */}
                  <div className="space-y-3">
                    <div className="flex flex-col gap-0.5">
                      <Label
                        htmlFor="adjustment-amount"
                        className="text-xs font-bold text-zinc-700 dark:text-zinc-300 flex items-center gap-1.5"
                      >
                        <ShieldAlert className="h-3.5 w-3.5 text-zinc-400" />
                        Корекция / Ръчно Отписване
                      </Label>
                      <p className="text-[10px] text-zinc-400 font-light">
                        Използвайте отрицателно число за бракуване/отписване
                        (напр. -5).
                      </p>
                    </div>

                    <div className="flex items-center gap-2">
                      <Input
                        id="adjustment-amount"
                        type="number"
                        placeholder="Количество"
                        value={adjustmentAmount}
                        onChange={(e) => setAdjustmentAmount(e.target.value)}
                        disabled={isProcessing}
                        className="rounded-xl h-11"
                      />
                      <Button
                        onClick={handleAdjustment}
                        disabled={isProcessing || !adjustmentAmount}
                        className="rounded-xl h-11 px-5 bg-rose-500 hover:bg-rose-600 text-white"
                      >
                        Коригирай
                      </Button>
                    </div>

                    <div className="grid gap-1.5">
                      <Label
                        htmlFor="adjustment-notes"
                        className="text-[10px] text-zinc-400 font-medium uppercase tracking-wider"
                      >
                        Причина / Бележка
                      </Label>
                      <Textarea
                        id="adjustment-notes"
                        placeholder="Причина (задължително при отписване/бракуване)..."
                        value={adjustmentNotes}
                        onChange={(e) => setAdjustmentNotes(e.target.value)}
                        disabled={isProcessing}
                        className="rounded-xl"
                        rows={2}
                      />
                    </div>
                  </div>
                </div>
              </TabsContent>

              {/* TAB 2: INVENTORY MOVEMENTS HISTORY */}
              <TabsContent
                value="movements"
                className="outline-none flex-1 max-h-[380px] overflow-y-auto custom-scrollbar space-y-4 pr-1"
              >
                {historyLoading ? (
                  <div className="py-20 flex flex-col items-center justify-center space-y-4">
                    <Loader2 className="h-8 w-8 animate-spin text-amber-500 opacity-35" />
                    <p className="text-zinc-400 text-xs font-light">
                      Зареждане на движения...
                    </p>
                  </div>
                ) : movements.length > 0 ? (
                  <div className="space-y-3">
                    {movements.map((move) => {
                      const isPositive = move.quantityChange > 0;
                      const isNegative = move.quantityChange < 0;
                      return (
                        <div
                          key={move.id}
                          className="p-4 bg-zinc-50 dark:bg-zinc-900/30 rounded-2xl border border-zinc-100/50 dark:border-zinc-900 space-y-2 text-xs"
                        >
                          <div className="flex justify-between items-center">
                            <span className="text-zinc-400 text-[10px]">
                              {formatDateTimeDisplay(move.createdAt)}
                            </span>
                            <Badge
                              className={`px-2 py-0.5 rounded text-[9px] uppercase font-bold tracking-wider shadow-none border-none ${getEventBadgeClass(move.type)}`}
                            >
                              {getEventLabel(move.type)}
                            </Badge>
                          </div>
                          <div className="flex justify-between items-center">
                            <span className="text-zinc-500">Количество:</span>
                            <span
                              className={`font-semibold ${isPositive ? "text-green-600" : isNegative ? "text-rose-600" : "text-zinc-650"}`}
                            >
                              {isPositive
                                ? `+${move.quantityChange}`
                                : move.quantityChange}{" "}
                              бр.
                            </span>
                          </div>
                          {move.notes && (
                            <p className="text-zinc-400 italic text-[11px] border-t border-zinc-200/50 dark:border-zinc-800/50 pt-1.5 mt-1">
                              Бележка: {move.notes}
                            </p>
                          )}
                          <div className="text-[10px] text-zinc-400/80 text-right mt-1">
                            Оператор: {move.userName}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                ) : (
                  <div className="py-20 text-center text-zinc-400 text-xs font-light">
                    Няма записани движения за този продукт.
                  </div>
                )}
              </TabsContent>

              {/* TAB 3: PRODUCT SALES HISTORY */}
              <TabsContent
                value="sales"
                className="outline-none flex-1 max-h-[380px] overflow-y-auto custom-scrollbar space-y-4 pr-1"
              >
                {historyLoading ? (
                  <div className="py-20 flex flex-col items-center justify-center space-y-4">
                    <Loader2 className="h-8 w-8 animate-spin text-emerald-500 opacity-35" />
                    <p className="text-zinc-400 text-xs font-light">
                      Зареждане на продажби...
                    </p>
                  </div>
                ) : sales.length > 0 ? (
                  <div className="space-y-3">
                    {sales.map((sale) => {
                      const item = sale.items.find(
                        (i) => i.productId === product.id
                      );
                      const memberName =
                        sale.memberId === "GUEST_EXTERNAL"
                          ? "Външен клиент"
                          : membersMap[sale.memberId] || "Зареден Член";
                      return (
                        <div
                          key={sale.id}
                          className="p-4 bg-zinc-50 dark:bg-zinc-900/30 rounded-2xl border border-zinc-100/50 dark:border-zinc-900 space-y-2 text-xs"
                        >
                          <div className="flex justify-between items-center">
                            <span className="text-zinc-400 text-[10px]">
                              {new Date(sale.saleDate).toLocaleDateString(
                                "bg-BG"
                              )}
                            </span>
                            <Badge
                              className={`px-2 py-0.5 rounded text-[9px] uppercase font-bold tracking-wider shadow-none border-none ${
                                sale.isPaid
                                  ? "bg-emerald-50 text-emerald-700 dark:bg-emerald-950/20 dark:text-emerald-400"
                                  : "bg-rose-50 text-rose-700 dark:bg-rose-950/20 dark:text-rose-400"
                              }`}
                            >
                              {sale.isPaid ? "Платено" : "Неплатено"}
                            </Badge>
                          </div>
                          <div className="flex justify-between items-center">
                            <span className="text-zinc-500">Клиент:</span>
                            <span className="font-semibold text-zinc-900 dark:text-white">
                              {memberName}
                            </span>
                          </div>
                          <div className="flex justify-between items-center">
                            <span className="text-zinc-500">Брой:</span>
                            <span className="font-medium">
                              {item?.quantity || 1} бр.
                            </span>
                          </div>
                          <div className="flex justify-between items-center pt-1 border-t border-zinc-200/50 dark:border-zinc-800/50">
                            <span className="text-zinc-500">Сума:</span>
                            <span className="font-bold text-emerald-500">
                              {formatPrice(sale.totalAmount)}
                            </span>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                ) : (
                  <div className="py-20 text-center text-zinc-400 text-xs font-light">
                    Няма записани продажби за този продукт.
                  </div>
                )}
              </TabsContent>
            </Tabs>
          </div>
        </div>

        <DialogFooter className="mt-8 pt-6 border-t border-zinc-100 dark:border-zinc-900 flex justify-end gap-3">
          <Button
            variant="outline"
            onClick={onClose}
            disabled={isProcessing}
            className="rounded-xl px-6"
          >
            Затвори
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

"use client";

import { useEffect, useState } from "react";
import { getSales } from "@/services/sales-service";
import { getAllMembers } from "@/services/member-service";
import { Sale, Member } from "@/types";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { formatPrice } from "@/lib/currency";
import { useRouter } from "next/navigation";
import { MoreVertical, Edit2, Trash2, Loader2, Receipt, Eye } from "lucide-react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { deleteSaleAction } from "@/lib/actions/sales";
import { EditSaleDialog } from "@/components/finances/EditSaleDialog";
import { getAuth } from "firebase/auth";

const InventorySalesHistory = () => {
  const [sales, setSales] = useState<Sale[]>([]);
  const [membersMap, setMembersMap] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [isDeleting, setIsDeleting] = useState<string | null>(null);
  const [saleToEdit, setSaleToEdit] = useState<Sale | null>(null);
  const router = useRouter();

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        // Load sales and members concurrently
        const [fetchedSales, fetchedMembers] = await Promise.all([
          getSales(),
          getAllMembers(),
        ]);

        // Build member ID to name dictionary
        const dict: Record<string, string> = {};
        fetchedMembers.forEach((m: Member) => {
          dict[m.id] = `${m.firstName} ${m.lastName}`;
        });
        setMembersMap(dict);
        
        const inventorySales = fetchedSales.filter(s => !s.type || s.type === "inventory");
        setSales(inventorySales);
      } catch (err) {
        setError("Грешка при зареждане на историята на продажбите.");
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const getClientName = (memberId: string) => {
    if (memberId === "GUEST_EXTERNAL") {
      return "Външен клиент";
    }
    return membersMap[memberId] || "Неизвестен член";
  };

  const refetch = async () => {
    try {
      setLoading(true);
      const fetchedSales = await getSales();
      const inventorySales = fetchedSales.filter(s => !s.type || s.type === "inventory");
      setSales(inventorySales);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteSale = async (saleId: string) => {
    if (!confirm("Сигурни ли сте, че искате да изтриете тази продажба?")) return;
    
    setIsDeleting(saleId);
    try {
      const auth = getAuth();
      const currentUser = auth.currentUser;
      if (!currentUser) throw new Error("Моля влезте в профила си");
      const idToken = await currentUser.getIdToken();
      
      const res = await deleteSaleAction(saleId, idToken);
      if (!res.success) throw new Error(res.message || "Грешка при изтриване");
      
      toast.success("Успех", { description: "Продажбата беше изтрита успешно." });
      refetch();
    } catch (error: any) {
      toast.error("Грешка", { description: error.message });
    } finally {
      setIsDeleting(null);
    }
  };

  return (
    <div className="bg-white dark:bg-zinc-950 rounded-2xl border border-zinc-100 dark:border-zinc-900 shadow-none overflow-hidden">
      {saleToEdit && (
        <EditSaleDialog
          sale={saleToEdit}
          isOpen={!!saleToEdit}
          onClose={() => setSaleToEdit(null)}
          onSuccess={() => {
            setSaleToEdit(null);
            refetch();
          }}
        />
      )}
      <div className="p-6 border-b border-zinc-100 dark:border-zinc-900">
        <h3 className="text-[11px] font-medium uppercase tracking-[0.3em] text-zinc-400">
          История на продажбите
        </h3>
      </div>
      <div className="p-0">
        {loading && (
          <div className="p-8 text-center text-[11px] uppercase tracking-widest text-zinc-400 font-medium animate-pulse">
            Зареждане на продажбите...
          </div>
        )}
        {error && (
          <div className="p-8 text-center text-[11px] uppercase tracking-widest text-rose-400 font-medium">
            {error}
          </div>
        )}
        {!loading && !error && (
          <Table>
            <TableHeader className="bg-zinc-50/50 dark:bg-zinc-900/50">
              <TableRow className="hover:bg-transparent border-none">
                <TableHead className="h-10 text-[10px] font-medium uppercase tracking-widest text-zinc-400 px-6">
                  Дата
                </TableHead>
                <TableHead className="h-10 text-[10px] font-medium uppercase tracking-widest text-zinc-400 px-6">
                  Купувач / Клиент
                </TableHead>
                <TableHead className="h-10 text-[10px] font-medium uppercase tracking-widest text-zinc-400 px-6">
                  Продадени Артикули
                </TableHead>
                <TableHead className="h-10 text-[10px] font-medium uppercase tracking-widest text-zinc-400 px-6">
                  Начин на плащане
                </TableHead>
                <TableHead className="h-10 text-[10px] font-medium uppercase tracking-widest text-zinc-400 px-6">
                  Статус
                </TableHead>
                <TableHead className="h-10 text-[10px] font-medium uppercase tracking-widest text-zinc-400 px-6 text-right">
                  Сума
                </TableHead>
                <TableHead className="w-12"></TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {sales.map((sale) => (
                <TableRow
                  key={sale.id}
                  className="border-zinc-50 dark:border-zinc-900 hover:bg-zinc-50/50 dark:hover:bg-zinc-900/50 transition-colors"
                >
                  <TableCell className="px-6 py-4 text-[11px] font-medium text-zinc-400">
                    {new Date(sale.saleDate).toLocaleString("bg-BG")}
                  </TableCell>
                  <TableCell className="px-6 py-4 text-sm font-semibold text-zinc-900 dark:text-zinc-100">
                    {getClientName(sale.memberId)}
                  </TableCell>
                  <TableCell className="px-6 py-4 text-xs font-light text-zinc-650 dark:text-zinc-350">
                    <div className="flex flex-col gap-1">
                      {sale.items && sale.items.length > 0 ? (
                        sale.items.map((item, idx) => (
                          <span key={idx}>
                            {item.name}{" "}
                            <strong className="font-semibold text-zinc-900 dark:text-white">
                              x{item.quantity}
                            </strong>
                          </span>
                        ))
                      ) : (
                        <span>--</span>
                      )}
                    </div>
                  </TableCell>
                  <TableCell className="px-6 py-4 text-xs text-zinc-500 dark:text-zinc-400 font-light">
                    {sale.paymentMethod === "Cash" ? "В брой" : (sale.paymentMethod || "В брой")}
                  </TableCell>
                  <TableCell className="px-6 py-4">
                    <Badge
                      className={`px-2 py-0.5 rounded text-[9px] font-bold uppercase tracking-widest border shadow-none ${
                        sale.isPaid
                          ? "bg-emerald-50 text-emerald-600 border-emerald-100 dark:bg-emerald-950/20 dark:text-emerald-400 dark:border-emerald-900/30"
                          : "bg-amber-50 text-amber-600 border-amber-100 dark:bg-amber-950/20 dark:text-amber-400 dark:border-amber-900/30"
                      }`}
                    >
                      {sale.isPaid ? "Платено" : "Неплатено"}
                    </Badge>
                  </TableCell>
                  <TableCell className="px-6 py-4 text-right font-semibold text-sm text-zinc-900 dark:text-white">
                    {formatPrice(sale.totalAmount)}
                  </TableCell>
                  <TableCell className="py-4 text-right pr-6">
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8 text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-100"
                          disabled={isDeleting === sale.id}
                        >
                          {isDeleting === sale.id ? (
                            <Loader2 className="h-4 w-4 animate-spin" />
                          ) : (
                            <MoreVertical className="h-4 w-4" />
                          )}
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end" className="w-[160px] rounded-xl">
                        <DropdownMenuItem
                          onClick={() => router.push(`/inventory/sales/${sale.id}/receipt`)}
                          className="flex items-center gap-2 text-xs font-medium cursor-pointer"
                        >
                          <Receipt className="h-3.5 w-3.5 text-zinc-500" />
                          Касова бележка
                        </DropdownMenuItem>
                        <DropdownMenuItem
                          onClick={() => router.push(`/inventory/sales/${sale.id}`)}
                          className="flex items-center gap-2 text-xs font-medium cursor-pointer"
                        >
                          <Eye className="h-3.5 w-3.5 text-zinc-500" />
                          Детайли
                        </DropdownMenuItem>
                        <DropdownMenuItem
                          onClick={() => setSaleToEdit(sale)}
                          className="flex items-center gap-2 text-xs font-medium cursor-pointer"
                        >
                          <Edit2 className="h-3.5 w-3.5 text-zinc-500" />
                          Редактирай
                        </DropdownMenuItem>
                        <DropdownMenuItem
                          onClick={() => handleDeleteSale(sale.id)}
                          className="flex items-center gap-2 text-xs font-medium text-rose-600 focus:bg-rose-50 dark:focus:bg-rose-950/30 focus:text-rose-600 cursor-pointer"
                        >
                          <Trash2 className="h-3.5 w-3.5" />
                          Изтрий
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
        {!loading && sales.length === 0 && (
          <div className="p-12 text-center text-[11px] uppercase tracking-widest text-zinc-400 font-medium">
            Няма регистрирани продажби.
          </div>
        )}
      </div>
    </div>
  );
};

export default InventorySalesHistory;

"use client";

import { useState, useEffect } from "react";
import { mutate } from "swr";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { toast } from "sonner";
import { Product, Member } from "@/types";
import { getAllMembers } from "@/services/member-service";
import { createMemberAction } from "@/lib/actions/members";
import { createSaleAction } from "@/lib/actions/sales";
import { useAuth } from "@/context/auth-context";
import { useAppStore } from "@/store/use-app-store";
import { formatPrice } from "@/lib/currency";
import { clubInfo } from "@/config/club";
import { cn } from "@/lib/utils";
import {
  ShoppingBag,
  Search,
  User,
  Check,
  CreditCard,
  Receipt,
  Loader2,
  ArrowLeft,
  ArrowRight,
  Printer,
  Sparkles,
  PlusCircle,
} from "lucide-react";

interface ProductSaleWizardDialogProps {
  product: Product;
  isOpen: boolean;
  onClose: () => void;
  onSaleSuccess: () => void;
}

export const ProductSaleWizardDialog = ({
  product,
  isOpen,
  onClose,
  onSaleSuccess,
}: ProductSaleWizardDialogProps) => {
  const [step, setStep] = useState(1);
  const [members, setMembers] = useState<Member[]>([]);
  const [membersLoading, setMembersLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedMember, setSelectedMember] = useState<Member | null>(null);

  const [clientTypeTab, setClientTypeTab] = useState<"member" | "guest">(
    "member"
  );
  const [showNewGuestForm, setShowNewGuestForm] = useState(false);
  const [newGuestFirstName, setNewGuestFirstName] = useState("");
  const [newGuestLastName, setNewGuestLastName] = useState("");
  const [newGuestPhone, setNewGuestPhone] = useState("");
  const [newGuestEmail, setNewGuestEmail] = useState("");
  const [isSavingNewGuest, setIsSavingNewGuest] = useState(false);

  // Form states
  const [quantity, setQuantity] = useState("1");
  const [paymentMethod, setPaymentMethod] = useState("В брой");
  const [isPaid, setIsPaid] = useState(true);
  const [note, setNote] = useState("");
  const [isProcessing, setIsProcessing] = useState(false);
  const [completedSaleId, setCompletedSaleId] = useState<string | null>(null);

  const { idToken } = useAuth();
  const { activeBranch } = useAppStore();

  // Load members
  useEffect(() => {
    if (isOpen) {
      const fetchMembers = async () => {
        setMembersLoading(true);
        try {
          const fetchedMembers = await getAllMembers();
          setMembers(fetchedMembers);
        } catch (err) {
          console.error("Error loading members:", err);
          toast.error("Грешка", {
            description: "Неуспешно зареждане на клубните членове.",
          });
        } finally {
          setMembersLoading(false);
        }
      };
      fetchMembers();

      // Reset state on open
      setStep(1);
      setQuantity("1");
      setSelectedMember(null);
      setCompletedSaleId(null);
      setNote("");
      setClientTypeTab("member");
      setShowNewGuestForm(false);
      setNewGuestFirstName("");
      setNewGuestLastName("");
      setNewGuestPhone("");
      setNewGuestEmail("");
      setIsSavingNewGuest(false);
    }
  }, [isOpen]);

  const filteredMembers = members.filter((m) => {
    const isGuest = m.isGuest || m.memberType === "guest";
    const matchesTab = clientTypeTab === "guest" ? isGuest : !isGuest;
    if (!matchesTab) return false;

    const fullName = `${m.firstName} ${m.lastName}`.toLowerCase();
    return fullName.includes(searchTerm.toLowerCase());
  });

  const handleNextStep = () => {
    if (step === 1 && !selectedMember) {
      toast.error("Избор на купувач", {
        description: "Моля, изберете член от списъка, за да продължите.",
      });
      return;
    }

    if (step === 2) {
      const qtyVal = parseInt(quantity, 10);
      if (isNaN(qtyVal) || qtyVal <= 0) {
        toast.error("Невалидно количество", {
          description: "Моля, въведете валидно положително количество.",
        });
        return;
      }
      if (qtyVal > product.stock) {
        toast.error("Недостатъчна наличност", {
          description: `Имате само ${product.stock} бр. от този артикул на склад.`,
        });
        return;
      }
    }

    setStep((prev) => prev + 1);
  };

  const handlePrevStep = () => {
    setStep((prev) => prev - 1);
  };

  const handleExecuteSale = async () => {
    if (!selectedMember || !idToken) return;
    setIsProcessing(true);
    setStep(4);

    const qty = parseInt(quantity, 10);
    const totalAmount = product.price * qty;

    try {
      const saleData = {
        siteId: product.siteId || activeBranch || "bkgalabovo",
        memberId: selectedMember.id,
        saleDate: new Date().toISOString(),
        items: [
          {
            productId: product.id,
            name: product.name,
            quantity: qty,
            price: product.price,
          },
        ],
        status: "completed",
        isPaid: isPaid,
        totalAmount: totalAmount,
        currency: "EUR",
        paymentMethod: paymentMethod,
        note: note || "",
        clientName:
          selectedMember.id === "GUEST_EXTERNAL"
            ? "Външен клиент"
            : `${selectedMember.firstName} ${selectedMember.lastName}`,
      };

      const result = await createSaleAction(idToken, saleData);

      if (result.success && result.data) {
        const saleId = (result.data as { id: string }).id;
        setCompletedSaleId(saleId);
        setStep(5);
        if (selectedMember.id !== "GUEST_EXTERNAL") {
          mutate(selectedMember.id);
        }
        toast.success("Готово!", {
          description: "Продажбата бе регистрирана успешно.",
        });
      } else {
        setStep(3);
        toast.error("Грешка", { description: result.message });
      }
    } catch (error) {
      setStep(3);
      toast.error("Грешка при продажба", {
        description: (error as Error).message,
      });
    } finally {
      setIsProcessing(false);
    }
  };

  const handleClose = () => {
    if (completedSaleId) {
      onSaleSuccess();
    } else {
      onClose();
    }
  };

  const qty = parseInt(quantity, 10) || 1;
  const totalAmount = product.price * qty;

  return (
    <Dialog open={isOpen} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-[600px] p-8 sm:p-10 rounded-4xl bg-white dark:bg-zinc-950 border-none shadow-xl max-h-[90vh] overflow-y-auto custom-scrollbar">
        <DialogHeader className="mb-6">
          <DialogTitle className="text-2xl font-light text-zinc-955 dark:text-zinc-50 flex items-center gap-3">
            <ShoppingBag
              className="h-6 w-6 text-emerald-500"
              strokeWidth={1.5}
            />
            Бърза Продажба: {product.name}
          </DialogTitle>
          <DialogDescription className="font-light text-zinc-400 mt-1">
            {step < 5 ? (
              <span>
                Стъпка {step} от 4: Попълнете детайлите за продажба на артикула.
              </span>
            ) : (
              <span>Продажбата е завършена успешно. Благодарим ви!</span>
            )}
          </DialogDescription>
        </DialogHeader>

        {/* STEP PROGRESS BAR */}
        {step < 5 && (
          <div className="w-full bg-zinc-100 dark:bg-zinc-900 h-1.5 rounded-full mb-8 overflow-hidden">
            <div
              className="bg-emerald-500 h-full transition-all duration-300"
              style={{ width: `${(step / 4) * 100}%` }}
            />
          </div>
        )}

        {/* STEP 1: SELECT BUYER */}
        {step === 1 && (
          <div className="space-y-6">
            <div className="flex items-center justify-between pb-2 border-b border-zinc-100 dark:border-zinc-900">
              <div className="flex items-center gap-2">
                <User className="h-4 w-4 text-emerald-500" strokeWidth={1.5} />
                <h3 className="text-sm font-semibold text-zinc-955 dark:text-zinc-50">
                  Избор на клиент
                </h3>
              </div>
            </div>

            {showNewGuestForm ? (
              /* QUICK NEW GUEST FORM */
              <div className="space-y-4 p-5 border border-amber-200 dark:border-amber-900/35 bg-amber-50/20 dark:bg-amber-950/5 rounded-2xl animate-in fade-in duration-300">
                <h4 className="text-xs font-bold uppercase tracking-wider text-amber-800 dark:text-amber-400">
                  Регистрация на Нов Външен клиент (Гост)
                </h4>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <Label className="text-[10px] font-bold uppercase text-zinc-500">
                      Име *
                    </Label>
                    <Input
                      placeholder="Име"
                      value={newGuestFirstName}
                      onChange={(e) => setNewGuestFirstName(e.target.value)}
                      className="h-10 rounded-xl border-zinc-200 text-xs"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-[10px] font-bold uppercase text-zinc-500">
                      Фамилия *
                    </Label>
                    <Input
                      placeholder="Фамилия"
                      value={newGuestLastName}
                      onChange={(e) => setNewGuestLastName(e.target.value)}
                      className="h-10 rounded-xl border-zinc-200 text-xs"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <Label className="text-[10px] font-bold uppercase text-zinc-500">
                      Телефон *
                    </Label>
                    <Input
                      placeholder="Телефон"
                      value={newGuestPhone}
                      onChange={(e) => setNewGuestPhone(e.target.value)}
                      className="h-10 rounded-xl border-zinc-200 text-xs"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-[10px] font-bold uppercase text-zinc-500">
                      Имейл
                    </Label>
                    <Input
                      placeholder="Имейл (по избор)"
                      value={newGuestEmail}
                      onChange={(e) => setNewGuestEmail(e.target.value)}
                      className="h-10 rounded-xl border-zinc-200 text-xs"
                    />
                  </div>
                </div>

                <div className="flex gap-2 justify-end pt-2">
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    disabled={isSavingNewGuest}
                    onClick={() => setShowNewGuestForm(false)}
                    className="rounded-xl text-xs"
                  >
                    Отказ
                  </Button>
                  <Button
                    type="button"
                    size="sm"
                    disabled={isSavingNewGuest}
                    onClick={async () => {
                      if (
                        !newGuestFirstName ||
                        !newGuestLastName ||
                        !newGuestPhone
                      ) {
                        toast.error("Непълни данни", {
                          description:
                            "Моля, попълнете Име, Фамилия и Телефон на госта.",
                        });
                        return;
                      }
                      setIsSavingNewGuest(true);
                      try {
                        const result = await createMemberAction(idToken!, {
                          firstName: newGuestFirstName,
                          lastName: newGuestLastName,
                          phone: newGuestPhone,
                          email: newGuestEmail || "",
                          isGuest: true,
                          memberType: "guest",
                          status: "active",
                          siteId: activeBranch || "bkgalabovo",
                        });

                        if (result.success && result.data) {
                          const newGuestObj: Member = {
                            id: result.data.id,
                            firstName: newGuestFirstName,
                            lastName: newGuestLastName,
                            name: `${newGuestFirstName} ${newGuestLastName}`,
                            phone: newGuestPhone,
                            email: newGuestEmail || "",
                            isGuest: true,
                            memberType: "guest",
                            status: "active",
                            siteId: activeBranch || "bkgalabovo",
                            registrationDate: new Date().toISOString(),
                          } as any;

                          setMembers((prev) => [newGuestObj, ...prev]);
                          setSelectedMember(newGuestObj);

                          toast.success("Успех!", {
                            description:
                              "Външният клиент беше регистриран и избран успешно.",
                          });

                          setShowNewGuestForm(false);
                          setNewGuestFirstName("");
                          setNewGuestLastName("");
                          setNewGuestPhone("");
                          setNewGuestEmail("");
                          setStep(2); // Go to step 2 details
                        } else {
                          toast.error("Грешка при регистрация", {
                            description: result.message,
                          });
                        }
                      } catch (err) {
                        console.error("Error creating quick guest:", err);
                        toast.error("Системна грешка при регистрация.");
                      } finally {
                        setIsSavingNewGuest(false);
                      }
                    }}
                    className="rounded-xl text-xs bg-amber-500 hover:bg-amber-600 text-white animate-in"
                  >
                    {isSavingNewGuest ? (
                      <Loader2 className="h-3 w-3 animate-spin mr-1" />
                    ) : null}
                    Регистрирай и избери
                  </Button>
                </div>
              </div>
            ) : (
              /* SELECTION TABS & MEMBER/GUEST SEARCH */
              <div className="space-y-4">
                <div className="flex bg-zinc-100 dark:bg-zinc-900 rounded-xl p-1 gap-1">
                  <button
                    type="button"
