const InfoRow = ({
  icon: Icon,
  label,
  value,
  isBlock = false,
}: {
  icon: React.ElementType;
  label: string;
  value: string | null | undefined;
  isBlock?: boolean;
}) => {
  if (value === null || value === undefined || value === "") return null;

  return (
    <div
      className={cn(
        "flex py-4 sm:py-6 border-b border-zinc-50 last:border-0",
        isBlock
          ? "flex-col items-start gap-3 sm:gap-4"
          : "flex-col sm:flex-row items-start sm:items-center justify-between gap-2 sm:gap-4"
      )}
    >
      <div className="flex items-center gap-4">
        <div className="w-8 h-8 rounded-lg bg-zinc-50 flex items-center justify-center shrink-0">
          <Icon className="h-3.5 w-3.5 text-zinc-400" strokeWidth={1.5} />
        </div>
        <span className="text-[10px] font-medium uppercase tracking-widest2 text-zinc-400">
          {label}
        </span>
      </div>
      {!isBlock ? (
        <span className="text-sm font-light text-zinc-900 sm:text-right w-full sm:w-auto pl-12 sm:pl-0">
          {value}
        </span>
      ) : (
        <span className="text-sm font-light text-zinc-400 leading-relaxed max-w-xl pl-12">
          {value}
        </span>
      )}
    </div>
  );
};

"use client";

import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { MemberSchema, Member } from "@/types/member.types";
import { z } from "zod";

import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { BentoCard } from "@/components/ui/bento-card";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
  FormDescription,
} from "@/components/ui/form";

import {
  Save,
  X,
  ArrowRight,
  ArrowLeft,
  User,
  Phone,
  FileText,
  Activity,
  Users,
} from "lucide-react";
import { Checkbox } from "@/components/ui/checkbox";
import { useAppStore } from "@/store/use-app-store";
import { cn } from "@/lib/utils";

const MemberFormSchema = MemberSchema.omit({
  id: true,
  name: true,
  registrationDate: true,
  updatedAt: true,
});
type MemberFormValues = z.infer<typeof MemberFormSchema>;

interface MemberFormProps {
  onSave: (data: MemberFormValues) => Promise<void>;
  onClose: () => void;
  initialData?: Partial<Member>;
}

export const MemberForm = ({
  onSave,
  onClose,
  initialData,
}: MemberFormProps) => {
  const [step, setStep] = useState(1);
  const { activeBranch } = useAppStore();

  // Safely convert dateOfBirth to string for Zod validation
  const safeInitialData = { ...initialData } as any;
  if (
    safeInitialData.dateOfBirth &&
    typeof safeInitialData.dateOfBirth !== "string"
  ) {
    if (typeof safeInitialData.dateOfBirth?.toDate === "function") {
      safeInitialData.dateOfBirth = safeInitialData.dateOfBirth
        .toDate()
        .toISOString()
        .split("T")[0];
    } else if (safeInitialData.dateOfBirth instanceof Date) {
      safeInitialData.dateOfBirth = safeInitialData.dateOfBirth
        .toISOString()
        .split("T")[0];
    } else {
      safeInitialData.dateOfBirth = String(safeInitialData.dateOfBirth);
    }
  }

  const form = useForm<MemberFormValues>({
    resolver: zodResolver(MemberFormSchema),
    defaultValues: {
      siteId: activeBranch,
      firstName: "",
      middleName: "",
      lastName: "",
      educationInstitution: "",
      dateOfBirth: undefined,
      gender: "male",
      phone: "",
      email: "",
      address: "",
      emergencyContactName: "",
      emergencyContactPhone: "",
      apparelSize: "",
      status: "active",
      notes: "",
      healthConditionNotes: "",
      familyId: undefined,
      skillLevel: undefined,
      hasSignedDeclaration: false,
      hasMedicalCertificate: false,
      isLicensed: false,
      memberType: activeBranch === "recoveryzone" ? "recovery" : "regular",
      ...safeInitialData,
    },
  });

  const {
    formState: { isSubmitting },
    trigger,
    watch,
    setValue,
  } = form;

  const selectedMemberType = watch("memberType") || "regular";
  const isRecoveryBranch = activeBranch === "recoveryzone";

  // Calculate total steps based on member type
  const totalSteps = selectedMemberType === "guest" ? 2 : 3;

  const handleNextStep = async () => {
    let isValid = false;

    if (step === 1) {
      isValid = await trigger([
        "firstName",
        "middleName",
        "lastName",
        "dateOfBirth",
        "gender",
      ]);
    } else if (step === 2) {
      isValid = await trigger([
        "phone",
        "email",
        "address",
        "emergencyContactName",
        "emergencyContactPhone",
      ]);
    }

    if (isValid) {
      setStep((prev) => prev + 1);
    }
  };

  const handlePrevStep = () => {
    setStep((prev) => prev - 1);
  };

  const onSubmit = async (data: MemberFormValues) => {
    // If guest, ensure we clear out some irrelevant fields just in case
    if (data.memberType === "guest") {
      data.isGuest = true;
    } else {
      data.isGuest = false;
    }
    await onSave(data);
  };

  return (
    <Form {...form}>
      <form
        aria-label="member-form"
        onSubmit={form.handleSubmit(onSubmit)}
        className="flex flex-col h-full"
      >
        {/* STEP PROGRESS BAR */}
        <div className="w-full bg-zinc-100 dark:bg-zinc-900 h-1.5 rounded-full mb-8 overflow-hidden">
          <div
            className="bg-zinc-950 dark:bg-zinc-50 h-full transition-all duration-300"
            style={{ width: `${(step / totalSteps) * 100}%` }}
          />
        </div>

        <div className="flex-1 space-y-6 sm:space-y-8 min-h-[400px]">
          {/* СТЪПКА 1: Основна информация */}
          {step === 1 && (
            <BentoCard className="p-5 sm:p-8 border-zinc-100 shadow-none rounded-3xl sm:rounded-4xl animate-in fade-in slide-in-from-right-4 duration-300">
              {/* Type Selection (Only for Badminton Club) */}
              {!isRecoveryBranch && (
                <div className="mb-8 pb-8 border-b border-zinc-100">
                  <FormLabel className="text-[10px] sm:text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-500 block mb-4">
                    Тип на профила *
                  </FormLabel>
                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                    <button
                      type="button"
                      onClick={() => setValue("memberType", "regular")}
                      className={cn(
                        "flex flex-col items-center justify-center p-4 rounded-2xl border-2 transition-all",
                        selectedMemberType === "regular"
                          ? "border-zinc-950 bg-zinc-50 dark:border-white dark:bg-zinc-900"
                          : "border-zinc-100 hover:border-zinc-200 bg-white dark:bg-zinc-950 dark:border-zinc-800"
                      )}
                    >
                      <Users
                        className={cn(
                          "h-6 w-6 mb-2",
                          selectedMemberType === "regular"
                            ? "text-zinc-950 dark:text-white"
                            : "text-zinc-400"
                        )}
                      />
                      <span
                        className={cn(
                          "text-xs font-semibold uppercase tracking-wider",
                          selectedMemberType === "regular"
                            ? "text-zinc-950 dark:text-white"
                            : "text-zinc-500"
                        )}
                      >
                        Клубен Член
                      </span>
                      <span className="text-[10px] text-zinc-400 text-center mt-1">
                        Пълно досие с документи
                      </span>
                    </button>

                    <button
                      type="button"
                      onClick={() => setValue("memberType", "recovery")}
                      className={cn(
                        "flex flex-col items-center justify-center p-4 rounded-2xl border-2 transition-all",
                        selectedMemberType === "recovery"
                          ? "border-emerald-500 bg-emerald-50 dark:bg-emerald-950/20"
                          : "border-zinc-100 hover:border-zinc-200 bg-white dark:bg-zinc-950 dark:border-zinc-800"
                      )}
                    >
                      <Activity
                        className={cn(
                          "h-6 w-6 mb-2",
                          selectedMemberType === "recovery"
                            ? "text-emerald-600 dark:text-emerald-400"
                            : "text-zinc-400"
                        )}
                      />
                      <span
                        className={cn(
                          "text-xs font-semibold uppercase tracking-wider",
                          selectedMemberType === "recovery"
                            ? "text-emerald-700 dark:text-emerald-400"
                            : "text-zinc-500"
                        )}
                      >
                        Възстановяване
                      </span>
                      <span className="text-[10px] text-zinc-400 text-center mt-1">
                        Досие + Здравен статус
                      </span>
                    </button>

                    <button
                      type="button"
                      onClick={() => setValue("memberType", "guest")}
                      className={cn(
                        "flex flex-col items-center justify-center p-4 rounded-2xl border-2 transition-all",
                        selectedMemberType === "guest"
                          ? "border-amber-500 bg-amber-50 dark:bg-amber-950/20"
                          : "border-zinc-100 hover:border-zinc-200 bg-white dark:bg-zinc-950 dark:border-zinc-800"
                      )}
                    >
                      <User
                        className={cn(
                          "h-6 w-6 mb-2",
                          selectedMemberType === "guest"
                            ? "text-amber-600 dark:text-amber-400"
                            : "text-zinc-400"
                        )}
                      />
                      <span
                        className={cn(
                          "text-xs font-semibold uppercase tracking-wider",
                          selectedMemberType === "guest"
                            ? "text-amber-700 dark:text-amber-400"
                            : "text-zinc-500"
                        )}
                      >
                        Външен / Гост
                      </span>
                      <span className="text-[10px] text-zinc-400 text-center mt-1">
                        Бърз профил (име и телефон)
                      </span>
                    </button>
                  </div>
                </div>
              )}

              <div className="flex items-center gap-2 mb-6">
                <User className="h-4 w-4 text-zinc-400" strokeWidth={1.5} />
                <h3 className="text-[10px] sm:text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-400">
                  Стъпка 1: Основна информация
                </h3>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-5 sm:gap-6">
                <FormField
                  name="firstName"
                  control={form.control}
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel className="text-[10px] sm:text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-500">
                        Име *
                      </FormLabel>
                      <FormControl>
                        <Input
                          {...field}
                          className="h-11 sm:h-12 rounded-xl border-zinc-100 bg-zinc-50/50 focus:bg-white focus:ring-0 text-sm"
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
                <FormField
                  name="lastName"
                  control={form.control}
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel className="text-[10px] sm:text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-500">
                        Фамилия *
                      </FormLabel>
                      <FormControl>
                        <Input
                          {...field}
                          className="h-11 sm:h-12 rounded-xl border-zinc-100 bg-zinc-50/50 focus:bg-white focus:ring-0 text-sm"
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
                {selectedMemberType === "regular" && (
                  <FormField
                    name="middleName"
                    control={form.control}
                    render={({ field }) => (
                      <FormItem className="sm:col-span-2">
                        <FormLabel className="text-[10px] sm:text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-500">
                          Презиме
                        </FormLabel>
                        <FormControl>
                          <Input
                            {...field}
                            value={field.value || ""}
                            className="h-11 sm:h-12 rounded-xl border-zinc-100 bg-zinc-50/50 focus:bg-white focus:ring-0 text-sm"
                          />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                )}

                {selectedMemberType !== "guest" && (
                  <>
                    <FormField
                      control={form.control}
                      name="gender"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel className="text-[10px] sm:text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-500">
                            Пол
                          </FormLabel>
                          <Select
                            onValueChange={field.onChange}
                            defaultValue={field.value || undefined}
                          >
                            <FormControl>
                              <SelectTrigger className="h-11 sm:h-12 rounded-xl border-zinc-100 bg-zinc-50/50 focus:bg-white focus:ring-0 text-sm">
                                <SelectValue />
                              </SelectTrigger>
                            </FormControl>
                            <SelectContent className="rounded-xl border-zinc-100">
                              <SelectItem value="male">Мъж</SelectItem>
                              <SelectItem value="female">Жена</SelectItem>
                            </SelectContent>
                          </Select>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                    <FormField
                      control={form.control}
                      name="dateOfBirth"
                      render={({ field }) => {
                        const years = Array.from({ length: 90 }, (_, i) =>
                          (new Date().getFullYear() - i).toString()
                        );
                        const months = [
                          { value: "01", label: "Януари" },
                          { value: "02", label: "Февруари" },
                          { value: "03", label: "Март" },
                          { value: "04", label: "Април" },
                          { value: "05", label: "Май" },
                          { value: "06", label: "Юни" },
                          { value: "07", label: "Юли" },
                          { value: "08", label: "Август" },
                          { value: "09", label: "Септември" },
                          { value: "10", label: "Октомври" },
                          { value: "11", label: "Ноември" },
                          { value: "12", label: "Декември" },
                        ];
                        const days = Array.from({ length: 31 }, (_, i) =>
                          (i + 1).toString().padStart(2, "0")
                        );

                        let curYear = "";
                        let curMonth = "";
                        let curDay = "";

                        if (field.value) {
                          const val: any = field.value;
                          const valStr =
                            typeof val === "string"
                              ? val.split("T")[0]
                              : typeof val?.toDate === "function"
                                ? val.toDate().toISOString().split("T")[0]
                                : val instanceof Date
                                  ? val.toISOString().split("T")[0]
                                  : String(val);
                          const parts = valStr.split("-");
                          curYear = parts[0] || "";
                          curMonth = parts[1] || "";
                          curDay = parts[2] || "";
                        }

                        const updateDate = (
                          y: string,
                          m: string,
                          d: string
                        ) => {
                          if (!y) {
                            field.onChange(null);
                            return;
                          }
                          let val = y;
                          if (m) {
                            val += `-${m}`;
                            if (d) val += `-${d}`;
                          }
                          field.onChange(val);
                        };

                        return (
                          <FormItem className="flex flex-col">
                            <FormLabel className="text-[10px] sm:text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-500 mt-0.5 mb-1.5">
                              Дата на раждане
                            </FormLabel>
                            <div className="grid grid-cols-3 gap-2">
                              <Select
                                onValueChange={(v) =>
                                  updateDate(v, curMonth, curDay)
                                }
                                value={curYear || undefined}
                              >
                                <FormControl>
                                  <SelectTrigger className="h-11 sm:h-12 rounded-xl border-zinc-100 bg-zinc-50/50 focus:bg-white focus:ring-0 text-sm">
                                    <SelectValue placeholder="Година" />
                                  </SelectTrigger>
                                </FormControl>
                                <SelectContent className="max-h-[300px]">
                                  {years.map((y) => (
                                    <SelectItem key={y} value={y}>
                                      {y}
                                    </SelectItem>
                                  ))}
                                </SelectContent>
                              </Select>

                              <Select
                                onValueChange={(v) =>
                                  updateDate(
                                    curYear,
                                    v === "none" ? "" : v,
                                    curDay
                                  )
                                }
                                value={curMonth || "none"}
                              >
                                <FormControl>
                                  <SelectTrigger className="h-11 sm:h-12 rounded-xl border-zinc-100 bg-zinc-50/50 focus:bg-white focus:ring-0 text-sm">
                                    <SelectValue placeholder="Месец" />
                                  </SelectTrigger>
                                </FormControl>
                                <SelectContent>
                                  <SelectItem value="none">Месец</SelectItem>
                                  {months.map((m) => (
                                    <SelectItem key={m.value} value={m.value}>
                                      {m.label}
                                    </SelectItem>
                                  ))}
                                </SelectContent>
                              </Select>

                              <Select
                                onValueChange={(v) =>
                                  updateDate(
                                    curYear,
                                    curMonth,
                                    v === "none" ? "" : v
                                  )
                                }
                                value={curDay || "none"}
                                disabled={!curMonth}
                              >
                                <FormControl>
                                  <SelectTrigger className="h-11 sm:h-12 rounded-xl border-zinc-100 bg-zinc-50/50 focus:bg-white focus:ring-0 text-sm">
                                    <SelectValue placeholder="Ден" />
                                  </SelectTrigger>
                                </FormControl>
                                <SelectContent>
                                  <SelectItem value="none">Ден</SelectItem>
                                  {days.map((d) => (
                                    <SelectItem key={d} value={d}>
                                      {d}
                                    </SelectItem>
                                  ))}
                                </SelectContent>
                              </Select>
                            </div>
                            <FormMessage />
                          </FormItem>
                        );
                      }}
                    />
                  </>
                )}
              </div>
            </BentoCard>
          )}

          {/* СТЪПКА 2: Контакти */}
          {step === 2 && (
            <BentoCard className="p-5 sm:p-8 border-zinc-100 shadow-none rounded-3xl sm:rounded-4xl animate-in fade-in slide-in-from-right-4 duration-300">
              <div className="flex items-center gap-2 mb-6">
                <Phone className="h-4 w-4 text-zinc-400" strokeWidth={1.5} />
                <h3 className="text-[10px] sm:text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-400">
                  Стъпка 2: Контакти
                </h3>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-5 sm:gap-6">
                <FormField
                  name="phone"
                  control={form.control}
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel className="text-[10px] sm:text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-500">
                        Телефон
                      </FormLabel>
                      <FormControl>
                        <Input
                          {...field}
                          value={field.value || ""}
                          className="h-11 sm:h-12 rounded-xl border-zinc-100 bg-zinc-50/50 focus:bg-white focus:ring-0 text-sm"
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
                <FormField
                  name="email"
                  control={form.control}
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel className="text-[10px] sm:text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-500">
                        Имейл
                      </FormLabel>
                      <FormControl>
                        <Input
                          type="email"
                          {...field}
                          value={field.value || ""}
                          className="h-11 sm:h-12 rounded-xl border-zinc-100 bg-zinc-50/50 focus:bg-white focus:ring-0 text-sm"
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                {selectedMemberType !== "guest" && (
                  <FormField
                    name="address"
                    control={form.control}
                    render={({ field }) => (
                      <FormItem className="sm:col-span-2">
                        <FormLabel className="text-[10px] sm:text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-500">
                          Адрес
                        </FormLabel>
                        <FormControl>
                          <Input
                            {...field}
                            value={field.value || ""}
                            className="h-11 sm:h-12 rounded-xl border-zinc-100 bg-zinc-50/50 focus:bg-white focus:ring-0 text-sm"
                          />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                )}

                {selectedMemberType !== "guest" && (
                  <div className="sm:col-span-2 pt-6 border-t border-zinc-100 mt-2">
                    <h4 className="text-[10px] sm:text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-400 mb-4">
                      Спешен Контакт
                    </h4>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-5 sm:gap-6">
                      <FormField
                        name="emergencyContactName"
                        control={form.control}
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel className="text-[10px] sm:text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-500">
                              Име на контакт
                            </FormLabel>
                            <FormControl>
                              <Input
                                {...field}
                                value={field.value || ""}
                                className="h-11 sm:h-12 rounded-xl border-zinc-100 bg-zinc-50/50 focus:bg-white focus:ring-0 text-sm"
                              />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                      <FormField
                        name="emergencyContactPhone"
                        control={form.control}
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel className="text-[10px] sm:text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-500">
                              Телефон на контакт
                            </FormLabel>
                            <FormControl>
                              <Input
                                {...field}
                                value={field.value || ""}
                                className="h-11 sm:h-12 rounded-xl border-zinc-100 bg-zinc-50/50 focus:bg-white focus:ring-0 text-sm"
                              />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                    </div>
                  </div>
                )}
              </div>
            </BentoCard>
          )}

          {/* СТЪПКА 3: Допълнителни данни (Само за Regular и Recovery) */}
          {step === 3 && selectedMemberType !== "guest" && (
            <BentoCard className="p-5 sm:p-8 border-zinc-100 shadow-none rounded-3xl sm:rounded-4xl animate-in fade-in slide-in-from-right-4 duration-300">
              <div className="flex items-center gap-2 mb-6">
                <FileText className="h-4 w-4 text-zinc-400" strokeWidth={1.5} />
                <h3 className="text-[10px] sm:text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-400">
                  {selectedMemberType === "recovery"
                    ? "Стъпка 3: Здравно досие и бележки"
                    : "Стъпка 3: Допълнителни данни"}
                </h3>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-5 sm:gap-6">
                {selectedMemberType === "regular" && (
                  <>
                    <FormField
                      name="educationInstitution"
                      control={form.control}
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel className="text-[10px] sm:text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-500">
                            Учебно заведение
                          </FormLabel>
                          <FormControl>
                            <Input
                              {...field}
                              value={field.value || ""}
                              className="h-11 sm:h-12 rounded-xl border-zinc-100 bg-zinc-50/50 focus:bg-white focus:ring-0 text-sm"
                            />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                    <FormField
                      control={form.control}
                      name="apparelSize"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel className="text-[10px] sm:text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-500">
                            Размер екипировка
                          </FormLabel>
                          <FormControl>
                            <Input
                              {...field}
                              value={field.value || ""}
                              placeholder="напр. M, L, XL"
                              className="h-11 sm:h-12 rounded-xl border-zinc-100 bg-zinc-50/50 focus:bg-white focus:ring-0 text-sm"
                            />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                    <FormField
                      control={form.control}
                      name="skillLevel"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel className="text-[10px] sm:text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-500">
                            Ниво на умения
                          </FormLabel>
                          <Select
                            onValueChange={field.onChange}
                            defaultValue={field.value || undefined}
                          >
                            <FormControl>
                              <SelectTrigger className="h-11 sm:h-12 rounded-xl border-zinc-100 bg-zinc-50/50 focus:bg-white focus:ring-0 text-sm">
                                <SelectValue placeholder="Избери ниво" />
                              </SelectTrigger>
                            </FormControl>
                            <SelectContent className="rounded-xl border-zinc-100">
                              <SelectItem value="beginner">Начално</SelectItem>
                              <SelectItem value="intermediate">
                                Средно
                              </SelectItem>
                              <SelectItem value="advanced">
                                Напреднало
                              </SelectItem>
                              <SelectItem value="professional">
                                Професионално
                              </SelectItem>
                            </SelectContent>
                          </Select>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </>
                )}

                <FormField
                  control={form.control}
                  name="status"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel className="text-[10px] sm:text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-500">
                        Статус
                      </FormLabel>
                      <Select
                        onValueChange={field.onChange}
                        defaultValue={field.value}
                      >
                        <FormControl>
                          <SelectTrigger className="h-11 sm:h-12 rounded-xl border-zinc-100 bg-zinc-50/50 focus:bg-white focus:ring-0 text-sm">
                            <SelectValue />
                          </SelectTrigger>
                        </FormControl>
                        <SelectContent className="rounded-xl border-zinc-100">
                          <SelectItem value="active">Активен</SelectItem>
                          <SelectItem value="inactive">Неактивен</SelectItem>
                        </SelectContent>
                      </Select>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                {selectedMemberType === "regular" && (
                  <div className="sm:col-span-2 grid grid-cols-1 sm:grid-cols-3 gap-5 sm:gap-6 pt-6 border-t border-zinc-100 mt-2">
                    <FormField
                      control={form.control}
                      name="hasSignedDeclaration"
                      render={({ field }) => (
                        <FormItem className="flex flex-row items-start space-x-3 space-y-0 rounded-2xl border border-zinc-100 p-4 sm:p-5 bg-zinc-50/30">
                          <FormControl>
                            <Checkbox
                              checked={field.value}
                              onCheckedChange={field.onChange}
                              className="h-5 w-5 rounded-md border-zinc-200 data-[state=checked]:bg-zinc-950 data-[state=checked]:border-zinc-950"
                            />
                          </FormControl>
                          <div className="space-y-1 leading-none">
                            <FormLabel className="text-sm font-medium text-zinc-950">
                              Декларация
                            </FormLabel>
                            <FormDescription className="text-[10px] font-light uppercase tracking-wider text-zinc-400">
                              Подписана декларация
                            </FormDescription>
                          </div>
                        </FormItem>
                      )}
                    />
                    <FormField
                      control={form.control}
                      name="hasMedicalCertificate"
                      render={({ field }) => (
                        <FormItem className="flex flex-row items-start space-x-3 space-y-0 rounded-2xl border border-zinc-100 p-4 sm:p-5 bg-zinc-50/30">
                          <FormControl>
                            <Checkbox
                              checked={field.value}
                              onCheckedChange={field.onChange}
                              className="h-5 w-5 rounded-md border-zinc-200 data-[state=checked]:bg-zinc-950 data-[state=checked]:border-zinc-950"
                            />
                          </FormControl>
                          <div className="space-y-1 leading-none">
                            <FormLabel className="text-sm font-medium text-zinc-950">
                              Медицинско
                            </FormLabel>
                            <FormDescription className="text-[10px] font-light uppercase tracking-wider text-zinc-400">
                              Предадено за годината
                            </FormDescription>
                          </div>
                        </FormItem>
                      )}
                    />
                    <FormField
                      control={form.control}
                      name="isLicensed"
                      render={({ field }) => (
                        <FormItem className="flex flex-row items-start space-x-3 space-y-0 rounded-2xl border border-zinc-100 p-4 sm:p-5 bg-zinc-50/30">
                          <FormControl>
                            <Checkbox
                              checked={field.value}
                              onCheckedChange={field.onChange}
                              className="h-5 w-5 rounded-md border-zinc-200 data-[state=checked]:bg-zinc-950 data-[state=checked]:border-zinc-950"
                            />
                          </FormControl>
                          <div className="space-y-1 leading-none">
                            <FormLabel className="text-sm font-medium text-zinc-950">
                              Картотека
                            </FormLabel>
                            <FormDescription className="text-[10px] font-light uppercase tracking-wider text-zinc-400">
                              Картотекиран в БФБ
                            </FormDescription>
                          </div>
                        </FormItem>
                      )}
                    />
                  </div>
                )}

                {(selectedMemberType === "recovery" ||
                  selectedMemberType === "regular") && (
                  <div className="sm:col-span-2 grid grid-cols-1 sm:grid-cols-2 gap-5 sm:gap-6 pt-6 border-t border-zinc-100 mt-2">
                    {selectedMemberType === "recovery" && (
                      <FormField
                        name="healthConditionNotes"
                        control={form.control}
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel className="text-[10px] sm:text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-500">
                              Здравно състояние / Предишни травми
                            </FormLabel>
                            <FormControl>
                              <Textarea
                                {...field}
                                value={field.value || ""}
                                rows={4}
                                placeholder="Опишете предишни травми, операции, алергии или други важни състояния..."
                                className="rounded-2xl border-zinc-200 bg-white focus:bg-white focus:ring-primary focus:border-primary resize-none p-4 text-sm shadow-sm"
                              />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                    )}

                    <FormField
                      name="notes"
                      control={form.control}
                      render={({ field }) => (
                        <FormItem
                          className={cn(
                            selectedMemberType !== "recovery" && "sm:col-span-2"
                          )}
                        >
                          <FormLabel className="text-[10px] sm:text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-500">
                            Общи Бележки
                          </FormLabel>
                          <FormControl>
                            <Textarea
                              {...field}
                              value={field.value || ""}
                              rows={4}
                              className="rounded-2xl border-zinc-100 bg-zinc-50/50 focus:bg-white focus:ring-0 resize-none p-4 font-light text-sm"
                            />
                          </FormControl>
                          <FormDescription className="text-[10px] font-light uppercase tracking-wider text-zinc-400 ml-1">
                            Вътрешни бележки, видими само за администратори.
                          </FormDescription>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </div>
                )}
              </div>
            </BentoCard>
          )}
        </div>

        {/* НАВИГАЦИОННИ БУТОНИ */}
        <div className="flex justify-between items-center pt-6 mt-6 border-t border-zinc-100 dark:border-zinc-900">
          <div>
            {step > 1 ? (
              <Button
                type="button"
                variant="outline"
                onClick={handlePrevStep}
                disabled={isSubmitting}
                className="h-11 sm:h-12 px-6 rounded-xl border-zinc-200 text-[10px] sm:text-[11px] font-medium uppercase tracking-[0.2em] hover:bg-zinc-50 text-zinc-500 flex items-center gap-2"
              >
                <ArrowLeft className="h-4 w-4" strokeWidth={1.5} /> Назад
              </Button>
            ) : (
              <Button
                type="button"
                variant="outline"
                onClick={onClose}
                disabled={isSubmitting}
                className="h-11 sm:h-12 px-6 rounded-xl border-zinc-200 text-[10px] sm:text-[11px] font-medium uppercase tracking-[0.2em] hover:bg-zinc-50 text-zinc-500 flex items-center gap-2"
              >
                <X className="h-4 w-4" strokeWidth={1.5} /> Отказ
              </Button>
            )}
          </div>

          <div>
            {step < totalSteps ? (
              <Button
                type="button"
                onClick={(e) => {
                  e.preventDefault();
                  handleNextStep();
                }}
                disabled={isSubmitting}
                className="h-11 sm:h-12 px-8 rounded-xl bg-zinc-950 text-white hover:bg-zinc-900 text-[10px] sm:text-[11px] font-medium uppercase tracking-[0.2em] flex items-center gap-2"
              >
                Напред <ArrowRight className="h-4 w-4" strokeWidth={1.5} />
              </Button>
            ) : (
              <Button
                type="submit"
                disabled={isSubmitting}
                className="h-11 sm:h-12 px-8 rounded-xl bg-emerald-500 hover:bg-emerald-600 text-white text-[10px] sm:text-[11px] font-medium uppercase tracking-[0.2em] flex items-center gap-2"
              >
                <Save className="h-4 w-4" strokeWidth={1.5} />{" "}
                {initialData && Object.keys(initialData).length > 0
                  ? "Запазване"
                  : "Създаване"}
              </Button>
            )}
          </div>
        </div>
      </form>
    </Form>
  );
};

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { useSales } from "@/hooks/useSales";
import { mutate } from "swr";
import { Button } from "@/components/ui/button";
import { Loader2, MoreHorizontal, Receipt } from "lucide-react";
import { cn } from "@/lib/utils";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
  DropdownMenuSeparator,
} from "@/components/ui/dropdown-menu";
import { Badge } from "@/components/ui/badge";
import { formatPrice } from "@/lib/currency";

interface MemberSalesHistoryProps {
  memberId: string;
  memberIds?: string[];
  familyMembers?: import("@/types").Member[];
}

// Helper to determine if an item is a true subscription based on its name
const isSubscriptionItem = (name: string): boolean => {
  const lower = name.toLowerCase();
  return (
    lower.includes("месечна") ||
    lower.includes("такса") ||
    lower.includes("членски") ||
    lower.includes("абонамент") ||
    lower.includes("годишна")
  );
};

const formatPaymentMethod = (method?: string) => {
  if (!method) return "В брой";
  if (method === "Cash") return "В брой";
  return method;
};

const formatSaleDateCell = (sale: import("@/types").Sale) => {
  const start = new Date(sale.saleDate);
  const isCourtRental = 
    sale.items?.[0]?.productId?.startsWith("court_rental") || 
    sale.items?.[0]?.name?.toLowerCase()?.includes("наем на корт");

  const formattedDate = start.toLocaleDateString("bg-BG") + " г.";

  if (isCourtRental) {
    const hours = sale.items?.[0]?.quantity || 1;
    const end = new Date(start.getTime() + hours * 3600000);
    const timeRange = start.toLocaleTimeString("bg-BG", { hour: "2-digit", minute: "2-digit" }) + 
      " - " + 
      end.toLocaleTimeString("bg-BG", { hour: "2-digit", minute: "2-digit" });
    return (
      <>
        <span className="font-medium text-sm text-zinc-900 dark:text-zinc-100">
          {formattedDate}
        </span>
        <div className="text-[10px] text-zinc-500 font-semibold mt-0.5 whitespace-nowrap">
          {timeRange} ({hours} ч.)
        </div>
      </>
    );
  }

  return (
    <>
      <span className="font-medium text-sm text-zinc-900 dark:text-zinc-100">
        {formattedDate}
      </span>
      <div className="text-[10px] text-zinc-400 mt-0.5">
        {start.toLocaleTimeString("bg-BG", {
          hour: "2-digit",
          minute: "2-digit",
        })}
      </div>
    </>
  );
};

const formatSaleDateMobile = (sale: import("@/types").Sale) => {
  const start = new Date(sale.saleDate);
  const isCourtRental = 
    sale.items?.[0]?.productId?.startsWith("court_rental") || 
    sale.items?.[0]?.name?.toLowerCase()?.includes("наем на корт");

  const formattedDate = start.toLocaleDateString("bg-BG") + " г.";

  if (isCourtRental) {
    const hours = sale.items?.[0]?.quantity || 1;
    const end = new Date(start.getTime() + hours * 3600000);
    const timeRange = start.toLocaleTimeString("bg-BG", { hour: "2-digit", minute: "2-digit" }) + 
      " - " + 
      end.toLocaleTimeString("bg-BG", { hour: "2-digit", minute: "2-digit" });
    return `${formattedDate} ${timeRange} (${hours} ч.)`;
  }

  return `${formattedDate} в ${start.toLocaleTimeString("bg-BG", { hour: "2-digit", minute: "2-digit" })}`;
};

// Helper to determine badge variant and text based on status, payment status, and amount
const getStatusDetails = (
  status: string,
  isPaid: boolean,
  totalAmount: number
) => {
  if (totalAmount === 0 && status === "informational") {
    return { text: "Системна", variant: "outline" as const };
  }

  if (isPaid === false || status === "pending") {
    return { text: "Неплатено", variant: "secondary" as const };
  }

  if (status === "completed") {
    if (totalAmount === 0) {
      return { text: "Нулева", variant: "outline" as const };
    }
    return { text: "Платено", variant: "default" as const };
  }

  return { text: status, variant: "secondary" as const };
};
export const MemberSalesHistory = ({
  memberId,
  memberIds,
  familyMembers,
}: MemberSalesHistoryProps) => {
  const router = useRouter();
  const { sales, loading, error, markAsPaid, markAsUnpaid, deleteSale } =
    useSales(memberIds || memberId);

  const handleMarkAsPaid = async (saleId: string) => {
    await markAsPaid(saleId);
    mutate(memberId);
  };

  const handleMarkAsUnpaid = async (saleId: string) => {
    await markAsUnpaid(saleId);
    mutate(memberId);
  };

  const handleDeleteSale = async (saleId: string) => {
    await deleteSale(saleId);
    mutate(memberId);
  };

  const [collapsedYears, setCollapsedYears] = useState<Record<number, boolean>>(
    {}
  );

  // Group sales by year
  const salesByYear: Record<number, typeof sales> = {};
  sales.forEach((sale) => {
    const year = new Date(sale.saleDate).getFullYear();
    if (!salesByYear[year]) {
      salesByYear[year] = [];
    }
    salesByYear[year].push(sale);
  });

  const sortedYears = Object.keys(salesByYear)
    .map(Number)
    .sort((a, b) => b - a);

  const toggleYear = (year: number) => {
    setCollapsedYears((prev) => {
      const currentlyCollapsed =
        prev[year] === undefined ? year !== sortedYears[0] : prev[year];
      return {
        ...prev,
        [year]: !currentlyCollapsed,
      };
    });
  };

  const handleRowClick = (saleId: string, isPaid: boolean, type?: string) => {
    if (isPaid) {
      if (type === "general_service") {
        router.push(`/finances/general-services/sales/${saleId}/receipt`);
      } else if (type === "inventory") {
        router.push(`/inventory/sales/${saleId}/receipt`);
      } else {
        router.push(`/sales/${saleId}/receipt`);
      }
    } else {
      router.push(`/sales/${saleId}`);
    }
  };

  return (
    <div className="bg-white border border-zinc-100 rounded-3xl sm:rounded-4xl lg:rounded-5xl p-4 sm:p-8 lg:p-10">
      <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-6 mb-8 sm:mb-12">
        <div>
          <h2 className="text-2xl sm:text-3xl font-light tracking-tighter text-zinc-950 mb-2">
            История на продажбите
          </h2>
          <p className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400">
            Списък с всички регистрирани плащания и услуги.
          </p>
        </div>
      </div>

      {loading ? (
        <div className="flex justify-center py-20">
          <Loader2
            className="h-8 w-8 animate-spin text-zinc-200"
            strokeWidth={1.5}
          />
        </div>
      ) : error ? (
        <div className="p-10 text-center bg-rose-50 rounded-4xl border border-rose-100 text-rose-500 text-sm font-light">
          Грешка: {error}
        </div>
      ) : sales.length === 0 ? (
        <div className="text-center py-20 bg-zinc-50/50 border border-zinc-100 border-dashed rounded-4xl">
          <p className="text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-300">
            Няма регистрирани продажби.
          </p>
        </div>
      ) : (
        <div className="space-y-6">
          {sortedYears.map((year) => {
            const yearSales = salesByYear[year];
            const isExpanded =
              collapsedYears[year] === undefined
                ? year === sortedYears[0]
                : !collapsedYears[year];
            const yearTotal = yearSales.reduce(
              (acc, sale) => acc + sale.totalAmount,
              0
            );

            return (
              <div
                key={year}
                className="border border-zinc-100 rounded-3xl overflow-hidden bg-zinc-50/20 transition-all"
              >
                <button
                  type="button"
                  onClick={() => toggleYear(year)}
                  className="w-full flex items-center justify-between p-5 sm:p-6 bg-zinc-50/50 hover:bg-zinc-50 transition-colors text-left border-b border-zinc-100"
                >
                  <div className="flex items-center gap-3 sm:gap-4">
                    <span className="text-lg sm:text-xl font-light text-zinc-950 tracking-tight">
                      {year} г.
                    </span>
                    <Badge
                      variant="outline"
                      className="rounded-full px-2.5 py-0.5 text-[8px] sm:text-[9px] font-medium text-zinc-400 border-zinc-200 uppercase tracking-widest"
                    >
                      {yearSales.length}{" "}
                      {yearSales.length === 1 ? "запис" : "записа"}
                    </Badge>
                  </div>
                  <div className="flex items-center gap-3 sm:gap-4">
                    <span className="text-xs sm:text-sm font-medium text-zinc-950">
                      Общо: {formatPrice(yearTotal)}
                    </span>
                    <MoreHorizontal
                      className={cn(
                        "h-4 w-4 text-zinc-400 transition-transform duration-300",
                        isExpanded && "rotate-90 text-zinc-950"
                      )}
                    />
                  </div>
                </button>

                {isExpanded && (
                  <div className="p-3 sm:p-6 bg-white animate-in slide-in-from-top-1 duration-200 space-y-4">
                    {/* Desktop Table View */}
                    <div className="hidden md:block overflow-hidden rounded-2xl border border-zinc-100">
                      <Table>
                        <TableHeader>
                          <TableRow className="bg-zinc-50/50 border-zinc-100 hover:bg-zinc-50/50">
                            <TableHead className="h-10 text-[9px] font-medium uppercase tracking-[0.2em] text-zinc-400 pl-5">
                              Дата
                            </TableHead>
                            <TableHead className="h-10 text-[9px] font-medium uppercase tracking-[0.2em] text-zinc-400">
                              Услуга / Продукт
                            </TableHead>
                            <TableHead className="h-10 text-[9px] font-medium uppercase tracking-[0.2em] text-zinc-400">
                              Плащане
                            </TableHead>
                            <TableHead className="h-10 text-[9px] font-medium uppercase tracking-[0.2em] text-zinc-400">
                              Статус
                            </TableHead>
                            <TableHead className="h-10 text-[9px] font-medium uppercase tracking-[0.2em] text-zinc-400 text-right">
                              Обща сума
                            </TableHead>
                            <TableHead className="h-10 w-[60px]">
                              <span className="sr-only">Действия</span>
                            </TableHead>
                          </TableRow>
                        </TableHeader>
                        <TableBody>
                          {yearSales.map((sale) => {
                            const statusDetails = getStatusDetails(
                              sale.status,
                              sale.isPaid,
                              sale.totalAmount
                            );

                            const itemsList = sale.items
                              .map(
                                (item) =>
                                  `${item.name}${item.quantity > 1 ? ` (x${item.quantity})` : ""}`
                              )
                              .join(", ");

                            return (
                              <TableRow
                                key={sale.id}
                                onClick={() =>
                                  handleRowClick(sale.id, sale.isPaid, sale.type)
                                }
                                className="cursor-pointer border-zinc-50 hover:bg-zinc-50/50 transition-all group"
                              >
                                <TableCell className="py-4 pl-5">
                                  {formatSaleDateCell(sale)}
                                </TableCell>
                                <TableCell className="py-4 max-w-[300px]">
                                  <div
                                    className="text-xs font-medium text-zinc-900 truncate"
                                    title={itemsList}
                                  >
                                    {itemsList}
                                  </div>
                                  {isSubscriptionItem(itemsList) && (
                                    <div className="text-[9px] text-zinc-400 uppercase tracking-widest mt-0.5">
                                      Услуга
                                    </div>
                                  )}
                                  {sale.memberId !== memberId &&
                                    familyMembers && (
                                      <div className="text-[9px] text-amber-600 font-medium mt-0.5">
                                        За:{" "}
                                        {familyMembers.find(
                                          (m) => m.id === sale.memberId
                                        )?.firstName || "Семейство"}{" "}
                                        {familyMembers.find(
                                          (m) => m.id === sale.memberId
                                        )?.lastName || ""}
                                      </div>
                                    )}
                                </TableCell>
                                <TableCell className="py-4">
                                  <span className="text-sm font-light text-zinc-600 dark:text-zinc-400">
                                    {formatPaymentMethod(sale.paymentMethod)}
                                  </span>
                                </TableCell>
                                <TableCell>
                                  <Badge
                                    variant={statusDetails.variant}
                                    className={cn(
                                      "rounded-full px-2 py-0.5 text-[8px] font-medium uppercase tracking-widest border-transparent",
                                      statusDetails.variant === "default"
                                        ? "bg-emerald-500 text-white"
                                        : statusDetails.variant === "secondary"
                                          ? "bg-amber-500 text-white"
                                          : "bg-zinc-100 text-zinc-400 border-zinc-100"
                                    )}
                                  >
                                    {statusDetails.text}
                                  </Badge>
                                </TableCell>
                                <TableCell className="text-right py-4 font-medium text-xs text-zinc-950">
                                  {formatPrice(sale.totalAmount)}
                                </TableCell>
                                <TableCell
                                  className="text-right pr-5"
                                  onClick={(e) => e.stopPropagation()}
                                >
                                  <div className="flex justify-end opacity-0 group-hover:opacity-100 transition-opacity">
                                    <DropdownMenu>
                                      <DropdownMenuTrigger asChild>
                                        <Button
                                          aria-haspopup="true"
                                          size="icon"
                                          variant="ghost"
                                          className="h-7 w-7 rounded-lg text-zinc-400 hover:text-zinc-950"
                                        >
                                          <MoreHorizontal className="h-3.5 w-3.5" />
                                          <span className="sr-only">
                                            Toggle menu
                                          </span>
                                        </Button>
                                      </DropdownMenuTrigger>
                                      <DropdownMenuContent
                                        align="end"
                                        className="rounded-xl border-zinc-100 shadow-none"
                                        onClick={(e) => e.stopPropagation()}
                                      >
                                        <DropdownMenuItem
                                          onSelect={() =>
                                            handleRowClick(sale.id, sale.isPaid, sale.type)
                                          }
                                          className="text-[10px] font-medium uppercase tracking-widest py-1.5"
                                        >
                                          Преглед на квитанция
                                        </DropdownMenuItem>
                                        {sale.isPaid ? (
                                          <DropdownMenuItem
                                            onSelect={() =>
                                              handleMarkAsUnpaid(sale.id)
                                            }
                                            className="text-[10px] font-medium uppercase tracking-widest py-1.5 text-rose-500 hover:text-rose-600 hover:bg-rose-50"
                                          >
                                            Отмени плащането
                                          </DropdownMenuItem>
                                        ) : (
                                          <DropdownMenuItem
                                            onSelect={() =>
                                              handleMarkAsPaid(sale.id)
                                            }
                                            className="text-[10px] font-medium uppercase tracking-widest py-1.5 text-emerald-500 hover:text-emerald-600 hover:bg-emerald-50"
                                          >
                                            Маркирай като платено
                                          </DropdownMenuItem>
                                        )}
                                        <DropdownMenuSeparator className="bg-zinc-100" />
                                        <DropdownMenuItem
                                          onSelect={() =>
                                            handleDeleteSale(sale.id)
                                          }
                                          className="text-[10px] font-medium uppercase tracking-widest py-1.5 text-red-500 hover:text-red-600 hover:bg-red-50"
                                        >
                                          Изтрий запис
                                        </DropdownMenuItem>
                                      </DropdownMenuContent>
                                    </DropdownMenu>
                                  </div>
                                </TableCell>
                              </TableRow>
                            );
                          })}
                        </TableBody>
                      </Table>
                    </div>

                    {/* Mobile Card View */}
                    <div className="md:hidden space-y-3">
                      {yearSales.map((sale) => {
                        const statusDetails = getStatusDetails(
                          sale.status,
                          sale.isPaid,
                          sale.totalAmount
                        );

                        const itemsList = sale.items
                          .map(
                            (item) =>
                              `${item.name}${item.quantity > 1 ? ` (x${item.quantity})` : ""}`
                          )
                          .join(", ");

                        return (
                          <div
                            key={sale.id}
                            onClick={() => handleRowClick(sale.id, sale.isPaid, sale.type)}
                            className="bg-zinc-50/40 border border-zinc-100 rounded-xl p-4 active:scale-[0.98] transition-all"
                          >
                            <div className="flex justify-between items-start mb-3">
                              <div className="space-y-1">
                                <p className="text-[8px] font-medium text-zinc-400 uppercase tracking-widest">
                                  {formatSaleDateMobile(sale)}
                                </p>
                                <h3 className="text-xs font-medium text-zinc-950 line-clamp-2 leading-relaxed">
                                  {itemsList}
                                </h3>
                                {sale.memberId !== memberId &&
                                  familyMembers && (
                                    <div className="text-[9px] text-amber-600 font-medium">
                                      За:{" "}
                                      {familyMembers.find(
                                        (m) => m.id === sale.memberId
                                      )?.firstName || "Семейство"}{" "}
                                      {familyMembers.find(
                                        (m) => m.id === sale.memberId
                                      )?.lastName || ""}
                                    </div>
                                  )}
                              </div>
                              <div
                                className="flex items-center gap-2"
                                onClick={(e) => e.stopPropagation()}
                              >
                                <Badge
                                  variant={statusDetails.variant}
                                  className={cn(
                                    "rounded-full px-2 py-0.5 text-[8px] font-medium uppercase tracking-widest border-transparent shrink-0",
                                    statusDetails.variant === "default"
                                      ? "bg-emerald-500 text-white shadow-lg shadow-emerald-500/10"
                                      : statusDetails.variant === "secondary"
                                        ? "bg-amber-500 text-white shadow-lg shadow-amber-500/10"
                                        : "bg-zinc-100 text-zinc-400 border-zinc-100"
                                  )}
                                >
                                  {statusDetails.text}
                                </Badge>
                                <DropdownMenu>
                                  <DropdownMenuTrigger asChild>
                                    <Button
                                      size="icon"
                                      variant="ghost"
                                      className="h-6 w-6 rounded-lg text-zinc-400 hover:text-zinc-950"
                                    >
                                      <MoreHorizontal className="h-3 w-3" />
                                    </Button>
                                  </DropdownMenuTrigger>
                                  <DropdownMenuContent
                                    align="end"
                                    className="rounded-xl border-zinc-100 shadow-none"
                                  >
                                    <DropdownMenuItem
                                      onSelect={() =>
                                        handleRowClick(sale.id, sale.isPaid, sale.type)
                                      }
                                      className="text-[10px] font-medium uppercase tracking-widest py-1.5"
                                    >
                                      Преглед на квитанция
                                    </DropdownMenuItem>
                                    {sale.isPaid ? (
                                      <DropdownMenuItem
                                        onSelect={() =>
                                          handleMarkAsUnpaid(sale.id)
                                        }
                                        className="text-[10px] font-medium uppercase tracking-widest py-1.5 text-rose-500 hover:text-rose-600 hover:bg-rose-50"
                                      >
                                        Отмени плащането
                                      </DropdownMenuItem>
                                    ) : (
                                      <DropdownMenuItem
                                        onSelect={() =>
                                          handleMarkAsPaid(sale.id)
                                        }
                                        className="text-[10px] font-medium uppercase tracking-widest py-1.5 text-emerald-500 hover:text-emerald-600 hover:bg-emerald-50"
                                      >
                                        Маркирай като платено
                                      </DropdownMenuItem>
                                    )}
                                    <DropdownMenuSeparator className="bg-zinc-100" />
                                    <DropdownMenuItem
                                      onSelect={() => handleDeleteSale(sale.id)}
                                      className="text-[10px] font-medium uppercase tracking-widest py-1.5 text-red-500 hover:text-red-600 hover:bg-red-50"
                                    >
                                      Изтрий запис
                                    </DropdownMenuItem>
                                  </DropdownMenuContent>
                                </DropdownMenu>
                              </div>
                            </div>
                            <div className="flex justify-between items-center pt-3 border-t border-zinc-100/50">
                              <div className="flex flex-wrap items-center gap-1.5">
                                <div className="h-5 w-5 rounded-full bg-white border border-zinc-100 flex items-center justify-center">
                                  <Receipt className="h-2.5 w-2.5 text-zinc-400" />
                                </div>
                                <span className="text-[8px] text-zinc-400 uppercase tracking-widest font-medium">
                                  {sale.type === "general_service"
                                    ? "Клубна Услуга"
                                    : isSubscriptionItem(itemsList)
                                      ? "Услуга"
                                      : "Продажба"}
                                </span>
                                <span className="text-[8px] text-zinc-400/80 font-normal">
                                  • {formatPaymentMethod(sale.paymentMethod)} • {new Date(sale.saleDate).toLocaleTimeString("bg-BG", { hour: "2-digit", minute: "2-digit" })}
                                </span>
                              </div>
                              <span className="text-sm font-medium tracking-tight text-zinc-950">
                                {formatPrice(sale.totalAmount)}
                              </span>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

// src/components/reports/attendance-report.tsx
"use client";

import { useState } from "react";
import { BentoCard } from "@/components/ui/bento-card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  generateAttendanceReport,
  AttendanceReportItem,
} from "@/services/report-service";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { formatDateInput } from "@/lib/date-utils";
import { exportToCSV } from "@/lib/export-utils";
import {
  Loader2,
  Download,
  Filter,
  Calendar,
  Users,
  Activity,
  Trophy,
} from "lucide-react";
import { Badge } from "@/components/ui/badge";

interface AttendanceReportProps {
  initialReportData: AttendanceReportItem[];
  initialStartDate: string;
  initialEndDate: string;
}

const AttendanceReport = ({
  initialReportData,
  initialStartDate,
  initialEndDate,
}: AttendanceReportProps) => {
  const [startDate, setStartDate] = useState<Date | undefined>(
    () => new Date(initialStartDate)
  );
  const [endDate, setEndDate] = useState<Date | undefined>(
    () => new Date(initialEndDate)
  );
  const [reportData, setReportData] = useState<AttendanceReportItem[]>(
    initialReportData
  );
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleDateChange =
    (setter: (date: Date | undefined) => void) =>
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const dateString = e.target.value;
      if (dateString) {
        const [year, month, day] = dateString.split("-").map(Number);
        setter(new Date(year, month - 1, day));
      } else {
        setter(undefined);
      }
    };

  const handleGenerateReport = async () => {
    if (!startDate || !endDate) {
      setError("Моля, изберете начална и крайна дата.");
      return;
    }
    setError(null);
    setIsLoading(true);
    try {
      const data = await generateAttendanceReport(startDate, endDate);
      setReportData(data);
    } catch (err) {
      setError("Възникна грешка при генериране на справката.");
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleExport = () => {
    if (reportData.length === 0) return;

    const csvData = reportData.map((item) => ({
      Име: `${item.member.firstName} ${item.member.lastName}`,
      Посещения: item.attendanceCount,
      Имейл: item.member.email || "N/A",
      Телефон: item.member.phone || "N/A",
    }));

    exportToCSV(csvData, `attendance-report-${formatDateInput(new Date())}`);
  };

  const totalAttendance = reportData.reduce(
    (sum, item) => sum + item.attendanceCount,
    0
  );
  const topAttendee =
    reportData.length > 0
      ? reportData.sort((a, b) => b.attendanceCount - a.attendanceCount)[0]
      : null;

  return (
    <div className="space-y-6">
      {/* Filters Card */}
      <BentoCard className="p-8 bg-white border border-zinc-100 shadow-none rounded-4xl">
        <div className="flex flex-col md:flex-row gap-6 items-end">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 flex-1">
            <div className="space-y-3">
              <Label className="text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-400 ml-1 flex items-center gap-2">
                <Calendar className="h-3.5 w-3.5" strokeWidth={1.5} /> Начална
                дата
              </Label>
              <Input
                type="date"
                value={startDate ? formatDateInput(startDate) : ""}
                onChange={handleDateChange(setStartDate)}
                className="h-12 rounded-xl border-zinc-100 bg-zinc-50/50 shadow-none focus:ring-zinc-200 font-light"
              />
            </div>
            <div className="space-y-3">
              <Label className="text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-400 ml-1 flex items-center gap-2">
                <Calendar className="h-3.5 w-3.5" strokeWidth={1.5} /> Крайна
                дата
              </Label>
              <Input
                type="date"
                value={endDate ? formatDateInput(endDate) : ""}
                onChange={handleDateChange(setEndDate)}
                className="h-12 rounded-xl border-zinc-100 bg-zinc-50/50 shadow-none focus:ring-zinc-200 font-light"
              />
            </div>
          </div>

          <div className="flex gap-3 w-full md:w-auto">
            <Button
              onClick={handleGenerateReport}
              disabled={isLoading}
              className="flex-1 md:flex-none rounded-xl bg-zinc-950 text-white hover:bg-zinc-800 font-medium text-[11px] uppercase tracking-widest h-12 px-8 shadow-none transition-all"
            >
              {isLoading ? (
                <Loader2 className="mr-3 h-4 w-4 animate-spin" />
              ) : (
                <Filter className="mr-3 h-4 w-4" strokeWidth={1.5} />
              )}
              Генерирай
            </Button>
            {reportData.length > 0 && (
              <Button
                onClick={handleExport}
                variant="outline"
                className="rounded-xl border-zinc-100 hover:bg-zinc-50 font-medium text-[11px] uppercase tracking-widest h-12 px-8 transition-all"
              >
                <Download className="mr-3 h-4 w-4" strokeWidth={1.5} /> Експорт
              </Button>
            )}
          </div>
        </div>
        {error && (
          <p className="text-rose-500 text-[11px] font-medium uppercase tracking-widest mt-6 ml-1">
            {error}
          </p>
        )}
      </BentoCard>

      {/* Stats Cards */}
      {reportData.length > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          <BentoCard className="p-8 bg-white border border-zinc-100 rounded-4xl shadow-none">
            <div className="flex items-center gap-4 mb-3 text-zinc-400">
              <Activity className="h-5 w-5" strokeWidth={1.5} />
              <span className="text-[11px] font-medium uppercase tracking-[0.2em]">
                Общо посещения
              </span>
            </div>
            <p className="text-4xl font-light tracking-tighter text-zinc-900">
              {totalAttendance}
            </p>
          </BentoCard>

          <BentoCard className="p-8 bg-white border border-zinc-100 rounded-4xl shadow-none">
            <div className="flex items-center gap-4 mb-3 text-zinc-400">
              <Users className="h-5 w-5" strokeWidth={1.5} />
              <span className="text-[11px] font-medium uppercase tracking-[0.2em]">
                Активни членове
              </span>
            </div>
            <p className="text-4xl font-light tracking-tighter text-zinc-900">
              {reportData.length}
            </p>
          </BentoCard>

          <BentoCard className="p-8 bg-white border border-zinc-100 rounded-4xl shadow-none relative group">
            <Trophy
              className="absolute top-8 right-8 h-8 w-8 text-zinc-100 group-hover:text-amber-100 transition-colors"
              strokeWidth={1}
            />
            <div className="flex items-center gap-4 mb-3 text-zinc-400">
              <Trophy className="h-5 w-5" strokeWidth={1.5} />
              <span className="text-[11px] font-medium uppercase tracking-[0.2em]">
                Най-активен
              </span>
            </div>
            <p className="text-xl font-light text-zinc-900 truncate">
              {topAttendee
                ? `${topAttendee.member.firstName} ${topAttendee.member.lastName}`
                : "N/A"}
            </p>
            <p className="text-[10px] font-medium text-zinc-400 uppercase tracking-widest mt-2">
              {topAttendee?.attendanceCount} посещения
            </p>
          </BentoCard>
        </div>
      )}

      {/* Table Card */}
      <BentoCard className="p-0 overflow-hidden bg-white border border-zinc-100 shadow-none rounded-5xl">
        <div className="p-8 border-b border-zinc-50 flex items-center justify-between">
          <h3 className="font-medium text-[11px] uppercase tracking-[0.2em] text-zinc-400 flex items-center gap-3">
            <Users className="h-4 w-4 text-primary" strokeWidth={1.5} />
            Списък с присъствия
          </h3>
          <Badge
            variant="outline"
            className="rounded-full px-4 py-1 text-[10px] font-medium uppercase tracking-widest border-zinc-100 text-zinc-400"
          >
            {reportData.length} резултата
          </Badge>
        </div>

        {isLoading ? (
          <div className="p-32 text-center">
            <Loader2
              className="h-10 w-10 animate-spin mx-auto text-zinc-200 mb-6"
              strokeWidth={1}
            />
            <p className="text-[11px] font-medium uppercase tracking-[0.3em] text-zinc-400">
              Обработка на данни...
            </p>
          </div>
        ) : reportData.length > 0 ? (
          <div className="overflow-x-auto">
            <Table>
              <TableHeader className="bg-zinc-50/50">
                <TableRow className="border-none hover:bg-transparent h-16">
                  <TableHead className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 px-8">
                    Член
                  </TableHead>
                  <TableHead className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400">
                    Контакти
                  </TableHead>
                  <TableHead className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 text-right pr-8">
                    Брой посещения
                  </TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {reportData.map((item) => (
                  <TableRow
                    key={item.member.id}
                    className="border-zinc-50 hover:bg-zinc-50/50 transition-colors h-24"
                  >
                    <TableCell className="px-8">
                      <p className="font-medium text-sm text-zinc-900">{`${item.member.firstName} ${item.member.lastName}`}</p>
                      <p className="text-[10px] font-light text-zinc-400 uppercase tracking-widest mt-1">
                        {item.member.status}
                      </p>
                    </TableCell>
                    <TableCell>
                      <p className="text-sm font-light text-zinc-600">
                        {item.member.email || "—"}
                      </p>
                      <p className="text-xs font-light text-zinc-400 mt-1">
                        {item.member.phone || "—"}
                      </p>
                    </TableCell>
                    <TableCell className="text-right pr-8">
                      <span className="inline-flex items-center justify-center h-10 w-16 rounded-xl bg-zinc-50 text-zinc-900 font-medium text-sm border border-zinc-100">
                        {item.attendanceCount}
                      </span>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        ) : (
          <div className="p-32 text-center">
            <div className="h-16 w-16 bg-zinc-50 rounded-2xl flex items-center justify-center mx-auto mb-6">
              <Activity className="h-8 w-8 text-zinc-200" strokeWidth={1} />
            </div>
            <p className="text-sm font-light text-zinc-400 tracking-wide">
              Няма намерени данни за избрания период.
            </p>
          </div>
        )}
      </BentoCard>
    </div>
  );
};

export default AttendanceReport;

"use client";

import { useState, useEffect, useTransition } from "react";
import {
  FinancialReportData,
  generateFinancialReportAction,
} from "@/lib/actions/reports";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableFooter,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

import {
  FileSpreadsheet,
  FileText,
  ChevronDown,
  Download,
  TrendingUp,
  PieChart as PieChartIcon,
  Calendar as CalendarIcon,
  Filter,
  Loader2,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  exportFinancialToExcel,
  exportFinancialToPdf,
} from "@/lib/export-utils";
import { formatDateInput, formatDateShort } from "@/lib/date-utils";
import { formatPrice } from "@/lib/currency";
import {
  PieChart,
  Pie,
  Cell,
  ResponsiveContainer,
  Tooltip,
  Legend,
} from "recharts";
import { cn } from "@/lib/utils";
import { Badge } from "@/components/ui/badge";

interface FinancialReportProps {
  initialData: FinancialReportData;
}

const FinancialReport = ({ initialData }: FinancialReportProps) => {
  const [data, setData] = useState<FinancialReportData>(initialData);
  const [isPending, startTransition] = useTransition();

  // Filters
  const [dateFrom, setDateFrom] = useState<Date | undefined>(() => {
    const d = new Date();
    return new Date(d.getFullYear(), d.getMonth(), 1);
  });
  const [dateTo, setDateTo] = useState<Date | undefined>(() => new Date());
  const [paymentType, setPaymentType] = useState<string>("all");

  useEffect(() => {
    startTransition(async () => {
      const fromStr = dateFrom ? dateFrom.toISOString() : null;
      const toStr = dateTo ? dateTo.toISOString() : null;
      const result = await generateFinancialReportAction(
        fromStr,
        toStr,
        paymentType
      );
      setData(result);
    });
  }, [dateFrom, dateTo, paymentType]);

  const handleDateChange =
    (setter: (date: Date | undefined) => void) =>
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const dateString = e.target.value;
      if (dateString) {
        const [year, month, day] = dateString.split("-").map(Number);
        setter(new Date(year, month - 1, day));
      } else {
        setter(undefined);
      }
    };

  return (
    <div className="space-y-10 animate-in fade-in duration-700">
      {/* Top Controls */}
      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        <div className="lg:col-span-3 grid grid-cols-1 md:grid-cols-3 gap-6 bg-zinc-50/50 p-6 rounded-3xl border border-zinc-100">
          <div className="space-y-2.5">
            <Label className="text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-400 ml-1">
              От дата
            </Label>
            <div className="relative">
              <CalendarIcon
                className="absolute left-4 top-1/2 -translate-y-1/2 h-4 w-4 text-zinc-400"
                strokeWidth={1.5}
              />
              <Input
                type="date"
                value={dateFrom ? formatDateInput(dateFrom) : ""}
                onChange={handleDateChange(setDateFrom)}
                className="pl-12 rounded-xl border-zinc-100 bg-white shadow-none h-12 text-sm font-light focus:ring-zinc-200"
              />
            </div>
          </div>
          <div className="space-y-2.5">
            <Label className="text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-400 ml-1">
              До дата
            </Label>
            <div className="relative">
              <CalendarIcon
                className="absolute left-4 top-1/2 -translate-y-1/2 h-4 w-4 text-zinc-400"
                strokeWidth={1.5}
              />
              <Input
                type="date"
                value={dateTo ? formatDateInput(dateTo) : ""}
                onChange={handleDateChange(setDateTo)}
                className="pl-12 rounded-xl border-zinc-100 bg-white shadow-none h-12 text-sm font-light focus:ring-zinc-200"
              />
            </div>
          </div>
          <div className="space-y-2.5">
            <Label className="text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-400 ml-1">
              Тип приходи
            </Label>
            <Select value={paymentType} onValueChange={setPaymentType}>
              <SelectTrigger className="h-12 rounded-xl border-zinc-100 bg-white shadow-none text-sm font-light focus:ring-zinc-200">
                <div className="flex items-center gap-3">
                  <Filter className="h-4 w-4 text-zinc-400" strokeWidth={1.5} />
                  <SelectValue placeholder="Всички" />
                </div>
              </SelectTrigger>
              <SelectContent className="rounded-xl border-zinc-100 shadow-2xl">
                <SelectItem value="all">Всички</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </div>

        <div className="flex flex-col justify-end">
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button
                variant="outline"
                disabled={data.sales.length === 0 || isPending}
                className="rounded-xl h-12 border-zinc-100 font-medium text-[11px] uppercase tracking-widest px-8 transition-all hover:bg-zinc-50 flex items-center justify-between"
              >
                <div className="flex items-center">
                  {isPending ? (
                    <Loader2
                      className="mr-3 h-4 w-4 animate-spin"
                      strokeWidth={1.5}
                    />
                  ) : (
                    <Download className="mr-3 h-4 w-4" strokeWidth={1.5} />
                  )}
                  Експорт
                </div>
                <ChevronDown
                  className="ml-3 h-4 w-4 text-zinc-400"
                  strokeWidth={1.5}
                />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent
              align="end"
              className="w-48 rounded-xl p-2 shadow-xl border-zinc-100"
            >
              <DropdownMenuItem
                className="text-sm font-medium rounded-lg cursor-pointer p-3 flex items-center"
                onClick={() => {
                  const exportData = data.sales.map((s) => ({
                    date: formatDateShort(s.saleDate),
                    member: s.memberName,
                    type: "Продажба",
                    amount: s.totalAmount,
                  }));
                  exportFinancialToExcel({
                    title: "Финансов Отчет",
                    subtitle: "Бадминтон Клуб Гълъбово",
                    period: `${dateFrom ? formatDateShort(dateFrom.toISOString()) : "Начало"} - ${dateTo ? formatDateShort(dateTo.toISOString()) : "Край"}`,
                    rows: exportData,
                    total: data.total,
                  });
                }}
              >
                <FileSpreadsheet className="mr-3 h-4 w-4 text-emerald-600" />{" "}
                Експорт в Excel
              </DropdownMenuItem>
              <DropdownMenuItem
                className="text-sm font-medium rounded-lg cursor-pointer p-3 flex items-center"
                onClick={() => {
                  const exportData = data.sales.map((s) => ({
                    date: formatDateShort(s.saleDate),
                    member: s.memberName,
                    type: "Продажба",
                    amount: s.totalAmount,
                  }));
                  exportFinancialToPdf({
                    title: "Финансов Отчет",
                    subtitle: "Бадминтон Клуб Гълъбово",
                    period: `${dateFrom ? formatDateShort(dateFrom.toISOString()) : "Начало"} - ${dateTo ? formatDateShort(dateTo.toISOString()) : "Край"}`,
                    rows: exportData,
                    total: data.total,
                  });
                }}
              >
                <FileText className="mr-3 h-4 w-4 text-red-500" /> Експорт в PDF
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>

      {/* Analytics Row */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <Card className="border border-zinc-100 shadow-none bg-white rounded-4xl overflow-hidden col-span-1 lg:col-span-2">
          <CardHeader className="border-b border-zinc-50 p-8">
            <div className="flex items-center justify-between">
              <div>
                <CardTitle className="text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-400">
                  Разпределение на приходите
                </CardTitle>
                <CardDescription className="text-sm font-light mt-2">
                  Визуализация на източниците за избрания период
                </CardDescription>
              </div>
              <PieChartIcon
                className="h-5 w-5 text-zinc-200"
                strokeWidth={1.5}
              />
            </div>
          </CardHeader>
          <CardContent className="p-8 h-[350px]">
            {isPending ? (
              <div className="flex items-center justify-center h-full">
                <Loader2 className="h-8 w-8 text-zinc-300 animate-spin" />
              </div>
            ) : data.chartData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={data.chartData}
                    cx="50%"
                    cy="50%"
                    innerRadius={80}
                    outerRadius={120}
                    paddingAngle={8}
                    dataKey="value"
                    stroke="none"
                  >
                    {data.chartData.map((entry: any, index: number) => (
                      <Cell
                        key={`cell-${index}`}
                        fill={entry.color}
                        opacity={0.8}
                      />
                    ))}
                  </Pie>
                  <Tooltip
                    contentStyle={{
                      borderRadius: "16px",
                      border: "1px solid #f4f4f5",
                      boxShadow: "0 20px 25px -5px rgb(0 0 0 / 0.05)",
                      fontSize: "12px",
                      fontWeight: "300",
                    }}
                    formatter={(value: unknown) => formatPrice(Number(value))}
                  />
                  <Legend
                    verticalAlign="bottom"
                    height={36}
                    iconType="circle"
                    formatter={(value) => (
                      <span className="text-[10px] uppercase tracking-widest font-medium text-zinc-400">
                        {value}
                      </span>
                    )}
                  />
                </PieChart>
              </ResponsiveContainer>
            ) : (
              <div className="flex items-center justify-center h-full text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-300">
                Няма данни за графиката
              </div>
            )}
          </CardContent>
        </Card>

        <div className="space-y-8">
          <Card className="border-none shadow-none bg-zinc-950 text-white rounded-4xl overflow-hidden relative group">
            <div className="absolute top-0 right-0 p-8 opacity-20 group-hover:opacity-30 transition-opacity">
              <TrendingUp className="h-24 w-24 text-zinc-400" strokeWidth={1} />
            </div>
            <CardContent className="p-10 relative z-10">
              <p className="text-[11px] font-medium uppercase tracking-[0.3em] text-zinc-500">
                Общ Приход
              </p>
              <h3 className="text-5xl font-light tracking-tighter mt-6 mb-8">
                {isPending ? "—" : formatPrice(data.total)}
              </h3>
              <div className="space-y-3"></div>
            </CardContent>
          </Card>
        </div>
      </div>

      {/* Detailed Table */}
      <Card className="border border-zinc-100 shadow-none bg-white rounded-5xl overflow-hidden">
        <CardHeader className="border-b border-zinc-50 p-8">
          <CardTitle className="text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-400">
            Детайлен списък
          </CardTitle>
        </CardHeader>
        <CardContent className="p-0">
          <Table>
            <TableHeader className="bg-zinc-50/50">
              <TableRow className="border-none hover:bg-transparent h-16">
                <TableHead className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 px-8">
                  Дата
                </TableHead>
                <TableHead className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400">
                  Член
                </TableHead>
                <TableHead className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400">
                  Тип
                </TableHead>
                <TableHead className="text-right text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 pr-8">
                  Сума
                </TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {isPending ? (
                <TableRow>
                  <TableCell colSpan={4} className="h-48 text-center">
                    <Loader2 className="h-6 w-6 text-zinc-300 animate-spin mx-auto" />
                  </TableCell>
                </TableRow>
              ) : data.sales.length > 0 ? (
                data.sales.map((s) => {
                  return (
                    <TableRow
                      key={s.id}
                      className="border-zinc-50 group hover:bg-zinc-50/50 transition-colors h-20"
                    >
                      <TableCell className="px-8 text-[11px] font-medium text-zinc-400">
                        {formatDateShort(s.saleDate)}
                      </TableCell>
                      <TableCell className="text-sm font-light text-zinc-600">
                        {s.memberName}
                      </TableCell>
                      <TableCell>
                        <Badge
                          variant="outline"
                          className={cn(
                            "rounded-full text-[9px] font-medium uppercase tracking-widest border-none px-3 py-1",
                            "bg-emerald-50 text-emerald-600"
                          )}
                        >
                          Продажба
                        </Badge>
                      </TableCell>
                      <TableCell className="text-right pr-8 font-medium text-sm text-zinc-900">
                        {formatPrice(s.totalAmount)}
                      </TableCell>
                    </TableRow>
                  );
                })
              ) : (
                <TableRow>
                  <TableCell colSpan={4} className="h-48 text-center">
                    <p className="text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-300">
                      Няма транзакции за този период
                    </p>
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
            {data.sales.length > 0 && !isPending && (
              <TableFooter className="bg-zinc-50/50 border-none">
                <TableRow className="h-20 hover:bg-transparent">
                  <TableCell
                    colSpan={3}
                    className="text-right text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 pr-4"
                  >
                    Общо за периода
                  </TableCell>
                  <TableCell className="text-right pr-8 font-light text-2xl text-zinc-950">
                    {formatPrice(data.total)}
                  </TableCell>
                </TableRow>
              </TableFooter>
            )}
          </Table>
        </CardContent>
      </Card>
    </div>
  );
};

