"use client";

import { useState } from "react";
import { Member } from "@/types";
import { generateLiabilityReport } from "@/services/report-service";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { BentoCard } from "@/components/ui/bento-card";
import {
  Loader2,
  Download,
  Filter,
  AlertCircle,
  Users,
  Mail,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { exportToCSV } from "@/lib/export-utils";
import { Badge } from "@/components/ui/badge";
import { Label } from "@/components/ui/label";

interface LiabilitiesReportProps {
  initialUnpaidMembers: Member[];
  initialYear: number;
  initialMonth: number;
}

// Генерираме последните 5 години за падащото меню
const years = Array.from({ length: 5 }, (_, i) =>
  (new Date().getFullYear() - i).toString()
);
const months = [
  { value: "1", label: "Януари" },
  { value: "2", label: "Февруари" },
  { value: "3", label: "Март" },
  { value: "4", label: "Април" },
  { value: "5", label: "Май" },
  { value: "6", label: "Юни" },
  { value: "7", label: "Юли" },
  { value: "8", label: "Август" },
  { value: "9", label: "Септември" },
  { value: "10", label: "Октомври" },
  { value: "11", label: "Ноември" },
  { value: "12", label: "Декември" },
];

const LiabilitiesReport = ({
  initialUnpaidMembers,
  initialYear,
  initialMonth,
}: LiabilitiesReportProps) => {
  const [unpaidMembers, setUnpaidMembers] = useState<Member[]>(
    initialUnpaidMembers
  );
  const [isLoading, setIsLoading] = useState(false);
  const [hasSearched, setHasSearched] = useState(true);

  const [year, setYear] = useState(initialYear.toString());
  const [month, setMonth] = useState(initialMonth.toString());

  const handleGenerateReport = async () => {
    setIsLoading(true);
    setHasSearched(true);
    try {
      const reportData = await generateLiabilityReport(
        parseInt(year, 10),
        parseInt(month, 10)
      );
      setUnpaidMembers(reportData);
    } catch (error) {
      console.error("Failed to generate liability report:", error);
      setUnpaidMembers([]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleExport = () => {
    const dataToExport = unpaidMembers.map((member) => ({
      Име: member.firstName,
      Фамилия: member.lastName,
      Имейл: member.email || "Н/А",
      Телефон: member.phone || "Н/А",
    }));
    exportToCSV(dataToExport, `liability-report-${month}-${year}`);
  };

  return (
    <div className="space-y-6">
      {/* Filters Card */}
      <BentoCard className="p-8 bg-white border border-zinc-100 shadow-none rounded-4xl">
        <div className="flex flex-col md:flex-row gap-6 items-end">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 flex-1">
            <div className="space-y-3">
              <Label className="text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-400 ml-1">
                Година
              </Label>
              <Select value={year} onValueChange={setYear}>
                <SelectTrigger className="h-12 rounded-xl border-zinc-100 bg-zinc-50/50 shadow-none focus:ring-zinc-200">
                  <SelectValue placeholder="Избери година" />
                </SelectTrigger>
                <SelectContent className="rounded-xl border-zinc-100 shadow-2xl">
                  {years.map((y) => (
                    <SelectItem key={y} value={y}>
                      {y}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-3">
              <Label className="text-[11px] font-medium uppercase tracking-[0.2em] text-zinc-400 ml-1">
                Месец
              </Label>
              <Select value={month} onValueChange={setMonth}>
                <SelectTrigger className="h-12 rounded-xl border-zinc-100 bg-zinc-50/50 shadow-none focus:ring-zinc-200">
                  <SelectValue placeholder="Избери месец" />
                </SelectTrigger>
                <SelectContent className="rounded-xl border-zinc-100 shadow-2xl">
                  {months.map((m) => (
                    <SelectItem key={m.value} value={m.value}>
                      {m.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="flex gap-3 w-full md:w-auto">
            <Button
              onClick={handleGenerateReport}
              disabled={isLoading}
              className="flex-1 md:flex-none rounded-xl bg-zinc-950 text-white hover:bg-zinc-800 font-medium text-[11px] uppercase tracking-widest h-12 px-8 shadow-none transition-all"
            >
              {isLoading ? (
                <Loader2 className="mr-3 h-4 w-4 animate-spin" />
              ) : (
                <Filter className="mr-3 h-4 w-4" strokeWidth={1.5} />
              )}
              Генерирай
            </Button>
            {unpaidMembers.length > 0 && (
              <Button
                onClick={handleExport}
                variant="outline"
                className="rounded-xl border-zinc-100 hover:bg-zinc-50 font-medium text-[11px] uppercase tracking-widest h-12 px-8 transition-all"
              >
                <Download className="mr-3 h-4 w-4" strokeWidth={1.5} /> Експорт
              </Button>
            )}
          </div>
        </div>
      </BentoCard>

      {/* Summary Stat Card */}
      {hasSearched && !isLoading && unpaidMembers.length > 0 && (
        <BentoCard className="p-8 bg-white border border-rose-100 rounded-4xl shadow-none">
          <div className="flex items-center gap-4 mb-3 text-rose-500">
            <AlertCircle className="h-5 w-5" strokeWidth={1.5} />
            <span className="text-[11px] font-medium uppercase tracking-[0.2em]">
              Общо неплатили за периода
            </span>
          </div>
          <p className="text-4xl font-light tracking-tighter text-rose-600">
            {unpaidMembers.length} <span className="text-xl">души</span>
          </p>
        </BentoCard>
      )}

      {/* Results Table Card */}
      <BentoCard className="p-0 overflow-hidden bg-white border border-zinc-100 shadow-none rounded-5xl">
        <div className="p-8 border-b border-zinc-50 flex items-center justify-between">
          <h3 className="font-medium text-[11px] uppercase tracking-[0.2em] text-zinc-400 flex items-center gap-3">
            <Users className="h-4 w-4 text-primary" strokeWidth={1.5} />
            Списък на длъжници
          </h3>
          {hasSearched && (
            <Badge
              variant={unpaidMembers.length > 0 ? "destructive" : "outline"}
              className="rounded-full px-4 py-1 text-[10px] font-medium uppercase tracking-widest border-none"
            >
              {unpaidMembers.length} задължения
            </Badge>
          )}
        </div>

        {isLoading ? (
          <div className="p-32 text-center">
            <Loader2
              className="h-10 w-10 animate-spin mx-auto text-zinc-200 mb-6"
              strokeWidth={1}
            />
            <p className="text-[11px] font-medium uppercase tracking-[0.3em] text-zinc-400">
              Проверка на плащания...
            </p>
          </div>
        ) : unpaidMembers.length === 0 ? (
          <div className="p-32 text-center text-emerald-600">
            <div className="h-16 w-16 bg-emerald-50 rounded-2xl flex items-center justify-center mx-auto mb-6">
              <Users className="h-8 w-8" strokeWidth={1} />
            </div>
            <p className="text-[11px] font-medium uppercase tracking-[0.2em]">
              Браво! Всички са платили.
            </p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <Table>
              <TableHeader className="bg-zinc-50/50">
                <TableRow className="border-none hover:bg-transparent h-16">
                  <TableHead className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 px-8">
                    Член
                  </TableHead>
                  <TableHead className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400">
                    Контакти
                  </TableHead>
                  <TableHead className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 text-right pr-8">
                    Действие
                  </TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {unpaidMembers.map((member) => (
                  <TableRow
                    key={member.id}
                    className="border-zinc-50 hover:bg-zinc-50/50 transition-colors h-24"
                  >
                    <TableCell className="px-8">
                      <p className="font-medium text-sm text-zinc-900">{`${member.firstName} ${member.lastName}`}</p>
                      <p className="text-[10px] font-light text-rose-500 uppercase tracking-widest mt-1">
                        Неплатен абонамент
                      </p>
                    </TableCell>
                    <TableCell>
                      <div className="flex flex-col gap-1.5">
                        <span className="text-sm font-light text-zinc-600 flex items-center gap-2">
                          <Mail
                            className="h-3.5 w-3.5 text-zinc-300"
                            strokeWidth={1.5}
                          />{" "}
                          {member.email || "—"}
                        </span>
                        <span className="text-xs font-light text-zinc-400">
                          {member.phone || "—"}
                        </span>
                      </div>
                    </TableCell>
                    <TableCell className="text-right pr-8">
                      <Button
                        variant="ghost"
                        size="sm"
                        className="rounded-xl text-zinc-600 hover:text-rose-500 hover:bg-rose-50 font-medium text-[10px] uppercase tracking-widest px-6 h-10 transition-all"
                      >
                        Напомняне
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        )}
      </BentoCard>
    </div>
  );
};

export default LiabilitiesReport;

"use client";

import { useEffect, useState, useMemo } from "react";
import { Reservation, BlockedSlot } from "@/types/reservation";
import {
  subscribeToReservationsForDay,
  subscribeToBlockedSlotsForDay,
} from "@/lib/reservations";
import {
  deleteReservationAction,
  deleteBlockedSlotAction,
  markReservationAsPaidAction,
} from "@/lib/actions/reservations";
import { cn } from "@/lib/utils";
import {
  Loader2,
  Trash2,
  Pencil,
  Lock,
  Clock,
  User,
  Phone,
  Tag,
  CheckCircle2,
  FileText,
  Activity,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { ReservationDialog } from "./reservation-dialog";
import { BlockSlotDialog } from "./block-slot-dialog";
import { DonationReceiptDialog } from "./donation-receipt-dialog";
import { useAppStore } from "@/store/use-app-store";
import { useAuth } from "@/context/auth-context";
import { formatPrice } from "@/lib/currency";
import { getAllRecoveryServices } from "@/services/club-service";
import { ClubService } from "@/types";

interface AgendaViewProps {
  date: Date;
  courtCount: number;
  refreshKey: number;
  mode?: "courts" | "recovery";
}

type AgendaItem =
  | { type: "reservation"; data: Reservation }
  | { type: "blocked"; data: BlockedSlot };

export function AgendaView({
  date,
  courtCount,
  refreshKey: _refreshKey,
  mode,
}: AgendaViewProps) {
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [blockedSlots, setBlockedSlots] = useState<BlockedSlot[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [services, setServices] = useState<ClubService[]>([]);
  const { activeBranch } = useAppStore();
  const { getFreshToken } = useAuth();

  const effectiveBranch = mode === "recovery" ? "recoveryzone" : activeBranch;

  useEffect(() => {
    if (mode === "recovery") {
      getAllRecoveryServices().then((data) => setServices(data));
    }
  }, [mode]);

  useEffect(() => {
    const unsubReservations = subscribeToReservationsForDay(
      date,
      (res) => {
        setReservations(res);
        setIsLoading(false);
      },
      effectiveBranch
    );

    const unsubBlocked = subscribeToBlockedSlotsForDay(
      date,
      (slots) => {
        setBlockedSlots(slots);
        setIsLoading(false);
      },
      effectiveBranch
    );

    return () => {
      unsubReservations();
      unsubBlocked();
    };
  }, [date, effectiveBranch]);

  const sortedItems = useMemo(() => {
    const items: AgendaItem[] = [
      ...reservations.map((r) => ({ type: "reservation" as const, data: r })),
      ...blockedSlots.map((s) => ({ type: "blocked" as const, data: s })),
    ];

    return items.sort((a, b) => {
      const timeA = a.data.startTime.toDate().getTime();
      const timeB = b.data.startTime.toDate().getTime();
      if (timeA !== timeB) return timeA - timeB;
      // Secondary sort by court
      const courtA =
        (a.type === "reservation" ? a.data.courtId : a.data.courtIds[0]) ?? 0;
      const courtB =
        (b.type === "reservation" ? b.data.courtId : b.data.courtIds[0]) ?? 0;
      return courtA - courtB;
    });
  }, [reservations, blockedSlots]);

  const handleDeleteReservation = async (id: string) => {
    const token = await getFreshToken(true);
    if (!token) return;
    try {
      const result = await deleteReservationAction(token, id);
      if (result.success) toast.success(result.message);
      else toast.error(result.message);
    } catch {
      toast.error("Грешка при изтриване.");
    }
  };

  const handleDeleteBlockedSlot = async (id: string) => {
    const token = await getFreshToken(true);
    if (!token) return;
    try {
      const result = await deleteBlockedSlotAction(token, id);
      if (result.success) toast.success(result.message);
      else toast.error(result.message);
    } catch {
      toast.error("Грешка при изтриване.");
    }
  };

  const handleMarkAsPaid = async (id: string) => {
    const token = await getFreshToken(true);
    if (!token) return;
    try {
      const result = await markReservationAsPaidAction(token, id);
      if (result.success) {
        toast.success(result.message);
      } else {
        toast.error(result.message);
      }
    } catch {
      toast.error("Грешка при актуализиране на плащане.");
    }
  };

  if (isLoading) {
    return (
      <div className="p-12 w-full flex items-center justify-center min-h-[400px]">
        <div className="flex flex-col items-center gap-4">
          <Loader2
            className="h-10 w-10 animate-spin text-primary/30"
            strokeWidth={1.5}
          />
          <p className="text-[10px] font-bold uppercase tracking-[0.3em] text-zinc-400">
            Синхронизиране...
          </p>
        </div>
      </div>
    );
  }

  if (sortedItems.length === 0) {
    return (
      <div className="p-20 text-center flex flex-col items-center justify-center">
        <div className="w-16 h-16 bg-zinc-50 dark:bg-zinc-900 rounded-3xl flex items-center justify-center mb-6 border border-zinc-100 dark:border-zinc-800">
          <Clock className="w-6 h-6 text-zinc-300" strokeWidth={1.5} />
        </div>
        <h3 className="text-zinc-900 dark:text-white font-semibold mb-2">
          Няма планирани събития
        </h3>
        <p className="text-zinc-400 text-sm max-w-xs mx-auto">
          За избраната дата няма открити резервации или блокирани часове.
        </p>
      </div>
    );
  }

  return (
    <div className="p-4 md:p-8 space-y-4">
      {sortedItems.map((item, index) => {
        const isReservation = item.type === "reservation";
        const data = item.data;
        const startTime = data.startTime.toDate();
        const endTime = data.endTime.toDate();

        return (
          <div
            key={isReservation ? data.id : `blocked-${data.id}-${index}`}
            className={cn(
              "group relative flex flex-col md:flex-row md:items-center gap-6 p-6 rounded-4xl border transition-all duration-300",
              isReservation
                ? "bg-white dark:bg-zinc-950 border-zinc-100 dark:border-zinc-900 hover:border-primary/20 hover:shadow-xl hover:shadow-black/5"
                : "bg-zinc-50/50 dark:bg-zinc-900/50 border-zinc-200/50 dark:border-zinc-800/50 border-dashed"
            )}
          >
            {/* Time Column */}
            <div className="flex flex-row md:flex-col items-center md:items-start gap-3 md:w-32 shrink-0">
              <div className="flex items-center gap-2 text-primary">
                <Clock className="w-4 h-4" strokeWidth={2.5} />
                <span className="font-black text-sm tracking-tight">
                  {startTime.toLocaleTimeString("bg-BG", {
                    hour: "2-digit",
                    minute: "2-digit",
                  })}
                </span>
              </div>
              <div className="h-px w-4 bg-zinc-200 dark:bg-zinc-800 md:hidden" />
              <span className="text-zinc-400 font-bold text-[10px] uppercase tracking-widest">
                до{" "}
                {endTime.toLocaleTimeString("bg-BG", {
                  hour: "2-digit",
                  minute: "2-digit",
                })}
              </span>
              {isReservation && (data as Reservation).bufferAfter ? (
                <span className="text-[9px] text-amber-500/80 font-bold tracking-tight">
                  + {(data as Reservation).bufferAfter} мин. почистване
                </span>
              ) : null}
            </div>

            {/* Content Column */}
            <div className="flex-1 flex flex-col md:flex-row md:items-center gap-6">
              {/* Court Badge */}
              <div className="flex items-center gap-3">
                <div className="flex flex-col items-center justify-center min-w-12 min-h-12 py-2 px-3 rounded-2xl bg-zinc-900 dark:bg-white text-white dark:text-zinc-900 shadow-lg shadow-black/10 max-w-[200px] text-center">
                  <span className="text-[8px] font-black uppercase tracking-tighter opacity-50 mb-0.5">
                    {effectiveBranch === "bkgalabovo" ? "Корт" : "Услуга"}
                  </span>
                  <span
                    className={cn(
                      "font-bold leading-tight",
                      effectiveBranch === "bkgalabovo"
                        ? "text-sm whitespace-nowrap"
                        : "text-[11px]"
                    )}
                  >
                    {isReservation
                      ? effectiveBranch === "bkgalabovo"
                        ? (data as Reservation).courtId
                        : (() => {
                            const res = data as Reservation;
                            const svcName =
                              res.serviceName ||
                              services.find((s) => s.id === res.serviceId)
                                ?.name;
                            return svcName || "Услуга";
                          })()
                      : (data as BlockedSlot).courtIds.length > 0
                        ? `Корт ${(data as BlockedSlot).courtIds.join(", ")}`
                        : "Всички кортове"}
                  </span>
                </div>

                <div className="flex flex-col gap-1">
                  <div className="flex items-center gap-2">
                    {isReservation ? (
                      effectiveBranch === "bkgalabovo" ? (
                        <User className="w-4 h-4 text-zinc-400" />
                      ) : (
                        <Activity className="w-4 h-4 text-primary" />
                      )
                    ) : (
                      <Lock className="w-4 h-4 text-zinc-400" />
                    )}
                    <h4 className="font-bold text-zinc-900 dark:text-white group-hover:text-primary transition-colors">
                      {isReservation
                        ? (data as Reservation).client2Name ||
                          (data as Reservation).client2Zone
                          ? `${(data as Reservation).clientName}${(data as Reservation).selectedZone ? ` (${(data as Reservation).selectedZone})` : ""} & ${(data as Reservation).client2Name || "Клиент 2"}${(data as Reservation).client2Zone ? ` (${(data as Reservation).client2Zone})` : ""}`
                          : `${(data as Reservation).clientName}${(data as Reservation).selectedZone ? ` (${(data as Reservation).selectedZone})` : ""}`
                        : (data as BlockedSlot).title}
                    </h4>
                  </div>
                  {isReservation && (
                    <div className="flex items-center gap-4 text-zinc-500 text-xs font-medium">
                      <div className="flex items-center gap-1.5">
                        <Phone className="w-3 h-3 opacity-50" />
                        {(data as Reservation).client2Phone
                          ? `${(data as Reservation).clientPhone} / ${(data as Reservation).client2Phone}`
                          : (data as Reservation).clientPhone}
                      </div>
                      {(data as Reservation).clientEmail && (
                        <div className="hidden sm:flex items-center gap-1.5">
                          <Tag className="w-3 h-3 opacity-50" />
                          {(data as Reservation).clientEmail}
                        </div>
                      )}
                    </div>
                  )}
                </div>
              </div>

              {/* Status & Price */}
              <div className="md:ml-auto flex items-center gap-6">
                {isReservation ? (
                  <>
                    <div className="flex flex-col items-end">
                      <span className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-400 mb-1">
                        Статус
                      </span>
                      <span
                        className={cn(
                          "text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-lg border",
                          (data as Reservation).status === "paid"
                            ? "bg-emerald-50 text-emerald-600 border-emerald-100 dark:bg-emerald-900/20 dark:border-emerald-800"
                            : "bg-amber-50 text-amber-600 border-amber-100 dark:bg-amber-900/20 dark:border-amber-800"
                        )}
                      >
                        {(data as Reservation).status === "paid"
                          ? "Платено"
                          : "Неплатено"}
                      </span>
                    </div>
                    <div className="flex flex-col items-end min-w-[80px]">
                      <span className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-400 mb-1">
                        Сума
                      </span>
                      <span className="text-lg font-black text-zinc-900 dark:text-white tracking-tight">
                        {formatPrice(
                          (data as Reservation).totalPrice ??
                            (data as Reservation).price ??
                            0
                        )}
                      </span>
                    </div>
