              {currentStep === "review" && (
                <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
                  <div className="bg-zinc-50 dark:bg-zinc-900/50 rounded-3xl p-6 border border-zinc-100 dark:border-zinc-800 space-y-4">
                    <div className="flex items-center justify-between pb-4 border-b border-zinc-200 dark:border-zinc-800">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-xl bg-zinc-900 dark:bg-white text-white dark:text-zinc-900 flex items-center justify-center font-bold">
                          {!isRecoveryZone ? (
                            courtId
                          ) : (
                            <Activity className="w-5 h-5" />
                          )}
                        </div>
                        <div className="max-w-[180px]">
                          <p className="text-[9px] font-black text-zinc-400 uppercase tracking-widest">
                            {!isRecoveryZone ? "Избран Корт" : "Избрана Услуга"}
                          </p>
                          <p className="text-sm font-bold text-zinc-900 dark:text-white truncate">
                            {!isRecoveryZone
                              ? `Корт № ${courtId}`
                              : services.find((s) => s.id === serviceId)
                                  ?.name || "Услуга"}
                          </p>
                        </div>
                      </div>
                      <div className="text-right">
                        <p className="text-[9px] font-black text-zinc-400 uppercase tracking-widest">
                          Обща Сума
                        </p>
                        <p className="text-xl font-black text-primary tracking-tight">
                          {formatPrice(price)}
                        </p>
                      </div>
                    </div>

                    <div className="grid grid-cols-2 gap-6">
                      <div className="space-y-1">
                        <p className="text-[9px] font-black text-zinc-400 uppercase tracking-widest flex items-center gap-1">
                          <Clock className="w-3 h-3" /> График
                        </p>
                        <p className="text-xs font-bold text-zinc-700 dark:text-zinc-300">
                          {startTime?.toLocaleDateString("bg-BG")}
                          <br />
                          {startTime?.toLocaleTimeString("bg-BG", {
                            hour: "2-digit",
                            minute: "2-digit",
                          })}{" "}
                          -{" "}
                          {endTime?.toLocaleTimeString("bg-BG", {
                            hour: "2-digit",
                            minute: "2-digit",
                          })}
                        </p>
                      </div>
                      <div className="space-y-1">
                        <p className="text-[9px] font-black text-zinc-400 uppercase tracking-widest flex items-center gap-1">
                          <User className="w-3 h-3" /> Клиент
                        </p>
                        <p className="text-xs font-bold text-zinc-700 dark:text-zinc-300 truncate">
                          {clientName}
                          <br />
                          {clientPhone}
                          {clientEmail && (
                            <span className="block opacity-60 text-[10px]">
                              {clientEmail}
                            </span>
                          )}
                        </p>
                      </div>
                    </div>

                    {selectedZone && (
                      <div className="pt-4 border-t border-zinc-200 dark:border-zinc-800">
                        <p className="text-[9px] font-black text-zinc-400 uppercase tracking-widest flex items-center gap-1">
                          <Activity className="w-3 h-3" /> Избрана Зона
                        </p>
                        <p className="text-sm font-bold text-cyan-600 uppercase tracking-wider">
                          {selectedZone}
                        </p>
                      </div>
                    )}
                  </div>

                  {/* Payment Options */}
                  <div className="bg-zinc-50 dark:bg-zinc-900/50 border border-zinc-100 dark:border-zinc-800 rounded-3xl p-6 space-y-4">
                    <div className="flex items-center justify-between">
                      <div>
                        <h4 className="text-xs font-black uppercase tracking-wider text-zinc-900 dark:text-white">
                          {isEditMode
                            ? "Статус на плащане"
                            : "Плащане при създаване?"}
                        </h4>
                        <p className="text-[10px] text-zinc-400 mt-1 uppercase tracking-tight font-bold">
                          {isEditMode
                            ? "Промяна на статуса на плащане"
                            : "Маркирайте резервацията като платена веднага"}
                        </p>
                      </div>
                      <button
                        type="button"
                        onClick={() => {
                          const isPaid = form.getValues("status") === "paid";
                          form.setValue("status", isPaid ? "unpaid" : "paid");
                          if (!isPaid) form.setValue("paymentMethod", "Cash");
                        }}
                        className={cn(
                          "w-12 h-6 rounded-full p-1 transition-all duration-300 relative focus:outline-none",
                          form.watch("status") === "paid"
                            ? "bg-emerald-500"
                            : "bg-zinc-200 dark:bg-zinc-800"
                        )}
                      >
                        <div
                          className={cn(
                            "w-4 h-4 bg-white rounded-full shadow-md transition-all duration-300 absolute top-1",
                            form.watch("status") === "paid"
                              ? "left-7"
                              : "left-1"
                          )}
                        />
                      </button>
                    </div>

                    {form.watch("status") === "paid" && (
                      <div className="grid grid-cols-2 gap-3 pt-3 border-t border-zinc-200/50 dark:border-zinc-800/50 animate-in slide-in-from-top-2 duration-300">
                        <button
                          type="button"
                          onClick={() => form.setValue("paymentMethod", "Cash")}
                          className={cn(
                            "h-12 rounded-2xl text-[10px] font-black uppercase tracking-wider transition-all border-2",
                            form.watch("paymentMethod") === "Cash" ||
                              !form.watch("paymentMethod")
                              ? "bg-emerald-500 border-emerald-500 text-white shadow-lg shadow-emerald-500/20"
                              : "bg-white dark:bg-zinc-950 border-zinc-200 dark:border-zinc-800 text-zinc-500 hover:border-zinc-300"
                          )}
                        >
                          В брой
                        </button>
                        <button
                          type="button"
                          onClick={() =>
                            form.setValue("paymentMethod", "Revolut")
                          }
                          className={cn(
                            "h-12 rounded-2xl text-[10px] font-black uppercase tracking-wider transition-all border-2",
                            form.watch("paymentMethod") === "Revolut"
                              ? "bg-emerald-500 border-emerald-500 text-white shadow-lg shadow-emerald-500/20"
                              : "bg-white dark:bg-zinc-950 border-zinc-200 dark:border-zinc-800 text-zinc-500 hover:border-zinc-300"
                          )}
                        >
                          Revolut
                        </button>
                      </div>
                    )}
                  </div>

                  {isEditMode && reservation?.packageGroupId && (
                    <div className="flex items-center gap-3 p-4 bg-primary/5 rounded-2xl border border-primary/20 mt-4">
                      <div className="flex-1">
                        <h4 className="text-sm font-bold text-zinc-900 dark:text-white">
                          Приложи за целия пакет
                        </h4>
                        <p className="text-xs text-zinc-500">
                          Промяната на статуса на плащане ще се отрази на всички
                          резервации от пакета.
                        </p>
                      </div>
                      <button
                        type="button"
                        onClick={() =>
                          setApplyPaymentToPackage(!applyPaymentToPackage)
                        }
                        className={cn(
                          "w-12 h-6 rounded-full p-1 transition-all duration-300 relative focus:outline-none",
                          applyPaymentToPackage
                            ? "bg-primary"
                            : "bg-zinc-200 dark:bg-zinc-800"
                        )}
                      >
                        <div
                          className={cn(
                            "w-4 h-4 bg-white rounded-full shadow-md transition-all duration-300 absolute top-1",
                            applyPaymentToPackage ? "left-7" : "left-1"
                          )}
                        />
                      </button>
                    </div>
                  )}

                  <div className="flex items-center gap-3 p-4 bg-amber-50 dark:bg-amber-900/10 rounded-2xl border border-amber-100 dark:border-amber-900/20 text-amber-700 dark:text-amber-400">
                    <CheckCircle2 className="w-5 h-5 shrink-0" />
                    <p className="text-[10px] font-bold uppercase tracking-tight leading-relaxed">
                      Моля, прегледайте данните внимателно преди да финализирате
                      резервацията.
                    </p>
                  </div>
                </div>
              )}

              {/* Wizard Footer */}
              <div className="flex items-center gap-3 pt-4">
                {currentStep !== "time" && (
                  <Button
                    type="button"
                    variant="outline"
                    onClick={handleBack}
                    className="h-14 rounded-2xl px-6 border-zinc-200 dark:border-zinc-800 font-bold uppercase tracking-widest text-[10px]"
                  >
                    <ChevronLeft className="mr-2 h-4 w-4" /> Назад
                  </Button>
                )}

                {currentStep !== "review" ? (
                  <Button
                    type="button"
                    onClick={handleNext}
                    className="flex-1 h-14 bg-zinc-950 dark:bg-white text-white dark:text-zinc-950 hover:bg-zinc-800 dark:hover:bg-zinc-200 rounded-2xl font-bold uppercase tracking-widest text-[10px] transition-all shadow-xl shadow-black/10"
                  >
                    Продължи <ChevronRight className="ml-2 h-4 w-4" />
                  </Button>
                ) : (
                  <Button
                    type="submit"
                    disabled={isSaving || !isReviewReady}
                    className="flex-1 h-14 bg-primary hover:bg-primary/90 text-white rounded-2xl font-bold uppercase tracking-widest text-[10px] transition-all shadow-xl shadow-primary/20 border-none"
                  >
                    {isSaving ? (
                      <Loader2 className="h-5 w-5 animate-spin" />
                    ) : isEditMode ? (
                      "Запази промените"
                    ) : (
                      "Финализирай резервация"
                    )}
                  </Button>
                )}
              </div>
            </form>
          </Form>
        </div>
      </DialogContent>
    </Dialog>
  );
};

import { useReservations } from "@/hooks/useReservations";
import { useAppStore } from "@/store/use-app-store";
import { format } from "date-fns";
import { bg } from "date-fns/locale";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  User,
  Clock,
  MapPin,
  Eye,
  Search,
  Activity,
  CheckCircle2,
  FileText,
  Pencil,
  Trash2,
} from "lucide-react";
import { Input } from "@/components/ui/input";
import { useState, useEffect } from "react";
import { toast } from "sonner";
import { useAuth } from "@/context/auth-context";
import {
  deleteReservationAction,
  markReservationAsPaidAction,
} from "@/lib/actions/reservations";
import { ReservationDialog } from "./reservation-dialog";
import { DonationReceiptDialog } from "./donation-receipt-dialog";
import { getAllRecoveryServices } from "@/services/club-service";

interface ReservationHistoryProps {
  onViewInCalendar: (date: Date) => void;
  mode?: "courts" | "recovery";
}

export function ReservationHistory({
  onViewInCalendar,
  mode,
}: ReservationHistoryProps) {
  const { activeBranch } = useAppStore();
  const { getFreshToken } = useAuth();
  const [services, setServices] = useState<any[]>([]);
  const effectiveBranch = mode === "recovery" ? "recoveryzone" : activeBranch;
  const { reservations, isLoading } = useReservations(effectiveBranch);
  const [searchTerm, setSearchTerm] = useState("");

  useEffect(() => {
    if (mode === "recovery") {
      getAllRecoveryServices().then((data) => setServices(data));
    }
  }, [mode]);

  const handleDeleteReservation = async (id: string) => {
    const token = await getFreshToken(true);
    if (!token) return;
    try {
      const result = await deleteReservationAction(token, id);
      if (result.success) toast.success(result.message);
      else toast.error(result.message);
    } catch {
      toast.error("Грешка при изтриване.");
    }
  };

  const handleMarkAsPaid = async (id: string) => {
    const token = await getFreshToken(true);
    if (!token) return;
    try {
      const result = await markReservationAsPaidAction(token, id);
      if (result.success) {
        toast.success(result.message);
      } else {
        toast.error(result.message);
      }
    } catch {
      toast.error("Грешка при актуализиране на плащане.");
    }
  };

  const filteredReservations = reservations.filter(
    (res) =>
      res.clientName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      res.clientPhone.includes(searchTerm) ||
      (res.clientEmail?.toLowerCase().includes(searchTerm.toLowerCase()) ??
        false)
  );

  if (isLoading) {
    return (
      <div className="p-12 text-center text-zinc-500">
        <div className="animate-spin h-8 w-8 border-4 border-primary border-t-transparent rounded-full mx-auto mb-4" />
        Зареждане на историята...
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4 bg-zinc-50 dark:bg-zinc-900/50 p-4 rounded-2xl border border-zinc-100 dark:border-zinc-800">
        <div className="relative flex-1 max-w-sm">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-zinc-400" />
          <Input
            placeholder="Търсене по име, телефон или имейл..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-10 rounded-xl bg-white dark:bg-zinc-950 border-zinc-200 dark:border-zinc-800"
          />
        </div>
        <div className="text-[10px] font-bold uppercase tracking-widest text-zinc-400">
          Намерени: {filteredReservations.length}
        </div>
      </div>

      <div className="border border-zinc-100 dark:border-zinc-800 rounded-3xl overflow-hidden shadow-sm shadow-black/2 bg-white dark:bg-zinc-950">
        <Table>
          <TableHeader className="bg-zinc-50/50 dark:bg-zinc-900/50">
            <TableRow className="hover:bg-transparent border-zinc-100 dark:border-zinc-800">
              <TableHead className="font-bold text-[10px] uppercase tracking-widest text-zinc-400 h-12">
                Дата и Час
              </TableHead>
              <TableHead className="font-bold text-[10px] uppercase tracking-widest text-zinc-400 h-12">
                Клиент
              </TableHead>
              <TableHead className="font-bold text-[10px] uppercase tracking-widest text-zinc-400 h-12">
                Ресурс / Услуга
              </TableHead>
              <TableHead className="font-bold text-[10px] uppercase tracking-widest text-zinc-400 h-12">
                Статус
              </TableHead>
              <TableHead className="font-bold text-[10px] uppercase tracking-widest text-zinc-400 h-12">
                Цена
              </TableHead>
              <TableHead className="font-bold text-[10px] uppercase tracking-widest text-zinc-400 h-12">
                Направена от
              </TableHead>
              <TableHead className="w-[200px] text-right"></TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {filteredReservations.length === 0 ? (
              <TableRow>
                <TableCell
                  colSpan={7}
                  className="h-48 text-center text-zinc-500 font-medium"
                >
                  Няма намерени резервации.
                </TableCell>
              </TableRow>
            ) : (
              (() => {
                const seenPackages = new Set<string>();
                return filteredReservations.map((res) => {
                  const startTime = res.startTime.toDate();
                  const endTime = res.endTime.toDate();
                  const displayPrice = res.totalPrice ?? res.price ?? 0;

                  const isPackageHead = res.packageGroupId
                    ? !seenPackages.has(res.packageGroupId)
                    : false;
                  if (res.packageGroupId) {
                    seenPackages.add(res.packageGroupId);
                  }
                  const isPackageTail = res.packageGroupId && !isPackageHead;

                  const getStatusLabel = (status: string) => {
                    switch (status) {
                      case "paid":
                        return "Платена";
                      case "unpaid":
                        return "Неплатена";
                      case "cancelled":
                        return "Отказана";
                      case "confirmed":
                        return "Потвърдена";
                      case "scheduled":
                        return "Планирана";
                      case "completed":
                        return "Завършена";
                      case "pending":
                        return "Изчакваща";
                      default:
                        return status;
                    }
                  };

                  const getStatusStyles = (status: string) => {
                    switch (status) {
                      case "paid":
                      case "completed":
                      case "confirmed":
                        return "bg-emerald-500/10 text-emerald-600 hover:bg-emerald-500/20";
                      case "cancelled":
                        return "bg-red-500/10 text-red-600";
                      case "pending":
                      case "unpaid":
                        return "bg-amber-500/10 text-amber-600";
                      default:
                        return "bg-zinc-500/10 text-zinc-600";
                    }
                  };

                  return (
                    <TableRow
                      key={res.id}
                      className="hover:bg-zinc-50/50 dark:hover:bg-zinc-900/50 border-zinc-50 dark:border-zinc-900 transition-colors"
                    >
                      <TableCell className="py-4">
                        <div className="flex flex-col gap-1">
                          <span className="font-semibold text-zinc-900 dark:text-zinc-100">
                            {format(startTime, "dd MMM yyyy", { locale: bg })}
                          </span>
                          <div className="flex items-center gap-1.5 text-xs text-zinc-400 font-medium">
                            <Clock className="h-3 w-3" />
                            {format(startTime, "HH:mm")} -{" "}
                            {format(endTime, "HH:mm")}
                          </div>
                          {res.bufferAfter ? (
                            <div className="text-[9px] text-amber-500/80 font-bold tracking-tight">
                              + {res.bufferAfter} мин. почистване
                            </div>
                          ) : null}
                        </div>
                      </TableCell>
                      <TableCell>
                        <div className="flex flex-col gap-0.5">
                          <span className="font-bold text-sm text-zinc-900 dark:text-zinc-100">
                            {res.client2Name || res.client2Zone
                              ? `${res.clientName}${res.selectedZone ? ` (${res.selectedZone})` : ""} & ${res.client2Name || "Клиент 2"}${res.client2Zone ? ` (${res.client2Zone})` : ""}`
                              : `${res.clientName}${res.selectedZone ? ` (${res.selectedZone})` : ""}`}
                          </span>
                          <span className="text-[10px] font-medium text-zinc-400 uppercase tracking-tight">
                            {res.client2Phone
                              ? `${res.clientPhone} / ${res.client2Phone}`
                              : res.clientPhone}
                          </span>
                        </div>
                      </TableCell>
                      <TableCell>
                        {res.courtId ? (
                          <Badge
                            variant="outline"
                            className="rounded-lg border-zinc-200 dark:border-zinc-800 bg-zinc-50 dark:bg-zinc-900 font-bold text-[10px] gap-1.5 py-1 px-2.5 whitespace-nowrap"
                          >
                            <MapPin className="h-3 w-3 text-primary" />
                            Корт {res.courtId}
                          </Badge>
                        ) : (
                          <Badge
                            variant="outline"
                            className="rounded-lg border-zinc-200 dark:border-zinc-800 bg-zinc-50 dark:bg-zinc-900 font-bold text-[10px] gap-1.5 py-1 px-2.5"
                          >
                            <Activity className="h-3 w-3 text-emerald-500" />
                            {(() => {
                              const svcName =
                                res.serviceName ||
                                services.find((s) => s.id === res.serviceId)
                                  ?.name;
                              return svcName || "Услуга";
                            })()}
                          </Badge>
                        )}
                      </TableCell>
                      <TableCell>
                        <Badge
                          className={`rounded-lg font-bold text-[9px] uppercase tracking-widest px-2.5 py-1 border-none shadow-none ${getStatusStyles(res.status)}`}
                        >
                          {getStatusLabel(res.status)}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        {isPackageTail ? (
                          <span className="text-xs font-bold text-zinc-400 italic">
                            в пакета
                          </span>
                        ) : (
                          <span className="font-bold text-sm text-zinc-900 dark:text-zinc-100 flex items-center gap-1">
                            {displayPrice}
                            <span className="text-[10px] text-zinc-400">
                              {res.currency || "EUR"}
                            </span>
                          </span>
                        )}
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center gap-2">
                          <div className="h-6 w-6 rounded-full bg-primary/10 flex items-center justify-center">
                            <User className="h-3 w-3 text-primary" />
                          </div>
                          <span className="text-xs font-medium text-zinc-500 truncate max-w-[120px]">
                            {res.createdBy?.userName ||
                              res.teamMemberName ||
                              "Система"}
                          </span>
                        </div>
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center justify-end gap-2">
                          {res.status !== "paid" && (
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-8 w-8 rounded-lg hover:bg-emerald-50 dark:hover:bg-emerald-900/20 text-emerald-600 transition-all"
                              onClick={() => handleMarkAsPaid(res.id)}
                              title="Маркирай като платено"
                            >
                              <CheckCircle2 className="w-4 h-4" />
                            </Button>
                          )}

                          {res.status === "paid" && !isPackageTail && (
                            <DonationReceiptDialog reservation={res as any}>
                              <Button
                                variant="ghost"
                                size="icon"
                                className="h-8 w-8 rounded-lg hover:bg-zinc-100 dark:hover:bg-zinc-800 text-zinc-900 dark:text-white transition-all"
                                title="Издай документ"
                              >
                                <FileText className="w-4 h-4" />
                              </Button>
                            </DonationReceiptDialog>
                          )}

                          <ReservationDialog
                            reservation={res as any}
                            mode={mode}
                            onSave={() => {}}
                          >
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-8 w-8 rounded-lg hover:bg-zinc-100 dark:hover:bg-zinc-800 transition-all"
                              title="Редактирай"
                            >
                              <Pencil className="w-4 h-4 text-zinc-400" />
                            </Button>
                          </ReservationDialog>

                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-8 w-8 rounded-lg hover:bg-rose-50 dark:hover:bg-rose-950/20 hover:text-rose-600 transition-all"
                            onClick={() => handleDeleteReservation(res.id)}
                            title="Изтрий"
                          >
                            <Trash2 className="w-4 h-4" />
                          </Button>

                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => onViewInCalendar(startTime)}
                            className="h-8 w-8 rounded-lg hover:bg-primary hover:text-white transition-all group"
                            title="Виж в календара"
                          >
                            <Eye className="h-4 w-4 group-hover:scale-110 transition-transform" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  );
                });
              })()
            )}
          </TableBody>
        </Table>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useMemo, useId, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Member, ScheduleEvent, Attendee } from "@/types";
import { Input } from "@/components/ui/input";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Loader2, Search, Check } from "lucide-react";
import { formatFullName } from "@/lib/utils";

interface AttendeesDialogProps {
  isOpen: boolean;
  onClose: () => void;
  event: ScheduleEvent | null;
  members: Member[];
  onUpdateAttendees: (eventId: string, attendees: Attendee[]) => Promise<void>;
}

export const AttendeesDialog: React.FC<AttendeesDialogProps> = ({
  isOpen,
  onClose,
  event,
  members,
  onUpdateAttendees,
}) => {
  const [searchTerm, setSearchTerm] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [attendeeIds, setAttendeeIds] = useState<Set<string>>(new Set());

  useEffect(() => {
    if (event && isOpen) {
      const presentIds = new Set(
        (event.attendees || []).filter((a) => a.attended).map((a) => a.memberId)
      );

      setAttendeeIds(presentIds);
    }
  }, [event, isOpen]);

  const handleToggleMember = (member: Member) => {
    const regDate = member.registrationDate
      ? new Date(member.registrationDate)
      : null;
    const eventDate = event?.startDate ? new Date(event.startDate) : null;

    if (regDate) regDate.setHours(0, 0, 0, 0);
    if (eventDate) eventDate.setHours(0, 0, 0, 0);

    const isBeforeRegistration = regDate && eventDate && eventDate < regDate;

    if (isBeforeRegistration) return; // Блокираме маркирането, ако събитието е преди регистрацията

    setAttendeeIds((prev) => {
      const next = new Set(prev);
      if (next.has(member.id)) {
        next.delete(member.id);
      } else {
        next.add(member.id);
      }
      return next;
    });
  };

  const handleSubmit = async () => {
    if (!event) return;
    setIsSubmitting(true);
    try {
      const attendees: Attendee[] = Array.from(attendeeIds).map((id) => {
        const member = members.find((m) => m.id === id);
        const existingAttendee = event.attendees?.find(
          (a) => a.memberId === id
        );

        return {
          memberId: id,
          name: member ? formatFullName(member) : "Unknown",
          attended: true,
          // Preserve existing payment data to avoid wiping it on UI updates
          ...(existingAttendee?.paymentStatus && {
            paymentStatus: existingAttendee.paymentStatus,
          }),
          ...(existingAttendee?.paymentType && {
            paymentType: existingAttendee.paymentType,
          }),
          ...(existingAttendee?.paymentDate && {
            paymentDate: existingAttendee.paymentDate,
          }),
          ...(existingAttendee?.saleId && { saleId: existingAttendee.saleId }),
        };
      });

      await onUpdateAttendees(event.id, attendees);
      onClose();
    } catch (error) {
      console.error("Failed to update attendees", error);
    } finally {
      setIsSubmitting(false);
    }
  };

  const filteredMembers = useMemo(() => {
    const search = searchTerm.toLowerCase().trim();
    if (!search) return members;
    return members.filter((m) =>
      formatFullName(m).toLowerCase().includes(search)
    );
  }, [members, searchTerm]);

  const sortedMembers = useMemo(() => {
    return [...filteredMembers].sort((a, b) => {
      const aPresent = attendeeIds.has(a.id);
      const bPresent = attendeeIds.has(b.id);
      if (aPresent && !bPresent) return -1;
      if (!aPresent && bPresent) return 1;
      return formatFullName(a).localeCompare(formatFullName(b));
    });
  }, [filteredMembers, attendeeIds]);

  const descriptionId = useId();

  return (
    <Dialog
      open={isOpen}
      onOpenChange={(open) => {
        if (!open) onClose();
      }}
    >
      <DialogContent
        key={event?.id}
        className="sm:max-w-lg w-[95vw] rounded-2xl border-none shadow-xl p-0 overflow-hidden bg-white dark:bg-zinc-950 flex flex-col h-[80vh] max-h-[800px]"
        aria-describedby={descriptionId}
      >
        <div className="p-4 sm:p-6 pb-0 shrink-0 border-b border-zinc-100 dark:border-zinc-900">
          <DialogHeader>
            <DialogTitle className="text-lg sm:text-xl font-semibold text-zinc-900 dark:text-white">
              Присъстващи
            </DialogTitle>
            <DialogDescription
              id={descriptionId}
              className="text-xs text-zinc-500 mt-1 line-clamp-1"
            >
              {event?.title || "Събитие"}
            </DialogDescription>
          </DialogHeader>

          <div className="py-4">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-zinc-400" />
              <Input
                placeholder="Търсене..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="h-10 rounded-lg border-zinc-200 bg-zinc-50 pl-10 text-sm focus:bg-white transition-all"
              />
            </div>
          </div>
        </div>

        <ScrollArea className="flex-1">
          <div className="p-2 sm:p-4 space-y-1">
            {sortedMembers.length > 0 ? (
              sortedMembers.map((member) => {
                const isPresent = attendeeIds.has(member.id);

                // Проверяваме дали събитието е преди датата на регистрация на члена
                const regDate = member.registrationDate
                  ? new Date(member.registrationDate)
                  : null;
                const eventDate = event?.startDate
                  ? new Date(event.startDate)
                  : null;

                if (regDate) regDate.setHours(0, 0, 0, 0);
                if (eventDate) eventDate.setHours(0, 0, 0, 0);

                const isBeforeRegistration =
                  regDate && eventDate && eventDate < regDate;

                return (
                  <div
                    key={member.id}
                    onClick={() => {
                      if (!isBeforeRegistration) {
                        handleToggleMember(member);
                      }
                    }}
                    className={`flex items-center justify-between px-3 py-2.5 rounded-lg transition-all group ${
                      isBeforeRegistration
                        ? "opacity-40 cursor-not-allowed bg-zinc-50/50 dark:bg-zinc-900/10 text-zinc-400 dark:text-zinc-600"
                        : isPresent
                          ? "bg-primary/10 text-primary cursor-pointer"
                          : "hover:bg-zinc-50 dark:hover:bg-zinc-900/50 text-zinc-700 dark:text-zinc-300 cursor-pointer"
                    }`}
                  >
                    <div className="flex items-center gap-3 min-w-0">
                      <div
                        className={`h-5 w-5 rounded border flex items-center justify-center transition-all shrink-0 ${
                          isBeforeRegistration
                            ? "border-zinc-200 bg-zinc-100 dark:border-zinc-800 dark:bg-zinc-900"
                            : isPresent
                              ? "bg-primary border-primary text-white"
                              : "border-zinc-300 bg-white dark:border-zinc-800 dark:bg-zinc-900"
                        }`}
                      >
                        {isPresent && !isBeforeRegistration && (
                          <Check className="h-3 w-3 stroke-3" />
                        )}
                      </div>
                      <div className="flex items-center gap-2 truncate">
                        <span className="text-sm font-medium truncate">
                          {formatFullName(member)}
                        </span>
                        {member.status === "inactive" && (
                          <span className="text-[9px] font-medium uppercase tracking-wide bg-amber-500/10 dark:bg-amber-950/20 px-2 py-0.5 rounded-full text-amber-600 dark:text-amber-400 border border-amber-500/10 shrink-0">
                            Неактивен
                          </span>
                        )}
                      </div>
                    </div>
                    {isBeforeRegistration ? (
                      <span className="text-[9px] font-medium uppercase tracking-wide bg-rose-500/10 dark:bg-rose-950/20 px-2 py-0.5 rounded-full text-rose-600 dark:text-rose-400 border border-rose-500/10 shrink-0">
                        преди рег. ({regDate.toLocaleDateString("bg-BG")})
                      </span>
                    ) : isPresent ? (
                      <span className="text-[10px] font-bold uppercase tracking-wider bg-primary/20 px-1.5 py-0.5 rounded text-primary">
                        Тук
                      </span>
                    ) : null}
                  </div>
                );
              })
            ) : (
              <div className="py-12 text-center">
                <p className="text-xs text-zinc-400">Няма намерени членове</p>
              </div>
            )}
          </div>
        </ScrollArea>

        <DialogFooter className="p-4 sm:p-6 border-t border-zinc-100 dark:border-zinc-900 bg-zinc-50/50 shrink-0">
          <div className="flex items-center justify-between w-full">
            <div className="text-xs font-medium text-zinc-500">
              <span className="text-zinc-900 dark:text-white">
                {attendeeIds.size}
              </span>{" "}
              присъстващи
            </div>
            <div className="flex items-center gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={onClose}
                disabled={isSubmitting}
                className="h-9 rounded-lg px-4 text-xs font-medium"
              >
                Отказ
              </Button>
              <Button
                size="sm"
                onClick={handleSubmit}
                disabled={isSubmitting}
                className="h-9 rounded-lg px-6 text-xs font-medium bg-zinc-900 hover:bg-zinc-800 text-white"
              >
                {isSubmitting ? (
                  <Loader2 className="h-3 w-3 animate-spin" />
                ) : (
                  "Запази"
                )}
              </Button>
            </div>
          </div>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

"use client";

import React, { useState, useId } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { ScheduleEvent, ScheduleEventType } from "@/types";
import { Loader2, ArrowRight, ArrowLeft, Calendar, MapPin, AlignLeft } from "lucide-react";
import { cn } from "@/lib/utils";

interface CreateEventDialogProps {
  isOpen: boolean;
  onClose: () => void;
  onAddEvent: (newEvent: Omit<ScheduleEvent, "id" | "color">) => Promise<void>;
}

const eventTypeTranslations: Record<ScheduleEventType, string> = {
  training: "Тренировка",
  competition: "Състезание",
  camp: "Лагер",
  event: "Събитие",
  other: "Друго",
};

const getDefaultStartTime = () => {
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  return now.toISOString().slice(0, 16);
};

const getDefaultEndTime = (startTime: string) => {
  const now = new Date(startTime);
  return new Date(now.getTime() + 60 * 60 * 1000).toISOString().slice(0, 16);
};

export const CreateEventDialog: React.FC<CreateEventDialogProps> = ({
  isOpen,
  onClose,
  onAddEvent,
}) => {
  const defaultStartTime = getDefaultStartTime();

  const [step, setStep] = useState(1);
  const [title, setTitle] = useState("");
  const [startDate, setStartDate] = useState(defaultStartTime);
  const [endDate, setEndDate] = useState(getDefaultEndTime(defaultStartTime));
  const [type, setType] = useState<ScheduleEventType>("training");
  const [location, setLocation] = useState("");
  const [description, setDescription] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const descriptionId = useId();

  const handleClose = () => {
    if (isSubmitting) return;
    setStep(1);
    setTitle("");
    setStartDate(defaultStartTime);
    setEndDate(getDefaultEndTime(defaultStartTime));
    setType("training");
    setLocation("");
    setDescription("");
    setError(null);
    onClose();
  };

  const validateStep = (currentStep: number) => {
    if (currentStep === 1) {
      if (!title || !type || !location) {
        setError("Моля, въведете име, тип и място.");
        return false;
      }
    }
    if (currentStep === 2) {
      if (!startDate || !endDate) {
        setError("Моля, въведете начало и край.");
        return false;
      }
      if (startDate >= endDate) {
        setError("Началото трябва да е преди края.");
        return false;
      }
    }
    setError(null);
    return true;
  };

  const handleNextStep = () => {
    if (validateStep(step)) {
      setStep((prev) => prev + 1);
    }
  };

  const handlePrevStep = () => {
    setError(null);
    setStep((prev) => prev - 1);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLFormElement>) => {
    const target = e.target as HTMLElement;
    if (e.key === "Enter" && target.tagName !== "TEXTAREA" && target.tagName !== "BUTTON") {
      e.preventDefault();
      if (step < 3) {
        handleNextStep();
      }
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (step < 3) {
      handleNextStep();
      return;
    }
    if (!validateStep(3)) return; // Final catch-all validation
    if (!title || !startDate || !endDate || !type || !location) {
      setError("Моля, попълнете всички задължителни полета.");
      return;
    }

    setError(null);
    setIsSubmitting(true);

    try {
      await onAddEvent({
        title,
        startDate,
        endDate,
        type,
        location,
        description,
        attendees: [],
        attendeeMemberIds: [],
      });
      handleClose();
    } catch (err) {
      setError("Възникна грешка при създаването на събитието.");
      console.error(err);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Dialog
      key={isOpen ? "open" : "closed"}
      open={isOpen}
      onOpenChange={handleClose}
    >
      <DialogContent
        className="sm:max-w-[540px] w-[92vw] rounded-4xl sm:rounded-5xl border-none shadow-2xl p-0 overflow-hidden bg-white dark:bg-zinc-950 flex flex-col max-h-[85vh] sm:max-h-[90vh]"
        aria-describedby={descriptionId}
      >
        <div className="flex flex-col h-full overflow-hidden">
          <div className="p-6 sm:p-8 pb-4 shrink-0 border-b border-zinc-100 dark:border-zinc-900 bg-white dark:bg-zinc-950 z-10">
            <DialogHeader>
              <DialogTitle className="text-xl sm:text-2xl font-light tracking-tight text-zinc-950 dark:text-white flex items-center justify-between">
                <span>Създаване на събитие</span>
                <span className="text-xs sm:text-sm font-medium text-zinc-400 bg-zinc-100 dark:bg-zinc-900 px-3 py-1 rounded-full">
                  Стъпка {step} от 3
                </span>
              </DialogTitle>
              <DialogDescription
                id={descriptionId}
                className="text-zinc-400 font-light mt-1 text-xs sm:text-sm"
              >
                {step === 1 && "Основна информация за събитието."}
                {step === 2 && "Кога ще се проведе?"}
                {step === 3 && "Допълнителни детайли (по желание)."}
              </DialogDescription>
            </DialogHeader>

            {/* Progress Bar */}
            <div className="mt-6 flex gap-2">
              {[1, 2, 3].map((i) => (
                <div
                  key={i}
                  className={cn(
                    "h-1.5 flex-1 rounded-full transition-all duration-500 ease-out",
                    i === step
                      ? "bg-zinc-950 dark:bg-white"
                      : i < step
                      ? "bg-zinc-950/30 dark:bg-white/30"
                      : "bg-zinc-100 dark:bg-zinc-800"
                  )}
                />
              ))}
            </div>
          </div>

          <div className="overflow-y-auto custom-scrollbar flex-1 overscroll-contain relative">
            <form
              id="create-event-form"
              onSubmit={handleSubmit}
              onKeyDown={handleKeyDown}
              className="p-6 sm:p-8 space-y-6"
            >
              {/* STEP 1: Basic Info */}
              <div className={cn("space-y-5 transition-all duration-500", step === 1 ? "block opacity-100" : "hidden opacity-0")}>
                <div className="space-y-2">
                  <label htmlFor="type" className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 ml-1 flex items-center gap-2">
                    <MapPin className="h-3 w-3" /> Тип на събитието
                  </label>
                  <Select
                    onValueChange={(value: ScheduleEventType) => setType(value)}
                    defaultValue={type}
                  >
                    <SelectTrigger
                      id="type"
                      className="h-12 rounded-2xl border-zinc-100 dark:border-zinc-800 bg-zinc-50/50 dark:bg-zinc-900/50 px-4 shadow-none font-light"
                    >
                      <SelectValue placeholder="Изберете тип" />
                    </SelectTrigger>
                    <SelectContent className="rounded-2xl border-zinc-100 dark:border-zinc-800 bg-white dark:bg-zinc-950 shadow-2xl">
                      {Object.entries(eventTypeTranslations).map(([key, value]) => (
                        <SelectItem key={key} value={key as ScheduleEventType} className="rounded-xl py-3 cursor-pointer">
                          {value}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                <div className="space-y-2">
                  <label htmlFor="title" className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 ml-1">
                    Име на събитието / Група
                  </label>
                  <Input
                    id="title"
                    placeholder="Например: Тренировка - Напреднали"
                    value={title}
                    onChange={(e) => setTitle(e.target.value)}
                    className="h-12 rounded-2xl border-zinc-100 dark:border-zinc-800 bg-zinc-50/50 dark:bg-zinc-900/50 px-4 shadow-none font-light focus:ring-zinc-950"
                    autoFocus={step === 1}
                  />
                </div>

                <div className="space-y-2">
                  <label htmlFor="location" className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 ml-1">
                    Място / Корт
                  </label>
                  <Input
                    id="location"
                    placeholder="Например: Спортна зала 'Енергетик'"
                    value={location}
                    onChange={(e) => setLocation(e.target.value)}
                    className="h-12 rounded-2xl border-zinc-100 dark:border-zinc-800 bg-zinc-50/50 dark:bg-zinc-900/50 px-4 shadow-none font-light"
                  />
                </div>
              </div>

              {/* STEP 2: Time Range */}
              <div className={cn("space-y-5 transition-all duration-500", step === 2 ? "block opacity-100" : "hidden opacity-0")}>
                <div className="space-y-2">
                  <label htmlFor="startDate" className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 ml-1 flex items-center gap-2">
                    <Calendar className="h-3 w-3" /> Начало
                  </label>
                  <Input
                    id="startDate"
                    type="datetime-local"
                    value={startDate}
                    onChange={(e) => setStartDate(e.target.value)}
                    className="h-12 rounded-2xl border-zinc-100 dark:border-zinc-800 bg-zinc-50/50 dark:bg-zinc-900/50 px-4 shadow-none font-light"
                    autoFocus={step === 2}
                  />
                </div>
                <div className="space-y-2">
                  <label htmlFor="endDate" className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 ml-1 flex items-center gap-2">
                    <Calendar className="h-3 w-3" /> Край
                  </label>
                  <Input
                    id="endDate"
                    type="datetime-local"
                    value={endDate}
                    onChange={(e) => setEndDate(e.target.value)}
                    className="h-12 rounded-2xl border-zinc-100 dark:border-zinc-800 bg-zinc-50/50 dark:bg-zinc-900/50 px-4 shadow-none font-light"
                  />
                </div>
              </div>

              {/* STEP 3: Additional details */}
              <div className={cn("space-y-5 transition-all duration-500", step === 3 ? "block opacity-100" : "hidden opacity-0")}>
                <div className="space-y-2">
                  <label htmlFor="description" className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 ml-1 flex items-center gap-2">
                    <AlignLeft className="h-3 w-3" /> Описание (по желание)
                  </label>
                  <Textarea
                    id="description"
                    placeholder="Допълнителни бележки, треньори..."
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                    className="min-h-[120px] rounded-2xl border-zinc-100 dark:border-zinc-800 bg-zinc-50/50 dark:bg-zinc-900/50 p-4 shadow-none font-light resize-none focus:ring-zinc-950"
                    autoFocus={step === 3}
                  />
                </div>
              </div>

              {error && (
                <div className="p-3 rounded-xl bg-rose-50 dark:bg-rose-950/30 border border-rose-100 dark:border-rose-900">
                  <p className="text-[11px] font-medium text-rose-500 uppercase tracking-widest text-center flex items-center justify-center gap-2">
                    <span className="w-1.5 h-1.5 rounded-full bg-rose-500 animate-pulse" />
                    {error}
                  </p>
                </div>
              )}
            </form>
          </div>

          <div className="p-6 sm:p-8 pt-4 border-t border-zinc-100 dark:border-zinc-900 bg-zinc-50/30 dark:bg-zinc-900/20 shrink-0 z-10">
            <DialogFooter className="flex flex-row justify-between sm:justify-between items-center w-full gap-3 sm:gap-0">
              {step > 1 ? (
                <Button
                  type="button"
                  variant="ghost"
                  onClick={handlePrevStep}
                  disabled={isSubmitting}
                  className="h-12 px-6 rounded-2xl font-medium text-[11px] uppercase tracking-widest hover:bg-white dark:hover:bg-zinc-900 transition-all flex items-center gap-2"
                >
                  <ArrowLeft className="h-4 w-4" /> Назад
                </Button>
              ) : (
                <Button
                  type="button"
                  variant="ghost"
                  onClick={handleClose}
                  disabled={isSubmitting}
                  className="h-12 px-6 rounded-2xl font-medium text-[11px] uppercase tracking-widest text-zinc-400 hover:text-zinc-950 transition-all"
                >
                  Отказ
                </Button>
              )}

              {step < 3 ? (
                <Button
                  type="button"
                  onClick={(e) => {
                    e.preventDefault();
                    handleNextStep();
                  }}
                  className="h-12 px-8 rounded-2xl bg-zinc-950 dark:bg-white text-white dark:text-zinc-950 hover:opacity-90 font-medium text-[11px] uppercase tracking-widest shadow-xl shadow-zinc-950/10 transition-all active:scale-[0.98] flex items-center gap-2"
                >
                  Напред <ArrowRight className="h-4 w-4" />
                </Button>
              ) : (
                <Button
                  type="submit"
                  form="create-event-form"
                  disabled={isSubmitting}
                  className="h-12 px-10 rounded-2xl bg-zinc-950 dark:bg-white text-white dark:text-zinc-950 hover:opacity-90 font-medium text-[11px] uppercase tracking-widest shadow-xl shadow-zinc-950/10 transition-all active:scale-[0.98]"
                >
                  {isSubmitting ? (
                    <>
                      <Loader2 className="mr-3 h-4 w-4 animate-spin" /> Създаване
                    </>
                  ) : (
                    "Създай събитие"
                  )}
                </Button>
              )}
            </DialogFooter>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
};

"use client";

import React, { useState, useId, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { ScheduleEvent, ScheduleEventType } from "@/types";
import { Loader2, ArrowRight, ArrowLeft, Calendar, MapPin, AlignLeft } from "lucide-react";
import { cn } from "@/lib/utils";

interface EditEventDialogProps {
  isOpen: boolean;
  onClose: () => void;
  event: ScheduleEvent | null;
  onUpdateEvent: (
    eventId: string,
    eventData: Partial<Omit<ScheduleEvent, "id" | "color">>
  ) => Promise<void>;
}

const eventTypeTranslations: Record<ScheduleEventType, string> = {
  training: "Тренировка",
  competition: "Състезание",
  camp: "Лагер",
  event: "Събитие",
  other: "Друго",
};

const toLocalISOString = (dateString: string | undefined | null): string => {
  if (!dateString) return "";
  try {
    const date = new Date(dateString);
    const tzoffset = new Date().getTimezoneOffset() * 60000;
    const localISOTime = new Date(date.getTime() - tzoffset)
      .toISOString()
      .slice(0, 16);
    return localISOTime;
  } catch {
    return "";
  }
};

export const EditEventDialog: React.FC<EditEventDialogProps> = ({
  isOpen,
  onClose,
  event,
  onUpdateEvent,
}) => {
  const [step, setStep] = useState(1);
  const [title, setTitle] = useState(event?.title || "");
  const [startDate, setStartDate] = useState(toLocalISOString(event?.startDate));
  const [endDate, setEndDate] = useState(toLocalISOString(event?.endDate));
  const [type, setType] = useState<ScheduleEventType>(event?.type || "training");
  const [location, setLocation] = useState(event?.location || "");
  const [description, setDescription] = useState(event?.description || "");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (event && isOpen) {
      setStep(1); // Reset to first step when opened
      setTitle(event.title || "");
      setStartDate(toLocalISOString(event.startDate));
      setEndDate(toLocalISOString(event.endDate));
      setType(event.type || "training");
      setLocation(event.location || "");
      setDescription(event.description || "");
      setError(null);
    }
  }, [event, isOpen]);

  const validateStep = (currentStep: number) => {
    if (currentStep === 1) {
      if (!title || !type || !location) {
        setError("Моля, въведете име, тип и място.");
        return false;
      }
    }
    if (currentStep === 2) {
      if (!startDate || !endDate) {
        setError("Моля, въведете начало и край.");
        return false;
      }
      if (startDate >= endDate) {
        setError("Началото трябва да е преди края.");
        return false;
      }
    }
    setError(null);
    return true;
  };

  const handleNextStep = () => {
    if (validateStep(step)) {
      setStep((prev) => prev + 1);
    }
  };

  const handlePrevStep = () => {
    setError(null);
    setStep((prev) => prev - 1);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLFormElement>) => {
    const target = e.target as HTMLElement;
    if (e.key === "Enter" && target.tagName !== "TEXTAREA" && target.tagName !== "BUTTON") {
      e.preventDefault();
      if (step < 3) {
        handleNextStep();
      }
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!event) return;
    if (step < 3) {
      handleNextStep();
      return;
    }
    if (!validateStep(3)) return;
    if (!title || !startDate || !endDate || !type || !location) {
      setError("Моля, попълнете всички задължителни полета.");
      return;
    }

    setError(null);
    setIsSubmitting(true);

    try {
      await onUpdateEvent(event.id, {
        title,
        startDate,
        endDate,
        type,
        location,
        description,
      });
      onClose();
    } catch (err) {
      setError("Възникна грешка при обновяването на събитието.");
      console.error(err);
    } finally {
      setIsSubmitting(false);
    }
  };

  const descriptionId = useId();

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent
        key={event?.id}
        className="sm:max-w-[540px] w-[92vw] rounded-4xl sm:rounded-5xl border-none shadow-2xl p-0 overflow-hidden bg-white dark:bg-zinc-950 flex flex-col max-h-[85vh] sm:max-h-[90vh]"
        aria-describedby={descriptionId}
      >
        <div className="flex flex-col h-full overflow-hidden">
          <div className="p-6 sm:p-8 pb-4 shrink-0 border-b border-zinc-100 dark:border-zinc-900 bg-white dark:bg-zinc-950 z-10">
            <DialogHeader>
              <DialogTitle className="text-xl sm:text-2xl font-light tracking-tight text-zinc-950 dark:text-white flex items-center justify-between">
                <span>Редактиране на събитие</span>
                <span className="text-xs sm:text-sm font-medium text-zinc-400 bg-zinc-100 dark:bg-zinc-900 px-3 py-1 rounded-full">
                  Стъпка {step} от 3
                </span>
              </DialogTitle>
              <DialogDescription
                id={descriptionId}
                className="text-zinc-400 font-light mt-1 text-xs sm:text-sm"
              >
                {step === 1 && "Основна информация за събитието."}
                {step === 2 && "Кога ще се проведе?"}
                {step === 3 && "Допълнителни детайли (по желание)."}
              </DialogDescription>
            </DialogHeader>

            {/* Progress Bar */}
            <div className="mt-6 flex gap-2">
              {[1, 2, 3].map((i) => (
                <div
                  key={i}
                  className={cn(
                    "h-1.5 flex-1 rounded-full transition-all duration-500 ease-out",
                    i === step
                      ? "bg-zinc-950 dark:bg-white"
                      : i < step
                      ? "bg-zinc-950/30 dark:bg-white/30"
                      : "bg-zinc-100 dark:bg-zinc-800"
                  )}
                />
              ))}
            </div>
          </div>

          <div className="overflow-y-auto custom-scrollbar flex-1 overscroll-contain relative">
            {event && (
              <form
                id="edit-event-form"
                onSubmit={handleSubmit}
                onKeyDown={handleKeyDown}
                className="p-6 sm:p-8 space-y-6"
              >
                {/* STEP 1: Basic Info */}
                <div className={cn("space-y-5 transition-all duration-500", step === 1 ? "block opacity-100" : "hidden opacity-0")}>
                  <div className="space-y-2">
                    <label htmlFor="edit-type" className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 ml-1 flex items-center gap-2">
                      <MapPin className="h-3 w-3" /> Тип на събитието
                    </label>
                    <Select
                      onValueChange={(value: ScheduleEventType) => setType(value)}
                      value={type}
                    >
                      <SelectTrigger
                        id="edit-type"
                        className="h-12 rounded-2xl border-zinc-100 dark:border-zinc-800 bg-zinc-50/50 dark:bg-zinc-900/50 px-4 shadow-none font-light"
                      >
                        <SelectValue placeholder="Изберете тип" />
                      </SelectTrigger>
                      <SelectContent className="rounded-2xl border-zinc-100 dark:border-zinc-800 bg-white dark:bg-zinc-950 shadow-2xl">
                        {Object.entries(eventTypeTranslations).map(([key, value]) => (
                          <SelectItem key={key} value={key as ScheduleEventType} className="rounded-xl py-3 cursor-pointer">
                            {value}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="space-y-2">
                    <label htmlFor="edit-title" className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 ml-1">
                      Име на събитието / Група
                    </label>
                    <Input
                      id="edit-title"
                      value={title}
                      onChange={(e) => setTitle(e.target.value)}
                      className="h-12 rounded-2xl border-zinc-100 dark:border-zinc-800 bg-zinc-50/50 dark:bg-zinc-900/50 px-4 shadow-none font-light focus:ring-zinc-950"
                      autoFocus={step === 1}
                    />
                  </div>

                  <div className="space-y-2">
                    <label htmlFor="edit-location" className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 ml-1">
                      Място / Корт
                    </label>
                    <Input
                      id="edit-location"
                      value={location}
                      onChange={(e) => setLocation(e.target.value)}
                      className="h-12 rounded-2xl border-zinc-100 dark:border-zinc-800 bg-zinc-50/50 dark:bg-zinc-900/50 px-4 shadow-none font-light"
                    />
                  </div>
                </div>

                {/* STEP 2: Time Range */}
                <div className={cn("space-y-5 transition-all duration-500", step === 2 ? "block opacity-100" : "hidden opacity-0")}>
                  <div className="space-y-2">
                    <label htmlFor="edit-startDate" className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 ml-1 flex items-center gap-2">
                      <Calendar className="h-3 w-3" /> Начало
                    </label>
                    <Input
                      id="edit-startDate"
                      type="datetime-local"
                      value={startDate}
                      onChange={(e) => setStartDate(e.target.value)}
                      className="h-12 rounded-2xl border-zinc-100 dark:border-zinc-800 bg-zinc-50/50 dark:bg-zinc-900/50 px-4 shadow-none font-light"
                      autoFocus={step === 2}
                    />
                  </div>
                  <div className="space-y-2">
                    <label htmlFor="edit-endDate" className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 ml-1 flex items-center gap-2">
                      <Calendar className="h-3 w-3" /> Край
                    </label>
                    <Input
                      id="edit-endDate"
                      type="datetime-local"
                      value={endDate}
                      onChange={(e) => setEndDate(e.target.value)}
                      className="h-12 rounded-2xl border-zinc-100 dark:border-zinc-800 bg-zinc-50/50 dark:bg-zinc-900/50 px-4 shadow-none font-light"
                    />
                  </div>
                </div>

                {/* STEP 3: Additional details */}
                <div className={cn("space-y-5 transition-all duration-500", step === 3 ? "block opacity-100" : "hidden opacity-0")}>
                  <div className="space-y-2">
                    <label htmlFor="edit-description" className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 ml-1 flex items-center gap-2">
                      <AlignLeft className="h-3 w-3" /> Описание
                    </label>
                    <Textarea
                      id="edit-description"
                      value={description}
                      onChange={(e) => setDescription(e.target.value)}
                      className="min-h-[120px] rounded-2xl border-zinc-100 dark:border-zinc-800 bg-zinc-50/50 dark:bg-zinc-900/50 p-4 shadow-none font-light resize-none focus:ring-zinc-950"
                      autoFocus={step === 3}
                    />
                  </div>
                </div>

                {error && (
                  <div className="p-3 rounded-xl bg-rose-50 dark:bg-rose-950/30 border border-rose-100 dark:border-rose-900">
                    <p className="text-[11px] font-medium text-rose-500 uppercase tracking-widest text-center flex items-center justify-center gap-2">
                      <span className="w-1.5 h-1.5 rounded-full bg-rose-500 animate-pulse" />
                      {error}
                    </p>
                  </div>
                )}
              </form>
            )}
          </div>

          <div className="p-6 sm:p-8 pt-4 border-t border-zinc-100 dark:border-zinc-900 bg-zinc-50/30 dark:bg-zinc-900/20 shrink-0 z-10">
            <DialogFooter className="flex flex-row justify-between sm:justify-between items-center w-full gap-3 sm:gap-0">
              {step > 1 ? (
                <Button
                  type="button"
                  variant="ghost"
                  onClick={handlePrevStep}
                  disabled={isSubmitting}
                  className="h-12 px-6 rounded-2xl font-medium text-[11px] uppercase tracking-widest hover:bg-white dark:hover:bg-zinc-900 transition-all flex items-center gap-2"
                >
                  <ArrowLeft className="h-4 w-4" /> Назад
                </Button>
              ) : (
                <Button
                  type="button"
                  variant="ghost"
                  onClick={onClose}
                  disabled={isSubmitting}
                  className="h-12 px-6 rounded-2xl font-medium text-[11px] uppercase tracking-widest text-zinc-400 hover:text-zinc-950 transition-all"
                >
                  Отказ
                </Button>
              )}

              {step < 3 ? (
                <Button
                  type="button"
                  onClick={(e) => {
                    e.preventDefault();
                    handleNextStep();
                  }}
                  className="h-12 px-8 rounded-2xl bg-zinc-950 dark:bg-white text-white dark:text-zinc-950 hover:opacity-90 font-medium text-[11px] uppercase tracking-widest shadow-xl shadow-zinc-950/10 transition-all active:scale-[0.98] flex items-center gap-2"
                >
                  Напред <ArrowRight className="h-4 w-4" />
                </Button>
              ) : (
                <Button
                  type="submit"
                  form="edit-event-form"
                  disabled={isSubmitting}
                  className="h-12 px-10 rounded-2xl bg-zinc-950 dark:bg-white text-white dark:text-zinc-950 hover:opacity-90 font-medium text-[11px] uppercase tracking-widest shadow-xl shadow-zinc-950/10 transition-all active:scale-[0.98]"
                >
                  {isSubmitting ? (
                    <>
                      <Loader2 className="mr-2 h-4 w-4 animate-spin" />{" "}
                      Запазване...
                    </>
                  ) : (
                    "Запази промените"
                  )}
                </Button>
              )}
            </DialogFooter>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
};

"use client";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import MonthlyScheduleForm from "./monthly-schedule-form";
import { ScheduleEvent } from "@/types";
import { endOfMonth, eachDayOfInterval, getDay } from "date-fns";

export default function MonthlyScheduleDialog({
  isOpen,
  onClose,
  onGenerate,
}: any) {
  const handleSave = async (data: any) => {
    const [year, monthStr] = data.month.split("-");
    const startDate = new Date(parseInt(year), parseInt(monthStr) - 1, 1);
    const endDate = endOfMonth(startDate);

    const allDaysInMonth = eachDayOfInterval({
      start: startDate,
      end: endDate,
    });

    const events: Omit<ScheduleEvent, "id">[] = [];

    const [startHour, startMinute] = data.startTime.split(":").map(Number);
    const [endHour, endMinute] = data.endTime.split(":").map(Number);

    allDaysInMonth.forEach((date) => {
      const dayOfWeek = getDay(date);
      if (data.days.includes(dayOfWeek)) {
        const eventStart = new Date(
          date.getFullYear(),
          date.getMonth(),
          date.getDate(),
          startHour,
          startMinute
        );
        const eventEnd = new Date(
          date.getFullYear(),
          date.getMonth(),
          date.getDate(),
          endHour,
          endMinute
        );

        events.push({
          title: data.title,
          type: data.type,
          location: data.location,
          startDate: eventStart.toISOString(),
          endDate: eventEnd.toISOString(),
          attendees: [],
          attendeeMemberIds: [],
        });
      }
    });

    await onGenerate(events);
    onClose();
  };

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="sm:max-w-[425px]">
        <DialogHeader>
          <DialogTitle>Генериране на график</DialogTitle>
        </DialogHeader>
        <MonthlyScheduleForm onSave={handleSave} />
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import { Button } from "@/components/ui/button";
import {
  Form,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import {
  Loader2,
  Calendar,
  MapPin,
  Clock,
  Type,
  Tag,
  ArrowRight,
  ArrowLeft,
  CheckCircle2,
} from "lucide-react";
import { format } from "date-fns";
import { cn } from "@/lib/utils";
import { useState, useCallback, useMemo, useEffect } from "react";

const daysOfWeek = [
  { id: "mon", label: "Пн", value: 1 },
  { id: "tue", label: "Вт", value: 2 },
  { id: "wed", label: "Ср", value: 3 },
  { id: "thu", label: "Чт", value: 4 },
  { id: "fri", label: "Пт", value: 5 },
  { id: "sat", label: "Сб", value: 6 },
  { id: "sun", label: "Нд", value: 0 },
];

const monthlyScheduleSchema = z
  .object({
    title: z.string().min(1, "Моля, въведете заглавие."),
    type: z.enum(["training", "competition", "camp", "event", "other"]),
    month: z.string().min(1, "Моля, изберете месец."),
    days: z.array(z.number()).min(1, "Моля, изберете поне един ден."),
    startTime: z.string().min(1, "Моля, въведете начален час."),
    endTime: z.string().min(1, "Моля, въведете краен час."),
    location: z.string().min(1, "Моля, въведете локация."),
  })
  .refine((data) => data.startTime < data.endTime, {
    message: "Крайният час трябва да е след началния.",
    path: ["endTime"],
  });

export type MonthlyScheduleFormData = z.infer<typeof monthlyScheduleSchema>;

interface MonthlyScheduleFormProps {
  onSave: (data: MonthlyScheduleFormData) => void;
  isSaving?: boolean;
}

export default function MonthlyScheduleForm({
  onSave,
  isSaving,
}: MonthlyScheduleFormProps) {
  const [step, setStep] = useState(1);

  const form = useForm<MonthlyScheduleFormData>({
    resolver: zodResolver(monthlyScheduleSchema),
    defaultValues: {
      title: "Тренировка",
      type: "training",
      month: format(new Date(), "yyyy-MM"),
      days: [],
      startTime: "17:00",
      endTime: "18:30",
      location: 'Спортна зала "Енергетик" град Гълъбово',
    },
  });

  const rawWatchedDays = form.watch("days");
  const currentValues = form.getValues();

  const [canSubmit, setCanSubmit] = useState(false);

  useEffect(() => {
    if (step === 3) {
      const timer = setTimeout(() => setCanSubmit(true), 600);
      return () => clearTimeout(timer);
    } else {
      setCanSubmit(false);
    }
  }, [step]);

  const handleNextStep = useCallback(async () => {
    let isValid = false;
    if (step === 1) {
      isValid = await form.trigger(["title", "type", "location"]);
    } else if (step === 2) {
      isValid = await form.trigger(["month", "days", "startTime", "endTime"]);
    }
    if (isValid) {
      setStep((prev) => prev + 1);
    }
  }, [step, form]);

  const handlePrevStep = useCallback(() => {
    setStep((prev) => prev - 1);
  }, []);

  const handleInputKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === "Enter") {
        e.preventDefault();
        if (step < 3) {
          handleNextStep();
        } else {
          form.handleSubmit(onSave)();
        }
      }
    },
    [step, handleNextStep, form, onSave]
  );

  const renderedDays = useMemo(() => {
    const watchedDays = rawWatchedDays || [];
    return daysOfWeek.map((day) => {
      const isSelected = watchedDays.includes(day.value);
      return (
        <div
          key={day.id}
          role="checkbox"
          aria-checked={isSelected}
          tabIndex={0}
          onClick={() => {
            const currentDays = form.getValues("days") || [];
            const newValue = isSelected
              ? currentDays.filter((v) => v !== day.value)
              : [...currentDays, day.value];
            form.setValue("days", newValue, { shouldValidate: true });
          }}
          onKeyDown={(e) => {
            if (e.key === " " || e.key === "Enter") {
              e.preventDefault();
              const currentDays = form.getValues("days") || [];
              const newValue = isSelected
                ? currentDays.filter((v) => v !== day.value)
                : [...currentDays, day.value];
              form.setValue("days", newValue, { shouldValidate: true });
            }
          }}
          className={cn(
            "h-12 rounded-xl border flex flex-col items-center justify-center cursor-pointer transition-all gap-0.5 flex-1 min-w-[50px] md:min-w-[60px] select-none outline-none focus-visible:ring-2 focus-visible:ring-zinc-950",
            isSelected
              ? "bg-zinc-950 border-zinc-950 text-white shadow-lg shadow-zinc-950/20"
              : "bg-white border-zinc-100 text-zinc-400 hover:border-zinc-200 hover:bg-zinc-50"
          )}
        >
          <span className="text-[11px] font-medium uppercase tracking-widest">
            {day.label}
          </span>
        </div>
      );
    });
  }, [rawWatchedDays, form]);

  return (
    <div className="flex flex-col h-full">
      <div className="mb-6 space-y-2">
        <div className="flex items-center justify-between text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400">
          <span>
            {step === 1
              ? "Стъпка 1: Основна информация"
              : step === 2
                ? "Стъпка 2: Време и Повторяемост"
                : "Стъпка 3: Финализиране"}
          </span>
          <span>Стъпка {step} от 3</span>
        </div>
        <div className="flex gap-2">
          {[1, 2, 3].map((i) => (
            <div
              key={i}
              className={cn(
                "h-1.5 flex-1 rounded-full transition-all duration-500 ease-out",
                i === step
                  ? "bg-zinc-950 dark:bg-white"
                  : i < step
                    ? "bg-zinc-950/30 dark:bg-white/30"
                    : "bg-zinc-100 dark:bg-zinc-800"
              )}
            />
          ))}
        </div>
      </div>

      <Form {...form}>
        <form
          id="monthly-schedule-form"
          onSubmit={(e) => {
            e.preventDefault();
            if (step < 3) {
              handleNextStep();
            } else {
              form.handleSubmit(onSave)();
            }
          }}
          className="space-y-8 flex-1"
        >
          {/* STEP 1 */}
          <div
            className={cn(
              "space-y-6 transition-all duration-500",
              step === 1 ? "block opacity-100" : "hidden opacity-0"
            )}
          >
            <FormField
              control={form.control}
              name="type"
              render={({ field }) => (
                <FormItem>
                  <FormLabel className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 flex items-center gap-2 mb-2">
                    <Tag className="h-3 w-3" /> Тип събитие
                  </FormLabel>
                  <select
                    className="w-full h-12 rounded-2xl bg-zinc-50/50 border-zinc-100 focus:ring-0 focus:border-zinc-200 transition-all text-sm font-light px-4"
                    value={field.value || "training"}
                    onChange={(e) => field.onChange(e.target.value)}
                  >
                    <option value="training">Тренировка</option>
                    <option value="competition">Състезание</option>
                    <option value="camp">Лагер</option>
                    <option value="event">Събитие</option>
                    <option value="other">Друго</option>
                  </select>
                  <FormMessage className="text-[10px] font-medium uppercase tracking-widest text-rose-500" />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="title"
              render={({ field }) => (
                <FormItem>
                  <FormLabel className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 flex items-center gap-2 mb-2">
                    <Type className="h-3 w-3" /> Име на събитието / Група
                  </FormLabel>
                  <Input
                    placeholder="напр. Тренировка - Група А"
                    className="h-12 rounded-2xl bg-zinc-50/50 border-zinc-100 focus:ring-0 focus:border-zinc-200 transition-all text-sm font-light"
                    onKeyDown={handleInputKeyDown}
                    {...field}
                  />
                  <FormMessage className="text-[10px] font-medium uppercase tracking-widest text-rose-500" />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="location"
              render={({ field }) => (
                <FormItem>
                  <FormLabel className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 flex items-center gap-2 mb-2">
                    <MapPin className="h-3 w-3" /> Място / Корт
                  </FormLabel>
                  <Input
                    className="h-12 rounded-2xl bg-zinc-50/50 border-zinc-100 focus:ring-0 focus:border-zinc-200 transition-all text-sm font-light"
                    onKeyDown={handleInputKeyDown}
                    {...field}
                  />
                  <FormMessage className="text-[10px] font-medium uppercase tracking-widest text-rose-500" />
                </FormItem>
              )}
            />
          </div>

          {/* STEP 2 */}
          <div
            className={cn(
              "space-y-6 transition-all duration-500",
              step === 2 ? "block opacity-100" : "hidden opacity-0"
            )}
          >
            <FormField
              control={form.control}
              name="month"
              render={({ field }) => (
                <FormItem>
                  <FormLabel className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 flex items-center gap-2 mb-2">
                    <Calendar className="h-3 w-3" /> Месец за генериране
                  </FormLabel>
                  <Input
                    type="month"
                    className="h-12 rounded-2xl bg-zinc-50/50 border-zinc-100 focus:ring-0 focus:border-zinc-200 transition-all text-sm font-light text-center"
                    {...field}
                  />
                </FormItem>
              )}
            />

            <div className="grid grid-cols-2 gap-4">
              <FormField
                control={form.control}
                name="startTime"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 flex items-center gap-2 mb-2">
                      <Clock className="h-3 w-3" /> Начален час
                    </FormLabel>
                    <Input
                      type="time"
                      className="h-12 rounded-2xl bg-zinc-50/50 border-zinc-100 focus:ring-0 focus:border-zinc-200 transition-all text-sm font-light"
                      onKeyDown={handleInputKeyDown}
                      {...field}
                    />
                    <FormMessage className="text-[10px] font-medium uppercase tracking-widest text-rose-500" />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="endTime"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 flex items-center gap-2 mb-2">
                      <Clock className="h-3 w-3" /> Краен час
                    </FormLabel>
                    <Input
                      type="time"
                      className="h-12 rounded-2xl bg-zinc-50/50 border-zinc-100 focus:ring-0 focus:border-zinc-200 transition-all text-sm font-light"
                      onKeyDown={handleInputKeyDown}
                      {...field}
                    />
                    <FormMessage className="text-[10px] font-medium uppercase tracking-widest text-rose-500" />
                  </FormItem>
                )}
              />
            </div>

            <div className="space-y-4">
              <FormLabel className="text-[10px] font-medium uppercase tracking-[0.2em] text-zinc-400 block mb-4">
                Повторение в дните (Дни от седмицата)
              </FormLabel>
              <div className="flex flex-wrap gap-2">{renderedDays}</div>
              <FormMessage className="text-[10px] font-medium uppercase tracking-widest text-rose-500" />
            </div>
          </div>

