import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

interface DataTableColumnHeaderProps<
  TData,
  TValue,
> extends React.HTMLAttributes<HTMLDivElement> {
  column: Column<TData, TValue>;
  title: string;
}

export function DataTableColumnHeader<TData, TValue>({
  column,
  title,
  className,
}: DataTableColumnHeaderProps<TData, TValue>) {
  if (!column.getCanSort()) {
    return <div className={cn(className)}>{title}</div>;
  }

  return (
    <div className={cn("flex items-center space-x-2", className)}>
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button
            variant="ghost"
            size="sm"
            className="-ml-3 h-8 data-[state=open]:bg-accent"
          >
            <span>{title}</span>
            {column.getIsSorted() === "desc" ? (
              <ArrowDownIcon className="ml-2 h-4 w-4" />
            ) : column.getIsSorted() === "asc" ? (
              <ArrowUpIcon className="ml-2 h-4 w-4" />
            ) : (
              <ChevronsUpDownIcon className="ml-2 h-4 w-4" />
            )}
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="start">
          <DropdownMenuItem onClick={() => column.toggleSorting(false)}>
            <ArrowUpIcon className="mr-2 h-3.5 w-3.5 text-muted-foreground/70" />
            Възходящ
          </DropdownMenuItem>
          <DropdownMenuItem onClick={() => column.toggleSorting(true)}>
            <ArrowDownIcon className="mr-2 h-3.5 w-3.5 text-muted-foreground/70" />
            Низходящ
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  );
}

import * as React from "react";
import {
  ColumnDef,
  SortingState,
  ColumnFiltersState,
  flexRender,
  getCoreRowModel,
  getFacetedRowModel,
  getFacetedUniqueValues,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
} from "@tanstack/react-table";

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Loader2, Search, ChevronLeft, ChevronRight } from "lucide-react";

interface DataTableProps<TData, TValue> {
  columns: ColumnDef<TData, TValue>[];
  data: TData[];
  filterColumnId: string;
  filterPlaceholder: string;
  isLoading: boolean;
  emptyStateMessage: string;
  getCellValue?: (row: TData, columnId: string) => TValue;
}

export function DataTable<TData, TValue>({
  columns,
  data,
  filterColumnId,
  filterPlaceholder,
  isLoading,
  emptyStateMessage,
  getCellValue,
}: DataTableProps<TData, TValue>) {
  const [sorting, setSorting] = React.useState<SortingState>([]);
  const [columnFilters, setColumnFilters] = React.useState<ColumnFiltersState>(
    []
  );

  const table = useReactTable({
    data,
    columns,
    state: {
      sorting,
      columnFilters,
    },
    onSortingChange: setSorting,
    onColumnFiltersChange: setColumnFilters,
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFacetedRowModel: getFacetedRowModel(),
    getFacetedUniqueValues: getFacetedUniqueValues(),
  });

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="relative w-full max-w-sm group">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 h-4 w-4 text-zinc-400 group-focus-within:text-primary transition-colors" />
          <Input
            id="table-filter"
            name="table-filter"
            placeholder={filterPlaceholder}
            value={
              (table.getColumn(filterColumnId)?.getFilterValue() as string) ??
              ""
            }
            onChange={(event) =>
              table
                .getColumn(filterColumnId)
                ?.setFilterValue(event.target.value)
            }
            className="pl-11 h-12 bg-zinc-50 border-zinc-100 rounded-2xl focus:ring-1 focus:ring-zinc-200 focus:bg-white transition-all shadow-sm"
          />
        </div>
      </div>

      <div className="overflow-hidden">
        <Table>
          <TableHeader className="bg-zinc-50/50 border-b border-zinc-100">
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow
                key={headerGroup.id}
                className="hover:bg-transparent border-none"
              >
                {headerGroup.headers.map((header) => {
                  return (
                    <TableHead
                      key={header.id}
                      className="h-14 text-zinc-500 font-medium text-[11px] uppercase tracking-wider px-6"
                    >
                      {header.isPlaceholder
                        ? null
                        : flexRender(
                            header.column.columnDef.header,
                            header.getContext()
                          )}
                    </TableHead>
                  );
                })}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {isLoading ? (
              <TableRow>
                <TableCell
                  colSpan={columns.length}
                  className="h-64 text-center"
                >
                  <div className="flex flex-col items-center justify-center gap-3">
                    <Loader2 className="h-8 w-8 animate-spin text-zinc-200" />
                    <p className="text-zinc-400 text-xs uppercase tracking-widest font-medium">
                      Зареждане на данни...
                    </p>
                  </div>
                </TableCell>
              </TableRow>
            ) : table.getRowModel().rows?.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow
                  key={row.id}
                  data-state={row.getIsSelected() && "selected"}
                  className="group hover:bg-zinc-50/50 transition-colors border-b border-zinc-50 last:border-none"
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id} className="px-6 py-4">
                      {getCellValue
                        ? (getCellValue(
                            row.original,
                            cell.column.id
                          ) as React.ReactNode)
                        : flexRender(
                            cell.column.columnDef.cell,
                            cell.getContext()
                          )}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell
                  colSpan={columns.length}
                  className="h-64 text-center"
                >
                  <div className="flex flex-col items-center justify-center gap-2">
                    <div className="h-12 w-12 rounded-2xl bg-zinc-50 flex items-center justify-center border border-zinc-100 mb-2">
                      <Search className="h-5 w-5 text-zinc-300" />
                    </div>
                    <p className="text-zinc-900 font-medium text-sm">
                      {emptyStateMessage}
                    </p>
                    <p className="text-zinc-400 text-xs">
                      Опитайте да потърсите с друго ключово име.
                    </p>
                  </div>
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>

      <div className="flex items-center justify-between px-2 pt-4 border-t border-zinc-100">
        <div className="text-[11px] text-zinc-400 uppercase tracking-widest font-medium">
          Страница {table.getState().pagination.pageIndex + 1} от{" "}
          {table.getPageCount()}
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => table.previousPage()}
            disabled={!table.getCanPreviousPage()}
            className="h-10 w-10 p-0 rounded-xl border-zinc-100 text-zinc-500 hover:bg-zinc-50 hover:text-zinc-900 disabled:opacity-30 transition-all"
          >
            <ChevronLeft className="h-4 w-4" />
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={() => table.nextPage()}
            disabled={!table.getCanNextPage()}
            className="h-10 w-10 p-0 rounded-xl border-zinc-100 text-zinc-500 hover:bg-zinc-50 hover:text-zinc-900 disabled:opacity-30 transition-all"
          >
            <ChevronRight className="h-4 w-4" />
          </Button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useMemo } from "react";
import { Match } from "@/types/tournament.types";
import { cn } from "@/lib/utils";
import { Trophy, Minus } from "lucide-react";

interface TournamentBracketProps {
  matches: Match[];
  getEntryName: (id?: string | null) => string;
  category: string;
}

/**
 * Visual round-robin bracket tree.
 * Renders matches grouped by round as vertical columns.
 * Completed matches show score and highlight the winner in emerald.
 * Pending matches show a subtle blue border.
 */
export function TournamentBracket({
  matches,
  getEntryName,
  category,
}: TournamentBracketProps) {
  const catMatches = useMemo(
    () => matches.filter((m) => m.categoryId === category),
    [matches, category]
  );

  const rounds = useMemo(() => {
    const roundMap = new Map<number, Match[]>();
    catMatches.forEach((m) => {
      const r = m.round ?? 1;
      if (!roundMap.has(r)) roundMap.set(r, []);
      roundMap.get(r)!.push(m);
    });
    return Array.from(roundMap.entries())
      .sort(([a], [b]) => a - b)
      .map(([round, roundMatches]) => ({ round, matches: roundMatches }));
  }, [catMatches]);

  if (catMatches.length === 0) {
    return (
      <div className="py-20 text-center text-zinc-400">
        <Trophy className="h-12 w-12 mx-auto mb-4 opacity-10" strokeWidth={1} />
        <p className="text-[11px] uppercase tracking-widest font-medium">
          Няма генерирани мачове
        </p>
      </div>
    );
  }

  const completedCount = catMatches.filter(
    (m) => m.status === "completed"
  ).length;
  const progress = Math.round((completedCount / catMatches.length) * 100);

  return (
    <div className="space-y-8">
      {/* Progress bar */}
      <div className="space-y-2 px-1">
        <div className="flex justify-between items-center">
          <span className="text-[10px] uppercase tracking-[0.2em] text-zinc-400 font-medium">
            Прогрес на турнира
          </span>
          <span className="text-[11px] font-medium text-zinc-600 tabular-nums">
            {completedCount}/{catMatches.length} мача ({progress}%)
          </span>
        </div>
        <div className="h-1.5 rounded-full bg-zinc-100 dark:bg-zinc-800 overflow-hidden">
          <div
            className={cn(
              "h-full rounded-full transition-all duration-700",
              progress === 100
                ? "bg-emerald-500"
                : progress > 50
                  ? "bg-primary"
                  : "bg-amber-400"
            )}
            style={{ width: `${progress}%` }}
          />
        </div>
      </div>

      {/* Round columns — horizontal scroll on small screens */}
      <div className="overflow-x-auto pb-4">
        <div
          className="flex gap-6 min-w-max"
          style={{ alignItems: "flex-start" }}
        >
          {rounds.map(({ round, matches: roundMatches }, colIdx) => (
            <div key={round} className="flex flex-col gap-4 w-72">
              {/* Round header */}
              <div className="flex items-center gap-2 px-2">
                <div
                  className={cn(
                    "h-6 w-6 rounded-full flex items-center justify-center text-[10px] font-black",
                    colIdx === 0
                      ? "bg-primary text-white"
                      : "bg-zinc-100 dark:bg-zinc-800 text-zinc-500"
                  )}
                >
                  {round}
                </div>
                <span className="text-[10px] uppercase tracking-[0.2em] font-bold text-zinc-400">
                  Кръг {round}
                </span>
                <div className="flex-1 h-px bg-zinc-100 dark:bg-zinc-800" />
              </div>

              {/* Match cards */}
              {roundMatches.map((match) => {
                const isCompleted = match.status === "completed";
                const p1Name = getEntryName(match.player1EntryId);
                const p2Name = getEntryName(match.player2EntryId);
                const isBye = !match.player1EntryId || !match.player2EntryId;

                return (
                  <div
                    key={match.id}
                    className={cn(
                      "rounded-3xl border transition-all duration-300 overflow-hidden",
                      isCompleted
                        ? "border-emerald-100 dark:border-emerald-900/30 bg-emerald-50/30 dark:bg-emerald-950/10"
                        : "border-zinc-100 dark:border-zinc-800 bg-white dark:bg-zinc-950 hover:border-primary/30"
                    )}
                  >
                    {/* Completed badge */}
                    {isCompleted && (
                      <div className="px-4 pt-3 pb-1">
                        <span className="text-[8px] font-black uppercase tracking-[0.3em] text-emerald-500">
                          Завършен
                        </span>
                      </div>
                    )}

                    {/* Players */}
                    <div className="px-4 pb-3 pt-2 space-y-2">
                      {isBye ? (
                        <div className="flex items-center gap-2 text-zinc-300 dark:text-zinc-600 py-2">
                          <Minus className="h-3 w-3" />
                          <span className="text-xs font-light">
                            Почивка (BYE)
                          </span>
                        </div>
                      ) : (
                        <>
                          {/* Player 1 */}
                          <div
                            className={cn(
                              "flex items-center justify-between gap-2 rounded-xl px-3 py-2 transition-colors",
                              isCompleted &&
                                match.winnerEntryId === match.player1EntryId
                                ? "bg-emerald-500 text-white"
                                : isCompleted
                                  ? "bg-zinc-100/50 dark:bg-zinc-800/50 text-zinc-400"
                                  : "bg-zinc-50 dark:bg-zinc-900 text-zinc-700 dark:text-zinc-300"
                            )}
                          >
                            <div className="flex items-center gap-2 min-w-0">
                              {isCompleted &&
                                match.winnerEntryId ===
                                  match.player1EntryId && (
                                  <Trophy className="h-3 w-3 text-yellow-300 shrink-0" />
                                )}
                              <span className="text-xs font-medium truncate">
                                {p1Name}
                              </span>
                            </div>
                          </div>

                          {/* VS divider with score */}
                          <div className="flex items-center justify-between px-1">
                            <span className="text-[9px] uppercase tracking-widest text-zinc-300 dark:text-zinc-600 font-medium">
                              срещу
                            </span>
                            {isCompleted && match.score && (
                              <span className="text-[11px] font-mono font-bold text-zinc-600 dark:text-zinc-400 tracking-wider">
                                {match.score}
                              </span>
                            )}
                          </div>

                          {/* Player 2 */}
                          <div
                            className={cn(
                              "flex items-center justify-between gap-2 rounded-xl px-3 py-2 transition-colors",
                              isCompleted &&
                                match.winnerEntryId === match.player2EntryId
                                ? "bg-emerald-500 text-white"
                                : isCompleted
                                  ? "bg-zinc-100/50 dark:bg-zinc-800/50 text-zinc-400"
                                  : "bg-zinc-50 dark:bg-zinc-900 text-zinc-700 dark:text-zinc-300"
                            )}
                          >
                            <div className="flex items-center gap-2 min-w-0">
                              {isCompleted &&
                                match.winnerEntryId ===
                                  match.player2EntryId && (
                                  <Trophy className="h-3 w-3 text-yellow-300 shrink-0" />
                                )}
                              <span className="text-xs font-medium truncate">
                                {p2Name}
                              </span>
                            </div>
                          </div>
                        </>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import {
  Match,
  MatchFormatPreset,
  isValidGameScore,
  getMatchFormat,
} from "@/types/tournament.types";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import {
  Plus,
  Minus,
  Trophy,
  X,
  AlertCircle,
  CheckCircle2,
} from "lucide-react";

interface GameScore {
  p1: number;
  p2: number;
}

interface ScoreDialogProps {
  isOpen: boolean;
  match: Match | null;
  matchFormatId?: string;
  getEntryName: (id?: string | null) => string;
  onClose: () => void;
  onSave: (
    matchId: string,
    score: string,
    winnerEntryId: string
  ) => Promise<void>;
}

function parseScoreString(score: string): GameScore[] {
  if (!score) return [{ p1: 0, p2: 0 }];
  return score.split(",").map((s) => {
    const parts = s.trim().split("-");
    return { p1: parseInt(parts[0]) || 0, p2: parseInt(parts[1]) || 0 };
  });
}

function buildScoreString(games: GameScore[]): string {
  return games.map((g) => `${g.p1}-${g.p2}`).join(", ");
}

function countWins(games: GameScore[]): { p1: number; p2: number } {
  return games.reduce(
    (acc, g) => {
      if (g.p1 > g.p2) acc.p1++;
      else if (g.p2 > g.p1) acc.p2++;
      return acc;
    },
    { p1: 0, p2: 0 }
  );
}

export function ScoreDialog({
  isOpen,
  match,
  matchFormatId,
  getEntryName,
  onClose,
  onSave,
}: ScoreDialogProps) {
  const [games, setGames] = useState<GameScore[]>(() => {
    if (match?.score && isOpen) {
      return parseScoreString(match.score);
    }
    return [{ p1: 0, p2: 0 }];
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  const fmt: MatchFormatPreset = getMatchFormat(matchFormatId);
  const maxGames = fmt.gamesNeededToWin * 2 - 1;

  // Use useEffect to reset games when match or isOpen changes,
  // though key={match.id} in parent handles most cases.

  if (!match) return null;

  const player1Name = getEntryName(match.player1EntryId);
  const player2Name = getEntryName(match.player2EntryId);
  const wins = countWins(games);

  // Валидираме всеки гейм
  const gameValidations = games.map((g) => {
    if (g.p1 === 0 && g.p2 === 0) return null; // Непопълнен гейм
    return isValidGameScore(g.p1, g.p2, fmt);
  });

  const allGamesValid = gameValidations.every((v) => v === null || v.valid);

  // Проверяваме дали мачът е приключил (някой е достигнал нужния брой геймове)
  const matchOver =
    wins.p1 >= fmt.gamesNeededToWin || wins.p2 >= fmt.gamesNeededToWin;

  const autoWinnerId =
    wins.p1 >= fmt.gamesNeededToWin
      ? match.player1EntryId
      : wins.p2 >= fmt.gamesNeededToWin
        ? match.player2EntryId
        : null;

  const canSave = allGamesValid && !!autoWinnerId;

  const updateScore = (gameIdx: number, player: "p1" | "p2", delta: number) => {
    setGames((prev) =>
      prev.map((g, i) => {
        if (i !== gameIdx) return g;
        const val = Math.max(0, g[player] + delta);
        const otherPlayer = player === "p1" ? "p2" : "p1";

        let newOtherVal = g[otherPlayer];
        if (delta > 0 && val > 0 && newOtherVal === 0) {
          if (val < fmt.pointsPerGame - 1) {
            newOtherVal = fmt.pointsPerGame;
          } else {
            newOtherVal = val + 2;
            if (fmt.maxPoints > 0 && newOtherVal > fmt.maxPoints)
              newOtherVal = fmt.maxPoints;
          }
        }

        return { ...g, [player]: val, [otherPlayer]: newOtherVal };
      })
    );
  };

  const setScore = (gameIdx: number, player: "p1" | "p2", value: number) => {
    setGames((prev) =>
      prev.map((g, i) => {
        if (i !== gameIdx) return g;
        const val = Math.max(0, isNaN(value) ? 0 : value);
        const otherPlayer = player === "p1" ? "p2" : "p1";

        // Автоматично попълване: ако другият играч е на 0, предлагаме победен резултат
        let newOtherVal = g[otherPlayer];
        if (val > 0 && newOtherVal === 0) {
          if (val < fmt.pointsPerGame - 1) {
            newOtherVal = fmt.pointsPerGame;
          } else {
            newOtherVal = val + 2;
            if (fmt.maxPoints > 0 && newOtherVal > fmt.maxPoints)
              newOtherVal = fmt.maxPoints;
          }
        }

        return { ...g, [player]: val, [otherPlayer]: newOtherVal };
      })
    );
  };

  const addGame = () => {
    if (games.length < maxGames) {
      setGames((prev) => [...prev, { p1: 0, p2: 0 }]);
    }
  };

  const removeGame = (idx: number) =>
    setGames((prev) => prev.filter((_, i) => i !== idx));

  const handleSave = async () => {
    if (!canSave || !autoWinnerId) return;
    setIsSubmitting(true);
    try {
      const scoreString = buildScoreString(
        games.filter((g) => !(g.p1 === 0 && g.p2 === 0))
      );
      await onSave(
        match.id!,
        scoreString || buildScoreString(games),
        autoWinnerId
      );
      onClose();
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="bg-white dark:bg-zinc-950 border-zinc-200 dark:border-zinc-800 sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>Въвеждане на резултат</DialogTitle>
        </DialogHeader>

        {/* Формат */}
        <div className="text-xs text-center text-muted-foreground bg-muted/50 px-3 py-1.5 rounded-md border">
          📋 Формат:{" "}
          <span className="font-medium text-foreground">{fmt.label}</span>
        </div>

        <div className="py-2 space-y-5">
          {/* Заглавна лента с имената */}
          <div className="grid grid-cols-3 gap-2 text-sm font-semibold text-center">
            <div
              className={`px-3 py-2 rounded-lg truncate transition-colors ${
                wins.p1 > wins.p2
                  ? "bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400"
                  : wins.p2 > wins.p1
                    ? "bg-muted text-muted-foreground"
                    : "bg-muted"
              }`}
            >
              {player1Name}
            </div>
            <div className="flex flex-col items-center justify-center gap-0.5">
              <span className="text-muted-foreground text-xs font-normal">
                VS
              </span>
              {matchOver && (
                <span className="text-[10px] font-bold text-green-600">
                  {wins.p1}–{wins.p2}
                </span>
              )}
            </div>
            <div
              className={`px-3 py-2 rounded-lg truncate transition-colors ${
                wins.p2 > wins.p1
                  ? "bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400"
                  : wins.p1 > wins.p2
                    ? "bg-muted text-muted-foreground"
                    : "bg-muted"
              }`}
            >
              {player2Name}
            </div>
          </div>

          {/* Резултати по геймове */}
          <div className="space-y-3">
            {games.map((game, idx) => {
              const validation = gameValidations[idx];
              const hasError = validation && !validation.valid;
              const isOk = validation && validation.valid;

              return (
                <div key={idx} className="space-y-1">
                  <div className="grid grid-cols-[1fr_auto_1fr] gap-3 items-center">
                    {/* Играч 1 */}
                    <div className="flex items-center gap-1 justify-end">
                      <button
                        type="button"
                        onClick={() => updateScore(idx, "p1", -1)}
                        className="w-8 h-8 rounded-full border flex items-center justify-center hover:bg-muted transition-colors"
                      >
                        <Minus className="w-3 h-3" />
                      </button>
                      <input
                        type="number"
                        min={0}
                        value={game.p1}
                        onChange={(e) =>
                          setScore(idx, "p1", parseInt(e.target.value))
                        }
                        className={`w-14 h-10 text-center text-xl font-bold border rounded-lg bg-background focus:outline-none focus:ring-2 transition-colors ${
                          hasError
                            ? "border-red-400 focus:ring-red-400"
                            : isOk
                              ? "border-green-400 focus:ring-green-400"
                              : "focus:ring-primary"
                        }`}
                      />
                      <button
                        type="button"
                        onClick={() => updateScore(idx, "p1", 1)}
                        className="w-8 h-8 rounded-full border flex items-center justify-center hover:bg-muted transition-colors"
                      >
                        <Plus className="w-3 h-3" />
                      </button>
                    </div>

                    {/* Разделител */}
                    <div className="flex flex-col items-center gap-1">
                      <span className="text-[10px] text-muted-foreground uppercase tracking-wider">
                        Гейм {idx + 1}
                      </span>
                      {isOk && (
                        <CheckCircle2 className="w-3 h-3 text-green-500" />
                      )}
                      {hasError && (
                        <AlertCircle className="w-3 h-3 text-red-500" />
                      )}
                      {games.length > 1 && !isOk && (
                        <button
                          type="button"
                          onClick={() => removeGame(idx)}
                          className="text-muted-foreground hover:text-destructive transition-colors"
                        >
                          <X className="w-3 h-3" />
                        </button>
                      )}
                    </div>

                    {/* Играч 2 */}
                    <div className="flex items-center gap-1 justify-start">
                      <button
                        type="button"
                        onClick={() => updateScore(idx, "p2", -1)}
                        className="w-8 h-8 rounded-full border flex items-center justify-center hover:bg-muted transition-colors"
                      >
                        <Minus className="w-3 h-3" />
                      </button>
                      <input
                        type="number"
                        min={0}
                        value={game.p2}
                        onChange={(e) =>
                          setScore(idx, "p2", parseInt(e.target.value))
                        }
                        className={`w-14 h-10 text-center text-xl font-bold border rounded-lg bg-background focus:outline-none focus:ring-2 transition-colors ${
                          hasError
                            ? "border-red-400 focus:ring-red-400"
                            : isOk
                              ? "border-green-400 focus:ring-green-400"
                              : "focus:ring-primary"
                        }`}
                      />
                      <button
                        type="button"
                        onClick={() => updateScore(idx, "p2", 1)}
                        className="w-8 h-8 rounded-full border flex items-center justify-center hover:bg-muted transition-colors"
                      >
                        <Plus className="w-3 h-3" />
                      </button>
                    </div>
                  </div>

                  {/* Грешка за гейма */}
                  {hasError && (
                    <p className="text-xs text-red-500 text-center flex items-center justify-center gap-1">
                      <AlertCircle className="w-3 h-3" />
                      {validation?.error}
                    </p>
                  )}
                </div>
              );
            })}
          </div>

          {/* Добави гейм */}
          {!matchOver && games.length < maxGames && (
            <Button
              variant="outline"
              size="sm"
              className="w-full"
              onClick={addGame}
              type="button"
            >
              <Plus className="w-4 h-4 mr-2" /> Добави гейм
            </Button>
          )}

          {/* Победител preview */}
          <div
            className={`p-3 rounded-lg text-center text-sm font-semibold transition-all border ${
              autoWinnerId && allGamesValid
                ? "bg-yellow-50 text-yellow-700 dark:bg-yellow-900/20 dark:text-yellow-400 border-yellow-200 dark:border-yellow-800"
                : !allGamesValid
                  ? "bg-red-50 text-red-600 dark:bg-red-900/20 dark:text-red-400 border-red-200 dark:border-red-800"
                  : "bg-muted text-muted-foreground border-transparent"
            }`}
          >
            {!allGamesValid ? (
              <span className="flex items-center justify-center gap-2">
                <AlertCircle className="w-4 h-4" />
                Невалиден резултат за формат &quot;{fmt.label}&quot;
              </span>
            ) : autoWinnerId ? (
              <span className="flex items-center justify-center gap-2">
                <Trophy className="w-4 h-4" />
                Победител: {getEntryName(autoWinnerId)}
              </span>
            ) : wins.p1 === wins.p2 && games.length < maxGames ? (
              `Равен резултат – добавете ${fmt.gamesNeededToWin > 1 ? "решителен гейм" : "още точки"}`
            ) : (
              "Въведете резултатите"
            )}
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={onClose} disabled={isSubmitting}>
            Отказ
          </Button>
          <Button onClick={handleSave} disabled={isSubmitting || !canSave}>
            Запази резултат
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

