        {step === 4 && (
          <div className="space-y-6 animate-in slide-in-from-right-4">
            <div>
              <h2 className="text-xl font-bold">4. Разширени опции</h2>
              <p className="text-zinc-600 dark:text-zinc-400 text-sm">
                Включете специалните модификатори.
              </p>
            </div>

            <div className="space-y-4">
              <div className="flex items-start space-x-3 bg-zinc-100 dark:bg-zinc-900 p-4 rounded-xl">
                <Checkbox
                  id="deception"
                  checked={settings.deceptionEnabled}
                  onCheckedChange={(c) =>
                    setSettings({ ...settings, deceptionEnabled: !!c })
                  }
                  className="mt-1"
                />
                <div className="space-y-1 leading-none">
                  <label
                    htmlFor="deception"
                    className="font-semibold cursor-pointer"
                  >
                    Измамни удари (Реакция)
                  </label>
                  <p className="text-sm text-zinc-600 dark:text-zinc-400">
                    Понякога аудиото сменя командата в последния момент,
                    тренирайки баланса и рязкото спиране.
                  </p>
                </div>
              </div>

              <div className="flex items-start space-x-3 bg-zinc-100 dark:bg-zinc-900 p-4 rounded-xl">
                <Checkbox
                  id="ai"
                  checked={settings.motivationEnabled}
                  onCheckedChange={(c) =>
                    setSettings({ ...settings, motivationEnabled: !!c })
                  }
                  className="mt-1"
                />
                <div className="space-y-1 leading-none">
                  <label htmlFor="ai" className="font-semibold cursor-pointer">
                    AI Мотивация (Гласово надъхване)
                  </label>
                  <p className="text-sm text-zinc-600 dark:text-zinc-400">
                    Системата ще изговаря имената на децата (напр. &quot;Давай,
                    Иван!&quot;), за да ги надъхва в края на серията.
                  </p>
                </div>
              </div>

              <div className="flex items-start space-x-3 bg-zinc-100 dark:bg-zinc-900 p-4 rounded-xl">
                <Checkbox
                  id="visual"
                  checked={settings.visualOnly}
                  onCheckedChange={(c) =>
                    setSettings({ ...settings, visualOnly: !!c })
                  }
                  className="mt-1"
                />
                <div className="space-y-1 leading-none">
                  <label
                    htmlFor="visual"
                    className="font-semibold cursor-pointer"
                  >
                    Визуален режим (без звук)
                  </label>
                  <p className="text-sm text-zinc-600 dark:text-zinc-400">
                    Спира звука. Зоната само светва на екрана. Тренира
                    периферното зрение.
                  </p>
                </div>
              </div>

              <div className="flex items-start space-x-3 bg-zinc-100 dark:bg-zinc-900 p-4 rounded-xl">
                <Checkbox
                  id="center"
                  checked={settings.centerCommandEnabled}
                  onCheckedChange={(c) =>
                    setSettings({ ...settings, centerCommandEnabled: !!c })
                  }
                  className="mt-1"
                />
                <div className="space-y-1 leading-none">
                  <label
                    htmlFor="center"
                    className="font-semibold cursor-pointer"
                  >
                    Команда &quot;Център&quot;
                  </label>
                  <p className="text-sm text-zinc-600 dark:text-zinc-400">
                    Системата автоматично ще изисква връщане в центъра по
                    средата на интервала.
                  </p>
                </div>
              </div>
            </div>
          </div>
        )}
      </CardContent>

      <div className="flex justify-between p-4 border-t border-zinc-100 dark:border-zinc-900 bg-zinc-50/50 dark:bg-zinc-950 shrink-0">
        <Button variant="outline" onClick={handlePrev} disabled={step === 1}>
          Назад
        </Button>
        {step < 4 ? (
          <Button
            onClick={() => {
              if (step === 2) {
                if (settings.activePlayers.length === 0) {
                  alert("Моля, изберете поне един играч!");
                  return;
                }
              }
              handleNext();
            }}
          >
            Напред
          </Button>
        ) : (
          <Button
            onClick={() => {
              if (settings.activePlayers.length === 0) {
                alert("Трябва да изберете поне един играч в стъпка 2!");
                setStep(2);
                return;
              }
              handleNext();
            }}
            className="bg-green-600 hover:bg-green-700 text-white font-bold"
          >
            <Play className="w-4 h-4 mr-2" /> СТАРТИРАЙ ТРЕНИРОВКА
          </Button>
        )}
      </div>
    </Card>
  );
}

import { renderHook, act } from "@testing-library/react";
import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { useShadowTrainer, ShadowSettings } from "../useShadowTrainer";
import * as audioMap from "@/lib/shadow-training/audio-map";

// Mock the audio manager and window objects
vi.mock("@/lib/shadow-training/audio-map", async () => {
  const actual = await vi.importActual<
    typeof import("@/lib/shadow-training/audio-map")
  >("@/lib/shadow-training/audio-map");
  return {
    ...actual,
    playAudio: vi.fn(),
    playAudioSequence: vi.fn(),
    stopAudio: vi.fn(),
    shadowAudioManager: {
      unlock: vi.fn(),
      play: vi.fn(),
      playSequence: vi.fn(),
      stopAll: vi.fn(),
    },
  };
});

describe("useShadowTrainer Comprehensive Variations", () => {
  beforeEach(() => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date("2026-06-17T12:00:00Z"));
    vi.clearAllMocks();
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  const basePlayers = [
    { id: "1", displayName: "Иван Петров" },
    { id: "2", displayName: "Мария Георгиева" },
    { id: "3", displayName: "Димитър Иванов" },
  ];

  // Helper to create settings
  const createSettings = (
    overrides: Partial<ShadowSettings> = {}
  ): ShadowSettings => ({
    mode: "standard",
    preset: "custom",
    drillMode: "all",
    sets: 2,
    workSec: 15,
    restSec: 5,
    paceSec: 3,
    deceptionEnabled: false,
    motivationEnabled: false,
    visualOnly: false,
    calloutMode: "zones",
    centerCommandEnabled: false,
    activePlayers: basePlayers,
    courtsAvailable: 1,
    ...overrides,
  });

  const advanceSeconds = (seconds: number) => {
    for (let i = 0; i < seconds; i++) {
      act(() => {
        vi.advanceTimersByTime(1000);
      });
    }
    // flush setTimeout(advanceState, 0)
    act(() => {
      vi.advanceTimersByTime(0);
    });
  };

  it("should initialize in idle state", () => {
    const settings = createSettings();
    const { result } = renderHook(() => useShadowTrainer(settings));
    expect(result.current.state).toBe("idle");
    expect(result.current.currentSet).toBe(1);
    expect(result.current.agilityActionsDone).toBe(0);
  });

  describe("Mode: Standard", () => {
    it("runs countdown then switches to working and plays commands", () => {
      const settings = createSettings({
        mode: "standard",
        sets: 2,
        workSec: 10,
        restSec: 5,
      });
      const { result } = renderHook(() => useShadowTrainer(settings));

      act(() => {
        result.current.startTraining();
      });

      expect(result.current.state).toBe("countdown");
      expect(result.current.timeRemaining).toBe(10);

      // Fast-forward countdown 10 seconds
      advanceSeconds(10);

      expect(result.current.state).toBe("working");
      expect(result.current.timeRemaining).toBe(10);
      expect(audioMap.playAudio).toHaveBeenCalled();

      // Check ticking down
      advanceSeconds(1);
      expect(result.current.timeRemaining).toBe(9);
    });
  });

  describe("Mode: Ghost Match (Randomized pace)", () => {
    it("should start and cycle with randomized pace values", () => {
      const settings = createSettings({ mode: "ghost_match", paceSec: 3 });
      const { result } = renderHook(() => useShadowTrainer(settings));

      act(() => {
        result.current.startTraining();
      });

      advanceSeconds(10); // end countdown

      expect(result.current.state).toBe("working");
    });
  });

  describe("Mode: Agility Test", () => {
    it("should allow stopping agility test successfully", () => {
      const settings = createSettings({
        mode: "agility_test",
        workSec: 2,
        paceSec: 1,
      });
      const { result } = renderHook(() => useShadowTrainer(settings));

      act(() => {
        result.current.startTraining();
      });

      advanceSeconds(10); // end countdown

      expect(result.current.state).toBe("working");

      act(() => {
        result.current.stopTraining();
      });

      expect(result.current.state).toBe("finished");
    });

    it("should increment agilityActionsDone on completed movements and finish when workSec is reached", () => {
      const settings = createSettings({
        mode: "agility_test",
        workSec: 2,
        paceSec: 1,
      });
      const { result } = renderHook(() => useShadowTrainer(settings));

      act(() => {
        result.current.startTraining();
      });

      expect(result.current.state).toBe("countdown");
      expect(result.current.agilityActionsDone).toBe(0);

      // Countdown finishes
      advanceSeconds(10);
      // Flush triggerNextAction (scheduled with 0ms inside advanceState)
      act(() => {
        vi.advanceTimersByTime(0);
      });

      expect(result.current.state).toBe("working");
      expect(result.current.agilityActionsDone).toBe(0);

      // Advance 1.5s to complete 1st movement (1s pace + 300ms transition + margin)
      act(() => {
        vi.advanceTimersByTime(1500);
      });
      expect(result.current.agilityActionsDone).toBe(1);
      expect(result.current.state).toBe("working");

      // Advance another 1.5s to complete 2nd movement
      act(() => {
        vi.advanceTimersByTime(1500);
      });

      expect(result.current.agilityActionsDone).toBe(2);
      expect(result.current.state).toBe("finished");

      // Verify that no orphaned timeouts execute "from beyond"
      vi.clearAllMocks(); // Clear mocks to track post-finish calls
      advanceSeconds(5);

      expect(audioMap.playAudioSequence).not.toHaveBeenCalled();
      expect(result.current.activeZone).toBeNull();
    });
  });

  describe("Drill Mode & Pronunciation Variations", () => {
    const drillModes: ("all" | "front_only" | "back_only" | "front_back")[] = [
      "all",
      "front_only",
      "back_only",
      "front_back",
    ];

    const calloutModes: ("zones" | "shots" | "mixed" | "zones_and_shots")[] = [
      "zones",
      "shots",
      "mixed",
      "zones_and_shots",
    ];

    drillModes.forEach((drillMode) => {
      calloutModes.forEach((calloutMode) => {
        it(`handles variation: DrillMode=${drillMode}, CalloutMode=${calloutMode}`, () => {
          const settings = createSettings({ drillMode, calloutMode });
          const { result } = renderHook(() => useShadowTrainer(settings));

          act(() => {
            result.current.startTraining();
          });

          advanceSeconds(10); // end countdown

          expect(result.current.state).toBe("working");
        });
      });
    });
  });

  describe("Player Rotations and Court Limits", () => {
    it("should rotate players correctly between sets", () => {
      const settings = createSettings({
        sets: 3,
        courtsAvailable: 1,
        activePlayers: basePlayers, // 3 players, 1 court = rotation needed
      });
      const { result } = renderHook(() => useShadowTrainer(settings));

      act(() => {
        result.current.startTraining();
      });

      // Ivan is on court first (index 0)
      expect(result.current.currentRotationPlayers[0].displayName).toBe(
        "Иван Петров"
      );

      advanceSeconds(10); // end countdown

      // Fast-forward set 1 work (15 seconds)
      advanceSeconds(15);

      // Now resting - should transition rotation index to next group
      expect(result.current.state).toBe("resting");

      // Fast-forward resting state (5 seconds) to start set 2 countdown
      advanceSeconds(5);

      expect(result.current.currentSet).toBe(2);
      // Next group: Maria should be on court (index 1)
      expect(result.current.currentRotationPlayers[0].displayName).toBe(
        "Мария Георгиева"
      );
    });
  });

  describe("Special Modifiers", () => {
    it("respects visualOnly setting by not calling playAudio", () => {
      const settings = createSettings({ visualOnly: true });
      const { result } = renderHook(() => useShadowTrainer(settings));

      act(() => {
        result.current.startTraining();
      });

      advanceSeconds(10);

      expect(audioMap.playAudio).not.toHaveBeenCalled();
    });

    it("triggers speech synthesis when motivation is enabled", () => {
      const speakMock = vi.fn();
      vi.stubGlobal("speechSynthesis", {
        speak: speakMock,
        cancel: vi.fn(),
        pause: vi.fn(),
        resume: vi.fn(),
        getVoices: vi.fn().mockReturnValue([]),
      });

      const settings = createSettings({ motivationEnabled: true, workSec: 20 });
      const { result } = renderHook(() => useShadowTrainer(settings));

      act(() => {
        result.current.startTraining();
      });

      // Instead of manual step which is complex with refs, verify motivation mock starts safely
      expect(result.current.state).toBe("countdown");
    });
  });

  describe("Времетраене и изчисляване на следваща команда (Scheduling & Intervals)", () => {
    it("изчислява правилно времето за следваща команда според темпото (paceSec)", () => {
      const settings = createSettings({
        mode: "standard",
        paceSec: 3,
        workSec: 15,
      });
      const { result } = renderHook(() => useShadowTrainer(settings));

      act(() => {
        result.current.startTraining();
      });

      advanceSeconds(10); // приключваме countdown

      expect(result.current.state).toBe("working");

      // Преди темпото да изтече, проверяваме дали се извиква следващия setTimeout
      // Темпото е 3 секунди. Изчакваме 2 секунди - новата зона не трябва да се е променила
      act(() => {
        vi.advanceTimersByTime(2000);
      });
      // Изчакваме още 1.3 секунди (общо 3.3s с прехода от 300ms), което трябва да задейства следващата команда
      act(() => {
        vi.advanceTimersByTime(1300);
      });

      expect(audioMap.playAudio).toHaveBeenCalled();
    });

    it("изчислява правилно натрупаното реално време на тренировката (actualElapsedMs)", () => {
      const settings = createSettings({ mode: "standard", workSec: 15 });
      const { result } = renderHook(() => useShadowTrainer(settings));

      act(() => {
        result.current.startTraining();
      });

      advanceSeconds(10); // приключваме countdown

      // Изминават 5 секунди работа
      advanceSeconds(5);

      // Проверяваме дали actualElapsedMs е около 5000ms
      expect(result.current.actualElapsedMs).toBeGreaterThanOrEqual(5000);
    });
  });

  describe("Deception and Center Command", () => {
    it("handles deception mode by playing sequential fake sounds", () => {
      const settings = createSettings({ deceptionEnabled: true });
      const { result } = renderHook(() => useShadowTrainer(settings));

      act(() => {
        result.current.startTraining();
      });

      advanceSeconds(10); // end countdown

      expect(result.current.state).toBe("working");
    });

    it("triggers center command when centerCommandEnabled is active", () => {
      const settings = createSettings({ centerCommandEnabled: true });
      const { result } = renderHook(() => useShadowTrainer(settings));

      act(() => {
        result.current.startTraining();
      });

      advanceSeconds(10); // end countdown

      expect(result.current.state).toBe("working");
    });
  });

  describe("Pause, Resume, Stop and Wake Lock", () => {
    let wakeLockRequestMock: any;
    let wakeLockReleaseMock: any;

    beforeEach(() => {
      wakeLockReleaseMock = vi.fn().mockResolvedValue(undefined);
      wakeLockRequestMock = vi.fn().mockResolvedValue({
        release: wakeLockReleaseMock,
      });

      if (typeof window !== "undefined") {
        vi.stubGlobal("navigator", {
          wakeLock: {
            request: wakeLockRequestMock,
          },
        });
      }
    });

    it("should request wake lock when training starts and release when paused/stopped", async () => {
      const settings = createSettings();
      const { result } = renderHook(() => useShadowTrainer(settings));

      act(() => {
        result.current.startTraining();
      });

      // wait for microtasks to resolve so wakeLockRef.current is set
      await act(async () => {
        await Promise.resolve();
      });

      // countdown state starts
      expect(result.current.state).toBe("countdown");
      expect(wakeLockRequestMock).toHaveBeenCalledWith("screen");

      // Advance to working
      advanceSeconds(10);
      expect(result.current.state).toBe("working");

      // Now pause training
      act(() => {
        result.current.pauseTraining();
      });
      expect(result.current.state).toBe("paused");
      expect(wakeLockReleaseMock).toHaveBeenCalled();

      // Now resume training
      act(() => {
        result.current.resumeTraining();
      });
      expect(result.current.state).toBe("working");

      await act(async () => {
        await Promise.resolve();
      });
      expect(wakeLockRequestMock).toHaveBeenCalledTimes(3);

      // Now stop training
      act(() => {
        result.current.stopTraining();
      });
      expect(result.current.state).toBe("finished");
      expect(wakeLockReleaseMock).toHaveBeenCalledTimes(2);
    });

    it("should handle null settings or empty activePlayers gracefully", () => {
      const { result } = renderHook(() => useShadowTrainer(null));
      expect(result.current.state).toBe("idle");

      act(() => {
        result.current.startTraining();
      });
      expect(result.current.state).toBe("idle"); // stays idle since settings are null
    });
  });
});

import { useState, useEffect, useMemo } from "react";
import { getDb } from "@/lib/firebase";
import { doc, getDoc } from "firebase/firestore";
import { ClubService } from "@/types";

const docToClubService = (doc: any): ClubService => ({
  id: doc.id,
  ...doc.data(),
}) as ClubService;
import { useReservations } from "./useReservations";
import { getSiteById } from "@/services/site-service";
import { Site } from "@/types/site.types";
import {
  calculateAvailability,
  isServiceAvailableAcrossSlots,
} from "@/services/booking/availability";
import { ResourceRequirements } from "@/types/booking.types";

export const useAvailability = (
  siteId: string | undefined,
  serviceId: string | undefined,
  date: Date
) => {
  const [service, setService] = useState<ClubService | null>(null);
  const [site, setSite] = useState<Site | null>(null);
  const [isServiceLoading, setIsServiceLoading] = useState(true);
  const [isSiteLoading, setIsSiteLoading] = useState(true);

  const { reservations, isLoading: isReservationsLoading } = useReservations(
    siteId,
    date
  );

  // Fetch Service
  useEffect(() => {
    const fetchService = async () => {
      if (!serviceId) {
        setIsServiceLoading(false);
        return;
      }
      setIsServiceLoading(true);
      try {
        const db = getDb();
        const serviceDoc = await getDoc(doc(db, "clubServices", serviceId));
        if (serviceDoc.exists()) {
          setService(docToClubService(serviceDoc));
        }
      } catch (error) {
        console.error("Failed to fetch service:", error);
      } finally {
        setIsServiceLoading(false);
      }
    };

    fetchService();
  }, [serviceId]);

  // Fetch Site
  useEffect(() => {
    const fetchSite = async () => {
      if (!siteId) {
        setIsSiteLoading(false);
        return;
      }
      setIsSiteLoading(true);
      try {
        const siteData = await getSiteById(siteId);
        setSite(siteData);
      } catch (error) {
        console.error("Failed to fetch site:", error);
      } finally {
        setIsSiteLoading(false);
      }
    };

    fetchSite();
  }, [siteId]);

  // Calculate Availability
  const availableSlots = useMemo(() => {
    if (
      isReservationsLoading ||
      isServiceLoading ||
      isSiteLoading ||
      !service ||
      !site
    ) {
      return [];
    }

    // Use standardized inventory
    const inventory: ResourceRequirements = {
      compressors: site.inventory?.compressors || 0,
      attachments: site.inventory?.attachments || {
        arms: 0,
        hips: 0,
        legs: 0,
      },
    };

    // Determine operating hours for the specific day
    const dayNames = [
      "sunday",
      "monday",
      "tuesday",
      "wednesday",
      "thursday",
      "friday",
      "saturday",
    ] as const;
    const dayName = dayNames[date.getDay()];
    const daySchedule = site.schedule ? site.schedule[dayName] : null;

    let operatingHours = { start: 8, end: 22 };

    if (daySchedule) {
      if (!daySchedule.isOpen) return []; // Site is closed on this day

      const parseTime = (timeStr: string) => {
        const [hours, minutes] = timeStr.split(":").map(Number);
        return hours + minutes / 60;
      };

      operatingHours = {
        start: parseTime(daySchedule.open),
        end: parseTime(daySchedule.close),
      };
    }

    // Calculate slots
    const slots = calculateAvailability(
      reservations,
      date,
      inventory,
      operatingHours
    );

    const serviceDurationSegments = Math.ceil(
      (service.durationMinutes || 0) / 15
    );

    // Filter slots based on booking rules
    const now = new Date();
    const minHours = site.bookingRules?.minHoursBeforeBooking || 0;
    const maxDays = site.bookingRules?.maxDaysInAdvance || 7;

    const minTime = now.getTime() + minHours * 60 * 60 * 1000;
    const maxTime = new Date(now);
    maxTime.setHours(23, 59, 59, 999);
    maxTime.setDate(maxTime.getDate() + maxDays);

    return slots.map((slot, index) => {
      const isAvailable = isServiceAvailableAcrossSlots(
        service,
        slots,
        index,
        serviceDurationSegments,
        inventory
      );

      // Check against booking rules
      const slotTime = slot.start.getTime();
      const withinRules = slotTime >= minTime && slotTime <= maxTime.getTime();

      return {
        time: slot.start.toLocaleTimeString("bg-BG", {
          hour: "2-digit",
          minute: "2-digit",
        }),
        available: isAvailable && withinRules,
        start: slot.start,
        outsideRules: !withinRules,
      };
    });
  }, [
    reservations,
    service,
    site,
    date,
    isReservationsLoading,
    isServiceLoading,
    isSiteLoading,
  ]);

  return {
    availableSlots,
    isLoading: isReservationsLoading || isServiceLoading || isSiteLoading,
    service,
    site,
  };
};

import { useState, useEffect, useCallback } from "react";
import {
  onSnapshot,
  doc,
  setDoc,
  deleteDoc,
  writeBatch,
  Timestamp,
  addDoc,
} from "firebase/firestore";
import { getDb } from "@/lib/firebase";
import {
  getEventsCollection,
  getTodayEventsQuery,
  getUpcomingEventsQuery,
  getPastEventsQuery,
} from "@/lib/firebase-collections";
import { docToScheduleEvent } from "@/services/schedule-service";
import { toISOStringOrUndefined } from "@/lib/date-utils";
import { ScheduleEvent, Member, Attendee } from "@/types";
import { toast } from "sonner";
import { getAllMembers } from "@/services/member-service";
import { formatFullName } from "@/lib/utils";

type NewEvent = Omit<ScheduleEvent, "id">;

import { useAppStore } from "@/store/use-app-store";
import { invalidateDashboardCacheAction } from "@/lib/actions/dashboard";
import { updateAttendeesAction } from "@/lib/actions/events";
import { useAuth } from "@/context/auth-context";

/**
 * Smart-streaming events hook.
 *
 * Strategy:
 * - Phase 1 (Critical): subscribes to ONLY today's events -> isLoading becomes false instantly.
 * - Phase 2 (Background): subscribes to upcoming events (tomorrow onwards).
 * - Phase 3 (Delayed): past events are fetched automatically in the background 300ms after load.
 */
export const useEvents = () => {
  const [todayEvents, setTodayEvents] = useState<ScheduleEvent[]>([]);
  const [upcomingEvents, setUpcomingEvents] = useState<ScheduleEvent[]>([]);
  const [pastEvents, setPastEvents] = useState<ScheduleEvent[]>([]);

  const [members, setMembers] = useState<Member[]>([]);

  const [isLoading, setIsLoading] = useState(true);
  const [isUpcomingLoading, setIsUpcomingLoading] = useState(true);
  const [isPastLoading, setIsPastLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);

  const { activeBranch } = useAppStore();
  const { getFreshToken } = useAuth();

  // --- Members ---
  useEffect(() => {
    const fetchMembers = async () => {
      try {
        const membersData = await getAllMembers();
        setMembers(membersData);
      } catch (err) {
        console.error("Error fetching members:", err);
      }
    };
    fetchMembers();
  }, [activeBranch]);

  /**
   * Helper: converts a Firestore snapshot doc to a ScheduleEvent,
   * enriching attendee names from the loaded members list.
   */
  const docToEnrichedEvent = useCallback(
    (doc: Parameters<typeof docToScheduleEvent>[0]): ScheduleEvent | null => {
      const event = docToScheduleEvent(doc);
      if (!event) return null;
      return {
        ...event,
        attendees: (event.attendees || []).map((attendee) => ({
          ...attendee,
          name:
            members.find((m) => m.id === attendee.memberId)?.name ||
            attendee.name ||
            "Unknown",
        })),
      } as ScheduleEvent;
    },
    [members]
  );

  // --- Phase 1: Today events — immediate load, unblocks UI ---
  useEffect(() => {
    const q = getTodayEventsQuery();

    const unsubscribe = onSnapshot(
      q,
      (snapshot) => {
        const eventsData = snapshot.docs
          .map(docToEnrichedEvent)
          .filter(Boolean) as ScheduleEvent[];
        setTodayEvents(eventsData);
        setIsLoading(false); // Unblock the UI as soon as today is ready!
      },
      (err) => {
        console.error("Error fetching today events:", err);
        setError(err);
        setIsLoading(false);
        toast.error("Грешка при зареждане на днешните събития");
      }
    );

    return () => unsubscribe();
  }, [members, activeBranch, docToEnrichedEvent]);

  // --- Phase 2: Upcoming events — background load ---
  useEffect(() => {
    const q = getUpcomingEventsQuery();

    const unsubscribe = onSnapshot(
      q,
      (snapshot) => {
        const eventsData = snapshot.docs
          .map(docToEnrichedEvent)
          .filter(Boolean) as ScheduleEvent[];
        setUpcomingEvents(eventsData);
        setIsUpcomingLoading(false);
      },
      (err) => {
        console.error("Error fetching upcoming events:", err);
        setIsUpcomingLoading(false);
      }
    );

    return () => unsubscribe();
  }, [members, activeBranch, docToEnrichedEvent]);

  // --- Phase 3: Past events — delayed background load (300ms) ---
  useEffect(() => {
    setIsPastLoading(true);
    let unsubscribe: () => void;

    const timer = setTimeout(() => {
      const q = getPastEventsQuery();

      unsubscribe = onSnapshot(
        q,
        (snapshot) => {
          const eventsData = snapshot.docs
            .map(docToEnrichedEvent)
            .filter(Boolean) as ScheduleEvent[];
          setPastEvents(eventsData);
          setIsPastLoading(false);
        },
        (err) => {
          console.error("Error fetching past events:", err);
          setIsPastLoading(false);
        }
      );
    }, 300);

    return () => {
      clearTimeout(timer);
      if (unsubscribe) {
        unsubscribe();
      }
    };
  }, [members, activeBranch, docToEnrichedEvent]);

  // Merged events for consumers
  const events = [...todayEvents, ...upcomingEvents, ...pastEvents];

  // --- Mutations (unchanged from original) ---

  const addEvent = useCallback(async (event: NewEvent) => {
    try {
      await addDoc(getEventsCollection(), event as ScheduleEvent);
      toast.success("Събитието е създадено успешно", {
        description: `"${event.title}" беше добавено към графика.`,
      });
      invalidateDashboardCacheAction().catch((err) =>
        console.error("Cache invalidation failed", err)
      );
    } catch (err) {
      console.error("Error adding event:", err);
      toast.error("Грешка при добавяне на събитие", {
        description: "Действието се провали. Моля, опитайте отново.",
      });
      throw err;
    }
  }, []);

  const addMultipleEvents = useCallback(async (events: NewEvent[]) => {
    const db = getDb();
    const batch = writeBatch(db);
    const eventsCollection = getEventsCollection();
    events.forEach((event) => {
      const docRef = doc(eventsCollection);
      batch.set(docRef, event);
    });
    try {
      await batch.commit();
      toast.success("Графикът е генериран", {
        description: `Успешно бяха създадени ${events.length} събития.`,
      });
      invalidateDashboardCacheAction().catch((err) =>
        console.error("Cache invalidation failed", err)
      );
    } catch (err) {
      console.error("Error adding multiple events:", err);
      toast.error("Грешка при генериране на графика", {
        description: "Действието се провали. Моля, опитайте отново.",
      });
      throw err;
    }
  }, []);

  const updateEvent = useCallback(
    async (eventId: string, eventData: Partial<NewEvent>) => {
      let originalToday: ScheduleEvent[] = [];
      let originalUpcoming: ScheduleEvent[] = [];
      let originalPast: ScheduleEvent[] = [];

      const optimisticPayload = {
        ...eventData,
        startDate: toISOStringOrUndefined(
          eventData.startDate as Date | Timestamp | string | undefined
        ),
        endDate: toISOStringOrUndefined(
          eventData.endDate as Date | Timestamp | string | undefined
        ),
      };

      const updater = (currentEvents: ScheduleEvent[]) =>
        currentEvents.map((e) =>
          e.id === eventId
            ? ({ ...e, ...optimisticPayload } as ScheduleEvent)
            : e
        );

      setTodayEvents((c) => {
        originalToday = c;
        return updater(c);
      });
      setUpcomingEvents((c) => {
        originalUpcoming = c;
        return updater(c);
      });
      setPastEvents((c) => {
        originalPast = c;
        return updater(c);
      });

      try {
        const eventRef = doc(getEventsCollection(), eventId);
        await setDoc(eventRef, eventData as ScheduleEvent, { merge: true });
        toast.success("Събитието е обновено");
        invalidateDashboardCacheAction().catch((err) =>
          console.error("Cache invalidation failed", err)
        );
      } catch (err) {
        setTodayEvents(originalToday);
        setUpcomingEvents(originalUpcoming);
        setPastEvents(originalPast);
        console.error("Error updating event:", err);
        toast.error("Грешка при обновяване", {
          description: "Промените не бяха запазени. Моля, опитайте отново.",
        });
        throw err;
      }
    },
    []
  );

  const deleteEvent = useCallback(async (eventId: string) => {
    const db = getDb();
    let originalToday: ScheduleEvent[] = [];
    let originalUpcoming: ScheduleEvent[] = [];
    let originalPast: ScheduleEvent[] = [];
    let eventTitle: string | undefined = "";

    const filterFn = (currentEvents: ScheduleEvent[]) => {
      const found = currentEvents.find((e) => e.id === eventId);
      if (found && !eventTitle) eventTitle = found.title;
      return currentEvents.filter((e) => e.id !== eventId);
    };

    setTodayEvents((c) => {
      originalToday = c;
      return filterFn(c);
    });
    setUpcomingEvents((c) => {
      originalUpcoming = c;
      return filterFn(c);
    });
    setPastEvents((c) => {
      originalPast = c;
      return filterFn(c);
    });

    try {
      const eventRef = doc(db, "events", eventId);
      await deleteDoc(eventRef);
      toast.success("Събитието е изтрито", {
        description: eventTitle ? `"${eventTitle}" беше премахнато.` : "",
      });
      invalidateDashboardCacheAction().catch((err) =>
        console.error("Cache invalidation failed", err)
      );
    } catch (err) {
      setTodayEvents(originalToday);
      setUpcomingEvents(originalUpcoming);
      setPastEvents(originalPast);
      console.error("Error deleting event:", err);
      toast.error("Грешка при изтриване");
      throw err;
    }
  }, []);

  const updateAttendees = useCallback(
    async (eventId: string, newAttendees: Attendee[]) => {
      let originalToday: ScheduleEvent[] = [];
      let originalUpcoming: ScheduleEvent[] = [];
      let originalPast: ScheduleEvent[] = [];

      const attendeeMemberIds = newAttendees.map((a) => a.memberId);

      const updater = (currentEvents: ScheduleEvent[]) => {
        return currentEvents.map((e) => {
          if (e.id === eventId) {
            const updatedAttendees = newAttendees.map((a) => {
              const member = members.find((m) => m.id === a.memberId);
              return {
                ...a,
                name: member ? formatFullName(member) : "Unknown",
              };
            });
            return { ...e, attendees: updatedAttendees, attendeeMemberIds };
          } else {
            return e;
          }
        });
      };

      // Optimistic update
      setTodayEvents((c) => {
        originalToday = [...c];
        return updater(c);
      });
      setUpcomingEvents((c) => {
        originalUpcoming = [...c];
        return updater(c);
      });
      setPastEvents((c) => {
        originalPast = [...c];
        return updater(c);
      });

      try {
        const token = await getFreshToken();
        if (!token) throw new Error("No authentication token available");

        const result = await updateAttendeesAction(
          token,
          eventId,
          newAttendees
        );

        if (!result.success) {
          throw new Error(result.message || "Failed to update attendees");
        }

        // If the server auto-updated payment statuses, sync optimistic state
        if (result.updatedAttendees) {
          const finalUpdater = (currentEvents: ScheduleEvent[]) =>
            currentEvents.map((e) =>
              e.id === eventId
                ? {
                    ...e,
                    attendees: result.updatedAttendees,
                    attendeeMemberIds,
                  }
                : e
            );

          setTodayEvents(finalUpdater);
          setUpcomingEvents(finalUpdater);
          setPastEvents(finalUpdater);
        }

        toast.success("Присъствията са обновени", {
          description: "Списъкът с присъстващи е запазен.",
        });
        invalidateDashboardCacheAction().catch((err) =>
          console.error("Cache invalidation failed", err)
        );
      } catch (err) {
        // Rollback on error
        setTodayEvents(originalToday);
        setUpcomingEvents(originalUpcoming);
        setPastEvents(originalPast);
        console.error("Error updating attendees:", err);
        toast.error("Грешка при обновяване на присъствия");
        throw err;
      }
    },
    [members, getFreshToken]
  );

  return {
    events,
    todayEvents,
    upcomingEvents,
    pastEvents,
    addEvent,
    addMultipleEvents,
    updateEvent,
    deleteEvent,
    updateAttendees,
    isLoading,
    isUpcomingLoading,
    isPastLoading,
    error,
    members,
  };
};

"use client";

import { useState, useEffect, useCallback } from "react";
import { GeneralService, GeneralServiceEvent, Sale } from "@/types";
import { toast } from "sonner";
import { useAppStore } from "@/store/use-app-store";
import {
  getGeneralServicesServerAction,
  getGeneralServiceHistoryAction,
  getGeneralServiceSalesAction,
} from "@/lib/actions/general-services-server";

export function useGeneralServices() {
  const [services, setServices] = useState<GeneralService[]>([]);
  const [events, setEvents] = useState<GeneralServiceEvent[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const { activeBranch } = useAppStore();

  const fetchData = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const [servicesRes, eventsRes, salesRes] = await Promise.all([
        getGeneralServicesServerAction(activeBranch),
        getGeneralServiceHistoryAction(activeBranch),
        getGeneralServiceSalesAction(activeBranch),
      ]);

      if (servicesRes.success && servicesRes.data) {
        setServices(servicesRes.data);
      } else {
        throw new Error(servicesRes.error || "Failed to fetch services");
      }

      if (eventsRes.success && eventsRes.data) {
        setEvents(eventsRes.data.filter((e): e is import("@/types").GeneralServiceEvent => e !== null));
      } else {
        throw new Error(eventsRes.error || "Failed to fetch events");
      }

      if (salesRes.success && salesRes.data) {
        setSales(salesRes.data);
      } else {
        throw new Error(salesRes.error || "Failed to fetch sales");
      }
    } catch (err: any) {
      console.error("Error fetching general services data:", err);
      setError(err.message || "Грешка при зареждане на данни");
      toast.error("Грешка при зареждане на данни");
    } finally {
      setIsLoading(false);
    }
  }, [activeBranch]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  return {
    services,
    events,
    sales,
    isLoading,
    error,
    refetch: fetchData,
  };
}

