"use client";

import { useState, useEffect, useRef, useCallback } from "react";
import {
  AUDIO_PATHS,
  ZoneId,
  getRandomZoneForMode,
  playAudio,
  playAudioSequence,
  stopAudio,
  shadowAudioManager,
  getRandomShotForZone,
  isAudioPlaying,
} from "@/lib/shadow-training/audio-map";

export type TrainerState =
  | "idle"
  | "countdown"
  | "working"
  | "resting"
  | "finished"
  | "paused";

export interface ShadowSettings {
  mode: "standard" | "ghost_match" | "agility_test";
  preset: string;
  drillMode: "all" | "front_only" | "back_only" | "front_back";
  sets: number;
  workSec: number; // For agility_test, this will be the Target Actions
  restSec: number;
  paceSec: number;
  deceptionEnabled: boolean;
  motivationEnabled: boolean;
  visualOnly: boolean;
  calloutMode: "zones" | "shots" | "mixed" | "zones_and_shots";
  centerCommandEnabled: boolean;
  activePlayers: any[]; // The full selected players array
  courtsAvailable: number;
}

export function useShadowTrainer(settings: ShadowSettings | null) {
  const [state, setState] = useState<TrainerState>("idle");
  const [currentSet, setCurrentSet] = useState(1);
  const [timeRemaining, setTimeRemaining] = useState(0); // Also used as elapsed time in agility
  const [activeZone, setActiveZone] = useState<ZoneId | null>(null);

  // Fair Rotation Scheduler State
  const [currentPlayersState, setCurrentPlayersState] = useState<any[]>([]);
  const playCountsRef = useRef<Record<string, number>>({});
  const consecutiveFastShotsRef = useRef(0);
  const currentPlayersRef = useRef<any[]>([]);
  const [agilityActionsDone, setAgilityActionsDone] = useState(0);
  const [actualElapsedMs, setActualElapsedMs] = useState(0);

  const expectedTimeRemainingRef = useRef<number>(0);
  const updateTimeRemaining = useCallback((val: number) => {
    expectedTimeRemainingRef.current = val;
    setTimeRemaining(val);
  }, []);

  const previousStateRef = useRef<TrainerState>("idle");

  // Refs for intervals, timeouts, and wake lock
  const timerRef = useRef<NodeJS.Timeout | null>(null);
  const actionTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const deceptionTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const centerTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const wakeLockRef = useRef<any>(null); // any because WakeLockSentinel might not be in standard DOM types
  const isFirstActionRef = useRef(false);

  const settingsRef = useRef(settings);
  useEffect(() => {
    settingsRef.current = settings;
    if (settings) {
      const counts = playCountsRef.current;
      settings.activePlayers.forEach((p) => {
        if (counts[p.id] === undefined) {
          counts[p.id] = 0;
        }
      });
      playCountsRef.current = counts;

      const groupSize = settings.courtsAvailable || 1;
      const initialPlayers = settings.activePlayers.slice(0, groupSize);
      currentPlayersRef.current = initialPlayers;
      setCurrentPlayersState(initialPlayers);
      consecutiveFastShotsRef.current = 0;
    }
  }, [settings]);

  const stateRef = useRef(state);
  useEffect(() => {
    stateRef.current = state;
  }, [state]);

  const currentSetRef = useRef(currentSet);
  useEffect(() => {
    currentSetRef.current = currentSet;
  }, [currentSet]);

  const agilityActionsDoneRef = useRef(agilityActionsDone);
  useEffect(() => {
    agilityActionsDoneRef.current = agilityActionsDone;
  }, [agilityActionsDone]);

  const requestWakeLock = async () => {
    if (typeof navigator !== "undefined" && "wakeLock" in navigator) {
      try {
        wakeLockRef.current = await (navigator as any).wakeLock.request(
          "screen"
        );
      } catch (err) {
        console.log("Wake Lock error:", err);
      }
    }
  };

  const releaseWakeLock = () => {
    if (wakeLockRef.current) {
      wakeLockRef.current.release().catch(() => {});
      wakeLockRef.current = null;
    }
  };

  const cleanup = useCallback(() => {
    if (timerRef.current) clearInterval(timerRef.current);
    if (actionTimeoutRef.current) clearTimeout(actionTimeoutRef.current);
    if (deceptionTimeoutRef.current) clearTimeout(deceptionTimeoutRef.current);
    if (centerTimeoutRef.current) clearTimeout(centerTimeoutRef.current);
    releaseWakeLock();
  }, []);

  // Handle Wake Lock re-acquisition if tab is backgrounded and foregrounded
  useEffect(() => {
    const handleVisibilityChange = () => {
      if (
        document.visibilityState === "visible" &&
        ["working", "resting", "countdown"].includes(stateRef.current)
      ) {
        requestWakeLock();
      }
    };
    document.addEventListener("visibilitychange", handleVisibilityChange);
    return () => {
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, []);

  const triggerNextAction = useCallback(() => {
    try {
      const currentSettings = settingsRef.current;
      if (!currentSettings) return;
      if (stateRef.current !== "working") return;

      const isFirst = isFirstActionRef.current;
      isFirstActionRef.current = false;

      if (currentSettings.mode === "agility_test") {
        let nextCount = agilityActionsDoneRef.current;
        if (!isFirst) {
          nextCount = nextCount + 1;
          setAgilityActionsDone(nextCount);
          agilityActionsDoneRef.current = nextCount;
        }
        if (nextCount >= currentSettings.workSec) {
          // Stop agility test when settings.workSec actions are done
          stateRef.current = "finished";
          setState("finished");
          cleanup();
          if (!currentSettings.visualOnly) playAudio(AUDIO_PATHS.common.endSet);
          return;
        }
      }

      let pace = currentSettings.paceSec;
      if (currentSettings.mode === "ghost_match") {
        if (consecutiveFastShotsRef.current >= 3) {
          if (Math.random() > 0.2) {
            pace = Math.random() * 1.0 + 2.5; // 2.5s to 3.5s
            consecutiveFastShotsRef.current = 0;
          } else {
            pace = Math.random() * 1.0 + 1.2; // 1.2s to 2.2s
            consecutiveFastShotsRef.current++;
          }
        } else {
          pace = Math.random() * 1.0 + 1.2; // 1.2s to 2.2s
          if (pace < 2.0) {
            consecutiveFastShotsRef.current++;
          } else {
            consecutiveFastShotsRef.current = 0;
          }
        }
      }

      let zone = getRandomZoneForMode(currentSettings.drillMode);
      if (!zone) {
        zone = "frontForehand";
      }
      setActiveZone(zone);

      let audioPath = AUDIO_PATHS.zones[zone];
      if (!audioPath) {
        audioPath = AUDIO_PATHS.zones.frontForehand;
      }
      let secondAudioPath: string | null = null;

      const isShotMode =
        currentSettings.calloutMode === "shots" ||
        (currentSettings.calloutMode === "mixed" && Math.random() > 0.5);

      if (isShotMode) {
        if (zone.startsWith("mid")) {
          // Tactical fix: In mid zone, "shots" alone is ambiguous. Force zone + shot.
          audioPath = AUDIO_PATHS.zones[zone] || AUDIO_PATHS.zones.midForehand;
          secondAudioPath =
            getRandomShotForZone(zone) || AUDIO_PATHS.shots.defense;
        } else {
          audioPath = getRandomShotForZone(zone) || AUDIO_PATHS.shots.defense;
        }
      } else if (currentSettings.calloutMode === "zones_and_shots") {
        audioPath = AUDIO_PATHS.zones[zone] || AUDIO_PATHS.zones.frontForehand;
        secondAudioPath =
          getRandomShotForZone(zone) || AUDIO_PATHS.shots.defense;
      }

      if (!currentSettings.visualOnly) {
        if (currentSettings.deceptionEnabled && Math.random() < 0.1) {
          const fakeZone =
            getRandomZoneForMode(currentSettings.drillMode) || "frontForehand";
          let fakePath =
            AUDIO_PATHS.zones[fakeZone] || AUDIO_PATHS.zones.frontForehand;
          let secondFakePath: string | null = null;
          const isFakeShotMode =
            currentSettings.calloutMode === "shots" ||
            (currentSettings.calloutMode === "mixed" && Math.random() > 0.5);

          if (isFakeShotMode) {
            if (fakeZone.startsWith("mid")) {
              fakePath =
                AUDIO_PATHS.zones[fakeZone] || AUDIO_PATHS.zones.frontForehand;
              secondFakePath =
                getRandomShotForZone(fakeZone) || AUDIO_PATHS.shots.defense;
            } else {
              fakePath =
                getRandomShotForZone(fakeZone) || AUDIO_PATHS.shots.defense;
            }
          } else if (currentSettings.calloutMode === "zones_and_shots") {
            fakePath =
              AUDIO_PATHS.zones[fakeZone] || AUDIO_PATHS.zones.frontForehand;
            secondFakePath =
              getRandomShotForZone(fakeZone) || AUDIO_PATHS.shots.defense;
          }

          const fakeSequence = [];
          if (isFirst) fakeSequence.push(AUDIO_PATHS.common.beep);
          fakeSequence.push(fakePath);
          if (secondFakePath) fakeSequence.push(secondFakePath);
          playAudioSequence(fakeSequence);

          const deceptionDelay = Math.max(
            300,
            Math.min(pace * 1000 * 0.35, 800)
          );
          deceptionTimeoutRef.current = setTimeout(() => {
            if (stateRef.current !== "working") return;
            const realSequence = [audioPath];
            if (secondAudioPath) realSequence.push(secondAudioPath);
            playAudioSequence(realSequence);
          }, deceptionDelay);
        } else {
          const sequence = [];
          if (isFirst) sequence.push(AUDIO_PATHS.common.beep);
          sequence.push(audioPath);
          if (secondAudioPath) sequence.push(secondAudioPath);
          playAudioSequence(sequence);
        }
      }

      if (currentSettings.centerCommandEnabled && !currentSettings.visualOnly) {
        centerTimeoutRef.current = setTimeout(
          () => {
            if (stateRef.current === "working") {
              playAudio(AUDIO_PATHS.common.center);
            }
          },
          (pace * 1000) / 2
        );
      }

      const expectedAudioFiles = 1 + (secondAudioPath ? 1 : 0);
      const approxAudioDuration = expectedAudioFiles * 900; // approx 900ms per file
      let nextPaceMs = pace * 1000;
      if (nextPaceMs < approxAudioDuration) {
        nextPaceMs = approxAudioDuration + 200; // Guaranteed buffer
      }

      actionTimeoutRef.current = setTimeout(() => {
        setActiveZone(null); // clear highlight
        actionTimeoutRef.current = setTimeout(triggerNextAction, 300);
      }, nextPaceMs);
    } catch (error) {
      console.error("Error in triggerNextAction", error);
      // Schedule fallback next action to prevent complete freeze
      const currentSettings = settingsRef.current;
      const pace = currentSettings?.paceSec || 3;
      actionTimeoutRef.current = setTimeout(triggerNextAction, pace * 1000);
    }
  }, [cleanup]);

  const speakMotivation = useCallback(() => {
    try {
      const currentSettings = settingsRef.current;
      if (!currentSettings?.motivationEnabled) return;
      if (typeof window === "undefined" || !("speechSynthesis" in window))
        return;
      if (isAudioPlaying()) return; // Do not overlap with ongoing voice command

      const currentPlayers = currentPlayersRef.current;

      if (currentPlayers.length > 0) {
        const randomPlayer =
          currentPlayers[Math.floor(Math.random() * currentPlayers.length)];
        if (!randomPlayer || !randomPlayer.displayName) return;
        const firstName = randomPlayer.displayName.split(" ")[0] || "играч";
        const phrases = [
          `Давай, ${firstName}!`,
          `Още малко, ${firstName}!`,
          `Дръж стойката, ${firstName}!`,
        ];
        const text = phrases[Math.floor(Math.random() * phrases.length)];
        const msg = new SpeechSynthesisUtterance(text);
        msg.lang = "bg-BG";
        window.speechSynthesis.speak(msg);
      }
    } catch (e) {
      console.error("Speech synthesis error", e);
    }
  }, []);

  const advanceState = useCallback(() => {
    const currentSettings = settingsRef.current;
    if (!currentSettings) return;

    // Explicitly kill the old interval so the next phase starts fresh with 0 accumulatedMs.
    // The useEffect will spawn a new clean interval after re-render.
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }

    if (stateRef.current === "countdown") {
      stateRef.current = "working";
      setState("working");
      isFirstActionRef.current = true;

      if (currentSettings.mode === "agility_test") {
        updateTimeRemaining(0); // count UP
        setAgilityActionsDone(0);
      } else {
        updateTimeRemaining(currentSettings.workSec); // count DOWN
        setAgilityActionsDone(0);
      }

      requestWakeLock();
      // Trigger the first action immediately on transition start
      actionTimeoutRef.current = setTimeout(triggerNextAction, 0);
    } else if (stateRef.current === "working") {
      cleanup();
      setActiveZone(null);

      if (
        currentSetRef.current >= currentSettings.sets ||
        currentSettings.mode === "agility_test"
      ) {
        stateRef.current = "finished";
        setState("finished");
        if (!currentSettings.visualOnly) playAudio(AUDIO_PATHS.common.endSet);
      } else {
        const groupSize = currentSettings.courtsAvailable || 1;
        if (currentSettings.activePlayers.length > groupSize) {
          currentPlayersRef.current.forEach((p) => {
            if (playCountsRef.current[p.id] !== undefined) {
              playCountsRef.current[p.id]++;
            }
          });
          const sorted = [...currentSettings.activePlayers].sort((a, b) => {
            const cA = playCountsRef.current[a.id] || 0;
            const cB = playCountsRef.current[b.id] || 0;
            if (cA !== cB) return cA - cB;
            // Secondary sort: original order to guarantee stable state
            return (
              currentSettings.activePlayers.indexOf(a) -
              currentSettings.activePlayers.indexOf(b)
            );
          });
          const nextPlayers = sorted.slice(0, groupSize);
          currentPlayersRef.current = nextPlayers;
          setCurrentPlayersState(nextPlayers);
        }

        stateRef.current = "resting";
        setState("resting");
        stopAudio(); // Prevent "Ghost Leaks" overlapping with "Rest" audio
        updateTimeRemaining(currentSettings.restSec);
        if (!currentSettings.visualOnly) playAudio(AUDIO_PATHS.common.rest);
      }
    } else if (stateRef.current === "resting") {
      setCurrentSet((c) => c + 1);

      stateRef.current = "countdown";
      setState("countdown");
      updateTimeRemaining(10);
      if (!currentSettings.visualOnly) {
        playAudioSequence([
          AUDIO_PATHS.common.endRest,
          AUDIO_PATHS.common.startSet,
        ]);
      }
    }
  }, [cleanup, triggerNextAction, updateTimeRemaining]);

  useEffect(() => {
    if (state === "idle" || state === "finished" || state === "paused") {
      if (timerRef.current) clearInterval(timerRef.current);
      return;
    }

    let accumulatedMs = 0;
    let lastTick = Date.now();

    const intervalId = setInterval(() => {
      const now = Date.now();
      const deltaMs = now - lastTick;
      lastTick = now;
      accumulatedMs += deltaMs;

      if (stateRef.current === "working" || stateRef.current === "resting") {
        setActualElapsedMs((prev) => prev + deltaMs);
      }

      if (accumulatedMs >= 1000) {
        accumulatedMs -= 1000;

        setTimeRemaining((prev) => {
          let currentPrev = prev;
          if (expectedTimeRemainingRef.current !== prev) {
            currentPrev = expectedTimeRemainingRef.current;
          }

          const currentSettings = settingsRef.current;
          const isAgilityWorking =
            stateRef.current === "working" &&
            currentSettings?.mode === "agility_test";

          if (isAgilityWorking) {
            const nextVal = currentPrev + 1;
            expectedTimeRemainingRef.current = nextVal;
            return nextVal;
          }

          if (currentPrev <= 1) {
            // Defer advanceState call to next tick to avoid state update loops inside setState
            if (!isAgilityWorking) {
              setTimeout(advanceState, 0);
            }
            expectedTimeRemainingRef.current = 0;
            return 0;
          }

          if (
            stateRef.current === "working" &&
            currentSettings?.mode !== "agility_test" &&
            currentPrev === 16 &&
            currentSettings?.motivationEnabled
          ) {
            speakMotivation();
          }

          const nextVal = currentPrev - 1;
          expectedTimeRemainingRef.current = nextVal;
          return nextVal;
        });
      }
    }, 100); // Poll more frequently for smooth ticks

    timerRef.current = intervalId;

    return () => {
      clearInterval(intervalId);
    };
  }, [state, advanceState, speakMotivation]);

  const startTraining = useCallback(() => {
    if (!settings) return;
    shadowAudioManager.unlock(); // Unlock audio on user gesture
    stopAudio();
    requestWakeLock();
    stateRef.current = "countdown";
    setState("countdown");
    setCurrentSet(1);
    updateTimeRemaining(10);
    setAgilityActionsDone(0);
    setActualElapsedMs(0);
    if (!settings.visualOnly) {
      playAudio(AUDIO_PATHS.common.startSet);
    }
  }, [settings, updateTimeRemaining]);

  const pauseTraining = useCallback(() => {
    if (
      stateRef.current !== "paused" &&
      stateRef.current !== "idle" &&
      stateRef.current !== "finished"
    ) {
      previousStateRef.current = stateRef.current;
    }
    stateRef.current = "paused";
    setState("paused");
    stopAudio();
    cleanup();
  }, [cleanup]);

  const resumeTraining = useCallback(() => {
    if (stateRef.current === "paused") {
      const targetState = previousStateRef.current;
      stateRef.current = targetState;
      setState(targetState);
      requestWakeLock();
      if (targetState === "working") {
        actionTimeoutRef.current = setTimeout(triggerNextAction, 1000);
      }
    }
  }, [triggerNextAction]);

  const stopTraining = useCallback(() => {
    stateRef.current = "finished";
    setState("finished");
    stopAudio();
    cleanup();
  }, [cleanup]);

  // Clean up if settings become null (user clicked Back) or component unmounts
  useEffect(() => {
    if (
      settings === null &&
      stateRef.current !== "idle" &&
      stateRef.current !== "finished"
    ) {
      stopTraining();
    }
  }, [settings, stopTraining]);

  useEffect(() => {
    return () => {
      cleanup();
    };
  }, [cleanup]);

  const currentRotationPlayers = currentPlayersState;

  return {
    state,
    currentSet,
    timeRemaining,
    activeZone,
    currentRotationPlayers,
    agilityActionsDone,
    actualElapsedMs,
    startTraining,
    pauseTraining,
    resumeTraining,
    stopTraining,
  };
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { Sale } from "@/types";
import { toast } from "sonner";
import { useAppStore } from "@/store/use-app-store";
import {
  getTrainingServiceHistoryAction,
  getTrainingServiceSalesAction,
} from "@/lib/actions/training-services-server";

export function useTrainingServices() {
  const [events, setEvents] = useState<any[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);

  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const { activeBranch } = useAppStore();

  const fetchData = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const [eventsRes, salesRes] = await Promise.all([
        getTrainingServiceHistoryAction(activeBranch),
        getTrainingServiceSalesAction(activeBranch),
      ]);

      if (eventsRes.success && eventsRes.data) {
        setEvents(eventsRes.data.filter((e: any) => e !== null));
      } else {
        throw new Error(eventsRes.error || "Failed to fetch events");
      }

      if (salesRes.success && salesRes.data) {
        setSales(salesRes.data);
      } else {
        throw new Error(salesRes.error || "Failed to fetch sales");
      }
    } catch (err: any) {
      console.error("Error fetching training services data:", err);
      setError(err.message || "Грешка при зареждане на данни");
      toast.error("Грешка при зареждане на данни");
    } finally {
      setIsLoading(false);
    }
  }, [activeBranch]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  return {
    events,
    sales,
    isLoading,
    error,
    refetch: fetchData,
  };
}

"use server";

import { getAdminDb } from "@/lib/firebase-admin";
import { getAuthUserFromSessionCookie } from "@/lib/auth-utils";
import { Member, Sale, ScheduleEvent, Reminder } from "@/types";
import { checkIsMemberOverdue } from "@/lib/membership-utils";
import { getRevenueTrendData } from "@/services/dashboard-service";
import { serverCache } from "@/lib/server-cache";
import * as admin from "firebase-admin";

function snapToData<T>(doc: admin.firestore.QueryDocumentSnapshot): T {
  const data = doc.data();
  const convertTimestamps = (val: any): any => {
    if (!val) return val;
    if (typeof val.toDate === "function") {
      return val.toDate().toISOString();
    }
    if (Array.isArray(val)) {
      return val.map(convertTimestamps);
    }
    if (typeof val === "object") {
      const copy: any = {};
      for (const key of Object.keys(val)) {
        copy[key] = convertTimestamps(val[key]);
      }
      return copy;
    }
    return val;
  };
  return {
    id: doc.id,
    ...convertTimestamps(data),
  } as T;
}

function getOverdueReminders(
  allMembers: Member[],
  allSales: Sale[]
): Reminder[] {
  const today = new Date();
  const dueDate = new Date(today.getFullYear(), today.getMonth() + 1, 0);

  const overdueMembers = allMembers.filter((member) => {
    if (member.status !== "active") return false;
    const familyMembers = member.familyId
      ? allMembers.filter(
          (m) => m.familyId === member.familyId && m.id !== member.id
        )
      : [];
    const memberSales = allSales.filter((s) => s.memberId === member.id);
    return checkIsMemberOverdue(member, familyMembers, memberSales).isOverdue;
  });

  return overdueMembers.map((member, index) => {
    const familyMembers = member.familyId
      ? allMembers.filter(
          (m) => m.familyId === member.familyId && m.id !== member.id
        )
      : [];
    const memberSales = allSales.filter((s) => s.memberId === member.id);
    const overdueCheck = checkIsMemberOverdue(
      member,
      familyMembers,
      memberSales
    );
    return {
      id: `overdue-${member.id}-${index}`,
      title: "Просрочено плащане",
      description: overdueCheck.reason
        ? `${member.firstName} ${member.lastName}: ${overdueCheck.reason}`
        : `Таксата за абонамента на ${member.firstName} ${member.lastName} не е платена.`,
      dueDate: dueDate.toISOString(),
      isCompleted: false,
      type: "payment",
      memberId: member.id,
      memberName: `${member.firstName} ${member.lastName}`,
      relatedId: member.id,
    };
  });
}

export async function getDashboardDataServerAction(activeBranch: string) {
  try {
    const user = await getAuthUserFromSessionCookie();
    if (!user) return { success: false, error: "Unauthorized" };

    const adminDb = getAdminDb();
    const now = new Date();

    // Date ranges
    const startOfDay = new Date(
      now.getFullYear(),
      now.getMonth(),
      now.getDate()
    );
    const endOfDay = new Date(
      now.getFullYear(),
      now.getMonth(),
      now.getDate(),
      23,
      59,
      59
    );
    const thirtyDaysAgo = new Date(now);
    thirtyDaysAgo.setDate(now.getDate() - 30);
    const sixtyDaysAgo = new Date(now);
    sixtyDaysAgo.setDate(now.getDate() - 60);
    const sixMonthsAgo = new Date(now);
    sixMonthsAgo.setMonth(now.getMonth() - 6);

    const startStr = startOfDay.toISOString();
    const endStr = endOfDay.toISOString();
    const thirtyDaysAgoStr = thirtyDaysAgo.toISOString();
    const sixtyDaysAgoStr = sixtyDaysAgo.toISOString();

    // Cache key: per branch + per day (stats are stable within a day)
    const todayKey = startOfDay.toISOString().slice(0, 10);
    const cacheKey = `dashboard:${activeBranch}:${todayKey}`;
    const TTL_MS = 90_000; // 90 seconds — reduces repeat reads on navigation

    return await serverCache.get(
      cacheKey,
      async () => {
        // Base collection references
        const siteFilter = activeBranch && activeBranch !== "bkgalabovo";

        const col = (name: string): admin.firestore.Query => {
          const ref = adminDb.collection(name);
          return siteFilter ? ref.where("siteId", "==", activeBranch) : ref;
        };

        // ── AGGREGATION QUERIES (count only — each costs 1 read) ──────────────
        const [
          totalMembersCount,
          activeMembersCount,
          newMembersThisMonthCount,
          newMembersPrevMonthCount,
          unpaidSalesCount,
          trainingsCount,
          guestsCount,
          familiesCount,
          recoveryMembersCount,
        ] = await Promise.all([
          col("members").count().get(),
          col("members").where("status", "==", "active").count().get(),
          col("members")
            .where("registrationDate", ">=", thirtyDaysAgoStr)
            .count()
            .get(),
          col("members")
            .where("registrationDate", ">=", sixtyDaysAgoStr)
            .where("registrationDate", "<", thirtyDaysAgoStr)
            .count()
            .get(),
          // Count sales that are NOT completed (pending/overdue)
          col("sales").where("status", "==", "pending").count().get(),
          col("events")
            .where("startDate", ">=", startStr)
            .where("startDate", "<=", endStr)
            .where("type", "==", "training")
            .count()
            .get(),
          col("members").where("isGuest", "==", true).count().get(),
          col("families").count().get(),
          col("members").where("memberType", "==", "recovery").count().get(),
        ]);

        // ── DOCUMENT QUERIES (only what must be displayed) ─────────────────────
        const adminStartOfDay = admin.firestore.Timestamp.fromDate(startOfDay);
        const adminEndOfDay = admin.firestore.Timestamp.fromDate(endOfDay);

        const [
          recentSalesSnap,
          salesFor6MonthsSnap,
          activeMembersSnap,
          activeSubsSnap,
          eventsSnap,
          productsSnap,
          reservationsSnap,
        ] = await Promise.all([
          // Last 5 sales for the "Recent Sales" widget
          col("sales").orderBy("saleDate", "desc").limit(5).get(),

          // Up to 6 months of completed+paid sales for revenue stats & chart
          col("sales").where("status", "==", "completed").limit(500).get(),

          // Active members (needed for overdue reminder generation)
          col("members").where("status", "==", "active").limit(300).get(),

          // Unpaid sales (needed for overdue check)
          col("sales").where("isPaid", "==", false).limit(300).get(),

          // Today's events for display
          col("events")
            .where("startDate", ">=", startStr)
            .where("startDate", "<=", endStr)
            .limit(30)
            .get(),

          // Products (small collection, needed for low-stock list)
          col("products").limit(200).get(),

          // Today's reservations (both court and recovery)
          col("reservations")
            .where("startTime", ">=", adminStartOfDay)
            .where("startTime", "<=", adminEndOfDay)
            .limit(100)
            .get(),
        ]);

        // Map documents
        const recentSales = recentSalesSnap.docs.map((d) =>
          snapToData<Sale>(d)
        );
        const salesFor6Months = salesFor6MonthsSnap.docs
          .map((d) => snapToData<Sale>(d))
          .filter((s): s is Sale => s !== null)
          .filter((s) => new Date(s.saleDate) >= sixMonthsAgo)
          .sort(
            (a, b) =>
              new Date(b.saleDate).getTime() - new Date(a.saleDate).getTime()
          );
        const activeMembers = activeMembersSnap.docs.map((d) =>
          snapToData<Member>(d)
        );
        const unpaidSales = activeSubsSnap.docs.map((d) => snapToData<Sale>(d));
        const events = eventsSnap.docs.map((d) => snapToData<ScheduleEvent>(d));
        const reservations = reservationsSnap.docs.map((d) =>
          snapToData<any>(d)
        );

        // Sort events by start date
        const sortedEvents = [...events].sort(
          (a, b) =>
            new Date(a.startDate).getTime() - new Date(b.startDate).getTime()
        );

        const todayTrainingsCount = events.filter(
          (e) => e.type === "training"
        ).length;
        const todayCompetitionsCount = events.filter(
          (e) => e.type === "competition"
        ).length;
        const todayCampsCount = events.filter((e) => e.type === "camp").length;
        const todayOtherEventsCount = events.filter(
          (e) =>
            e.type !== "training" &&
            e.type !== "competition" &&
            e.type !== "camp"
        ).length;
        const todayEventsCount = events.length;

        const todayRecoveryCount = reservations.filter(
          (r) => !r.courtId
        ).length;
        const todayCourtCount = reservations.filter((r) => r.courtId).length;

        const allProducts = productsSnap.docs.map((d) => snapToData<any>(d));

        // Low-stock products (client-side filter — products collection is small)
        const lowStockProducts = allProducts.filter((p) => {
          const threshold =
            typeof p.restockThreshold === "number" ? p.restockThreshold : 5;
          return p.stock <= threshold;
        });

        // Revenue calculations from the scoped sales set
        const calcRevenue = (list: Sale[]) =>
          list
            .filter((s) => s.isPaid === true)
            .reduce((sum, s) => sum + (s.totalAmount || 0), 0);

        const salesLast30Days = salesFor6Months.filter(
          (s) => new Date(s.saleDate) >= thirtyDaysAgo
        );
        const salesPrev30Days = salesFor6Months.filter(
          (s) =>
            new Date(s.saleDate) >= sixtyDaysAgo &&
            new Date(s.saleDate) < thirtyDaysAgo
        );

        const revenueLast30Days = calcRevenue(salesLast30Days);
        const revenuePrev30Days = calcRevenue(salesPrev30Days);
        const revenueChange =
          revenuePrev30Days > 0
            ? ((revenueLast30Days - revenuePrev30Days) / revenuePrev30Days) *
              100
            : revenueLast30Days > 0
              ? 100
              : 0;

        const revenueTrainings = salesLast30Days
          .filter((s) => s.isPaid === true && s.type === "training_service")
          .reduce((sum, s) => sum + (s.totalAmount || 0), 0);

        const revenueCourts = salesLast30Days
          .filter(
            (s) =>
              s.isPaid === true &&
              s.type === "general_service" &&
              s.items?.some((i) => i.productId?.startsWith("court_rental_"))
          )
          .reduce((sum, s) => sum + (s.totalAmount || 0), 0);

        const revenueRecovery = salesLast30Days
          .filter(
            (s) =>
              s.isPaid === true &&
              s.type === "general_service" &&
              s.items?.some((i) => i.productId?.startsWith("recovery_session_"))
          )
          .reduce((sum, s) => sum + (s.totalAmount || 0), 0);

        const revenueServices = salesLast30Days
          .filter(
            (s) =>
              s.isPaid === true &&
              s.type === "general_service" &&
              !s.items?.some(
                (i) =>
                  i.productId?.startsWith("court_rental_") ||
                  i.productId?.startsWith("recovery_session_")
              )
          )
          .reduce((sum, s) => sum + (s.totalAmount || 0), 0);

        const revenueShop = salesLast30Days
          .filter(
            (s) => s.isPaid === true && (s.type === "inventory" || !s.type)
          )
          .reduce((sum, s) => sum + (s.totalAmount || 0), 0);

        const totalRevenue = salesFor6Months
          .filter((s) => s.isPaid === true)
          .reduce(
            (acc, s) => {
              const cur = s.currency || "EUR";
              acc[cur] = (acc[cur] || 0) + (s.totalAmount || 0);
              return acc;
            },
            {} as Record<string, number>
          );

        const salesCountLast30 = salesLast30Days.length;
        const salesCountPrev30 = salesPrev30Days.length;
        const salesChange =
          salesCountPrev30 > 0
            ? ((salesCountLast30 - salesCountPrev30) / salesCountPrev30) * 100
            : salesCountLast30 > 0
              ? 100
              : 0;

        const tMem = totalMembersCount.data().count;
        const aMem = activeMembersCount.data().count;
        const newMemThis = newMembersThisMonthCount.data().count;
        const newMemPrev = newMembersPrevMonthCount.data().count;
        const newMembersChange =
          newMemPrev > 0
            ? ((newMemThis - newMemPrev) / newMemPrev) * 100
            : newMemThis > 0
              ? 100
              : 0;

        const totalGuests = guestsCount.data().count;
        const totalFamilies = familiesCount.data().count;
        const totalRecovery = recoveryMembersCount.data().count;
        const totalClubMembers = Math.max(
          0,
          tMem - totalGuests - totalRecovery
        );

        const stats = {
          totalMembers: tMem,
          activeMembersCount: aMem,
          totalRevenue,
          unpaidSales: unpaidSalesCount.data().count,
          revenueLast30Days,
          revenueChange,
          newMembersCount: newMemThis,
          newMembersLast30Days: newMemThis,
          newMembersChange,
          salesLast30Days: salesCountLast30,
          salesChange,
          lowStockCount: lowStockProducts.length,
          lowStockProducts: lowStockProducts.map((p) => ({
            id: p.id,
            name: p.name || "",
            stock: p.stock || 0,
            restockThreshold: p.restockThreshold || 0,
          })),
          trainingsToday: trainingsCount.data().count,
          totalGuests,
          totalFamilies,
          totalClubMembers,
          totalRecovery,
          inactiveMembersCount: tMem - aMem,
          revenueTrainings,
          revenueServices,
          revenueCourts,
          revenueRecovery,
          revenueShop,
          todayTrainingsCount,
          todayCompetitionsCount,
          todayCampsCount,
          todayOtherEventsCount,
          todayEventsCount,
          todayRecoveryCount,
          todayCourtCount,
          todayEventsList: sortedEvents.map((e) => ({
            id: e.id,
            title: e.title,
            startDate: e.startDate,
            type: e.type,
            attendeesCount: e.attendees?.length || 0,
          })),
        };

        const revenueChartData = getRevenueTrendData(salesFor6Months);
        const reminders = getOverdueReminders(activeMembers, unpaidSales);

        return {
          success: true,
          data: {
            stats,
            revenueChartData,
            reminders,
            recentSales,
            todayTrainings: events.filter((e) => e.type === "training"),
          },
        };
      },
      TTL_MS
    );
  } catch (error: any) {
    console.error("Error fetching dashboard data on server:", error);
    return {
      success: false,
      error: error.message || "Неуспешно извличане на данни",
    };
  }
}

