export interface ExportRow {
  position: number | string;
  name: string;
  played: number;
  wins: number;
  losses: number;
  pointsRatio: string;
  winRate: string;
  totalPoints: number;
}

export interface ExportOptions {
  title: string;
  subtitle?: string;
  category?: string;
  rows: ExportRow[];
}

// ──────────────────────────────────────────────
// EXCEL EXPORT
// ──────────────────────────────────────────────
export async function exportToExcel(options: ExportOptions): Promise<void> {
  const ExcelJS = (await import("exceljs")).default;
  const workbook = new ExcelJS.Workbook();
  const worksheet = workbook.addWorksheet("Класиране");

  // Заглавни редове
  let currentRow = 1;
  worksheet.getCell(`A${currentRow}`).value = options.title;
  worksheet.getCell(`A${currentRow}`).font = { bold: true, size: 14 };
  currentRow++;

  if (options.subtitle) {
    worksheet.getCell(`A${currentRow}`).value = options.subtitle;
    worksheet.getCell(`A${currentRow}`).font = { italic: true };
    currentRow++;
  }

  if (options.category) {
    worksheet.getCell(`A${currentRow}`).value =
      `Категория: ${options.category}`;
    currentRow++;
  }

  currentRow++; // Празен ред

  // Заглавия на колоните
  const headers = [
    "#",
    "Участник",
    "Изиграни",
    "Победи",
    "Загуби",
    "Т. Разлика",
    "% Победи",
    "Точки",
  ];
  const headerRow = worksheet.getRow(currentRow);
  headerRow.values = headers;
  headerRow.font = { bold: true };
  headerRow.fill = {
    type: "pattern",
    pattern: "solid",
    fgColor: { argb: "FFE0E0E0" },
  };
  currentRow++;

  // Данни
  options.rows.forEach((r) => {
    worksheet.getRow(currentRow).values = [
      r.position,
      r.name,
      r.played,
      r.wins,
      r.losses,
      r.pointsRatio,
      r.winRate,
      r.totalPoints,
    ];
    currentRow++;
  });

  // Ширини на колоните
  worksheet.columns = [
    { key: "pos", width: 5 },
    { key: "name", width: 30 },
    { key: "played", width: 12 },
    { key: "wins", width: 10 },
    { key: "losses", width: 10 },
    { key: "ratio", width: 15 },
    { key: "rate", width: 12 },
    { key: "points", width: 10 },
  ];

  // Генериране и изтегляне
  const buffer = await workbook.xlsx.writeBuffer();
  const blob = new Blob([buffer], {
    type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
  });
  const url = window.URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = `${options.title.replace(/[^а-яА-Яa-zA-Z0-9]/g, "_")}_класиране.xlsx`;
  anchor.click();
  window.URL.revokeObjectURL(url);
}

