    const query = db
      .collection(TOURNAMENTS_COLLECTION)
      .where("countsForRanking", "==", true)
      .where("status", "==", "completed");

    const tourSnap = await query.get();
    let tournaments = tourSnap.docs.map((doc) => ({
      ...(doc.data() as Tournament),
      id: doc.id,
    }));

    // Filter by date if provided
    if (dateFilter) {
      tournaments = tournaments.filter((t) => {
        const rawDate = t.startDate as unknown as
          | { toDate: () => Date }
          | string
          | Date;
        const tDate =
          typeof (rawDate as { toDate?: () => Date }).toDate === "function"
            ? (rawDate as { toDate: () => Date }).toDate()
            : new Date(rawDate as string);
        return tDate >= dateFilter.start && tDate <= dateFilter.end;
      });
    }

    if (tournaments.length === 0) return [];

    const playerMap: Record<string, PlayerRanking> = {};

    for (const tourn of tournaments) {
      const multiplier = tourn.pointsMultiplier ?? 1;

      // Entries
      const entriesSnap = await db
        .collection(ENTRIES_COLLECTION)
        .where("tournamentId", "==", tourn.id)
        .get();
      const entries = entriesSnap.docs.map((doc) => ({
        ...(doc.data() as TournamentEntry),
        id: doc.id,
      }));

      // Matches
      const matchesSnap = await db
        .collection(MATCHES_COLLECTION)
        .where("tournamentId", "==", tourn.id)
        .get();
      const matches = matchesSnap.docs.map((doc) => ({
        ...(doc.data() as Match),
        id: doc.id,
      }));

      for (const cat of tourn.categories) {
        const catEntries = entries.filter((e) => e.categoryId === cat);
        const catMatches = matches.filter((m) => m.categoryId === cat);

        if (catEntries.length === 0) continue;

        const positionMap = calcTournamentStandings(catEntries, catMatches);
        const catMatchesCompleted = catMatches.filter(
          (m) => m.status === "completed"
        );

        catEntries.forEach((entry) => {
          if (!entry.memberId) return;

          const position = positionMap[entry.id!] ?? catEntries.length;
          const rawPoints = getPlacementPoints(position);
          const finalPoints = Math.round(rawPoints * multiplier);

          let entryWins = 0;
          let entryLosses = 0;
          catMatchesCompleted.forEach((m) => {
            if (
              m.player1EntryId === entry.id ||
              m.player2EntryId === entry.id
            ) {
              if (m.winnerEntryId === entry.id) entryWins++;
              else entryLosses++;
            }
          });

          const addPointsToPlayer = (mId: string, name: string) => {
            if (!playerMap[mId]) {
              playerMap[mId] = {
                memberId: mId,
                memberName: name,
                totalPoints: 0,
                tournamentsPlayed: 0,
                wins: 0,
                losses: 0,
                bestPlacement: null,
                categoryBreakdown: [],
              };
            }

            const player = playerMap[mId];
            player.totalPoints += finalPoints;
            player.tournamentsPlayed++;
            player.wins += entryWins;
            player.losses += entryLosses;

            if (
              player.bestPlacement === null ||
              position < player.bestPlacement
            ) {
              player.bestPlacement = position;
            }

            const catLabel =
              cat === "singles"
                ? "Единично"
                : cat === "doubles"
                  ? "Двойки"
                  : "Смесени";
            const existing = player.categoryBreakdown.find(
              (c) => c.category === catLabel
            );
            if (existing) {
              existing.points += finalPoints;
              existing.played++;
            } else {
              player.categoryBreakdown.push({
                category: catLabel,
                points: finalPoints,
                played: 1,
              });
            }
          };

          if (entry.memberId) {
            addPointsToPlayer(
              entry.memberId,
              entry.externalName || entry.memberId
            );
          }

          if (entry.partnerMemberId) {
            addPointsToPlayer(
              entry.partnerMemberId,
              entry.partnerExternalName || entry.partnerMemberId
            );
          }
        });
      }
    }

    const sorted = Object.values(playerMap).sort(
      (a, b) => b.totalPoints - a.totalPoints
    );

    // Final serialization for Client Component
    return serializeFirestoreData(
      sorted.map((p, idx) => ({ ...p, position: idx + 1 }))
    ) as RankingEntry[];
  } catch (error) {
    console.error("Error computing rankings on server:", error);
    throw error;
  }
}

import { getDocs, query, where } from "firebase/firestore";
import { PlayerRanking, RankingEntry } from "@/types/ranking.types";
import {
  mapDocToTournament,
  mapDocToEntry,
  mapDocToMatch,
} from "@/lib/tournament-mapper";

import {
  getTournamentsQuery,
  getTournamentEntriesQuery,
  getTournamentMatchesQuery,
} from "@/lib/firebase-collections";

import {
  getPlacementPoints,
  calcTournamentStandings,
} from "@/lib/ranking-utils";

// ──────────────────────────────────────────────
// Основна функция за ранглиста
// ──────────────────────────────────────────────
export async function computeGlobalRankings(dateFilter?: {
  start: Date;
  end: Date;
}): Promise<RankingEntry[]> {
  // 1. Всички завършени турнири, влизащи в ранглистата
  const q = query(
    getTournamentsQuery(),
    where("countsForRanking", "==", true),
    where("status", "==", "completed")
  );

  const tourSnap = await getDocs(q);
  let tournaments = tourSnap.docs.map(mapDocToTournament);

  // Филтриране по дата, ако е зададено
  if (dateFilter) {
    tournaments = tournaments.filter((t) => {
      const tDate = new Date(t.startDate);
      return tDate >= dateFilter.start && tDate <= dateFilter.end;
    });
  }

  if (tournaments.length === 0) return [];

  // 2. За всеки турнир – вземаме entries и matches
  const playerMap: Record<string, PlayerRanking> = {};

  for (const tourn of tournaments) {
    const multiplier = tourn.pointsMultiplier ?? 1;

    // Entries
    const entriesSnap = await getDocs(
      query(getTournamentEntriesQuery(), where("tournamentId", "==", tourn.id))
    );
    const entries = entriesSnap.docs.map(mapDocToEntry);

    // Matches
    const matchesSnap = await getDocs(
      query(getTournamentMatchesQuery(), where("tournamentId", "==", tourn.id))
    );
    const matches = matchesSnap.docs.map(mapDocToMatch);

    // 3. Изчисляваме позиции по категория
    for (const cat of tourn.categories) {
      const catEntries = entries.filter((e) => e.categoryId === cat);
      const catMatches = matches.filter((m) => m.categoryId === cat);

      if (catEntries.length === 0) continue;

      const positionMap = calcTournamentStandings(catEntries, catMatches);
      const catMatchesCompleted = catMatches.filter(
        (m) => m.status === "completed"
      );

      catEntries.forEach((entry) => {
        if (!entry.memberId) return; // Пропускаме гости

        const position = positionMap[entry.id!] ?? catEntries.length;
        const rawPoints = getPlacementPoints(position);
        const finalPoints = Math.round(rawPoints * multiplier);

        // Статистики от мачовете
        let entryWins = 0;
        let entryLosses = 0;
        catMatchesCompleted.forEach((m) => {
          if (m.player1EntryId === entry.id || m.player2EntryId === entry.id) {
            if (m.winnerEntryId === entry.id) entryWins++;
            else entryLosses++;
          }
        });

        // Функция за добавяне на точки на играч
        const addPointsToPlayer = (mId: string, name: string) => {
          if (!playerMap[mId]) {
            playerMap[mId] = {
              memberId: mId,
              memberName: name,
              totalPoints: 0,
              tournamentsPlayed: 0,
              wins: 0,
              losses: 0,
              bestPlacement: null,
              categoryBreakdown: [],
            };
          }

          const player = playerMap[mId];
          player.totalPoints += finalPoints;
          player.tournamentsPlayed++;
          player.wins += entryWins;
          player.losses += entryLosses;

          if (
            player.bestPlacement === null ||
            position < player.bestPlacement
          ) {
            player.bestPlacement = position;
          }

          const catLabel =
            cat === "singles"
              ? "Единично"
              : cat === "doubles"
                ? "Двойки"
                : "Смесени";
          const existing = player.categoryBreakdown.find(
            (c: { category: string; points: number; played: number }) =>
              c.category === catLabel
          );
          if (existing) {
            existing.points += finalPoints;
            existing.played++;
          } else {
            player.categoryBreakdown.push({
              category: catLabel,
              points: finalPoints,
              played: 1,
            });
          }
        };

        // Добавяме точки на първия играч
        if (entry.memberId) {
          addPointsToPlayer(
            entry.memberId,
            entry.externalName || entry.memberId
          );
        }

        // Добавяме точки на партньора (ако има такъв)
        if (entry.partnerMemberId) {
          addPointsToPlayer(
            entry.partnerMemberId,
            entry.partnerExternalName || entry.partnerMemberId
          );
        }
      });
    }
  }

  // 4. Сортираме и добавяме позиции
  const sorted = Object.values(playerMap).sort(
    (a, b) => b.totalPoints - a.totalPoints
  );
  return sorted.map((p, idx) => ({ ...p, position: idx + 1 }));
}

import {
  getDocs,
  query,
  where,
  DocumentSnapshot,
  QueryDocumentSnapshot,
} from "firebase/firestore";
import { ScheduleEvent, Attendee, ScheduleEventType } from "@/types";
import { toISOStringOrUndefined } from "@/lib/date-utils";
import { getEventsQuery } from "@/lib/firebase-collections";

export const docToScheduleEvent = (
  doc: DocumentSnapshot | QueryDocumentSnapshot
): ScheduleEvent | null => {
  if (!doc.id || !doc.exists()) return null;
  const data = doc.data() || {};

  const attendees = (Array.isArray(data.attendees) ? data.attendees : [])
    .map((item: Omit<Attendee, "id">): Attendee | null => {
      if (!item || typeof item !== "object") return null;
      return {
        memberId: typeof item.memberId === "string" ? item.memberId : "",
        name: typeof item.name === "string" ? item.name : "Anonymous",
        attended: typeof item.attended === "boolean" ? item.attended : false,
        paymentStatus: item.paymentStatus,
        paymentType: item.paymentType,
        paymentDate: item.paymentDate,
        saleId: item.saleId,
      };
    })
    .filter(Boolean) as Attendee[];

  return {
    id: doc.id,
    title: typeof data.title === "string" ? data.title : "Untitled Event",
    description: typeof data.description === "string" ? data.description : "",
    startDate:
      toISOStringOrUndefined(data.startDate) || new Date().toISOString(),
    endDate: toISOStringOrUndefined(data.endDate) || new Date().toISOString(),
    type: (["training", "competition", "camp", "event", "other"].includes(
      data.type
    )
      ? data.type
      : data.title === "Тренировка"
        ? "training"
        : "other") as ScheduleEventType,
    location:
      typeof data.location === "string" ? data.location : "Unknown Location",
    attendees: attendees,
    attendeeMemberIds: Array.isArray(data.attendeeMemberIds)
      ? data.attendeeMemberIds
      : [],
  };
};

/**
 * Извлича всички събития за даден период.
 * @param startDate Начална дата.
 * @param endDate Крайна дата.
 * @returns Масив от събития.
 */
export const getEventsForPeriod = async (
  startDate: Date,
  endDate: Date
): Promise<ScheduleEvent[]> => {
  console.log(
    `getEventsForPeriod: Querying from ${startDate.toISOString()} to ${endDate.toISOString()}`
  );
  const q = query(
    getEventsQuery(),
    where("startDate", ">=", startDate.toISOString()),
    where("startDate", "<=", endDate.toISOString())
  );

  const snapshot = await getDocs(q);

  const events = snapshot.docs
    .map(docToScheduleEvent)
    .filter(Boolean) as ScheduleEvent[];

  return events;
};

export const getEventsByMemberId = async (
  memberId: string
): Promise<ScheduleEvent[]> => {
  const q = query(
    getEventsQuery(),
    where("attendeeMemberIds", "array-contains", memberId)
  );

  const snapshot = await getDocs(q);

  const events = snapshot.docs
    .map(docToScheduleEvent)
    .filter(Boolean) as ScheduleEvent[];

  events.sort(
    (a, b) => new Date(b.startDate).getTime() - new Date(a.startDate).getTime()
  );

  return events;
};

export type TrainingType = "shadow" | "physical" | "court";
export type ShadowMode = "standard" | "ghost_match" | "agility_test";
export type ShadowPace = "slow" | "medium" | "fast";
export type ShadowPreset = "beginner" | "advanced" | "custom";

export interface TrainingSession {
  id?: string;
  siteId: string;
  type: TrainingType;
  date: string; // ISO string
  memberIds: string[];
  durationMs: number;

  // Specific to Shadow Training
  shadowDetails?: {
    mode: ShadowMode;
    preset?: ShadowPreset;
    setsCompleted: number;
    totalSets: number;
    workTimeSec: number;
    restTimeSec: number;
    pace?: ShadowPace;
    deceptionEnabled: boolean;
    agilityTestTimeSec?: number; // If it was an agility test
    heatmap?: Record<string, number>; // zone -> count
  };

  rpeScores?: Record<string, number>; // memberId -> 1-10

  createdAt?: any;
  createdBy?: { uid: string; email: string; name?: string };
}
